let _pmDisplayFps = null;        // actual playback fps for display badge (e.g. 23.976)

// ── FrameClock: exact rational playback rate to eliminate drift ────────────────
// secondsToFrame(T) = floor(T × playNum/playDen) — no floating-point accumulation.
// tcBase drives all TC string math; playNum/playDen drives video time → frame.
const _pmFrameClock = {
  playNum: 24000, playDen: 1001, tcBase: 24, seqStart: 0, displayFormat: 'NDF',
  secondsToFrame(t) { return Math.floor(t * this.playNum / this.playDen + 1e-9); },
  frameToTC(f)      { return framesToTC(f, this.tcBase); },
};
function _pmFpsToRational(fps) {
  if (Math.abs(fps - 23.976)  < 0.01) return { num: 24000,  den: 1001 };
  if (Math.abs(fps - 29.97)   < 0.01) return { num: 30000,  den: 1001 };
  if (Math.abs(fps - 47.952)  < 0.01) return { num: 48000,  den: 1001 };
  if (Math.abs(fps - 59.94)   < 0.01) return { num: 60000,  den: 1001 };
  if (Math.abs(fps - 119.88)  < 0.01) return { num: 120000, den: 1001 };
  return { num: Math.round(fps), den: 1 };
}
