// Safe getter — falls back to seqBase so formulas never break before EDL loads
const _pmVidZero = () => _pmVideoZeroAbsF !== null ? _pmVideoZeroAbsF : _pmSeqBaseFrames;
const _pmRememberVideoMediaTimeSec = (sec) => {
  if (Number.isFinite(sec)) _pmLastVideoMediaTimeSec = sec;
};
function _pmToast(msg, type = 'info', durationMs = 3500) {
  const container = document.getElementById('main-prepmark') || document.body;
  let el = container.querySelector('._pm-toast');
  if (!el) {
    el = document.createElement('div');
    el.className = '_pm-toast';
    container.appendChild(el);
  }
  el.textContent = msg;
  el.dataset.type = type;
  el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:99999;padding:8px 18px;border-radius:8px;font-size:13px;font-weight:500;pointer-events:none;transition:opacity .2s;' +
    (type === 'error' ? 'background:#c0392b;color:#fff;' : type === 'warn' ? 'background:#e67e22;color:#fff;' : 'background:#2d3436;color:#f5f5f5;');
  el.style.opacity = '1';
  clearTimeout(el._pmToastTimer);
  el._pmToastTimer = setTimeout(() => { el.style.opacity = '0'; }, durationMs);
}

function _pmReadVideoMediaTimeSec({ preferPresented = true } = {}) {
  if (!pmVideo) return 0;
  let sec = NaN;
  if (preferPresented && !pmVideo.seeking && !pmVideo.paused && Number.isFinite(_pmPresentedMediaTimeSec)) {
    sec = _pmPresentedMediaTimeSec;
  }
  if (!Number.isFinite(sec)) sec = Number(pmVideo.currentTime);
  if (!Number.isFinite(sec)) sec = Number.isFinite(_pmLastVideoMediaTimeSec) ? _pmLastVideoMediaTimeSec : 0;
  _pmRememberVideoMediaTimeSec(sec);
  return sec;
}
function _pmReadVideoAbsFrame(opts = {}) {
  return _pmFrameClock.secondsToFrame(_pmReadVideoMediaTimeSec(opts)) + _pmVidZero();
}
function _pmEventHasNamedVfxClipMarker(ev) {
  if (!ev) return false;
  const markers = Array.isArray(ev._markers) ? ev._markers
    : (Array.isArray(ev?.metadata?.markers) ? ev.metadata.markers : []);
  for (const m of markers) {
    if (!m) continue;
    const sc = (m.scope == null) ? '' : String(m.scope).toLowerCase();
    if (sc && sc !== 'clip' && m._from !== 'edlLoc') continue;
    let name = String(m.name || '').trim();
    if (!name || /^marker\s*\d*$/i.test(name)) {
      name = String(ev.clipName || ev.reel || '').trim();
    }
    if (name) return true;
  }
  if (ev._edlLoc) return true;
  return false;
}
function _pmGetPullEvents() {
  if (_pmQs('vfxmarker')) {
    return (_pmEvents || []).filter(_pmEventHasNamedVfxClipMarker);
  }
  if (_pmQs('conform')) {
    return (_pmEvents || []).filter(ev => ev && !ev._pmConformSkip);
  }
  return _pmEvents || [];
}
function _pmGetSelectedMarkerForDisplay(currentFrame, fps) {
  if (!_pmSelectedMarkerId || !_pmQs('vfxmarker')) return null;
  const mk = _pmClipMarkers.find(m => m.id === _pmSelectedMarkerId);
  if (!mk?.recIn) return null;
  if (!pmVideo || !pmVideo.src) return mk;
  const mkF = tcToFrames(mk.recIn, fps);
  return (pmVideo.paused && currentFrame === mkF) ? mk : null;
}
function _pmSeekVideoAbsFrame(absF, { navTarget = null, syncNow = false } = {}) {
  if (!pmVideo || !Number.isFinite(absF)) return;
  // Seek to the center of the requested frame instead of the boundary.
  // Boundary seeks can decode the previous frame, which shows up most often on
  // the first clip where "previous" means the video's absolute frame 0.
  const targetFrameInVideo = absF - _pmVidZero();
  // When a ProRes/QuickTime clip is playing through the native-AV canvas engine,
  // the hidden <video> (whose currentTime we set below) can't repaint the canvas
  // overlay — so drive the engine to the sought frame directly. Without this the
  // canvas stays on frame 0 and reads black after any relayout (e.g. project load).
  try { pmVideo._pfxNativeEngine?.seekFrame?.(Math.max(0, targetFrameInVideo)); } catch {}
  const biasedMediaTime = Math.max(0, (targetFrameInVideo + 0.5) * _pmFrameClock.playDen / _pmFrameClock.playNum);
  const dur = Number(pmVideo.duration);
  const maxMediaTime = (Number.isFinite(dur) && dur > 0)
    ? Math.max(0, dur - (0.25 * _pmFrameClock.playDen / _pmFrameClock.playNum))
    : Infinity;
  const mediaTime = Math.min(biasedMediaTime, maxMediaTime);
  _pmSeekTargetF = absF;
  _pmPresentedMediaTimeSec = NaN;
  if (Number.isFinite(navTarget)) _pmNavTarget = navTarget;
  try { pmVideo.currentTime = mediaTime; } catch {}
  _pmRememberVideoMediaTimeSec(mediaTime);
  _pmLastSyncedF = -1;
  if (syncNow) _pmSyncFrame();
  // Non-playable companion clip (proxy not ready): seeking the <video> is a
  // no-op, so paint a companion-decoded frame at the playhead instead of
  // leaving the frame-0 placeholder/black pane.
  _pmScheduleCompanionFrame(targetFrameInVideo);
}

// Debounced, token-guarded companion frame grab for the current playhead while
// a non-browser-playable clip has no proxy yet. Best-effort — failures leave
// the existing placeholder. Only runs in companion mode when the <video> can't
// decode the source itself.
function _pmScheduleCompanionFrame(frameInVideo) {
  if (!_pmCompanionMode || _pmNativeCanPlay || !_pmNativeAssetId || !pmVideoHint) return;
  if (_pmCompanionFrameTimer) { clearTimeout(_pmCompanionFrameTimer); _pmCompanionFrameTimer = 0; }
  const f = Math.max(0, Math.round(Number(frameInVideo) || 0));
  _pmCompanionFrameTimer = setTimeout(() => { _pmCompanionFrameTimer = 0; _pmPaintCompanionFrameAt(f); }, 120);
}

async function _pmPaintCompanionFrameAt(frame) {
  if (!_pmCompanionMode || _pmNativeCanPlay || !pmVideoHint) return;
  const assetId = _pmNativeAssetId;
  if (!assetId) return;
  const myTok = ++_pmCompanionFrameToken;
  const _live = () => _pmNativeAssetId === assetId && myTok === _pmCompanionFrameToken && pmVideoHint;
  try {
    let r = null;
    try {
      r = await withTimeout(
        sharedMediaGetFrame(assetId, frame, { quality: 'half', width: 640, height: 360 }),
        6000, 'companion seek frame',
      );
    } catch { /* fall through — keep placeholder */ }
    let src = r?.data?.dataUrl || r?.data?.url || null;
    if (!src || !_live()) return;
    if (src.startsWith('http')) {
      const resp = await _pmCompanionFetch(src);
      if (!resp.ok || !_live()) return;
      const blob = await resp.blob();
      src = await new Promise((res, rej) => {
        const rd = new FileReader(); rd.onload = () => res(rd.result); rd.onerror = rej; rd.readAsDataURL(blob);
      });
    }
    if (!src || !_live()) return;
    pmVideoHint.style.display          = '';
    pmVideoHint.style.backgroundImage  = `url("${src}")`;
    pmVideoHint.style.backgroundSize   = 'contain';
    pmVideoHint.style.backgroundRepeat = 'no-repeat';
    pmVideoHint.style.backgroundPosition = 'center';
  } catch { /* best-effort live preview */ }
}
function _pmStartVideoFrameClock() {
  if (!pmVideo || typeof pmVideo.requestVideoFrameCallback !== 'function' || _pmVideoFrameCbId) return;
  const onFrame = (_now, metadata = {}) => {
    _pmVideoFrameCbId = 0;
    if (Number.isFinite(metadata?.mediaTime)) {
      _pmPresentedMediaTimeSec = metadata.mediaTime;
      _pmRememberVideoMediaTimeSec(metadata.mediaTime);
    }
    _pmLastSyncedF = -1;
    _pmSyncFrame();
    if (pmVideo && !pmVideo.paused && !pmVideo.ended) _pmStartVideoFrameClock();
  };
  try {
    _pmVideoFrameCbId = pmVideo.requestVideoFrameCallback(onFrame);
  } catch {}
}
function _pmStopVideoFrameClock({ clearPresented = true } = {}) {
  if (pmVideo && _pmVideoFrameCbId && typeof pmVideo.cancelVideoFrameCallback === 'function') {
    try { pmVideo.cancelVideoFrameCallback(_pmVideoFrameCbId); } catch {}
  }
  _pmVideoFrameCbId = 0;
  if (clearPresented) _pmPresentedMediaTimeSec = NaN;
}
function _pmVideoEndAbsFrame() {
  if (!pmVideo) return _pmVidZero();
  const fps = Math.max(1, _pmFps || 24);
  const dur = Number(pmVideo.duration);
  return _pmVidZero() + (Number.isFinite(dur) && dur > 0 ? Math.floor(dur * fps + 1e-6) : 0);
}

function _pmEventAbsRange(ev, fps) {
  const eIn  = tcToFrames(ev?.recIn  || '00:00:00:00', fps);
  const rOut = tcToFrames(ev?.recOut || '00:00:00:00', fps);
  const eOut = rOut > eIn ? rOut
             : ev?.durationFrames ? eIn + Number(ev.durationFrames)
             : eIn + 1;
  return { eIn, eOut };
}

function _pmGetNavProtectState(currentFrame, fps) {
  if (_pmNavTarget < 0 || _pmActiveEventIdx !== _pmNavTarget) return { active: false, floor: null, eOut: null };
  const navEv = _pmEvents[_pmNavTarget];
  if (!navEv) return { active: false, floor: null, eOut: null };

  const { eIn, eOut } = _pmEventAbsRange(navEv, fps);
  let floor = eIn;
  if (_pmQs('vfxmarker') && _pmSelectedMarkerId) {
    const navMk = _pmClipMarkers.find(m => m.id === _pmSelectedMarkerId);
    if (navMk?.recIn) floor = tcToFrames(navMk.recIn, fps);
  }

  const beforeTarget = currentFrame < floor;
  const holdTolerance = Math.max(6, Math.ceil(fps / 4));
  const active = beforeTarget && (pmVideo?.seeking || (floor - currentFrame) <= holdTolerance);
  return { active, floor, eOut };
}

