let _pmPreviewSuppressDepth = 0;
let _pmPreviewSuppressSnapshot = null;

function _pmSetPreviewSuppressed(suppressed, reason = '') {
  if (suppressed) {
    _pmPreviewSuppressDepth++;
    if (_pmPreviewSuppressDepth > 1) {
      return () => _pmSetPreviewSuppressed(false, reason);
    }
    const video = pmVideo || document.getElementById('pmVideo');
    const wrap = pmPlayerWrap || document.querySelector('.pm-player-wrap');
    _pmPreviewSuppressSnapshot = video ? {
      display: video.style.display,
      visibility: video.style.visibility,
      opacity: video.style.opacity,
      pointerEvents: video.style.pointerEvents,
    } : null;
    try { video?.pause?.(); } catch {}
    if (wrap) wrap.classList.add('pm-preview-suppressed');
    if (video) {
      video.style.display = 'none';
      video.style.visibility = 'hidden';
      video.style.opacity = '0';
      video.style.pointerEvents = 'none';
    }
    try { window.__pfxElectron?.avplayer?.command?.({ type: 'hide' }); } catch {}
    return () => _pmSetPreviewSuppressed(false, reason);
  }

  if (_pmPreviewSuppressDepth > 0) _pmPreviewSuppressDepth--;
  if (_pmPreviewSuppressDepth > 0) return;
  const video = pmVideo || document.getElementById('pmVideo');
  const wrap = pmPlayerWrap || document.querySelector('.pm-player-wrap');
  if (wrap) wrap.classList.remove('pm-preview-suppressed');
  if (video && _pmPreviewSuppressSnapshot) {
    video.style.display = _pmPreviewSuppressSnapshot.display;
    video.style.visibility = _pmPreviewSuppressSnapshot.visibility;
    video.style.opacity = _pmPreviewSuppressSnapshot.opacity;
    video.style.pointerEvents = _pmPreviewSuppressSnapshot.pointerEvents;
  }
  _pmPreviewSuppressSnapshot = null;
  try { window.__pfxElectron?.avplayer?.command?.({ type: 'show' }); } catch {}
}

function _pmForcePreviewVisible(reason = '') {
  _pmPreviewSuppressDepth = 0;
  const video = pmVideo || document.getElementById('pmVideo');
  const wrap = pmPlayerWrap || document.querySelector('.pm-player-wrap');
  if (wrap) wrap.classList.remove('pm-preview-suppressed');
  if (video) {
    video.style.display = '';
    video.style.visibility = '';
    video.style.opacity = '';
    video.style.pointerEvents = '';
  }
  _pmPreviewSuppressSnapshot = null;
  try { window.__pfxElectron?.avplayer?.command?.({ type: 'show' }); } catch {}
}

async function _pmWithPreviewSuppressed(work, reason = 'dialog') {
  const restore = _pmSetPreviewSuppressed(true, reason);
  try {
    return await work();
  } finally {
    try { restore?.(); } catch {}
  }
}

function _pmClickFileInputWithPreviewGuard(inputEl) {
  if (!inputEl) return;
  const restore = _pmSetPreviewSuppressed(true, 'file-input');
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    try { restore?.(); } catch {}
    try { window.removeEventListener('focus', onFocus); } catch {}
    try { inputEl.removeEventListener('change', finish); } catch {}
    try { inputEl.removeEventListener('cancel', finish); } catch {}
  };
  const onFocus = () => setTimeout(finish, 250);
  try { inputEl.addEventListener('change', finish, { once: true }); } catch {}
  try { inputEl.addEventListener('cancel', finish, { once: true }); } catch {}
  try { window.addEventListener('focus', onFocus, { once: true }); } catch {}
  inputEl.click();
}

try {
  window.__pfxHideMediaOverlaysForDialog = (reason) => _pmSetPreviewSuppressed(true, reason || 'external-dialog');
  window.__pfxShowMediaOverlaysAfterDialog = (reason) => _pmSetPreviewSuppressed(false, reason || 'external-dialog');
} catch {}

// Project-scoped storage — each key is prefixed with the current project name so
// that loading a different EDL never overwrites another project's data.
function _lsKey(suffix) {
  return `pfx.prepmark.${_pmCurrentProjectKey || 'default'}.${suffix}`;
}
// Expose current project key for project_setup.js and other modules.
window.__pfxGetProjectKey = () => _pmCurrentProjectKey || 'default';

// Restore the proxy video persisted in the project file (pull_prep state).
// Called by projectFile.js on load — works even when there is no EDL (so
// _pmRefreshData's project-change path never fires) and on the per-tab load
// path (which doesn't restore the settings-tab localStorage snapshot).
window.MPS_restorePullPrepMedia = function restorePullPrepMedia(media){
  try {
    window.__PFX_PULLPREP_MEDIA = (media && media.proxyVideoNativePath) ? media : null;
  } catch {}
  if (!window.__PFX_PULLPREP_MEDIA) return;
  // Ensure a project key so _lsKey()/_pmTryRestoreVideo() resolve, even when no
  // EDL is loaded to derive one from.
  if (!_pmCurrentProjectKey) {
    try {
      const pn = window.__MPS_PROJECT_NAME || window.__MPS_EDL_RAW?.projectName || '';
      _pmCurrentProjectKey = String(pn).trim().replace(/[^a-zA-Z0-9_\-\.]/g, '_') || 'default';
    } catch { _pmCurrentProjectKey = 'default'; }
  }
  try { _pmTryRestoreVideo().catch(() => {}); } catch {}
};

function _pmSerializableClipMarkers() {
  return (_pmClipMarkers || []).map(mk => {
    const { thumb, thumbAnn, annoStrokes, _thumbCapturing, _thumbError, ...rest } = mk || {};
    return rest;
  });
}

function _pmObjectFromMap(map) {
  const out = {};
  try {
    for (const [k, v] of map || []) out[k] = v;
  } catch {}
  return out;
}

function _pmSerializableAnnotations() {
  const out = {};
  try {
    for (const [k, v] of _pmAnnotMap || []) {
      if (v && Array.isArray(v.shapes) && v.shapes.length) out[k] = v;
    }
  } catch {}
  return out;
}

function _pmAdoptProjectKeyFromState(state) {
  const projectName = state?.projectName || state?.project || window.__MPS_PROJECT_NAME || '';
  const key = String(projectName || '').trim().replace(/[^a-zA-Z0-9_\-\.]/g, '_') || _pmCurrentProjectKey || 'default';
  _pmCurrentProjectKey = key;
  return key;
}

function _pmStoredMediaDescriptor() {
  try {
    if (window.__PFX_PULLPREP_MEDIA?.proxyVideoNativePath) return window.__PFX_PULLPREP_MEDIA;
  } catch {}
  try {
    if (_pmVideoFile?._nativePath) {
      return {
        proxyVideoNativePath: _pmVideoFile._nativePath,
        proxyVideoName: _pmVideoFile.name || ''
      };
    }
  } catch {}
  return null;
}

window.PFX_exportPullPrepState = function exportPullPrepState() {
  try { _pmSaveClipMarkers(); } catch {}
  try { _pmSaveStatus(); } catch {}

  const raw = (() => { try { return window.__MPS_EDL_RAW || null; } catch { return null; } })();
  const media = _pmStoredMediaDescriptor();
  const prepMark = {
    schema: 'pfx_pull_prep_content',
    schemaVersion: 1,
    projectKey: _pmCurrentProjectKey || 'default',
    clipMarkers: _pmSerializableClipMarkers(),
    shotStatus: _pmObjectFromMap(_pmStatusMap),
    eventMeta: _pmObjectFromMap(_pmMetaMap),
    annotations: _pmSerializableAnnotations(),
    video: {
      zeroAbsF: Number.isFinite(_pmVideoZeroAbsF) ? _pmVideoZeroAbsF : null,
      syncManuallySet: !!_pmSyncManuallySet,
      lastMediaTimeSec: Number.isFinite(_pmLastVideoMediaTimeSec) ? _pmLastVideoMediaTimeSec : null
    }
  };

  const hasContent = !!(
    prepMark.clipMarkers.length ||
    Object.keys(prepMark.shotStatus).length ||
    Object.keys(prepMark.eventMeta).length ||
    Object.keys(prepMark.annotations).length
  );
  if (!raw && !media && !hasContent) return null;

  const out = raw ? { ...raw } : {
    projectName: window.__MPS_PROJECT_NAME || _pmCurrentProjectKey || 'Project'
  };
  if (media) out._pfxMedia = media;
  if (hasContent || prepMark.video.zeroAbsF !== null) out._pfxPrepMark = prepMark;
  return out;
};

window.PFX_applyPullPrepState = function applyPullPrepState(state) {
  if (!state || typeof state !== 'object') return false;
  const key = _pmAdoptProjectKeyFromState(state);
  const prepMark = state._pfxPrepMark || null;
  const media = state._pfxMedia || state.media || null;

  if (prepMark && typeof prepMark === 'object') {
    try {
      if (Array.isArray(prepMark.clipMarkers)) {
        const cleaned = prepMark.clipMarkers.map(mk => {
          const { _thumbCapturing, _thumbError, ...rest } = mk || {};
          return { thumb: '', thumbAnn: '', annoStrokes: null, ...rest };
        });
        _pmClipMarkers = cleaned;
        localStorage.setItem(_lsKey('clipMarkers.v2'), JSON.stringify(_pmSerializableClipMarkers()));
      }
    } catch {}
    try {
      _pmStatusMap.clear();
      for (const [k, v] of Object.entries(prepMark.shotStatus || {})) _pmStatusMap.set(k, v);
      localStorage.setItem(_lsKey('shotStatus.v1'), JSON.stringify(prepMark.shotStatus || {}));
    } catch {}
    try {
      _pmMetaMap.clear();
      for (const [k, v] of Object.entries(prepMark.eventMeta || {})) _pmMetaMap.set(k, v);
      localStorage.setItem(_lsKey('eventMeta.v1'), JSON.stringify(prepMark.eventMeta || {}));
    } catch {}
    try {
      _pmAnnotMap.clear();
      _pmAnnotImgCache.clear();
      for (const [k, v] of Object.entries(prepMark.annotations || {})) {
        if (v && Array.isArray(v.shapes)) _pmAnnotMap.set(k, v);
      }
      const annotations = _pmSerializableAnnotations();
      const annKey = _lsKey('annotations.v1');
      localStorage.setItem(annKey, JSON.stringify(annotations));
      if (typeof chrome !== 'undefined' && chrome.storage?.local?.set) {
        chrome.storage.local.set({ [annKey]: annotations }).catch(() => {});
      }
    } catch {}
    try {
      if (prepMark.video?.zeroAbsF !== null && Number.isFinite(+prepMark.video.zeroAbsF)) {
        _pmVideoZeroAbsF = +prepMark.video.zeroAbsF;
        _pmSyncManuallySet = prepMark.video.syncManuallySet !== false;
        localStorage.setItem(_lsKey('vidZeroAbsF.v1'), String(_pmVideoZeroAbsF));
      }
      if (Number.isFinite(+prepMark.video?.lastMediaTimeSec)) {
        _pmLastVideoMediaTimeSec = +prepMark.video.lastMediaTimeSec;
      }
    } catch {}
  }

  if (media?.proxyVideoNativePath) {
    try {
      window.__PFX_PULLPREP_MEDIA = media;
      localStorage.setItem(_lsKey('lastVideoNativePath.v1'), media.proxyVideoNativePath);
      if (media.proxyVideoName) localStorage.setItem(_lsKey('lastVideoName.v1'), media.proxyVideoName);
    } catch {}
  }

  try { window.dispatchEvent(new CustomEvent('pfx:pull-prep-state-applied', { detail: { projectKey: key, state } })); } catch {}
  return true;
};

// Expose VFX shot list data for the settings panel (vfxPullSettings.js).
window._pfxGetVfxShotList = function () {
  try {
    const fps = _pmFps || 24;
    const evLinkCount = _pmBuildEventLinkCount();
    const renderOrder = _pmBuildRenderOrder(evLinkCount);
    return renderOrder.map(({ ev, i }) => {
      const linkedMks = _pmGetAllLinkedMarkersForEvent(i);
      const mk0 = linkedMks[0];
      if (!mk0) return null;
      const ocfState = _pmResolveVfxOcfState(ev, mk0);
      const durF = (ev?.recOut && ev?.recIn)
        ? (tcToFrames(ev.recOut, fps) - tcToFrames(ev.recIn, fps)) : 0;
      const hasSpeed = !!(ev?._pmRetime || ev?._pmRetimeAuto ||
        (Array.isArray(ev?.speedKeys) && ev.speedKeys.length > 0));
      const hasReframe = !!(ev?.resize?.width || ev?.reformatName || ev?.resizeMode);
      return {
        eventIndex: i,
        shotName:   String(mk0.shotName || ev?.clipName || '').trim(),
        clipName:   String(ev?.clipName || ev?.reel || '').trim(),
        recIn: ev?.recIn || '', recOut: ev?.recOut || '',
        srcIn: ev?.srcIn || '', srcOut: ev?.srcOut || '',
        durFrames: durF, fps,
        ocfLinked:  ocfState.status === 'linked',
        ocfStatus:  ocfState.status,
        ocfPath:    ocfState.sourcePath || '',
        approved:   !!(mk0?.approved),
        linkVerified: mk0?._linkVerified === true,
        hasSpeedChange: hasSpeed,
        hasReframe,
        matchScore: mk0?.matchScore ?? null,
      };
    }).filter(Boolean);
  } catch { return []; }
};

// Column widths are a UI preference, not project data — keep global.

// ── Timeline view-state persistence (zoom, pan, toggles, track heights) ──
// Saved as one bundle per project so a reload restores exactly the view
// the user left. Debounced — flushed from _pmScheduleDraw + pagehide.
let _pmTlViewSaveTimer = 0;
let _pmTlViewLoaded    = false;  // suppress saves until first load completes
function _pmTlViewSave() {
  if (!_pmCurrentProjectKey) return;
  try {
    const trackHeightsObj = {};
    for (const [k, v] of _pmTrackHeights) trackHeightsObj[String(k)] = v;
    const bundle = {
      zoom: _pmTlZoom, panFr: _pmTlPanFr, scrollY: _pmTlScrollY,
      snap: _pmTlSnap, showMk: _pmTlShowMk, showTr: _pmTlShowTr,
      showSub: _pmTlShowSub, compact: _pmTlCompact,
      pack: _pmTlPack, packIntelligent: _pmPackIntelligent,
      trackHeights: trackHeightsObj,
    };
    localStorage.setItem(_lsKey('tlView.v1'), JSON.stringify(bundle));
  } catch {}
}
function _pmTlViewSaveSoon() {
  if (!_pmTlViewLoaded) return;
  if (_pmTlViewSaveTimer) return;
  _pmTlViewSaveTimer = setTimeout(() => {
    _pmTlViewSaveTimer = 0;
    _pmTlViewSave();
  }, 400);
}
function _pmTlViewLoad() {
  _pmTlViewLoaded = false;
  try {
    const raw = localStorage.getItem(_lsKey('tlView.v1'));
    if (raw) {
      const b = JSON.parse(raw) || {};
      if (Number.isFinite(+b.zoom))    _pmTlZoom    = Math.max(1, Math.min(64, +b.zoom));
      if (Number.isFinite(+b.panFr))   _pmTlPanFr   = Math.max(0, +b.panFr);
      if (Number.isFinite(+b.scrollY)) _pmTlScrollY = Math.max(0, +b.scrollY);
      if (typeof b.snap    === 'boolean') _pmTlSnap    = b.snap;
      if (typeof b.showMk  === 'boolean') _pmTlShowMk  = b.showMk;
      if (typeof b.showTr  === 'boolean') _pmTlShowTr  = b.showTr;
      if (typeof b.showSub === 'boolean') _pmTlShowSub = b.showSub;
      if (typeof b.compact === 'boolean') _pmTlCompact = b.compact;
      if (typeof b.pack    === 'boolean') _pmTlPack    = b.pack;
      if (typeof b.packIntelligent === 'boolean') _pmPackIntelligent = b.packIntelligent;
      _pmTrackHeights.clear();
      if (b.trackHeights && typeof b.trackHeights === 'object') {
        for (const [k, v] of Object.entries(b.trackHeights)) {
          const ki = parseInt(k, 10);
          if (Number.isFinite(ki) && Number.isFinite(+v)) _pmTrackHeights.set(ki, +v);
        }
      }
    }
  } catch {}
  _pmTlViewLoaded = true;
}

// ── Smart Diff base persistence ─────────────────────────────────────────
// Base cuts can be large (hundreds of parsed events) so prefer chrome.storage.local
// which has no 5 MB cap; fall back to localStorage when unavailable.
function _pmSmartDiffSave() {
  if (!_pmCurrentProjectKey) return;
  const key = _lsKey('smartDiffBase.v1');
  const payload = _pmSmartDiffBase ? { ..._pmSmartDiffBase } : null;
  try {
    if (typeof chrome !== 'undefined' && chrome.storage?.local?.set) {
      if (payload === null) {
        chrome.storage.local.remove(key).catch(() => {});
      } else {
        chrome.storage.local.set({ [key]: payload }).catch(() => {
          try { localStorage.setItem(key, JSON.stringify(payload)); } catch {}
        });
      }
    } else if (payload === null) {
      localStorage.removeItem(key);
    } else {
      localStorage.setItem(key, JSON.stringify(payload));
    }
  } catch {}
}
function _pmSmartDiffLoad() {
  if (!_pmCurrentProjectKey) return;
  const key = _lsKey('smartDiffBase.v1');
  const _hydrate = (b) => {
    if (!b || typeof b !== 'object' || !Array.isArray(b.events)) return;
    _pmSmartDiffBase = { name: String(b.name || 'Base Cut'), fps: +b.fps || _pmFps || 24, events: b.events };
    try { _pmAnalyzeSmartDiff(); } catch {}
    try { _pmUpdateSmartDiffUi?.(); } catch {}
  };
  // Sync localStorage read first for immediate availability.
  try {
    const raw = localStorage.getItem(key);
    if (raw) _hydrate(JSON.parse(raw));
  } catch {}
  // Async chrome.storage read takes precedence (canonical store).
  if (typeof chrome !== 'undefined' && chrome.storage?.local?.get) {
    const snapKey = _pmCurrentProjectKey;
    chrome.storage.local.get(key, (res) => {
      if (_pmCurrentProjectKey !== snapKey) return;
      const data = res?.[key];
      if (data) _hydrate(data);
    });
  }
}

// One-shot pagehide handler: flush any pending debounced save before the
// extension page is suspended. Registered once at module load.
if (typeof window !== 'undefined' && !window.__pmTlViewUnloadWired) {
  window.__pmTlViewUnloadWired = true;
  const _flush = () => {
    if (_pmTlViewSaveTimer) {
      clearTimeout(_pmTlViewSaveTimer);
      _pmTlViewSaveTimer = 0;
      _pmTlViewSave();
    }
  };
  window.addEventListener('pagehide', _flush);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') _flush();
  });
}

const _IDB_NAME      = 'pfx_pm_v1';
const _IDB_STORE     = 'vhnd';
const _IDB_KEY       = 'last'; // legacy fallback key

// Returns the per-project IDB key for the video handle, falling back to 'last'.
function _pmIdbProjectKey() {
  return _pmCurrentProjectKey ? `proj.${_pmCurrentProjectKey}` : _IDB_KEY;
}

// ─── IndexedDB helpers for FileSystemFileHandle persistence ──────────────────
function _pmIdbOpen() {
  return new Promise((res, rej) => {
    const req = indexedDB.open(_IDB_NAME, 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore(_IDB_STORE);
    req.onsuccess = e => res(e.target.result);
    req.onerror   = e => rej(e.target.error);
  });
}
async function _pmIdbSaveHandle(handle) {
  try {
    const db = await _pmIdbOpen();
    const tx = db.transaction(_IDB_STORE, 'readwrite');
    const store = tx.objectStore(_IDB_STORE);
    const projKey = _pmIdbProjectKey();
    if (handle) {
      // Save under the project-specific key only.
      // Never write to the legacy 'last' key — that causes any new project that
      // hasn't explicitly linked a video to silently inherit the previous project's video.
      store.put(handle, projKey);
    } else {
      // null = only wipe the legacy 'last' key.
      // Never delete the project-specific key here — it is managed by _pmClear separately.
      store.delete(_IDB_KEY);
    }
    // Wait for the transaction to fully commit before closing.
    await new Promise((res, rej) => { tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
    db.close();
  } catch {}
}
async function _pmIdbGetHandle(key) {
  try {
    const k = key || _pmIdbProjectKey();
    const db = await _pmIdbOpen();
    return await new Promise(res => {
      const req = db.transaction(_IDB_STORE, 'readonly').objectStore(_IDB_STORE).get(k);
      req.onsuccess = () => { db.close(); res(req.result || null); };
      req.onerror   = () => { db.close(); res(null); };
    });
  } catch { return null; }
}

// Annotation state — tcKey → { shapes, annoDataUrl }
let _pmAnnotMap = new Map();

// Active MutationObserver for the SM Naming Template modal (prevents stacking on re-open)
let _pmNamingTemplateObserver = null;

// ALE match state — statusKey → ALE record object
let _pmAleMap = new Map();

// ─── Start Fresh reset ────────────────────────────────────────────────────────
function _pmClear() {
  _pmStopVideoFrameClock();
  // Fully release the video element: cancels proxy, revokes blob URL, resets all state.
  if (pmVideo) {
    try { pmVideo.pause(); } catch {}
    releasePlayableVideo(pmVideo);
    // Hide the element so no stale frame is visible after reset.
    pmVideo.style.display = 'none';
    pmVideo.style.visibility = 'hidden';
  }

  // Clear in-memory state
  _pmVideoFile   = null;
  _pmEvents      = [];
  _pmMarkers     = [];
  _pmClipMarkers = [];
  window.__pmPlateSeq = 1; // reset plate counter on new project
  _pmLinkMap.clear();
  _pmClipMatchMap.clear();
  _pmStatusMap.clear();
  _pmMetaMap.clear();
  _pmAnnotMap.clear();
  _pmAnnotImgCache.clear();
  _pmAleMap.clear();
  _pmSmartDiffBase = null;
  _pmSmartDiffByEventIdx.clear();
  _pmSmartDiffSummary = null;
  _pmSmartDiffOnly = false;
  _pmSmartDiffProjectKey = '';
  _pmLastRaw         = null;
  _pmActiveEventIdx  = -1;
  _pmSlyAiHistory    = [];
  _pmNavTarget       = -1;
  _pmSelectedMarkerId  = null;
  _pmSelectedMarkerIds.clear();
  _pmTrackHeights.clear();
  _pmDurationSec     = 0;
  _pmTlPlayhead      = -1;
  _pmTlZoom          = 1;
  _pmTlPanFr         = 0;
  _pmVideoZeroAbsF   = null;
  _pmSyncManuallySet   = false;
  _pmSyncMode          = false;
  _pmShowDisabledClips = false;
  _pmPresentedMediaTimeSec = NaN;
  _pmLastVideoMediaTimeSec = NaN;
  _pmVideoFrameCbId        = 0;
  _pmNativeAssetId   = null;
  _pmDisplayFps      = null;
  _pmNativeFps       = null;
  _pmNativeStartTc   = null;
  _pmCompanionMode   = false;
  _pmNativeCanPlay   = false;

  // Reset event table
  if (pmEventBody) pmEventBody.innerHTML = '';
  if (pmEventEmpty) pmEventEmpty.style.display = '';

  // Reset video area — show hint, keep player wrap visible
  _pmProxyBarHide();
  _pmSetVideoStatus(null);
  _pmRemoveNativeEngineBadge();
  if (pmVideoHint) {
    pmVideoHint.classList.remove('pm-proxying');
    pmVideoHint.style.display         = '';
    pmVideoHint.style.backgroundImage = '';  // clear companion-mode preview frame
  }
  if (pmPlayerWrap)  pmPlayerWrap.style.display   = '';

  // Reset inspector
  if (pmInspector) pmInspector.innerHTML = '';

  // Reset scrubber
  if (pmScrub) { pmScrub.value = 0; pmScrub.max = 0; }
  if (pmHudRecTc)  pmHudRecTc.textContent  = '—';
  if (pmHudSrcTc)  pmHudSrcTc.textContent  = '—';
  if (pmHudFrame)  pmHudFrame.textContent  = '—';
  if (pmClipBanner) pmClipBanner.style.display = 'none';

  // Reset context bar
  if (pmCtxProject) pmCtxProject.textContent = '—';
  if (pmCtxFps)     pmCtxFps.textContent     = '—';
  if (pmCtxEvents)  pmCtxEvents.textContent  = '0 events';
  if (pmCtxMarkers) pmCtxMarkers.textContent = '0 markers';
  if (pmCtxLinked)  pmCtxLinked.textContent  = '0 linked';
  try { _pmUpdateSmartDiffUi(); } catch {}

  // Clear timeline canvas
  if (_pmTlCanvas && _pmTlCtx) {
    _pmTlCtx.clearRect(0, 0, _pmTlCanvas.width, _pmTlCanvas.height);
  }

  // Reset coverage stats
  if (pmCovStats) pmCovStats.textContent = '';

  // Close export menu
  if (pmExportMenu) pmExportMenu.style.display = 'none';

  // Cancel any pending RAF callbacks so they don't fire into cleared state
  if (_pmPlayRafId)    { cancelAnimationFrame(_pmPlayRafId);    _pmPlayRafId    = 0; }
  if (_pmRafId)        { cancelAnimationFrame(_pmRafId);        _pmRafId        = 0; }
  if (_pmResizeRetryId){ cancelAnimationFrame(_pmResizeRetryId);_pmResizeRetryId= 0; }

  // Reset export-in-progress flag so the next project can export without being blocked.
  _pmQtExporting = false;

  // Reset VFX Pull panel — clears match results, jobs, OCF folder, and manual links.
  try { resetVfxPullCard(); } catch {}

  // Clear naming-template project values (SHOW, SQ, VENDOR, etc.) so the
  // inspector chips do not bleed from the previous project into the new one.
  try { window.__ntResetProjectValues?.(); } catch {}

  // Disconnect naming-template MutationObserver so it doesn't fire into cleared state.
  if (_pmNamingTemplateObserver) {
    try { _pmNamingTemplateObserver.disconnect(); } catch {}
    _pmNamingTemplateObserver = null;
  }

  // Remove the legacy 'last' IDB key so it can't bleed into other projects.
  // Do NOT remove the project-specific key (proj.<name>) — the video association
  // should survive a "New" click and restore when the project is re-opened.
  try { localStorage.removeItem(_lsKey('lastVideoName.v1')); } catch {}
  try { localStorage.removeItem(_lsKey('lastVideoNativePath.v1')); } catch {}
  try {
    (async () => {
      try {
        const db = await _pmIdbOpen();
        const tx = db.transaction(_IDB_STORE, 'readwrite');
        tx.objectStore(_IDB_STORE).delete(_IDB_KEY);
        await new Promise((res, rej) => { tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
        db.close();
      } catch {}
    })();
  } catch {}
}

// ─── Public init ──────────────────────────────────────────────────────────────
export function initPrepMark() {
  if (_pmInitDone) return;

  // One-time migration: remove the legacy 'last' IDB key so it can never be
  // restored as a cross-project fallback again.
  (async () => {
    try {
      const db = await _pmIdbOpen();
      const tx = db.transaction(_IDB_STORE, 'readwrite');
      tx.objectStore(_IDB_STORE).delete(_IDB_KEY);
      await new Promise((res, rej) => { tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
      db.close();
    } catch {}
  })();

  const $ = id => document.getElementById(id);

  pmVideo           = $('pmVideo');
  pmEventBody       = $('pmEventBody');
  pmEventEmpty      = $('pmEventEmpty');
  pmTlWrap          = $('pmTlWrap');
  pmScrub           = $('pmScrub');
  pmPlayBtn         = $('pmPlayBtn');
  pmPrevFrameBtn    = $('pmPrevFrameBtn');
  pmNextFrameBtn    = $('pmNextFrameBtn');
  pmPrevEventBtn    = $('pmPrevEventBtn');
  pmNextEventBtn    = $('pmNextEventBtn');
  pmAddMarkerBtn       = $('pmAddMarkerBtn');
  pmMarkerColorBtn     = $('pmMarkerColorBtn');
  pmMarkerColorSwatch  = $('pmMarkerColorSwatch');
  pmMarkerColorMenu    = $('pmMarkerColorMenu');
  pmVidQtTcOverlay  = $('pmVidQtTcOverlay');
  pmHudRecTc        = $('pmHudRecTc');
  if (pmHudRecTc) {
    pmHudRecTc.title = 'Click to jump to REC timecode';
    pmHudRecTc.style.cursor = 'text';
    pmHudRecTc.addEventListener('click', () => {
      if (pmHudRecTc.querySelector('input')) return; // already editing
      const currentText = pmHudRecTc.textContent.replace(/^REC\s*/i, '').trim();
      const inp = document.createElement('input');
      inp.className = 'pm-hud-tc-input';
      inp.value = currentText === '—' ? '' : currentText;
      inp.maxLength = 11;
      inp.placeholder = '00:00:00:00';
      inp.title = 'Enter REC timecode and press Enter to jump';
      pmHudRecTc.textContent = '';
      pmHudRecTc.appendChild(inp);
      inp.focus();
      inp.select();
      const commit = () => {
        const raw = inp.value.trim().replace(/[^0-9:;]/g, '');
        if (raw) {
          const fps = Math.max(1, _pmFps || 24);
          const targetF = tcToFrames(raw, fps);
          if (Number.isFinite(targetF) && targetF >= 0) {
            _pmSeekVideoAbsFrame(targetF, { syncNow: true });
          }
        }
        pmHudRecTc.textContent = currentText ? `REC ${currentText}` : 'REC —';
      };
      inp.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); commit(); }
        if (e.key === 'Escape') { pmHudRecTc.textContent = currentText ? `REC ${currentText}` : 'REC —'; }
      });
      inp.addEventListener('blur', commit);
    });
  }
  pmHudSrcTc        = $('pmHudSrcTc');
  pmHudFrame        = $('pmHudFrame');
  pmHudBurninTc     = $('pmHudBurninTc');
  pmHudTcOffset     = $('pmHudTcOffset');
  pmHudTcWarn       = $('pmHudTcWarn');
  pmClipBanner      = $('pmClipBanner');
  pmCtxProject      = $('pmCtxProject');
  pmCtxFps          = $('pmCtxFps');
  pmCtxEvents       = $('pmCtxEvents');
  pmCtxMarkers      = $('pmCtxMarkers');
  pmCtxLinked       = $('pmCtxLinked');
  _pmInitFpsChip();
  pmAutoLinkBtn     = $('pmAutoLinkBtn');
  pmExportBtn       = $('pmExportBtn');
  pmExportMenu      = $('pmExportMenu');
  pmImportEdlBtn    = $('pmImportEdlBtn');
  pmEdlFileInput    = $('pmEdlFileInput');
  pmVideoBrowseBtn  = $('pmVideoBrowseBtn');
  pmVideoImportBtn  = $('pmVideoImportBtn');
  pmVideoFileInput  = $('pmVideoFileInput');
  pmVideoHint       = $('pmVideoHint');
  // Delegate clicks on dynamic warning links injected into pmVideoHint
  if (pmVideoHint) {
    pmVideoHint.addEventListener('click', (e) => {
      const link = e.target.closest('.pm-settings-link[data-goto]');
      if (!link) return;
      e.preventDefault();
      try { window.setMainTab?.(link.dataset.goto); } catch {}
    });
  }
  pmPlayerWrap      = $('pmPlayerWrap');
  pmBurninCanvas    = $('pmBurninCanvas');
  if (pmBurninCanvas && pmPlayerWrap) {
    if (_pmPlayerWrapRO) _pmPlayerWrapRO.disconnect();
    _pmPlayerWrapRO = new ResizeObserver(() => {
      if (_pmActiveEventIdx >= 0) _pmUpdateBurninCanvas(_pmActiveEventIdx);
    });
    _pmPlayerWrapRO.observe(pmPlayerWrap);
  }
  pmInspector       = $('pmInspector');
  pmCovStats        = $('pmCovStats');
  pmAnnotCanvas     = $('pmAnnotCanvas');
  pmAnnotateBtn     = $('pmAnnotateBtn');
  pmAleMatchBtn          = $('pmAleMatchBtn');
  pmAleFileInput         = $('pmAleFileInput');
  pmMarkerMatchBtn       = $('pmMarkerMatchBtn');
  pmMarkerMatchFileInput = $('pmMarkerMatchFileInput');
  pmKpiExr          = $('pmKpiExr');
  pmKpiCam          = $('pmKpiCam');
  pmKpiEvts         = $('pmKpiEvts');
  pmKpiDur          = $('pmKpiDur');
  pmDiffBaseBtn     = $('pmDiffBaseBtn');
  pmDiffAnalyzeBtn  = $('pmDiffAnalyzeBtn');
  pmDiffOpenBtn     = $('pmDiffOpenBtn');
  pmDiffOnlyBtn     = $('pmDiffOnlyBtn');
  pmDiffClearBtn    = $('pmDiffClearBtn');
  pmDiffBaseFileInput = $('pmDiffBaseFileInput');
  pmDiffSummary     = $('pmDiffSummary');
  pmDiffBaseLabel   = $('pmDiffBaseLabel');
  pmDiffChipNew     = $('pmDiffChipNew');
  pmDiffChipExt     = $('pmDiffChipExt');
  pmDiffChipChg     = $('pmDiffChipChg');
  pmDiffChipTrim    = $('pmDiffChipTrim');
  pmDiffChipRisk    = $('pmDiffChipRisk');

  if (!pmVideo || !pmEventBody) return; // pane not in DOM yet

  _pmInitDone = true;

  // Project data is loaded on first _pmRefreshData() call once the project key is known.

  try { _wireVideoPlayer();      } catch(e) { console.warn('[PM] _wireVideoPlayer failed', e); }
  try { _wireControls();         } catch(e) { console.warn('[PM] _wireControls failed', e); }
  try { _wireKeyboard();         } catch(e) { console.warn('[PM] _wireKeyboard failed', e); }
  try { _wireExport();           } catch(e) { console.warn('[PM] _wireExport failed', e); }
  try { _wireTimeline();         } catch(e) { console.warn('[PM] _wireTimeline failed', e); }
  try { _wireQsRow();            } catch(e) { console.warn('[PM] _wireQsRow failed', e); }
  try { _wireAnnotations();      } catch(e) { console.warn('[PM] _wireAnnotations failed', e); }
  try { _wireViewerContextMenu();} catch(e) { console.warn('[PM] _wireViewerContextMenu failed', e); }
  try { _wireAleMatch();         } catch(e) { console.warn('[PM] _wireAleMatch failed', e); }
  try { _wireCtxBuildProxiesBtn(); } catch(e) { console.warn('[PM] _wireCtxBuildProxiesBtn failed', e); }
  try { _wireSmartDiff();        } catch(e) { console.warn('[PM] _wireSmartDiff failed', e); }
  try { _pmWireStoragePopover(); } catch(e) { console.warn('[PM] _pmWireStoragePopover failed', e); }
  try { _wireAdvancedMode();      } catch(e) { console.warn('[PM] _wireAdvancedMode failed', e); }
  try { _wireSlyUndoRedo();      } catch(e) { console.warn('[PM] _wireSlyUndoRedo failed', e); }
  try { _wireResetBtn();         } catch(e) { console.warn('[PM] _wireResetBtn failed', e); }
  try { _wireSlyFrameSync();     } catch(e) { console.warn('[PM] _wireSlyFrameSync failed', e); }
  try { _wirePmVidBrightness(); } catch(e) { console.warn('[PM] _wirePmVidBrightness failed', e); }
  try { _wirePmVidFullscreen(); } catch(e) { console.warn('[PM] _wirePmVidFullscreen failed', e); }
  try { _wirePmVidAnnotate();   } catch(e) { console.warn('[PM] _wirePmVidAnnotate failed', e); }
  try { _wirePmQuickAnnotate(); } catch(e) { console.warn('[PM] _wirePmQuickAnnotate failed', e); }
  try { _wireVfxWorkspace();    } catch(e) { console.warn('[PM] _wireVfxWorkspace failed', e); }
  // Listen for EDL updates from Pull Prep
  window.addEventListener('mps:edl-timeline-updated', () => {
    try { _pmRefreshData(); } catch {}
  });

  // Listen for tab changes
  document.addEventListener('mps:mainTabChanged', (e) => {
    if (e.detail?.key === 'prepmark') {
      try { _pmRefreshData(); } catch {}
      // Double-rAF: first frame applies display change, second frame has valid layout metrics
      if (_pmResizeRetryId) cancelAnimationFrame(_pmResizeRetryId);
      _pmResizeRetryId = requestAnimationFrame(() => { _pmResizeRetryId = requestAnimationFrame(() => { _pmResizeRetryId = 0; try { _pmResizeTlCanvas(); } catch {} }); });
    }
  });

  // Expose for ui.js hook
  window.__pmRefresh = () => {
    try { _pmRefreshData(); } catch {}
    requestAnimationFrame(() => requestAnimationFrame(() => { try { _pmResizeTlCanvas(); } catch {} }));
  };

  window.__pmClear = _pmClear;

  // Pre-fetch companion HTTP token so video.src streaming is authenticated
  // even before the user manually browses for a file.
  (async () => {
    try {
      if (!window.__pfxCompanionHttpToken) {
        const r = await nativeHelperPing().catch(() => null);
        if (r?.data?.httpToken) window.__pfxCompanionHttpToken = r.data.httpToken;
      }
    } catch {}
  })();

  // Initial data load
  requestAnimationFrame(() => { _pmRefreshData(); });

  // Column resize
  _pmInitColResize();
}

// ─── Column resize ────────────────────────────────────────────────────────────
const _LS_COL_WIDTHS_KEY = 'pfx.prepmark.colWidths.v1';
const _PM_COL_WIDTH_DEFAULTS = {
  'pm-col-num': 20,
  'pm-col-dot': 12,
  'pm-col-reel': 124,
  'pm-col-tc': 84,
  'pm-col-dur': 46,
  'pm-col-shot': 180,
  'pm-col-rt': 18,
  'pm-col-st': 18,
  'pm-col-rs': 18,
  'pm-col-hdl': 40,
  'pm-col-link': 74,
  'pm-col-mk-add': 36,
};
const _PM_COL_WIDTH_MINS = {
  'pm-col-reel': 84,
  'pm-col-tc': 72,
  'pm-col-dur': 34,
  'pm-col-shot': 120,
  'pm-col-hdl': 30,
  'pm-col-link': 52,
};

function _pmApplyColWidths(widths = {}) {
  const table = document.getElementById('pmEventTable');
  if (!table) return;
  for (const [key, fallback] of Object.entries(_PM_COL_WIDTH_DEFAULTS)) {
    const next = Math.max(12, Number(widths?.[key]) || fallback);
    table.style.setProperty(`--${key}-w`, `${next}px`);
  }
}

function _pmInitColResize() {
  const table = document.getElementById('pmEventTable');
  if (!table) return;
  if (table.dataset.pmColResizeReady === '1') return;

  const ths = Array.from(table.querySelectorAll('thead th'));
  const saved = (() => {
    try {
      return JSON.parse(localStorage.getItem(_LS_COL_WIDTHS_KEY) || '{}') || {};
    } catch {
      return {};
    }
  })();

  _pmApplyColWidths(saved);

  const SKIP = new Set(['pm-col-dot', 'pm-col-rt', 'pm-col-st', 'pm-col-rs', 'pm-col-num']);

  const persistWidths = () => {
    const widths = {};
    ths.forEach(th => {
      const key = th.className.trim().split(/\s+/)[0];
      if (!key || !_PM_COL_WIDTH_DEFAULTS[key]) return;
      const raw = table.style.getPropertyValue(`--${key}-w`).trim();
      const px = parseInt(raw, 10);
      if (Number.isFinite(px)) widths[key] = px;
    });
    try { localStorage.setItem(_LS_COL_WIDTHS_KEY, JSON.stringify(widths)); } catch {}
  };

  ths.forEach(th => {
    const key = th.className.trim().split(/\s+/)[0];
    if (SKIP.has(key)) return;

    th.style.position = 'relative';
    th.classList.add('pm-col-resizable');
    const handle = document.createElement('div');
    handle.className = 'pm-col-resize-handle';
    handle.title = 'Drag to resize column · double-click to reset';
    th.appendChild(handle);

    handle.addEventListener('mousedown', e => {
      e.preventDefault();
      e.stopPropagation();
      const startX = e.clientX;
      const startW = th.getBoundingClientRect().width;
      const minW = _PM_COL_WIDTH_MINS[key] || 24;
      document.body.classList.add('pm-col-resizing');

      const onMove = e => {
        const next = Math.max(minW, Math.round(startW + e.clientX - startX));
        table.style.setProperty(`--${key}-w`, `${next}px`);
      };
      const onUp = () => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        document.body.classList.remove('pm-col-resizing');
        persistWidths();
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });

    handle.addEventListener('dblclick', e => {
      e.preventDefault();
      e.stopPropagation();
      const fallback = _PM_COL_WIDTH_DEFAULTS[key];
      table.style.setProperty(`--${key}-w`, `${fallback}px`);
      persistWidths();
    });
  });

  table.dataset.pmColResizeReady = '1';
}

// ─── Project-scoped data load ─────────────────────────────────────────────────
function _pmLoadProjectData() {
  // Shot statuses
  _pmStatusMap.clear();
  try {
    const raw = localStorage.getItem(_lsKey('shotStatus.v1'));
    if (raw) {
      const obj = JSON.parse(raw);
      for (const [k, v] of Object.entries(obj)) _pmStatusMap.set(k, v);
    }
  } catch {}

  // Event metadata (shot names, handles, flags)
  _pmMetaMap.clear();
  try {
    const raw = localStorage.getItem(_lsKey('eventMeta.v1'));
    if (raw) {
      const obj = JSON.parse(raw);
      for (const [k, v] of Object.entries(obj)) _pmMetaMap.set(k, v);
    }
  } catch {}

  // Clip markers (blobs and transient UI flags stripped on save)
  try {
    const raw = localStorage.getItem(_lsKey('clipMarkers.v2'));
    const _cmParsed = raw ? JSON.parse(raw) : null;
    _pmClipMarkers = (Array.isArray(_cmParsed) ? _cmParsed : []).map(mk => {
      // Strip any stale transient flags that may have been saved by older code.
      // _thumbError / _thumbCapturing must never survive a reload — a stale error
      // permanently blocks auto-capture until the user manually clicks retry.
      const { _thumbCapturing, _thumbError, ...rest } = mk;
      return { thumb: '', thumbAnn: '', annoStrokes: null, ...rest };
    });
  } catch { _pmClipMarkers = []; }

  // Annotations
  _pmAnnotMap.clear();
  _pmAnnotImgCache.clear();
  const _annotLoadRaw = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    for (const [k, v] of Object.entries(obj)) {
      if (v && typeof v === 'object' && Array.isArray(v.shapes)) {
        _pmAnnotMap.set(k, v);
      } else if (Array.isArray(v) && v.length) {
        _pmAnnotMap.set(k, { shapes: v, annoDataUrl: null }); // migrate old format
      }
    }
  };
  try {
    // Sync load from localStorage first so data is immediately available.
    const raw = localStorage.getItem(_lsKey('annotations.v1'));
    if (raw) _annotLoadRaw(JSON.parse(raw));
  } catch {}
  // Async load from chrome.storage.local — this is the primary store (no quota cap).
  // When available its data overwrites the localStorage snapshot (more recent + complete).
  if (typeof chrome !== 'undefined' && chrome.storage?.local?.get) {
    const csKey = _lsKey('annotations.v1');
    const _csProjectKey = _pmCurrentProjectKey; // snapshot — guard against project switch before callback fires
    chrome.storage.local.get(csKey, (res) => {
      // Bail if the user switched projects while the async read was in-flight.
      if (_pmCurrentProjectKey !== _csProjectKey) return;
      try {
        const csData = res?.[csKey];
        if (csData && typeof csData === 'object') {
          for (const [k, v] of Object.entries(csData)) {
            if (v && typeof v === 'object' && Array.isArray(v.shapes)) {
              _pmAnnotMap.set(k, v);
            }
          }
        }
      } catch {}
    });
  }

  // Video sync offset — always reset and reload from the new project's localStorage key.
  _pmSyncManuallySet = false;
  _pmVideoZeroAbsF = null;
  try {
    const savedZ = localStorage.getItem(_lsKey('vidZeroAbsF.v1'));
    if (savedZ !== null && Number.isFinite(+savedZ)) {
      _pmVideoZeroAbsF   = +savedZ;
      _pmSyncManuallySet = true;
    }
  } catch {}

  // Restore timeline view (zoom/pan/toggles/track heights) and Smart Diff base.
  // Both are project-scoped, so they live alongside the per-project state above.
  _pmTlViewLoad();
  _pmSmartDiffLoad();
}

// ─── Frame rate helpers ────────────────────────────────────────────────────────
function _pmGetProjectSettingsFps() {
  return window.__pfxProjectSetup?.getSettings?.()?.general?.frameRate || 0;
}

function _pmHandleFpsMismatch(importFps, projFps) {
  return new Promise(resolve => {
    // Build a simple modal using the existing pfx-modal pattern
    const fmt = n => {
      const presets = { 23.976: '23.976', 24: '24', 25: '25', 29.97: '29.97', 30: '30', 50: '50', 59.94: '59.94', 60: '60', 120: '120' };
      return presets[Math.round(n * 1000) / 1000] || n.toFixed(3);
    };
    const uid = `pfx-fps-mismatch-${Date.now()}`;
    const html = `
      <div class="pfx-modal-backdrop" id="${uid}-backdrop" style="position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.6)">
        <div class="pfx-modal-box" style="background:#1e1e1e;border:1px solid #444;border-radius:8px;padding:24px 28px;max-width:420px;width:90%;color:#e0e0e0;font-family:inherit">
          <div style="font-weight:600;font-size:14px;margin-bottom:12px">Frame Rate Mismatch</div>
          <p style="font-size:13px;margin:0 0 18px;line-height:1.5;color:#bbb">
            The imported file uses <strong style="color:#e0e0e0">${fmt(importFps)} fps</strong>,
            but the project is set to <strong style="color:#e0e0e0">${fmt(projFps)} fps</strong>.<br>
            Which frame rate should be used?
          </p>
          <div style="display:flex;flex-direction:column;gap:8px">
            <button id="${uid}-use-import" style="background:#2d6af5;border:none;border-radius:5px;padding:9px 14px;color:#fff;font-size:13px;cursor:pointer;text-align:left">
              Use imported fps (${fmt(importFps)} fps)
            </button>
            <button id="${uid}-keep-proj" style="background:#333;border:1px solid #555;border-radius:5px;padding:9px 14px;color:#e0e0e0;font-size:13px;cursor:pointer;text-align:left">
              Keep project fps (${fmt(projFps)} fps)
            </button>
            <button id="${uid}-cancel" style="background:transparent;border:none;border-radius:5px;padding:9px 14px;color:#888;font-size:13px;cursor:pointer;text-align:left">
              Cancel import
            </button>
          </div>
        </div>
      </div>`;
    const wrap = document.createElement('div');
    wrap.innerHTML = html;
    document.body.appendChild(wrap);
    const close = () => wrap.remove();

    wrap.querySelector(`#${uid}-use-import`).addEventListener('click', () => {
      _pmFps = Math.max(1, importFps);
      close(); resolve('import');
    });
    wrap.querySelector(`#${uid}-keep-proj`).addEventListener('click', () => {
      // _pmFps already set to projFps; nothing to change
      close(); resolve('project');
    });
    wrap.querySelector(`#${uid}-cancel`).addEventListener('click', () => {
      // Revert raw so the data is not rendered
      window.__MPS_EDL_RAW = _pmLastRaw;
      window.__MPS_EDL_VIEW = null;
      close(); resolve('cancel');
    });
  });
}

// ─── Data refresh ─────────────────────────────────────────────────────────────
async function _pmRefreshData() {
  _pmSyncMode = true;
  const raw  = window.__MPS_EDL_RAW;

  // VFX Rename / VFX Marker / Conform all use RAW events so the timeline canvas
  // always has correct sequence recIn/recOut. The pipeline (decompose, flatten, etc.)
  // restructures events in __MPS_EDL_VIEW which can corrupt TC values used by the canvas.
  // Table-level filtering (VFX-only rows) is handled by CSS display:none rules.
  if ((_pmQs('vfxmarker') || _pmQs('vfxrename') || _pmQs('conform')) && Array.isArray(raw?.events)) {
    // VFX modes: use raw events for correct sequence TC (decompose/flatten in pipeline
    // may produce sub-clip TCs that break the timeline canvas layout).
    // CSS rules hide non-VFX rows in the table; _pmClipMarkers drives VFX filter badges.
    _pmEvents = raw.events.filter(ev => ev != null && typeof ev === 'object');
    _pmEvents.forEach(ev => { delete ev._pmConformSkip; });
  } else {
    const view = window.__MPS_EDL_VIEW;
    _pmEvents = Array.isArray(view) ? view : (Array.isArray(raw?.events) ? raw.events : []);
    _pmEvents = _pmEvents.filter(ev => ev != null && typeof ev === 'object');
    // Clear any stale skip flags from a previous Conform session
    _pmEvents.forEach(ev => { delete ev._pmConformSkip; });
  }
  // Unscripted mode: strip stills, graphics, text-only events from table + timeline
  if (_pmImportMode === 'unscripted') {
    // Remove only extension-blocked stills/docs; keep NLE graphic stubs but mark disabled
    _pmEvents = _pmEvents.filter(ev => {
      const src = ev.srcFile || ev.reel || ev.clip || ev.name || '';
      return !_PM_UNSCRIPTED_BLOCK_EXT.test(src);
    });
    _pmEvents.forEach(ev => {
      delete ev._pmUnscriptedSkip;
      delete ev._pmSkipReason;
      const noActionKind = _pmGetUnscriptedNoActionKind(ev);
      if (noActionKind) {
        ev._pmUnscriptedSkip = true;
        ev._pmSkipReason = `${noActionKind} layer — no action needed in Unscripted mode`;
      }
    });
  } else {
    _pmEvents.forEach(ev => {
      delete ev._pmUnscriptedSkip;
      delete ev._pmSkipReason;
    });
  }
  {
    const _projFps = _pmGetProjectSettingsFps();
    // raw.fps = playback fps (e.g. 23.976); raw.timecodeBase = integer for TC math (e.g. 24)
    const _importPlayFps = raw?.fps || _pmEvents[0]?.fps || 24;
    const _importTcBase  = raw?.timecodeBase || Math.round(_importPlayFps) || 24;
    // _pmFps = integer timecode base for tcToFrames / framesToTC correctness.
    // NDF NTSC: 23.976→24, 29.97→30, 59.94→60. Integer rates: 24→24, 25→25, etc.
    const _projTcBase = _projFps > 0 ? Math.max(1, Math.round(_projFps)) : 0;
    _pmFps = Math.max(1, _projTcBase > 0 ? _projTcBase : _importTcBase);
    // _pmDisplayFps = actual playback fps for badge and video timing
    _pmDisplayFps = _projFps > 0 ? _projFps : _importPlayFps;
    // Update FrameClock exact rational rate
    { const _r = _pmFpsToRational(_pmDisplayFps || _pmFps);
      _pmFrameClock.playNum = _r.num;
      _pmFrameClock.playDen = _r.den;
      _pmFrameClock.tcBase  = _pmFps;
      _pmFrameClock.displayFormat = raw?.displayFormat || 'NDF'; }
    // Mismatch is by NOMINAL rate (the integer TC base), not raw playback fps:
    // 24 and 23.976 (=24000/1001 NTSC pulldown), 30/29.97, 60/59.94 are the SAME
    // family and share a timecode base, so they must NOT prompt. The old
    // |Δfps| > 0.02 check fired on 24 vs 23.976 (Δ=0.024) — spurious. Only a real
    // nominal difference (e.g. 24 vs 25, 24 vs 30) is a genuine mismatch.
    if (raw !== _pmLastRaw && isFpsMismatch(_importPlayFps, _projFps)) {
      await _pmHandleFpsMismatch(_importPlayFps, _projFps).catch(() => {});
    }
    // Debug log on new import
    if (raw !== _pmLastRaw) {
      const g = window.__pfxProjectSetup?.getSettings?.()?.general;
      const ex = g?.frameRateExact;
      console.log(
        `[ProjectSettings] frameRate=${_pmDisplayFps} tcBase=${_pmFps}`,
        `exact=${ex ? `${ex.numerator}/${ex.denominator}` : 'n/a'}`,
        `dropFrame=${!!(g?.dropFrame)}`,
        raw?.timecodeBase ? `xmlTcBase=${raw.timecodeBase}` : '',
        raw?.displayFormat ? `displayFormat=${raw.displayFormat}` : ''
      );
    }
  }

  // ── Compute sequence range directly from events (absolute recIn/recOut) ──────
  // Always derive from events, not the Pull Prep model (which uses sequential display TCs).
  // VFX Rename → span all events; VFX Marker → span only marker-linked events.
  //
  // Pre-detect project change so _pmLinkMap is current when the seqBase filter below runs.
  // (The definitive project-change block later still handles pan/zoom reset etc.)
  {
    const _preKey = (raw?.projectName || '').trim().replace(/[^a-zA-Z0-9_\-\.]/g, '_') || 'default';
    if (raw !== _pmLastRaw || _preKey !== _pmCurrentProjectKey) {
      const _savedKey = _pmCurrentProjectKey;
      _pmCurrentProjectKey = _preKey;
      try {
        _pmLoadProjectData();   // load new project's _pmClipMarkers
        _pmRunAutoLink();       // rebuild _pmLinkMap from fresh markers
      } finally {
        _pmCurrentProjectKey = _savedKey; // always restore; main block below commits the change
      }
    }
  }
  {
    const _isVfxRename = _pmQs('vfxrename');
    const _isVfxMarker = _pmQs('vfxmarker');

    // Build marker-linked event index set (needed here before evLinkCount is available)
    const _linkedEvIdxSet = new Set([..._pmLinkMap.values()]);

    const _evIncluded = (ev, i) => {
      if (_isVfxRename) return true;
      if (_isVfxMarker) return _linkedEvIdxSet.size > 0 ? _linkedEvIdxSet.has(i) : true;
      return true; // default mode: all events
    };

    let minIn = Infinity, maxOut = -Infinity;
    for (let i = 0; i < _pmEvents.length; i++) {
      const ev = _pmEvents[i];
      if (!ev || !_evIncluded(ev, i)) continue;
      if (_pmGetUnscriptedNoActionKind(ev)) continue; // graphic/title clips excluded from sequence range
      const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', _pmFps);
      const rOut = tcToFrames(ev.recOut || '00:00:00:00', _pmFps);
      const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
      if (eIn  < minIn)  minIn  = eIn;
      if (eOut > maxOut) maxOut = eOut;
    }
    // Fallback: if filter left nothing, use all events (excluding graphics)
    if (minIn === Infinity) {
      for (const ev of _pmEvents) {
        if (!ev || _pmGetUnscriptedNoActionKind(ev)) continue;
        const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', _pmFps);
        const rOut = tcToFrames(ev.recOut || '00:00:00:00', _pmFps);
        const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
        if (eIn  < minIn)  minIn  = eIn;
        if (eOut > maxOut) maxOut = eOut;
      }
    }
    _pmSeqBaseFrames = (minIn !== Infinity) ? Math.max(0, minIn) : 0;
    _pmFrameClock.seqStart = _pmSeqBaseFrames;

    // In VFX Marker mode: also extend the timeline to cover all linked markers' positions
    // so a marker placed beyond its clip's recOut is still visible on the timeline.
    // Use mk._eventIdx directly — _pmLinkMap isn't rebuilt until after this block.
    if (_isVfxMarker && _pmClipMarkers.length > 0) {
      for (const mk of _pmClipMarkers) {
        if (mk._eventIdx === undefined || mk._eventIdx < 0) continue; // skip unlinked
        const mIn = tcToFrames(mk.recIn || mk.tcIn || '00:00:00:00', _pmFps);
        if (mIn + 1 > maxOut) maxOut = mIn + 1;
      }
    }

    _pmSeqEndFrames  = (maxOut > _pmSeqBaseFrames) ? maxOut : _pmSeqBaseFrames + 1;
  }

  // ── Per-clip sync data ───────────────────────────────────────────────────────
  // xmlRecInFrame  = absolute record frame for the clip's IN point (from sequence TC + clipitem start)
  // sourceInFrame  = absolute source frame at clip IN (from file timecode + clipitem in)
  // burninOffsetFrames = sourceInFrame - xmlRecInFrame (per-clip; constant within a clip, varies across clips)
  // This is the authority for the three-clock TC model: XML REC / Source / Reference burn-in
  for (const ev of _pmEvents) {
    if (!ev) continue;
    const xmlRecInFrame  = tcToFrames(ev.recIn  || '00:00:00:00', _pmFps);
    const sourceInFrame  = tcToFrames(ev.srcIn  || '00:00:00:00', _pmFps);
    ev.sync = {
      xmlRecInFrame,
      sourceInFrame,
      sourceTimecodeStartFrame: ev._tcStartFrames ?? 0,
      burninRecFrameAtIn:       null,
      burninOffsetFrames:       sourceInFrame - xmlRecInFrame,
      syncStatus:               'xml_only',
    };
  }

  // Detect clips that span the entire timeline and auto-disable them
  _pmDetectFullTimelineClips();

  // Sync offset: reset to seqBase on every EDL load UNLESS user has manually set a sync point.
  // Smart re-sync: if manually set but confidence drops below 40% with the new EDL, re-arm.
  if (!_pmSyncManuallySet) {
    _pmVideoZeroAbsF = _pmSeqBaseFrames;
  } else {
    const _reSyncConf = _pmSyncConfidence();
    if (_reSyncConf < 40) {
      _pmSyncManuallySet = false;
      _pmVideoZeroAbsF   = _pmSeqBaseFrames;
      try { localStorage.removeItem(_lsKey('vidZeroAbsF.v1')); } catch {}
      setTimeout(() => _pmShowSyncToast('Sync reset — new EDL has <40% alignment with saved offset'), 300);
    } else {
      setTimeout(() => _pmShowSyncToast(`Sync retained · ${_reSyncConf}% confidence with new EDL`), 300);
    }
  }

  // Markers from Shot Marker tab
  try { _pmMarkers = window.__smGetMarkersRef?.() || []; } catch { _pmMarkers = []; }

  // Detect project change — raw object reference changes every time ui.js parses a new EDL,
  // even if the projectName string happens to be the same. Use both as signals.
  const projectName = raw?.projectName || '—';
  const projKey = (raw?.projectName || '').trim().replace(/[^a-zA-Z0-9_\-\.]/g, '_') || 'default';
  const rawChanged = raw !== _pmLastRaw;
  const projectChanged = rawChanged || projKey !== _pmCurrentProjectKey;
  _pmLastRaw = raw;
  if (projectChanged && _pmSmartDiffProjectKey && _pmSmartDiffProjectKey !== projKey) {
    _pmResetSmartDiff({ keepBase: false });
  }
  if (projectChanged) {
    _pmCurrentProjectKey = projKey;
    _pmLoadProjectData();
    // Reset timeline pan/zoom so it fits the new sequence
    _pmTlZoom   = 1;
    _pmTlPanFr  = 0;
    _pmTlPlayhead = 0; // always show playhead at sequence start on project load
    // Clear stale event selection — old index is meaningless in the new event list
    _pmActiveEventIdx = -1;
    _pmNavTarget = -1;
    // Restore the project-specific proxy video. Runs after key is updated so
    // _pmIdbProjectKey() and _lsKey() both refer to the new project.
    _pmTryRestoreVideo().catch(() => {});
    // Notify project_setup.js so it can reload its settings for the new project.
    window.dispatchEvent(new CustomEvent('pfx:projectKeyChanged', { detail: { projKey } }));
  }

  // Dead guard removed — _pmLastRaw was already set to raw above
  // console.log(`[FrameClock] playbackRate=`,
  if (pmCtxProject) pmCtxProject.textContent = projectName;
  if (pmCtxFps)     pmCtxFps.textContent     = _pmFormatFpsBadge();
  if (pmCtxEvents)  pmCtxEvents.textContent  = `${_pmEvents.length} events`;
  if (pmCtxMarkers) pmCtxMarkers.textContent = `${_pmClipMarkers.length} markers`;

  // Update video hint with sequence summary
  const hintSeq = document.getElementById('pmVideoHintSeq');
  if (hintSeq && _pmEvents.length > 0) {
    const totalFr = _pmSeqEndFrames - _pmSeqBaseFrames;
    const totalSec = totalFr / Math.max(1, _pmFps);
    const mm = Math.floor(totalSec / 60);
    const ss = Math.floor(totalSec % 60);
    hintSeq.textContent = `${projectName} · ${_pmEvents.length} events · ${mm}:${String(ss).padStart(2,'0')}`;
  } else if (hintSeq) {
    hintSeq.textContent = '';
  }

  _pmAutoDetectFlags(_pmEvents);
  _pmApplyMetaToEvents();
  _pmRunAutoLink();
  if (_pmSmartDiffBase?.events?.length) {
    try { _pmAnalyzeSmartDiff(); } catch (e) { console.warn('[PM] Smart Diff auto-refresh failed', e); }
  } else {
    _pmUpdateSmartDiffUi();
  }
  // Ensure playhead is always visible on first load (never stays at -1)
  if (_pmTlPlayhead < 0) _pmTlPlayhead = 0;
  try { _pmRenderEventTable(); } catch(e) { console.error('[PrepMark] _pmRenderEventTable failed', e); }
  try { _pmPushTimelineData(); } catch(e) { console.error('[PrepMark] _pmPushTimelineData failed', e); }
  try { _pmUpdateQsButtons();  } catch(e) { console.warn('[PrepMark] _pmUpdateQsButtons failed', e); }
  try { _pmUpdateStorageKpi(); } catch(e) { console.warn('[PrepMark] _pmUpdateStorageKpi failed', e); }
  try { _pmUpdateCtxBtns();   } catch(e) { console.warn('[PrepMark] _pmUpdateCtxBtns failed', e); }
  try { _pmUpdateInfoRail();   } catch(e) { console.warn('[PrepMark] _pmUpdateInfoRail failed', e); }
  try { window.__pmUpdateSyncDisplay?.(); } catch {}  // refresh offset display after seqBase update

  // Sync default already applied at line 530; display updated above via __pmUpdateSyncDisplay.

  const linked = _pmLinkMap.size;
  if (pmCtxLinked) pmCtxLinked.textContent = `${linked} linked`;

  try { _pmSlyRefresh();    } catch(e) { console.warn('[PM] _pmSlyRefresh failed', e); }
  try { _pmUpdateMkRail(); } catch(e) { console.warn('[PM] _pmUpdateMkRail failed', e); }
}

// ─── Auto-Link Engine ─────────────────────────────────────────────────────────
// Searches four sources in priority order for each marker:
//   1. Stored _eventIdx (exact, validated at creation)
//   2. recIn TC range — event whose [recIn, recOut) contains the marker's recIn
//   3. Reel name + srcIn proximity — same reel, tcIn within 5 frames of event srcIn
//   4. clipName exact match (last resort)
// After linking, _pmVerifyLink() checks the link for consistency and flags warnings.
function _pmCollectLinkWarnings(mk, r, fps) {
  const warnings = [];

  // Check 1: marker recIn falls within the event's sequence TC range
  if (mk.recIn) {
    const mkF = tcToFrames(mk.recIn, fps);
    if (mkF < r.eIn || mkF >= r.eOut) warnings.push('recIn outside clip range');
  }

  // Check 2: reel name consistency (allow prefix/suffix overlap for truncated names)
  if (mk.reel && r.ev.reel) {
    const a = mk.reel.trim().toUpperCase();
    const b = r.ev.reel.trim().toUpperCase();
    if (a !== b && !a.startsWith(b) && !b.startsWith(a)) warnings.push('reel mismatch');
  }

  // Check 3: ALE cross-reference — if ALE data exists for the event, tape should match
  if (_pmAleMap.size > 0) {
    const aleMeta = _pmAleMap.get(_pmStatusKey(r.ev));
    if (aleMeta) {
      // 3a: tape/reel name consistency
      if (mk.reel) {
        const aleTape = (aleMeta.Tape || aleMeta.tape || '').trim().toUpperCase();
        const mkReel  = mk.reel.trim().toUpperCase();
        if (aleTape && aleTape !== mkReel && !aleTape.startsWith(mkReel) && !mkReel.startsWith(aleTape)) {
          warnings.push('ALE tape mismatch');
        }
      }
      // 3b: ALE Start boundary — marker tcIn must not precede the source clip's first frame
      if (mk.tcIn) {
        const aleStart = aleMeta.Start || aleMeta.start || aleMeta['Start TC'] || '';
        if (aleStart) {
          const aleStartF = tcToFrames(aleStart, fps);
          const mkTcInF   = tcToFrames(mk.tcIn,  fps);
          if (mkTcInF < aleStartF - 1) warnings.push(`tcIn precedes ALE clip start (${aleStart})`);
        }
      }
    }
  }

  return warnings;
}

function _pmMarkerTimingFromEvent(ev, fps) {
  if (!ev) return null;
  const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
  const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
  const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
  const recIn  = ev.recIn  || framesToTC(eIn,  fps);
  const recOut = ev.recOut || framesToTC(eOut, fps);
  let tcIn, tcOut;
  if (ev.srcIn && ev.srcOut) {
    tcIn  = ev.srcIn;
    tcOut = ev.srcOut;
  } else if (ev.srcIn && ev.recIn) {
    const offsetF = tcToFrames(ev.srcIn, fps) - tcToFrames(ev.recIn, fps);
    tcIn  = framesToTC(tcToFrames(recIn,  fps) + offsetF, fps);
    tcOut = framesToTC(tcToFrames(recOut, fps) + offsetF, fps);
  } else {
    tcIn  = recIn;
    tcOut = recOut;
  }
  return {
    recIn,
    recOut,
    tcIn,
    tcOut,
    frame: tcToFrames(recIn || '00:00:00:00', fps),
    tc: recIn,
  };
}

function _pmLinkTextOverlap(a, b) {
  const aa = String(a || '').trim().toUpperCase();
  const bb = String(b || '').trim().toUpperCase();
  return !!aa && !!bb && (aa === bb || aa.startsWith(bb) || bb.startsWith(aa));
}

function _pmShouldAutoHealMarkerLink(mk, ev, warnings, fps) {
  if (!mk || !ev || !Array.isArray(warnings) || warnings.length === 0) return false;
  if (mk._timingEdited === true) return false;
  const isPrepOwned = mk._fromPrepMark === true || (Number.isInteger(mk._eventIdx) && mk._eventIdx >= 0);
  if (!isPrepOwned) return false;
  const likelySameClip =
    _pmLinkTextOverlap(mk.reel, ev.reel) ||
    _pmLinkTextOverlap(mk.clipName, ev.clipName || ev.clip) ||
    ((mk.tcIn && ev.srcIn) ? Math.abs(tcToFrames(mk.tcIn, fps) - tcToFrames(ev.srcIn, fps)) <= 3 : false);
  if (!likelySameClip) return false;
  const hasRecWarning  = warnings.includes('recIn outside clip range');
  const hasReelWarning = warnings.includes('reel mismatch') || warnings.includes('ALE tape mismatch');
  let srcMismatch = false;
  if (mk.tcIn && ev.srcIn) {
    srcMismatch = Math.abs(tcToFrames(mk.tcIn, fps) - tcToFrames(ev.srcIn, fps)) > 3;
  } else if (mk.tcIn || ev.srcIn) {
    srcMismatch = true;
  }
  const clipMismatch = !!(mk.clipName && ev.clipName && String(mk.clipName).trim() !== String(ev.clipName).trim());
  return hasReelWarning || (hasRecWarning && (srcMismatch || clipMismatch));
}

function _pmHealMarkerToEvent(mk, ev, fps) {
  if (!mk || !ev) return;
  const timing = _pmMarkerTimingFromEvent(ev, fps);
  if (!timing) return;
  mk.reel     = ev.reel || mk.reel || '';
  mk.clipName = ev.clipName || ev.clip || mk.clipName || '';
  mk.recIn    = timing.recIn;
  mk.recOut   = timing.recOut;
  mk.tcIn     = timing.tcIn;
  mk.tcOut    = timing.tcOut;
  mk.frame    = timing.frame;
  mk.tc       = timing.tc;
  delete mk._timingEdited;
}

function _pmTryLinkCandidate(mk, evIdx, source, evRanges, fps) {
  if (!Number.isInteger(evIdx) || evIdx < 0 || evIdx >= evRanges.length || !evRanges[evIdx]) return false;
  mk._linkSource = source;
  _pmLinkMap.set(mk.id, evIdx);
  _pmVerifyLink(mk, evIdx, evRanges, fps);
  if (mk._linkVerified) {
    mk._eventIdx = evIdx;
    return true;
  }
  _pmLinkMap.delete(mk.id);
  return false;
}

// Clear ev._pmShot for every event that has no linked markers (call after _pmRunAutoLink).
function _pmClearOrphanedShotNames() {
  const linked = new Set(_pmLinkMap.values());
  for (let i = 0; i < _pmEvents.length; i++) {
    const ev = _pmEvents[i];
    if (ev && ev._pmShot != null && !linked.has(i)) {
      ev._pmShot = undefined;
      _pmSaveMeta(ev);
    }
  }
}

function _pmRunAutoLink() {
  _pmLinkMap.clear();
  if (!_pmClipMarkers.length || !_pmEvents.length) return;

  const fps = _pmFps || 24;

  // Pre-compute event frame ranges once for fast lookup across all markers
  const evRanges = _pmEvents.map((ev, i) => {
    if (!ev || typeof ev !== 'object' || _pmEventActionsDisabled(ev)) return null;
    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    return { i, ev, eIn, eOut };
  });

  let reLinked = 0;
  let healed = 0;
  let unlinked = 0;

  for (const mk of _pmClipMarkers) {
    delete mk._linkHealed;
    mk._linkSource = null;
    mk._linkVerified = false;
    mk._linkWarning = null;

    // ── Source 1: validated _eventIdx (fastest path) ─────────────────────────
    if (mk._eventIdx !== undefined && mk._eventIdx >= 0 &&
        mk._eventIdx < _pmEvents.length && _pmEvents[mk._eventIdx]) {
      if (_pmTryLinkCandidate(mk, mk._eventIdx, 'index', evRanges, fps)) {
        if (mk._linkHealed) healed++;
        continue;
      }
    }

    // Marker is unlinked or has a stale index — search fallback sources
    const mkRecInF = mk.recIn ? tcToFrames(mk.recIn, fps) : -1;
    const mkTcInF  = mk.tcIn  ? tcToFrames(mk.tcIn,  fps) : -1;
    const mkReel   = (mk.reel     || '').trim().toUpperCase();
    const mkClip   = (mk.clipName || '').trim().toUpperCase();
    let accepted = false;
    let lastFailedWarning = mk._linkWarning || null;

    const _tryCandidates = (candidates, source) => {
      for (const idx of candidates) {
        if (_pmTryLinkCandidate(mk, idx, source, evRanges, fps)) return true;
        if (mk._linkWarning) lastFailedWarning = mk._linkWarning;
      }
      return false;
    };

    const recInCandidates = [];
    if (mkRecInF >= 0) {
      for (const r of evRanges) {
        if (!r) continue;
        if (mkRecInF >= r.eIn && mkRecInF < r.eOut) recInCandidates.push(r.i);
      }
    }
    // When the marker has a reel or clipName, prefer matching events first — avoids
    // linking to a no-reel event when a better-matched one exists at the same TC.
    if (recInCandidates.length > 1 && (mkReel || mkClip)) {
      recInCandidates.sort((a, b) => {
        const evA = _pmEvents[a], evB = _pmEvents[b];
        const aReel = (evA?.reel || '').trim().toUpperCase();
        const bReel = (evB?.reel || '').trim().toUpperCase();
        const aClip = (evA?.clipName || '').trim().toUpperCase();
        const bClip = (evB?.clipName || '').trim().toUpperCase();
        const aScore = (mkReel && aReel && aReel === mkReel ? 2 : 0) + (mkClip && aClip && aClip === mkClip ? 1 : 0);
        const bScore = (mkReel && bReel && bReel === mkReel ? 2 : 0) + (mkClip && bClip && bClip === mkClip ? 1 : 0);
        return bScore - aScore; // higher score first
      });
    }
    accepted = _tryCandidates(recInCandidates, 'recIn');

    if (!accepted && mkReel && mkTcInF >= 0) {
      const reelTcCandidates = evRanges
        .filter(r => r && (r.ev.reel || '').trim().toUpperCase() === mkReel)
        .map(r => ({ idx: r.i, dist: Math.abs(mkTcInF - tcToFrames(r.ev.srcIn || '00:00:00:00', fps)) }))
        .filter(x => x.dist <= 5)
        .sort((a, b) => a.dist - b.dist)
        .map(x => x.idx);
      accepted = _tryCandidates(reelTcCandidates, 'reel+tc');
    }

    if (!accepted && mkReel && _pmAleMap.size > 0) {
      const aleCandidates = [];
      for (const r of evRanges) {
        if (!r) continue;
        const aleMeta = _pmAleMap.get(_pmStatusKey(r.ev));
        if (!aleMeta) continue;
        const aleTape = (aleMeta.Tape || aleMeta.tape || '').trim().toUpperCase();
        if (aleTape && aleTape === mkReel) aleCandidates.push(r.i);
      }
      accepted = _tryCandidates(aleCandidates, 'ale');
    }

    if (!accepted && mkClip) {
      const clipNameCandidates = [];
      for (const r of evRanges) {
        if (!r) continue;
        if ((r.ev.clipName || '').trim().toUpperCase() === mkClip) clipNameCandidates.push(r.i);
      }
      accepted = _tryCandidates(clipNameCandidates, 'clipName');
    }

    if (accepted) {
      if (mk._linkHealed) healed++;
      reLinked++;
    } else {
      if (mk._eventIdx !== undefined) unlinked++;
      delete mk._eventIdx;
      mk._linkSource   = null;
      mk._linkVerified = false;
      mk._linkWarning  = lastFailedWarning || 'No matching event found';
    }
  }

  // ── Heal mismatched IN timecodes on pinned markers ───────────────────────────
  // Old bug: pinned markers got recIn = playhead but recOut = ev.recOut.
  // Signature: recOut matches event AND recIn is inside the clip but ≠ ev.recIn.
  // Only heal if the event has both recIn and srcIn so we can set both fields.
  let tcHealed = 0;
  for (const [mkId, evIdx] of _pmLinkMap) {
    const mk  = _pmClipMarkers.find(m => m.id === mkId);
    const ev  = _pmEvents[evIdx];
    if (!mk || !ev || !ev.recIn || !ev.recOut || !ev.srcIn) continue;
    const evRecInF  = tcToFrames(ev.recIn,  fps);
    const evRecOutF = tcToFrames(ev.recOut, fps);
    const mkRecInF  = mk.recIn  ? tcToFrames(mk.recIn,  fps) : -1;
    const mkRecOutF = mk.recOut ? tcToFrames(mk.recOut, fps) : -1;
    // Heal only when: recOut matches event end AND recIn differs from event start
    if (mkRecOutF === evRecOutF && mkRecInF !== evRecInF && mkRecInF >= evRecInF && mkRecInF < evRecOutF) {
      mk.recIn = ev.recIn;
      mk.tcIn  = ev.srcIn;
      if (ev.srcOut) mk.tcOut = ev.srcOut;
      mk._linkHealed = true;
      tcHealed++;
    }
  }
  if (reLinked > 0 || healed > 0 || unlinked > 0 || tcHealed > 0) _pmSaveClipMarkers();   // persist healed/cleared link state

  const linked = _pmLinkMap.size;
  if (pmCtxLinked) {
    const details = [];
    if (reLinked > 0) details.push(`${reLinked} re-linked`);
    if (healed  > 0) details.push(`${healed} repaired`);
    if (unlinked > 0) details.push(`${unlinked} unlinked`);
    pmCtxLinked.textContent = details.length
      ? `${linked} linked (${details.join(', ')})`
      : `${linked} linked`;
  }
}

// Verify a marker↔event link for consistency; sets mk._linkVerified + mk._linkWarning.
function _pmVerifyLink(mk, evIdx, evRanges, fps) {
  const r = evRanges[evIdx];
  if (!r) { mk._linkVerified = false; mk._linkWarning = 'Event not found'; return; }
  let warnings = _pmCollectLinkWarnings(mk, r, fps);
  if (_pmShouldAutoHealMarkerLink(mk, r.ev, warnings, fps)) {
    _pmHealMarkerToEvent(mk, r.ev, fps);
    mk._linkHealed = true;
    warnings = _pmCollectLinkWarnings(mk, r, fps);
  }
  mk._linkVerified = warnings.length === 0;
  mk._linkWarning  = warnings.length > 0 ? warnings.join('; ') : null;
}

// Normalize reel for display: strip extension, DISABLED tag, and FCPX " - v1" suffix.
// ─── Clip Match Engine ────────────────────────────────────────────────────────
// Matches each VFX shot marker to the timeline clip whose record range contains it.
// Stores results in _pmClipMatchMap (markerId → MatchResult).
// Unlike Auto-Link (which mutates _pmLinkMap), Clip Match is non-destructive:
// it only populates _pmClipMatchMap and triggers a re-render.
function _pmRunClipMatch() {
  if (!_pmClipMarkers.length) {
    console.log('[ClipMatch] no markers — nothing to match');
    return;
  }
  const fps   = _pmFps || 24;
  const clips = buildClipsFromEvents(_pmEvents, fps);

  if (!clips.length) {
    // Mark all as orphan with a helpful hint
    _pmClipMatchMap.clear();
    for (const mk of _pmClipMarkers) {
      _pmClipMatchMap.set(mk.id, {
        markerId: mk.id, matchStatus: 'orphan', confidence: 0,
        matchedClipId: null, matchedTrack: null, matchedClipName: null,
        matchedSourceFile: null, sourceIn: null, sourceOut: null,
        candidates: [], warning: 'No timeline clips loaded — import an EDL first',
      });
    }
    _pmRenderEventTable();
    return;
  }

  _pmClipMatchMap = matchMarkersToTimelineClips(_pmClipMarkers, clips, fps);

  const matched  = [..._pmClipMatchMap.values()].filter(r => r.matchStatus === 'matched').length;
  const multi    = [..._pmClipMatchMap.values()].filter(r => r.matchStatus === 'multi_match').length;
  const orphaned = [..._pmClipMatchMap.values()].filter(r => r.matchStatus === 'orphan').length;
  console.log(`[ClipMatch] done — ${matched} matched, ${multi} multi, ${orphaned} orphaned`);

  _pmRenderEventTable();
}

// Mirrors edl_export.js normReel() but always strips extension even when ev.reel is present.
// Falls back to srcFile → clipName stem when reel is empty.
function _pmNormReel(ev) {
  const _stem  = s => { if (!s) return ''; const i = s.lastIndexOf('.'); return i > 0 ? s.slice(0, i) : s; };
  const _clean = s => String(s || '').replace(/\s*\[DISABLED\]/ig, '').replace(/\s+-\s+v\d+$/i, '').trim();
  if (ev?.reel?.trim()) return _stem(_clean(ev.reel)) || _clean(ev.reel);
  const raw = ev?.srcFile?.trim() || ev?.clipName?.trim() || '';
  return _stem(_clean(raw)) || '—';
}

function _pmBuildEventLinkCount() {
  const evLinkCount = new Map();
  for (const [, evIdx] of _pmLinkMap) {
    evLinkCount.set(evIdx, (evLinkCount.get(evIdx) || 0) + 1);
  }
  return evLinkCount;
}

function _pmBuildRenderOrder(evLinkCount = _pmBuildEventLinkCount()) {
  if (_pmQs('flatten')) {
    return _pmEvents.map((ev, i) => ({ ev, i }))
      .filter(x => x.ev && typeof x.ev === 'object')
      .sort((a, b) => a.i - b.i);
  }
  if (_pmQs('conform')) {
    return _pmEvents.map((ev, i) => ({ ev, i }))
      .filter(x => x.ev && typeof x.ev === 'object')
      .sort((a, b) => tcToFrames(a.ev.recIn || '00:00:00:00', _pmFps) - tcToFrames(b.ev.recIn || '00:00:00:00', _pmFps));
  }
  if (_pmQs('vfxmarker')) {
    return _pmEvents.map((ev, i) => ({ ev, i }))
      .filter(x => x.ev && typeof x.ev === 'object' && evLinkCount.has(x.i));
  }
  return _pmEvents.map((ev, i) => ({ ev, i }));
}

function _pmSmartDiffNormalizeEvent(ev, fps = _pmFps) {
  if (!ev || typeof ev !== 'object') return null;
  const reel = _pmNormReel(ev);
  const clipName = String(ev.clipName || ev.clip || reel || '').trim() || reel || '—';
  const safeFps = Math.max(1, Number(ev.fps) || Number(fps) || 24);
  const srcInF = tcToFrames(ev.srcIn || '00:00:00:00', safeFps);
  const srcOutF = tcToFrames(ev.srcOut || '00:00:00:00', safeFps);
  const recInF = tcToFrames(ev.recIn || '00:00:00:00', safeFps);
  const recOutF = tcToFrames(ev.recOut || '00:00:00:00', safeFps);
  const durF = Number(ev.durationFrames || ev._lenFrames || 0)
    || (srcOutF > srcInF ? srcOutF - srcInF : 0)
    || (recOutF > recInF ? recOutF - recInF : 0)
    || 1;
  return {
    ...ev,
    reel,
    clipName,
    fps: safeFps,
    srcIn: ev.srcIn || framesToTC(srcInF, safeFps),
    srcOut: ev.srcOut || framesToTC(srcInF + durF, safeFps),
    recIn: ev.recIn || framesToTC(recInF, safeFps),
    recOut: ev.recOut || framesToTC(recInF + durF, safeFps),
    durationFrames: durF,
    _lenFrames: Number(ev._lenFrames || durF) || durF,
  };
}

function _pmSmartDiffRisk(diffEv, eventIdx) {
  const dt = String(diffEv?.diffType || 'UNCHANGED').toUpperCase();
  if (dt === 'UNCHANGED') return 'none';
  const ev = _pmEvents[eventIdx];
  const linkedMks = _pmClipMarkers.filter(mk => _pmLinkMap.get(mk.id) === eventIdx);
  const hasVfxContext =
    linkedMks.length > 0 ||
    !!(ev?._pmShot) ||
    !!(ev?._pmRetime || ev?._pmRetimeAuto || ev?._pmStabilize || ev?._pmResize || ev?._pmResizeAuto) ||
    !!_pmParseTransition(ev);
  if (dt === 'CHANGED') return hasVfxContext ? 'high' : 'med';
  if (dt === 'NEW' || dt === 'EXTENDED') return hasVfxContext ? 'high' : 'med';
  if (dt === 'TRIMMED') return hasVfxContext ? 'med' : 'low';
  return 'low';
}

function _pmUpdateSmartDiffUi() {
  const ready = !!(_pmSmartDiffBase?.events?.length);
  const summary = _pmSmartDiffSummary?.summary || { NEW: 0, EXTENDED: 0, CHANGED: 0, TRIMMED: 0 };
  const review = Number(_pmSmartDiffSummary?.review || 0);

  if (pmDiffBaseBtn) {
    pmDiffBaseBtn.textContent = ready ? 'BASE CUT ✓' : 'BASE CUT ▲';
    pmDiffBaseBtn.title = ready
      ? `Loaded baseline cut: ${_pmSmartDiffBase?.name || 'Unnamed'}`
      : 'Load a baseline cut to compare against the current Pulls Prep timeline';
  }
  if (pmDiffAnalyzeBtn) {
    pmDiffAnalyzeBtn.textContent = ready ? 'REFRESH DIFF ⚡' : 'SMART DIFF ⚡';
    pmDiffAnalyzeBtn.disabled = !_pmEvents.length;
  }
  if (pmDiffSummary) pmDiffSummary.style.display = ready ? 'inline-flex' : 'none';
  if (pmDiffBaseLabel) pmDiffBaseLabel.textContent = ready ? `BASE ${_pmSmartDiffBase?.name || '—'}` : 'BASE —';
  if (pmDiffChipNew)  pmDiffChipNew.textContent  = `${Number(summary.NEW || 0)} NEW`;
  if (pmDiffChipExt)  pmDiffChipExt.textContent  = `${Number(summary.EXTENDED || 0)} EXT`;
  if (pmDiffChipChg)  pmDiffChipChg.textContent  = `${Number(summary.CHANGED || 0)} CHG`;
  if (pmDiffChipTrim) pmDiffChipTrim.textContent = `${Number(summary.TRIMMED || 0)} TRIM`;
  if (pmDiffChipRisk) pmDiffChipRisk.textContent = `${review} REVIEW`;
  if (pmDiffOnlyBtn) {
    pmDiffOnlyBtn.classList.toggle('is-active', !!_pmSmartDiffOnly);
    pmDiffOnlyBtn.setAttribute('aria-pressed', _pmSmartDiffOnly ? 'true' : 'false');
  }
  if (pmDiffOpenBtn) pmDiffOpenBtn.disabled = !ready;
}

function _pmResetSmartDiff({ keepBase = false } = {}) {
  if (!keepBase) {
    _pmSmartDiffBase = null;
    _pmSmartDiffProjectKey = '';
    try { _pmSmartDiffSave(); } catch {}  // clears persisted base too
  }
  _pmSmartDiffByEventIdx.clear();
  _pmSmartDiffSummary = null;
  _pmSmartDiffOnly = false;
  _pmUpdateSmartDiffUi();
}

async function _pmParseSmartDiffFiles(files) {
  const list = Array.from(files || []).filter(Boolean);
  for (const file of list) {
    const nameLower = String(file.name || '').toLowerCase();
    if (!nameLower) continue;

    if (nameLower.endsWith('.fcpxml')) {
      const txt = await file.text();
      const mod = await import('./parsers/fcpxml.js');
      const parse = mod.parseFCPXML || mod.default?.parseFCPXML;
      const parsed = parse ? parse(txt) : null;
      if (parsed?.events?.length) return parsed;
      continue;
    }

    if (nameLower.endsWith('.xml')) {
      const txt = await file.text();
      if (/<\s*fcpxml\b/i.test(txt)) {
        const mod = await import('./parsers/fcpxml.js');
        const parse = mod.parseFCPXML || mod.default?.parseFCPXML;
        const parsed = parse ? parse(txt) : null;
        if (parsed?.events?.length) return parsed;
      } else {
        const mod = await import('./parsers/xml.js');
        const parsed = mod.parseXMEML ? mod.parseXMEML(txt) : mod.default?.parseXMEML?.(txt);
        if (parsed?.events?.length) return parsed;
      }
      continue;
    }

    if (nameLower.endsWith('.otio') || nameLower.endsWith('.json')) {
      const txt = await file.text();
      const mod = await import('./parsers/otio.js');
      const parse = mod.parseOTIO || mod.default?.parseOTIO;
      const parsed = parse ? parse(txt) : null;
      if (parsed?.events?.length) return parsed;
      continue;
    }

    if (nameLower.endsWith('.edl')) {
      const txt = await file.text();
      const mod = await import('./parsers/edl.js');
      const parse = mod.parseEDL || mod.default?.parseEDL;
      const parsed = parse ? parse(txt, file.name) : null;
      if (parsed?.events?.length) return parsed;
    }
  }
  throw new Error('No valid timeline events found in the selected base cut.');
}

function _pmAnalyzeSmartDiff() {
  if (!_pmSmartDiffBase?.events?.length) {
    _pmResetSmartDiff({ keepBase: false });
    return false;
  }

  const evLinkCount = _pmBuildEventLinkCount();
  const renderOrder = _pmBuildRenderOrder(evLinkCount);
  const newItems = renderOrder.filter(x => x?.ev && typeof x.ev === 'object');
  const oldEvents = (_pmSmartDiffBase.events || [])
    .map(ev => _pmSmartDiffNormalizeEvent(ev, _pmSmartDiffBase.fps || _pmFps))
    .filter(Boolean);
  const newEvents = newItems
    .map(x => _pmSmartDiffNormalizeEvent(x.ev, _pmFps))
    .filter(Boolean);

  const diff = computeCutDiff(oldEvents, newEvents, { includeTrimmed: true, includeUnchanged: true });
  const byIdx = new Map();
  let review = 0;

  diff.forEach((item, pos) => {
    const idx = newItems[pos]?.i;
    if (!Number.isInteger(idx)) return;
    const risk = _pmSmartDiffRisk(item, idx);
    if (risk === 'high' || risk === 'med') review++;
    byIdx.set(idx, { ...item, _pmRisk: risk });
  });

  _pmSmartDiffByEventIdx = byIdx;
  window.__PFX_LAST_CUTDIFF = diff;
  try { window.__pfxApplyCutDiff?.(diff); } catch {}
  _pmSmartDiffSummary = {
    summary: summarizeDiff(diff),
    review,
    total: newItems.length,
  };
  _pmSmartDiffProjectKey = _pmCurrentProjectKey || 'default';
  _pmUpdateSmartDiffUi();
  return true;
}

function _pmOpenSmartDiffInCutDiff() {
  if (!_pmSmartDiffBase?.events?.length) return;
  const evLinkCount = _pmBuildEventLinkCount();
  const renderOrder = _pmBuildRenderOrder(evLinkCount);
  const newItems = renderOrder.filter(x => x?.ev && typeof x.ev === 'object');
  const oldEvents = (_pmSmartDiffBase.events || [])
    .map(ev => _pmSmartDiffNormalizeEvent(ev, _pmSmartDiffBase.fps || _pmFps))
    .filter(Boolean);
  const newEvents = newItems
    .map(x => _pmSmartDiffNormalizeEvent(x.ev, _pmFps))
    .filter(Boolean);
  const diff = computeCutDiff(oldEvents, newEvents, { includeTrimmed: true, includeUnchanged: true })
    .map((item, pos) => ({ ...item, _pmRisk: _pmSmartDiffRisk(item, newItems[pos]?.i) }));

  try {
    window.MPS_applyCutDiffSnapshot?.({
      v: 2,
      oldName: _pmSmartDiffBase.name || 'Base Cut',
      newName: window.__MPS_EDL_RAW?.projectName || pmCtxProject?.textContent || 'Pulls Prep',
      fps: _pmFps || _pmSmartDiffBase.fps || 24,
      analyzed: true,
      oldEvents,
      newEvents,
      diff,
      filterType: 'ALL',
      filterRisk: 'all',
      status: {},
      notes: {},
      vcOldName: '',
      vcNewName: '',
    });
  } catch (err) {
    console.warn('[PM] unable to hand off Smart Diff to Cut Diff 2.0', err);
  }
  document.querySelector('.tabs .tab[data-main="cutdiff2"]')?.click();
}

function _wireSmartDiff() {
  _pmUpdateSmartDiffUi();

  pmDiffBaseBtn?.addEventListener('click', () => pmDiffBaseFileInput?.click());

  pmDiffBaseFileInput?.addEventListener('change', async () => {
    const files = Array.from(pmDiffBaseFileInput.files || []);
    pmDiffBaseFileInput.value = '';
    if (!files.length) return;
    try {
      const parsed = await _pmParseSmartDiffFiles(files);
      const fallbackName = String(files[0]?.name || 'Base Cut').replace(/\.[^.]+$/, '');
      _pmSmartDiffBase = {
        name: parsed.projectName || fallbackName,
        fps: parsed.fps || _pmFps || 24,
        events: Array.isArray(parsed.events) ? parsed.events.filter(ev => ev && typeof ev === 'object') : [],
      };
      _pmAnalyzeSmartDiff();
      _pmRenderEventTable();
      _pmSmartDiffSave();
      _pmShowAleToast(`Smart Diff ready · ${_pmSmartDiffBase.name}`);
    } catch (err) {
      console.warn('[PM] Smart Diff base load failed', err);
      _pmShowAleToast(`Smart Diff failed · ${err?.message || 'Unknown error'}`);
      _pmResetSmartDiff({ keepBase: false });
      _pmRenderEventTable();
    }
  });

  pmDiffAnalyzeBtn?.addEventListener('click', () => {
    if (!_pmSmartDiffBase?.events?.length) {
      pmDiffBaseFileInput?.click();
      return;
    }
    _pmAnalyzeSmartDiff();
    _pmRenderEventTable();
    _pmShowAleToast(`Smart Diff refreshed · ${_pmSmartDiffSummary?.total || 0} visible clips`);
  });

  pmDiffOnlyBtn?.addEventListener('click', () => {
    if (!_pmSmartDiffBase?.events?.length) return;
    _pmSmartDiffOnly = !_pmSmartDiffOnly;
    _pmUpdateSmartDiffUi();
    _pmRenderEventTable();
  });

  pmDiffClearBtn?.addEventListener('click', () => {
    _pmResetSmartDiff({ keepBase: false });
    _pmRenderEventTable();
  });

  pmDiffOpenBtn?.addEventListener('click', () => {
    if (!_pmSmartDiffBase?.events?.length) return;
    _pmOpenSmartDiffInCutDiff();
  });
}

// ─── Event Table ──────────────────────────────────────────────────────────────
function _pmGetActivePullRowIndex() {
  if (Number.isFinite(_pmActiveEventIdx) && _pmActiveEventIdx >= 0) return _pmActiveEventIdx;
  const inspIdx = parseInt(pmInspector?.querySelector('.pm-insp-layers')?.dataset.evidx ?? '-1', 10);
  if (Number.isFinite(inspIdx) && inspIdx >= 0) return inspIdx;
  const rowIdx = parseInt(pmEventBody?.querySelector('tr.pm-row-active')?.dataset.i ?? '-1', 10);
  return Number.isFinite(rowIdx) && rowIdx >= 0 ? rowIdx : -1;
}

function _pmResolveActivePullTarget(preferredMarkerIds = []) {
  const passedIds = Array.isArray(preferredMarkerIds)
    ? preferredMarkerIds.filter(Boolean)
    : (preferredMarkerIds ? [preferredMarkerIds] : []);
  const inspectorSel = pmInspector?.querySelector('.pm-insp-layers')?.dataset.selected || null;
  const markerId = _pmSelectedMarkerId || inspectorSel || passedIds[0] || null;
  const marker = markerId
    ? (_pmClipMarkers.find(m => String(m.id) === String(markerId)) || null)
    : null;
  const markerEi = marker
    ? (_pmLinkMap.get(marker.id) ?? _pmLinkMap.get(Number(marker.id)) ?? marker._eventIdx ?? -1)
    : -1;
  const eventIndex = markerEi >= 0 ? markerEi : _pmGetActivePullRowIndex();
  const linkedMarkers = eventIndex >= 0 ? _pmGetLinkedMarkersForEvent(eventIndex) : [];
  return {
    eventIndex: eventIndex >= 0 ? eventIndex : null,
    rowIndex: eventIndex >= 0 ? eventIndex : null,
    markerId: marker?.id || passedIds[0] || null,
    markerIds: linkedMarkers.length ? linkedMarkers.map(m => m.id) : passedIds,
  };
}

function _pmGetAllLinkedMarkersForEvent(evIdx) {
  if (!(evIdx >= 0)) return [];
  const seen = new Set();
  return _pmClipMarkers.filter(mk => {
    const linkedEi = _pmLinkMap.get(mk.id)
      ?? _pmLinkMap.get(Number(mk.id))
      ?? mk._eventIdx
      ?? -1;
    if (linkedEi !== evIdx) return false;
    const key = String(mk.id ?? '');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function _pmResolveMarkerById(markerId) {
  if (markerId == null) return null;
  const key = String(markerId);
  return _pmClipMarkers.find(m => String(m.id) === key)
    || (_pmMarkers || []).find(m => String(m?.id) === key)
    || (() => {
      try {
        const smMarkers = window.__smGetMarkersRef?.();
        return Array.isArray(smMarkers) ? smMarkers.find(m => String(m?.id) === key) || null : null;
      } catch {
        return null;
      }
    })();
}

function _pmIsShotNameLocked(markerOrId) {
  const mk = (markerOrId && typeof markerOrId === 'object')
    ? markerOrId
    : _pmResolveMarkerById(markerOrId);
  return !!mk?._pmShotLocked;
}

function _pmGetLockedLinkedMarkersForEvent(evIdx) {
  return _pmGetAllLinkedMarkersForEvent(evIdx).filter(mk => !!mk?._pmShotLocked);
}

function _pmNotifyShotNameLocked(lockedMarkers, { source = 'manual' } = {}) {
  const list = (Array.isArray(lockedMarkers) ? lockedMarkers : [lockedMarkers]).filter(Boolean);
  if (!list.length) return;
  const action = source === 'ocr'
    ? 'apply OCR text'
    : source === 'template'
      ? 'apply the naming template'
      : 'change the shot name';
  const msg = list.length === 1
    ? `Shot name is locked. Unlock it to ${action}.`
    : `${list.length} linked shot names are locked. Unlock them to rename.`;
  _pmToast(msg, 'info', 2200);
}

function _pmSetShotNameLocked(markerId, locked) {
  const key = String(markerId || '').trim();
  if (!key) return false;

  const stores = [];
  if (Array.isArray(_pmClipMarkers)) stores.push(_pmClipMarkers);
  if (Array.isArray(_pmMarkers)) stores.push(_pmMarkers);
  try {
    const smMarkers = window.__smGetMarkersRef?.();
    if (Array.isArray(smMarkers)) stores.push(smMarkers);
  } catch {}

  let changed = false;
  const touchedRefs = new WeakSet();
  for (const store of stores) {
    for (const mk of store) {
      if (!mk || String(mk.id) !== key || touchedRefs.has(mk)) continue;
      touchedRefs.add(mk);
      const nextLocked = !!locked;
      if (!!mk._pmShotLocked !== nextLocked) changed = true;
      if (nextLocked) {
        mk._pmShotLocked = true;
        mk._pmNameMode = 'shot';
      } else {
        delete mk._pmShotLocked;
      }
    }
  }

  if (!changed) return false;
  _pmSaveClipMarkers();
  window.MPS_markProjectDirty?.();
  const ei = _pmLinkMap.get(markerId) ?? _pmLinkMap.get(Number(markerId)) ?? _pmResolveMarkerById(markerId)?._eventIdx ?? -1;
  _pmRenderEventTable();
  if (ei >= 0) _pmRenderInspector(ei);
  _pmPushTimelineData();
  _pmScheduleDraw();
  _pmUpdateInfoRail();
  _pmToast(locked ? 'Shot name locked' : 'Shot name unlocked', 'info', 1600);
  return true;
}

function _pmSyncShotNameAcrossMarkerStores(markerIds, text, ocrMeta = null, source = 'manual') {
  const ids = [...new Set((Array.isArray(markerIds) ? markerIds : [markerIds]).filter(id => id != null).map(id => String(id)))];
  if (!ids.length) return [];
  const stores = [];
  if (Array.isArray(_pmClipMarkers)) stores.push(_pmClipMarkers);
  if (Array.isArray(_pmMarkers)) stores.push(_pmMarkers);
  try {
    const smMarkers = window.__smGetMarkersRef?.();
    if (Array.isArray(smMarkers)) stores.push(smMarkers);
  } catch {}

  const touchedIds = new Set();
  const touchedRefs = new WeakSet();
  const renamedAt = Date.now();
  for (const store of stores) {
    for (const mk of store) {
      if (!mk || !ids.includes(String(mk.id))) continue;
      if (touchedRefs.has(mk)) continue;
      touchedRefs.add(mk);
      const oldName = mk.shotName || mk.name || mk.label || '';
      mk.shotName = text;
      if (Object.prototype.hasOwnProperty.call(mk, 'name')) mk.name = text;
      if (Object.prototype.hasOwnProperty.call(mk, 'label')) mk.label = text;
      if (Object.prototype.hasOwnProperty.call(mk, 'title')) mk.title = text;
      if (Object.prototype.hasOwnProperty.call(mk, 'displayName')) mk.displayName = text;
      if (source === 'ocr') {
        mk._ocrHistory = mk._ocrHistory || [];
        mk._ocrHistory.push({
          previousShotName: oldName,
          ocrAppliedText: text,
          newShotName: text,
          renamedBy: 'ocr',
          renamedAt,
          ocrRawText: ocrMeta?.rawText || '',
          ocrConfidence: ocrMeta?.confidence ?? null,
          ocrRegion: ocrMeta?.region || '',
          ocrDetectionMode: ocrMeta?.detectionMode || 'vfxShotName',
          ocrMatchedPattern: !!ocrMeta?.isVfxMatch,
        });
      }
      touchedIds.add(String(mk.id));
    }
  }
  return [...touchedIds];
}

function _pmCommitShotNameChange({
  name,
  eventIndices = [],
  markerIds = [],
  source = 'manual',
  ocrMeta = null,
  expandEventMarkers = true,
  markerNameMode = null,
  notifyLocked = false,
} = {}) {
  const text = String(name || '').trim();
  if (!text) return { ok: false, reason: 'empty', applied: [], touchedEi: [] };

  // ── Unified undo snapshot ─────────────────────────────────────────────────
  _pmSlySnapshot(`Shot: ${String(name || '').trim().slice(0, 24)}`);

  const touchedEi = new Set();
  const allMarkerIds = new Set();
  const lockedMarkers = [];
  const lockedMarkerIds = new Set();

  const rememberLocked = (mk) => {
    if (!mk?.id) return;
    const key = String(mk.id);
    if (lockedMarkerIds.has(key)) return;
    lockedMarkerIds.add(key);
    lockedMarkers.push(mk);
  };

  for (const rawEi of eventIndices) {
    const ei = Number(rawEi);
    if (!Number.isFinite(ei) || ei < 0 || !_pmEvents[ei]) continue;
    if (expandEventMarkers) {
      const linkedMarkers = _pmGetAllLinkedMarkersForEvent(ei);
      const lockedLinked = linkedMarkers.filter(mk => !!mk?._pmShotLocked);
      if (lockedLinked.length) {
        lockedLinked.forEach(rememberLocked);
        continue;
      }
      touchedEi.add(ei);
      for (const mk of linkedMarkers) {
        if (mk?.id != null) allMarkerIds.add(mk.id);
      }
    }
  }

  for (const markerId of markerIds) {
    const mk = _pmResolveMarkerById(markerId);
    if (_pmIsShotNameLocked(mk)) {
      rememberLocked(mk);
      continue;
    }
    if (markerId != null) allMarkerIds.add(markerId);
  }

  if (!allMarkerIds.size && !touchedEi.size) {
    if (notifyLocked && lockedMarkers.length) _pmNotifyShotNameLocked(lockedMarkers, { source });
    return { ok: false, reason: lockedMarkers.length ? 'locked' : 'noop', applied: [], touchedEi: [], lockedMarkerIds: [...lockedMarkerIds] };
  }

  // Snapshot markers before writing
  for (const mkId of allMarkerIds) {
    const mk = _pmResolveMarkerById(mkId);
  }

  const applied = [];
  const syncedMarkerIds = _pmSyncShotNameAcrossMarkerStores([...allMarkerIds], text, ocrMeta, source);
  for (const markerId of syncedMarkerIds) {
    const mk = _pmClipMarkers.find(m => String(m.id) === String(markerId))
      || (_pmMarkers || []).find(m => String(m?.id) === String(markerId))
      || null;
    if (!mk) continue;
    if (markerNameMode === 'shot' || markerNameMode === 'plate') {
      mk._pmNameMode = markerNameMode;
    }
    const ei = _pmLinkMap.get(mk.id) ?? _pmLinkMap.get(Number(mk.id)) ?? mk._eventIdx ?? -1;
    if (ei >= 0 && _pmEvents[ei]) touchedEi.add(ei);
    applied.push(mk.id);
  }

  for (const ei of touchedEi) {
    if (!_pmEvents[ei]) continue;
    _pmEvents[ei]._pmShot = text;
    _pmEvents[ei].shotName = text;
  }

  for (const ei of touchedEi) {
    _pmSaveMeta(_pmEvents[ei]);
  }
  if (applied.length) _pmSaveClipMarkers();

  // ── Targeted DOM sync — only the rows that were actually changed ──────────
  // Do NOT use querySelectorAll('.pm-shot-input') here — that would overwrite
  // every blank shot input on the page with the renamed value.
  for (const ei of touchedEi) {
    const row = pmEventBody?.querySelector(`tr[data-i="${ei}"] .pm-shot-input`);
    if (row && document.activeElement !== row) row.value = text;
  }
  if (pmInspector) {
    for (const mkId of applied) {
      const inp = pmInspector.querySelector(`.pm-layer-shot[data-mkid="${CSS.escape(String(mkId))}"]`);
      if (inp && document.activeElement !== inp) inp.value = text;
    }
  }

  window.MPS_markProjectDirty?.();
  _pmRenderEventTable();

  const renderEi = touchedEi.size
    ? [...touchedEi][0]
    : _pmGetActivePullRowIndex();
  if (renderEi >= 0) {
    if (__pmRenderingInspector) {
      // Called from inside a render (e.g. naming template auto-apply during _pmRenderInspector).
      // Defer so the current render finishes first — prevents the infinite loop while
      // still ensuring the inspector reflects the committed name after the render.
      const _deferEi = renderEi;
      setTimeout(() => { _pmRenderInspector(_deferEi); }, 0);
    } else {
      _pmRenderInspector(renderEi);
    }
  }
  _pmPushTimelineData();
  _pmScheduleDraw();
  _pmUpdateInfoRail();

  if (applied.length && window.PFX_SWI?.renameByMarkerIds) {
    const renameMeta = source === 'ocr'
      ? {
          source,
          rawText: ocrMeta?.rawText || '',
          confidence: ocrMeta?.confidence ?? null,
          region: ocrMeta?.region || '',
          detectionMode: ocrMeta?.detectionMode || 'vfxShotName',
        }
      : { source };
    window.PFX_SWI.renameByMarkerIds(applied, text, renameMeta).catch(err => {
      console.warn('[PM] SWI shot rename sync failed', err);
    });
  }

  if (notifyLocked && lockedMarkers.length) _pmNotifyShotNameLocked(lockedMarkers, { source });

  return { ok: true, text, applied, touchedEi: [...touchedEi], renderEi, lockedMarkerIds: [...lockedMarkerIds] };
}

// Undo the most recent shot name rename committed via _pmCommitShotNameChange.
function _pmUndoLastShotRename() {
  const entry = _pmShotNameUndoStack.pop();
  if (!entry) { _pmToast('Nothing to undo', 'info'); return; }

  for (const snap of entry.snapshots) {
    if (snap.type === 'event') {
      if (_pmEvents[snap.ei]) {
        _pmEvents[snap.ei]._pmShot = snap.prev;
        _pmEvents[snap.ei].shotName = snap.prev;
        _pmSaveMeta(_pmEvents[snap.ei]);
        const row = pmEventBody?.querySelector(`tr[data-i="${snap.ei}"] .pm-shot-input`);
        if (row && document.activeElement !== row) row.value = snap.prev ?? '';
      }
    } else if (snap.type === 'marker') {
      const mk = _pmClipMarkers.find(m => String(m.id) === String(snap.id))
        || (_pmMarkers || []).find(m => String(m?.id) === String(snap.id));
      if (mk) {
        mk.shotName = snap.prev;
        const inp = pmInspector?.querySelector(`.pm-layer-shot[data-mkid="${CSS.escape(String(snap.id))}"]`);
        if (inp && document.activeElement !== inp) inp.value = snap.prev ?? '';
      }
    }
  }

  _pmSaveClipMarkers();
  window.MPS_markProjectDirty?.();
  _pmRenderEventTable();
  const firstEiSnap = entry.snapshots.find(s => s.type === 'event');
  if (firstEiSnap && firstEiSnap.ei >= 0) _pmRenderInspector(firstEiSnap.ei);
  _pmToast('Shot name rename undone', 'info', 2000);
}

function _pmSaveShotInput(inp) {
  if (inp?.readOnly) return;
  const i = parseInt(inp.dataset.i, 10);
  if (!Number.isFinite(i)) return;
  if (_pmEventActionsDisabled(_pmEvents[i])) return;
  const lockedMarkers = _pmGetLockedLinkedMarkersForEvent(i);
  if (lockedMarkers.length) {
    _pmNotifyShotNameLocked(lockedMarkers, { source: 'manual' });
    const ev = _pmEvents[i];
    const linkedShot = _pmGetAllLinkedMarkersForEvent(i)[0]?.shotName || '';
    inp.value = String(linkedShot || ev?._pmShot || ev?.shotName || ev?.clipName || ev?.reel || '').trim();
    return;
  }
  _pmCommitShotNameChange({
    name: inp.value,
    eventIndices: [i],
    source: 'manual',
    markerNameMode: 'shot',
    notifyLocked: true,
  });
}

function _pmRenderEventTable() {
  if (!pmEventBody) return;

  if (!_pmEvents.length) {
    pmEventBody.innerHTML = '';
    if (pmEventEmpty) {
      pmEventEmpty.style.display = 'flex';
      const t = pmEventEmpty.querySelector('.pm-drop-hint-title');
      const s = pmEventEmpty.querySelector('.pm-drop-hint-sub');
      if (t) t.textContent = 'Drop EDL / FCPXML / OTIO / ALE';
      if (s) s.textContent = 'or use the Import button above';
    }
    if (pmCovStats) pmCovStats.textContent = '';
    const _strip0 = pmTlWrap?.parentElement;
    if (_strip0) _strip0.style.display = _pmQs('vfxmarker') ? 'none' : '';
    return;
  }
  if (pmEventEmpty) pmEventEmpty.style.display = 'none';

  // Build inverted link map: eventIndex → marker count
  const evLinkCount = _pmBuildEventLinkCount();

  // Unique camera list for color assignment — Map for O(1) lookup per row
  const camColorMap = new Map(
    [...new Set(_pmEvents.map(ev => ev.camera || ev.reel || ''))].map((key, idx) => [key, _CAM_COLORS[idx % _CAM_COLORS.length] || '#555'])
  );
  const camColor = (ev) => camColorMap.get(ev.camera || ev.reel || '') || '#555';

  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  // When Flatten is ON: render pull list sorted by event number (data-i stays = original index)
  // When Conform is ON: sort by rec timecode (recIn ascending) so timeline order is preserved
  // When VFX Marker is ON: show only clips that have at least one linked marker
  const renderOrder = _pmBuildRenderOrder(evLinkCount);

  // VFX Marker mode with no linked clips yet → show empty state (clips are added via timeline)
  const vfxEmpty = _pmQs('vfxmarker') && renderOrder.length === 0;
  if (vfxEmpty && pmEventEmpty) {
    pmEventBody.innerHTML = '';
    const t = pmEventEmpty.querySelector('.pm-drop-hint-title');
    const s = pmEventEmpty.querySelector('.pm-drop-hint-sub');
    if (t) t.textContent = 'No VFX markers linked';
    if (s) s.textContent = 'Click events on the timeline to add markers';
    pmEventEmpty.style.display = 'flex';
    if (pmCovStats) pmCovStats.textContent = '0 of ' + _pmEvents.length + ' clips marked';
    return;
  }
  if (pmEventEmpty) pmEventEmpty.style.display = 'none';

  const renderRows = (_pmSmartDiffOnly && _pmSmartDiffBase?.events?.length)
    ? renderOrder.filter(({ i }) => {
        const diffItem = _pmSmartDiffByEventIdx.get(i);
        return diffItem && String(diffItem.diffType || '') !== 'UNCHANGED';
      })
    : renderOrder;

  if (_pmSmartDiffOnly && _pmSmartDiffBase?.events?.length && renderRows.length === 0) {
    pmEventBody.innerHTML = '';
    const t = pmEventEmpty?.querySelector('.pm-drop-hint-title');
    const s = pmEventEmpty?.querySelector('.pm-drop-hint-sub');
    if (t) t.textContent = 'No changed clips in the current view';
    if (s) s.textContent = 'Turn off Diff Only or load another base cut';
    if (pmEventEmpty) pmEventEmpty.style.display = 'flex';
    return;
  }

  // Pre-build inverted markers Map: eventIndex → marker[] (avoids O(n×m) per-row filter)
  const linkedMksByEvent = new Map();
  for (const mk of _pmClipMarkers) {
    const evIdx = _pmLinkMap.get(mk.id);
    if (evIdx == null) continue;
    if (!linkedMksByEvent.has(evIdx)) linkedMksByEvent.set(evIdx, []);
    linkedMksByEvent.get(evIdx).push(mk);
  }

  const rows = renderRows.map(({ ev, i }) => {
    if (!ev || typeof ev !== 'object') return '';
    if (_pmGetUnscriptedNoActionKind(ev)) return '';
    const statusKey = _pmStatusKey(ev);
    const status    = _pmStatusMap.get(statusKey) || 'none';
    const linkCount = evLinkCount.get(i) || 0;
    const dur       = ev.durationFrames || (
      tcToFrames(ev.recOut || '00:00:00:00', _pmFps) - tcToFrames(ev.recIn || '00:00:00:00', _pmFps)
    );
    const isActive  = i === _pmActiveEventIdx;
    const shotVal   = esc(ev._pmShot || '');
    const color     = camColor(ev);
    const aleMeta   = _pmAleMap.get(statusKey);
    const reelNorm  = _pmNormReel(ev);
    const reelDisp  = aleMeta?.Tape || reelNorm;
    const reelFixed = !!(aleMeta?.Tape && aleMeta.Tape !== (ev.reel || ''));
    const aleComment = aleMeta?.Comments || aleMeta?.comments || '';
    const diffData = _pmSmartDiffByEventIdx.get(i) || null;
    const diffType = String(diffData?.diffType || '');
    const diffRisk = String(diffData?._pmRisk || 'none');
    const diffChanged = !!diffType && diffType !== 'UNCHANGED';

    const linkedMks = linkedMksByEvent.get(i) || [];
    const isSel = linkedMks.some(mk => mk.id === _pmSelectedMarkerId);
    const shotColor = linkedMks.length ? _pmMarkerHex(linkedMks[0].color || 'Green') : '';
    const shotLocked = linkedMks.some(mk => !!mk?._pmShotLocked);

    // displayShot depends on active mode
    let displayShot;
    if (_pmQs('vfxrename')) {
      // VFX Rename: clip name is the default VFX shot name; explicit _pmShot overrides
      displayShot = shotVal || esc(ev.clipName || ev.reel || '');
    } else if (_pmQs('vfxmarker')) {
      // VFX Marker: marker shot name is authoritative; fall back to explicit _pmShot
      displayShot = (linkedMks[0]?.shotName ? esc(linkedMks[0].shotName) : shotVal);
    } else {
      // Only show ev._pmShot when the event has linked markers; hide orphaned names
      displayShot = linkedMks.length
        ? (shotVal || (linkedMks[0]?.shotName ? esc(linkedMks[0].shotName) : ''))
        : '';
    }

    // Layer-count pill: green filled when marked, amber outline when unlinked long clip
    // In VFX Marker mode also show verification status badge (✓ / ⚠) next to the pill.
    let linkHtml = '';
    if (linkCount > 0) {
      const mk0     = linkedMks[0];
      const vfyIcon = _pmQs('vfxmarker')
        ? mk0?._linkVerified === true
          ? `<span class="pm-vfy-ok"  title="Link verified — all sources match">✓</span>`
          : mk0?._linkVerified === false
            ? `<span class="pm-vfy-warn" title="${esc(mk0._linkWarning || 'Link unverified')}">⚠</span>`
            : ''
        : '';
      linkHtml = `<span class="pm-link-pill pm-link-pill-ok" title="${linkCount} VFX layer${linkCount>1?'s':''} — click row to open">L${linkCount}</span>${vfyIcon}`;
    } else if (dur > 30)
      linkHtml = `<span class="pm-link-pill pm-link-pill-warn" title="No VFX layers yet">?</span>`;

    // VFX flag chips — aggregate across all linked markers
    const vfxRetime    = linkedMks.some(mk => mk.retime);
    const vfxStabilize = linkedMks.some(mk => mk.stabilize);
    const vfxResize    = linkedMks.some(mk => mk.resize);
    const vfxHtml = (vfxRetime || vfxStabilize || vfxResize)
      ? `<span class="pm-row-vfx-flags">`
        + (vfxRetime    ? `<span class="pm-rvf pm-rvf-rt"  title="Retime">RT</span>`    : '')
        + (vfxStabilize ? `<span class="pm-rvf pm-rvf-st"  title="Stabilize">ST</span>` : '')
        + (vfxResize    ? `<span class="pm-rvf pm-rvf-rs"  title="Resize">RS</span>`    : '')
        + `</span>`
      : '';

    // Clip Match badge — shown in VFX Marker mode when _pmRunClipMatch() has run
    let clipMatchBadge = '';
    if (_pmQs('vfxmarker') && _pmClipMatchMap.size > 0 && linkedMks.length > 0) {
      const cmResults = linkedMks.map(mk => _pmClipMatchMap.get(mk.id)).filter(Boolean);
      if (cmResults.length) {
        const hasOrphan   = cmResults.some(r => r.matchStatus === 'orphan');
        const hasConflict = cmResults.some(r => r.matchStatus === 'conflict');
        const hasMulti    = cmResults.some(r => r.matchStatus === 'multi_match');
        const allMatched  = cmResults.every(r => r.matchStatus === 'matched');
        if (allMatched) {
          const r0  = cmResults[0];
          const tip = esc(`Clip matched — ${r0.matchedClipName || '—'} · ${r0.matchedTrack || 'V1'}\nSrc In: ${r0.sourceIn || '—'}`);
          clipMatchBadge = `<span class="pm-cm-badge pm-cm-linked" title="${tip}">LINKED</span>`;
        } else if (hasOrphan) {
          const r0  = cmResults.find(r => r.matchStatus === 'orphan');
          clipMatchBadge = `<span class="pm-cm-badge pm-cm-orphan" title="${esc(r0?.warning || 'No matching clip')}">ORPHAN</span>`;
        } else if (hasConflict) {
          clipMatchBadge = `<span class="pm-cm-badge pm-cm-conflict" title="Conflict — clip already claimed by another marker">CONFLICT</span>`;
        } else if (hasMulti) {
          const r0  = cmResults.find(r => r.matchStatus === 'multi_match');
          clipMatchBadge = `<span class="pm-cm-badge pm-cm-multi" title="${esc(r0?.warning || 'Multiple clips matched')}">MULTI</span>`;
        }
      }
    }

    // Action buttons: + always, ✕ only when layers exist
    const rmBtn = linkCount > 0
      ? `<button class="pm-mk-rm-btn" data-i="${i}" title="Remove all VFX layers for this event">✕</button>`
      : '';

    // hasName drives pm-row-named → controls visibility in VFX Rename filter
    const hasName = _pmQs('vfxrename')
      ? !!(ev._pmShot || ev.clipName || ev.reel)           // clip name counts as a name in rename mode
      : _pmQs('vfxmarker')
        ? !!(linkedMks[0]?.shotName)                       // marker mode: named if marker has shot
        : !!(ev._pmShot || linkedMks[0]?.shotName);        // default: explicit shot only
    const isSkipped      = _pmEventActionsDisabled(ev);
    const isDisabledClip = !!(ev.disabled);  // clip disabled/muted in original timeline
    const rowClass = [
      'pm-row',
      isActive        ? 'pm-row-active'        : '',
      isSel           ? 'pm-row-selected'      : '',
      linkCount       ? 'pm-row-has-mk'        : '',
      hasName         ? 'pm-row-named'         : '',
      isSkipped       ? 'pm-row-skipped'       : '',
      isDisabledClip  ? 'pm-row-disabled-clip' : '',
      diffChanged ? `pm-row-diff pm-row-diff-${diffType.toLowerCase()}` : '',
      diffRisk !== 'none' ? `pm-row-diff-risk-${diffRisk}` : '',
    ].filter(Boolean).join(' ');

    // Show SKIP badge for conform/unscripted skips; DIS badge for parser-disabled clips
    const isSkippedNonDisabled = !isDisabledClip && isSkipped;
    const skipReason = ev._pmSkipReason || (ev._pmConformSkip ? 'Non-camera original — excluded from conform pull' : 'Actions disabled');
    const skipBadge = isSkippedNonDisabled ? `<span class="pm-skip-badge" title="${esc(skipReason)}">SKIP</span>` : '';
    const disBadge  = isDisabledClip ? `<span class="pm-dis-badge" title="Clip is disabled/muted in the original timeline">DIS</span>` : '';

    // Transition badge — shown in clip cell when transition precedes this clip
    const trObj = _pmParseTransition(ev);
    const trBadge = (!isSkipped && trObj)
      ? `<span class="pm-tr-badge pm-tr-${trObj.type}" title="Transition: ${esc(trObj.raw)} (${trObj.dur}f) — handle frames suggested">${trObj.type === 'dissolve' ? 'DIS' : trObj.type === 'fadein' ? 'FI' : trObj.type === 'fadeout' ? 'FO' : trObj.type === 'wipe' ? 'WPE' : 'TR'}</span>`
      : '';
    const diffBadge = diffChanged
      ? `<span class="pm-diff-badge pm-diff-badge-${diffType.toLowerCase()}" title="Smart Diff: ${esc(diffType)}${diffData?.matchOldClip ? ` · OLD ${esc(diffData.matchOldClip)}` : ''}">${diffType === 'EXTENDED' ? 'EXT' : diffType === 'CHANGED' ? 'CHG' : diffType === 'TRIMMED' ? 'TRIM' : 'NEW'}</span>`
      : '';
    const diffRiskBadge = diffChanged && (diffRisk === 'high' || diffRisk === 'med')
      ? `<span class="pm-diff-risk-badge pm-diff-risk-badge-${diffRisk}" title="${diffRisk === 'high' ? 'High' : 'Medium'} review suggested">${diffRisk === 'high' ? '⚠' : '!'}</span>`
      : '';

    // CONFORM_ANALYSIS chip — shown for .prproj events (CornerCut-style per-clip analysis)
    const ppAnalysis = ev.sourceType === 'prproj' ? (() => {
      const target  = esc(ev.role || `V${(ev._trackIdx || 0) + 1}`);
      const seq     = esc(ev._seqName || '—');
      const remap   = ev._pmRetime || ev._pmRetimeAuto ? 'BEZIER' : 'CUT';
      const audio   = 'STEREO';
      const opacity = 'NODAL_STEPS';
      const tip = [
        `TARGET    ${target}`,
        `SEQ       ${seq}`,
        `REMAP     ${remap}`,
        `AUDIO     ${audio}`,
        `OPACITY   ${opacity}`,
      ].join('\n');
      return `<span class="pm-pp-badge" title="${tip}">PP</span>`;
    })() : '';

    return `<tr class="${rowClass}" data-i="${i}">
      <td class="pm-col-num">${i + 1}</td>
      <td class="pm-col-dot"><span class="pm-dot" style="background:${color}"></span></td>
      <td class="pm-col-reel${reelFixed ? ' pm-ale-fixed' : ''}" title="${reelFixed ? `ALE corrected: ${esc(aleMeta.Tape)} (EDL: ${esc(reelNorm)})` : esc(reelNorm)}${ev.clipName ? `\n${esc(ev.clipName)}` : ''}${aleComment ? `\n💬 ${esc(aleComment)}` : ''}">${esc(reelDisp)}${aleMeta ? '<span class="pm-ale-dot"></span>' : ''}${ppAnalysis}${diffBadge}${diffRiskBadge}${trBadge}${skipBadge}${disBadge}</td>
      <td class="pm-col-tc">${esc(ev.srcIn || '—')}</td>
      <td class="pm-col-dur">${dur}f</td>
      <td class="pm-col-shot"><input class="pm-shot-input${shotLocked ? ' is-locked' : ''}" data-i="${i}" value="${displayShot}" placeholder="type shot name…" title="${shotLocked ? 'Shot name locked — unlock it in the layer inspector to edit' : 'VFX shot name — type here and press Enter to save'}" autocomplete="off" spellcheck="false" ${shotColor ? `style="color:${shotColor}"` : ''} ${isSkipped ? 'disabled' : ''} ${shotLocked ? 'readonly aria-readonly="true"' : ''}>${!isSkipped && !displayShot && !shotLocked ? `<button class="pm-shot-ai-btn" data-i="${i}" tabindex="-1" title="AI suggest shot name">✦</button>` : ''}${!isSkipped ? (() => { const h = ev._pmAiVfxHint; if (h?.needsVfx) { const src = h.source === 'claude' ? 'Claude vision' : 'heuristic'; const conf = h.confidence != null ? ` · ${h.confidence}%` : ''; const tip = esc(`Needs VFX · ${h.type} · ${src}${conf}\n${h.note || ''}\nClick to clear`); return `<span class="pm-vfx-hint pm-vfx-hint--yes" data-i="${i}" title="${tip}">VFX${h.confidence != null ? `<sub style="font-size:7px;opacity:.7">${h.confidence}%</sub>` : ''}</span>`; } return `<button class="pm-vfx-scan-btn" data-i="${i}" tabindex="-1" title="Scan this shot for VFX indicators">🎬</button>`; })() : ''}</td>
      <td class="pm-col-rt" >${isSkipped ? '' : (() => {
        const rtEffective = ev._pmRetime === true || (ev._pmRetime == null && !!ev._pmRetimeAuto);
        const rtAutoStr   = ev._pmRetimeAuto && ev._pmSpeedDisplay ? ` · auto: ${ev._pmSpeedDisplay}` : ev._pmRetimeAuto ? ' · auto-detected' : '';
        const rtUserStr   = ev._pmRetime === true ? ' · user ON' : ev._pmRetime === false ? ' · user OFF' : '';
        const rtTip = `Retime${rtAutoStr}${rtUserStr}\nClick to toggle · click again to restore auto`;
        return `<span class="pm-flag-chip pm-flag-rt${rtEffective ? ' active' : ''}${ev._pmRetimeAuto ? ' auto-badge' : ''}" data-i="${i}" data-flag="retime" title="${esc(rtTip)}">RT</span>`;
      })()}</td>
      <td class="pm-col-st" >${isSkipped ? '' : `<span class="pm-flag-chip pm-flag-st${ev._pmStabilize ? ' active' : ''}" data-i="${i}" data-flag="stabilize" title="Stabilize">ST</span>`}</td>
      <td class="pm-col-rs" >${isSkipped ? '' : (() => {
        const rsEffective = ev._pmResize === true || (ev._pmResize == null && !!ev._pmResizeAuto);
        const rsAutoStr   = ev._pmResizeAuto && ev._pmTransformDisplay ? ` · auto: ${ev._pmTransformDisplay}` : ev._pmResizeAuto ? ' · auto-detected' : '';
        const rsUserStr   = ev._pmResize === true ? ' · user ON' : ev._pmResize === false ? ' · user OFF' : '';
        const rsTip = `Resize/Transform${rsAutoStr}${rsUserStr}\nClick to toggle · click again to restore auto`;
        return `<span class="pm-flag-chip pm-flag-rs${rsEffective ? ' active' : ''}${ev._pmResizeAuto ? ' auto-badge' : ''}" data-i="${i}" data-flag="resize" title="${esc(rsTip)}">RS</span>`;
      })()}</td>
      <td class="pm-col-hdl">${isSkipped ? '' : (() => {
        const hdlVal  = ev._pmHandle ?? '';
        const hdlPh   = ev._pmHandleAutoSuggestion != null ? String(ev._pmHandleAutoSuggestion) : '0';
        const rtEffective = ev._pmRetime === true || (ev._pmRetime == null && !!ev._pmRetimeAuto);
        let hdlTip, hdlCls;
        if (ev._pmTransitionHandleFrames) {
          hdlTip = `Handle frames · transition detected (${ev._pmTransitionHandleFrames}f) — suggested: ${hdlPh}f`;
          hdlCls = 'pm-hdl-input pm-hdl-transition';
        } else if (rtEffective) {
          const rtHint = ev._pmRetimeHandleFrames ? ` — suggested: ${hdlPh}f` : '';
          hdlTip = `Handle frames · retime${rtHint}`;
          hdlCls = 'pm-hdl-input pm-hdl-retime';
        } else {
          hdlTip = 'Handle frames';
          hdlCls = 'pm-hdl-input';
        }
        return `<input class="${hdlCls}" data-i="${i}" value="${hdlVal}" placeholder="${hdlPh}" type="number" min="0" max="999" title="${esc(hdlTip)}">`;
      })()}</td>
      <td class="pm-col-link">${isSkipped ? '' : linkHtml + clipMatchBadge}</td>
      <td class="pm-col-mk-add">${isSkipped ? '' : `${rmBtn}<button class="pm-mk-add-btn" data-i="${i}" title="Add VFX layer for this event">+</button>`}</td>
    </tr>`;
  });

  const banner = vfxEmpty
    ? `<tr class="pm-vfx-empty-banner"><td colspan="20" class="pm-vfx-empty-banner-cell">No clips have VFX markers yet — click \u2795 on any row to add one</td></tr>`
    : '';
  pmEventBody.innerHTML = banner + rows.join('');

  // Hide NLE timeline strip in VFX Marker mode when no markers are linked yet
  const _pmTlStrip = pmTlWrap?.parentElement;
  if (_pmTlStrip) _pmTlStrip.style.display = vfxEmpty ? 'none' : '';

  // VFX Rename mode: update filter notice
  const namedCount = _pmEvents.filter((ev, i) => {
    if (!ev) return false;
    const linkedMks = _pmClipMarkers.filter(mk => _pmLinkMap.get(mk.id) === i);
    if (_pmQs('vfxrename'))  return !!(ev._pmShot || ev.clipName || ev.reel);
    if (_pmQs('vfxmarker'))  return !!(linkedMks[0]?.shotName);
    return !!(ev._pmShot || linkedMks[0]?.shotName);
  }).length;
  let notice = document.getElementById('pmVfxRenameNotice');
  if (!notice) {
    notice = document.createElement('div');
    notice.id = 'pmVfxRenameNotice';
    notice.className = 'pm-vfxrename-notice';
    pmEventBody.closest('table')?.parentElement?.prepend(notice);
  }
  const skipCount = _pmQs('conform') ? _pmEvents.filter(ev => ev._pmConformSkip).length : 0;
  const unscriptedSkipCount = _pmImportMode === 'unscripted'
    ? _pmEvents.filter(ev => ev && ev._pmUnscriptedSkip).length
    : 0;
  const actionEventCount = _pmEvents.filter(ev => ev && !_pmEventActionsDisabled(ev)).length;
  notice.textContent = _pmQs('flatten')
    ? `${_pmEvents.length} clips · sorted by event number · rec TC preserved for sync`
    : _pmQs('conform')
    ? `${_pmEvents.length - skipCount} clips · ${skipCount} skipped (shown dimmed) · sorted by rec TC`
    : _pmQs('vfxrename')
      ? `${namedCount} clips · clip name used as VFX shot name`
      : _pmQs('vfxmarker')
        ? `${evLinkCount.size} of ${_pmEvents.length} clips have VFX marker`
        : _pmImportMode === 'unscripted'
          ? `${actionEventCount} action clips · ${unscriptedSkipCount} graphic/text/adjustment disabled`
        : `${namedCount} of ${_pmEvents.length} clips named`;

  // ── Wire event-table interactions via delegation (attached once per container) ──
  if (!pmEventBody._pmDelegated) {
    pmEventBody._pmDelegated = true;

    pmEventBody.addEventListener('click', (e) => {
      // .pm-flag-chip — RT/ST/RS toggle
      const chip = e.target.closest('.pm-flag-chip');
      if (chip) {
        e.stopPropagation();
        const i    = parseInt(chip.dataset.i, 10);
        const flag = chip.dataset.flag;
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        const ev = _pmEvents[i];
        const propMap  = { retime: '_pmRetime', stabilize: '_pmStabilize', resize: '_pmResize' };
        const autoMap  = { retime: '_pmRetimeAuto', stabilize: null, resize: '_pmResizeAuto' };
        const prop     = propMap[flag];
        const autoProp = autoMap[flag];
        if (!prop) return;
        _pmSlySnapshot(`${flag} toggle`);
        const autoVal    = autoProp ? !!ev[autoProp] : false;
        const userVal    = ev[prop];
        const effective  = userVal === true || (userVal == null && autoVal);
        if (effective)         ev[prop] = false;
        else if (userVal === false) ev[prop] = null;
        else                   ev[prop] = true;
        const newEffective = ev[prop] === true || (ev[prop] == null && autoVal);
        chip.classList.toggle('active', newEffective);
        if (flag === 'retime' && !ev._pmTransitionHandleFrames) {
          const hdlInp = pmEventBody.querySelector(`.pm-hdl-input[data-i="${i}"]`);
          if (hdlInp) {
            hdlInp.classList.toggle('pm-hdl-retime', newEffective);
            if (newEffective) {
              if (!hdlInp.value && ev._pmHandle == null) {
                const isDynamic = Array.isArray(ev.speedKeys) && ev.speedKeys.length > 0;
                const suggested = isDynamic ? 24 : 12;
                hdlInp.placeholder = String(suggested);
                ev._pmRetimeHandleFrames   = suggested;
                ev._pmHandleAutoSuggestion = suggested;
              }
            } else if (!ev._pmRetimeAuto) {
              hdlInp.placeholder = '0';
              ev._pmRetimeHandleFrames   = 0;
              ev._pmHandleAutoSuggestion = undefined;
            }
          }
        }
        _pmSaveMeta(ev);
        const _rtEff = ev._pmRetime === true || (ev._pmRetime == null && !!ev._pmRetimeAuto);
        const _rsEff = ev._pmResize === true || (ev._pmResize == null && !!ev._pmResizeAuto);
        let _markerUpdated = false;
        for (const [mkId, evIdx] of _pmLinkMap) {
          if (evIdx !== i) continue;
          const mk = _pmClipMarkers.find(m => m.id === mkId);
          if (!mk) continue;
          if (flag === 'retime')    mk.retime    = _rtEff;
          if (flag === 'stabilize') mk.stabilize = !!ev._pmStabilize;
          if (flag === 'resize')    mk.resize    = _rsEff;
          _markerUpdated = true;
          if (_pmSelectedMarkerId === mkId) _pmRenderInspector(i);
        }
        if (_markerUpdated) _pmSaveClipMarkers();
        window.MPS_markProjectDirty?.();
        return;
      }

      // .pm-mk-add-btn — quick add marker
      const addBtn = e.target.closest('.pm-mk-add-btn');
      if (addBtn) {
        e.stopPropagation();
        const i = parseInt(addBtn.dataset.i, 10);
        if (!Number.isFinite(i)) return;
        if (_pmEventActionsDisabled(_pmEvents[i])) return;
        _pmAddMarker(i);
        return;
      }

      // .pm-mk-rm-btn — remove all markers for event
      const rmBtn = e.target.closest('.pm-mk-rm-btn');
      if (rmBtn) {
        e.stopPropagation();
        if (window.PFX_PERMISSIONS && !window.PFX_PERMISSIONS.canDoAction('delete_marker')) {
          window.pfxNoAccessView?.showDeniedToast('delete_marker');
          return;
        }
        const i = parseInt(rmBtn.dataset.i, 10);
        if (!Number.isFinite(i)) return;
        const toRemove = _pmClipMarkers.filter(mk => _pmLinkMap.get(mk.id) === i);
        if (!toRemove.length) return;
        _pmSlySnapshot('Remove markers');
        for (const mk of toRemove) {
          const idx = _pmClipMarkers.indexOf(mk);
          if (idx >= 0) _pmClipMarkers.splice(idx, 1);
          window.__ntUnregisterMarker?.(mk.id);
        }
        for (const mk of toRemove) _pmSelectedMarkerIds.delete(mk.id);
        _pmSaveClipMarkers();
        if (toRemove.some(mk => mk.id === _pmSelectedMarkerId)) _pmSelectedMarkerId = null;
        if (_pmActiveEventIdx === i) _pmActiveEventIdx = -1;
        _pmRunAutoLink();
        _pmClearOrphanedShotNames();
        _pmRenderEventTable();
        _pmPushTimelineData();
        _pmRenderInspector();
        if (pmCtxMarkers) pmCtxMarkers.textContent = `${_pmClipMarkers.length} marker${_pmClipMarkers.length === 1 ? '' : 's'}`;
        _pmScheduleDraw();
        return;
      }

      // .pm-status — cycle status badge
      const badge = e.target.closest('.pm-status');
      if (badge) {
        const i = parseInt(badge.dataset.i, 10);
        if (!Number.isFinite(i)) return;
        const ev = _pmEvents[i];
        if (_pmEventActionsDisabled(ev)) return;
        const key  = _pmStatusKey(ev);
        const cur  = _pmStatusMap.get(key) || 'none';
        const next = _STATUSES[(_STATUSES.indexOf(cur) + 1) % _STATUSES.length];
        _pmStatusMap.set(key, next);
        badge.className   = `pm-status pm-status-${next}`;
        badge.textContent = _STATUS_LABELS[next];
        _pmSaveStatus();
        try { window.MPS_markProjectDirty?.('prepmark'); } catch {}
        return;
      }

      // .pm-shot-ai-btn — inline AI shot name suggestion
      const aiShotBtn = e.target.closest('.pm-shot-ai-btn');
      if (aiShotBtn) {
        const i = parseInt(aiShotBtn.dataset.i, 10);
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        const ev = _pmEvents[i];
        const suggested = _pmAutoShotName(ev, i);
        if (!suggested) return;
        ev._pmShot = suggested;
        _pmSaveMeta(ev);
        window.MPS_markProjectDirty?.();
        _pmRenderEventTable();
        return;
      }

      // .pm-vfx-scan-btn — per-row AI frame scan for VFX work
      const vfxScanBtn = e.target.closest('.pm-vfx-scan-btn');
      if (vfxScanBtn) {
        const i = parseInt(vfxScanBtn.dataset.i, 10);
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        _pmVfxScanEvent(_pmEvents[i], i, vfxScanBtn);
        return;
      }

      // .pm-vfx-hint — click to clear the hint
      const vfxHintBadge = e.target.closest('.pm-vfx-hint');
      if (vfxHintBadge) {
        const i = parseInt(vfxHintBadge.dataset.i, 10);
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        delete _pmEvents[i]._pmAiVfxHint;
        _pmSaveMeta(_pmEvents[i]);
        _pmRenderEventTable();
        return;
      }

      // .pm-row — seek / sync / vfx-marker (skip if click originated on a handled child)
      if (e.target.closest('.pm-shot-input, .pm-status, .pm-mk-add-btn, .pm-flag-chip, .pm-hdl-input, .pm-shot-ai-btn, .pm-vfx-scan-btn, .pm-vfx-hint')) return;
      const row = e.target.closest('.pm-row');
      if (!row) return;
      const i = parseInt(row.dataset.i, 10);
      if (!Number.isFinite(i)) return;
      const ev = _pmEvents[i];
      const actionsDisabled = _pmEventActionsDisabled(ev);
      if (_pmSyncMode && pmVideo && !_pmQs('vfxmarker') && !actionsDisabled) {
        const recInAbsF = tcToFrames(ev?.recIn || '00:00:00:00', _pmFps);
        _pmVideoZeroAbsF   = recInAbsF - _pmFrameClock.secondsToFrame(_pmReadVideoMediaTimeSec());
        _pmSyncManuallySet = true;
        // Sync stays ON — do NOT disarm after row click
        try { localStorage.setItem(_lsKey('vidZeroAbsF.v1'), String(_pmVideoZeroAbsF)); } catch {}
        window.__pmUpdateSyncDisplay?.();
        _pmShowSyncToast('Sync set ✓  — timeline aligned to this event');
        _pmScheduleDraw();
        return;
      }
      // Guard: browser fires two `click` events before `dblclick`, so debounce to
      // ensure a rapid double-click on a row only creates ONE marker, not two.
      if (_pmQs('vfxmarker')) {
        _pmSeekToEvent(i);
        _pmTlFocusEvent(i);
        if (actionsDisabled) return;
        if (!pmEventBody._pmMkBusy) {
          pmEventBody._pmMkBusy = true;
          setTimeout(() => { pmEventBody._pmMkBusy = false; }, 400);
          _pmAddMarker(i);
        }
        return;
      }
      _pmSeekToEvent(i);
      _pmTlFocusEvent(i);
    });

    // dblclick delegation — add marker on row double-click in non-VFX-marker modes.
    // In VFX Marker mode the click handler above already adds the marker on every click
    // (with debounce), so we skip it here to avoid a duplicate call.
    pmEventBody.addEventListener('dblclick', (e) => {
      if (_pmQs('vfxmarker')) return;
      if (e.target.closest('.pm-shot-input, .pm-status, .pm-mk-add-btn, .pm-flag-chip, .pm-hdl-input, .pm-shot-ai-btn, .pm-vfx-scan-btn, .pm-vfx-hint')) return;
      const row = e.target.closest('.pm-row');
      if (!row) return;
      const i = parseInt(row.dataset.i, 10);
      if (!Number.isFinite(i)) return;
      const ev = _pmEvents[i];
      if (_pmEventActionsDisabled(ev)) return;
      _pmAddMarker(i);
    });

    // focusout delegation — covers blur for inputs (focusout bubbles, blur does not)
    pmEventBody.addEventListener('focusout', (e) => {
      const inp = e.target;
      if (inp.classList.contains('pm-hdl-input')) {
        const i = parseInt(inp.dataset.i, 10);
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        let v = parseInt(inp.value, 10);
        if (!Number.isFinite(v) && _pmEvents[i]._pmHandleAutoSuggestion != null) {
          v = _pmEvents[i]._pmHandleAutoSuggestion;
          inp.value = v;
        }
        _pmEvents[i]._pmHandle = Number.isFinite(v) && v >= 0 ? v : undefined;
        _pmSaveMeta(_pmEvents[i]);
        window.MPS_markProjectDirty?.();
        return;
      }
      if (inp.classList.contains('pm-shot-input')) {
        _pmSaveShotInput(inp);
      }
    });

    // keydown delegation — Enter commits inputs without a full re-render
    pmEventBody.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      const inp = e.target;
      if (inp.classList.contains('pm-hdl-input')) {
        const i = parseInt(inp.dataset.i, 10);
        if (!Number.isFinite(i) || !_pmEvents[i]) return;
        let v = parseInt(inp.value, 10);
        if (!Number.isFinite(v) && _pmEvents[i]._pmHandleAutoSuggestion != null) {
          v = _pmEvents[i]._pmHandleAutoSuggestion;
          inp.value = v;
        }
        _pmEvents[i]._pmHandle = Number.isFinite(v) && v >= 0 ? v : undefined;
        _pmSaveMeta(_pmEvents[i]);
        window.MPS_markProjectDirty?.();
        inp.blur();
        return;
      }
      if (inp.classList.contains('pm-shot-input')) {
        _pmSaveShotInput(inp);
        inp.blur();
      }
    });
  }

  // Coverage stats
  const taggedCount  = [...new Set([..._pmLinkMap.values()])].length;
  const orphanCount  = _pmClipMarkers.length - _pmLinkMap.size;
  const coverageTotal = _pmImportMode === 'unscripted'
    ? _pmEvents.filter(ev => ev && !_pmEventActionsDisabled(ev)).length
    : _pmEvents.length;
  if (pmCovStats) {
    pmCovStats.textContent =
      `${taggedCount} / ${coverageTotal} events tagged · ` +
      `${Math.max(0, orphanCount)} orphan marker${orphanCount !== 1 ? 's' : ''}`;
  }

  // Keep VFX workspace shot list in sync whenever the pull list re-renders.
  if (_pmLocalQs.vfxmarker && document.getElementById('pmVfxWorkspace')?.offsetParent != null) {
    _pmVfxWorkspacePopulateShotList();
  }
}

function _pmStatusKey(ev) {
  const base = `${ev?.reel || ''}|${ev?.srcIn || ''}`;
  if (!ev?.reel && !ev?.srcIn && ev?.recIn) return `${base}|rec:${ev.recIn}`;
  return base;
}

function _pmSaveClipMarkers() {
  // Strip large binary blobs and transient UI state before serialising.
  const slim = _pmClipMarkers.map(mk => {
    const { thumb, thumbAnn, annoStrokes, _thumbCapturing, _thumbError, ...rest } = mk;
    return rest;
  });
  const key  = _lsKey('clipMarkers.v2');
  const json = JSON.stringify(slim);
  try {
    localStorage.setItem(key, json);
    return;
  } catch (e) {
    if (e.name !== 'QuotaExceededError' && !(e instanceof DOMException)) {
      console.warn('[PM] clip markers save failed:', e);
      return;
    }
  }
  // ── Quota exceeded: evict stale pfx.prepmark.* keys from other projects ──
  const currentPrefix = `pfx.prepmark.${_pmCurrentProjectKey || 'default'}.`;
  for (let i = localStorage.length - 1; i >= 0; i--) {
    const k = localStorage.key(i);
    if (k && k.startsWith('pfx.prepmark.') && !k.startsWith(currentPrefix)) {
      try { localStorage.removeItem(k); } catch {}
    }
  }
  try {
    localStorage.setItem(key, json);
    return;
  } catch {}
  // ── Still over quota: save a trimmed set (most recent 300 markers) ──
  try {
    const trimmed = slim.slice(-300);
    localStorage.setItem(key, JSON.stringify(trimmed));
    const lost = slim.length - trimmed.length;
    console.warn(`[PM] localStorage quota hit — saved last ${trimmed.length} of ${slim.length} markers`);
    if (lost > 0) {
      try { _pmToast(`⚠ Storage full — only the last ${trimmed.length} of ${slim.length} markers saved. Use Save to project file to preserve all.`, 'warn'); } catch {}
    }
  } catch (e) {
    console.warn('[PM] clip markers save failed even after trimming:', e);
    try { _pmToast('⚠ Could not save markers — storage quota exceeded. Save to project file immediately.', 'warn'); } catch {}
  }
}

function _pmSaveStatus() {
  try {
    const obj = {};
    for (const [k, v] of _pmStatusMap) obj[k] = v;
    localStorage.setItem(_lsKey('shotStatus.v1'), JSON.stringify(obj));
  } catch {}
}

function _pmSaveMeta(ev) {
  if (!ev) return;
  const key = _pmStatusKey(ev);
  const meta = {
    shot:       ev._pmShot       != null ? ev._pmShot       : null,
    handle:     ev._pmHandle     != null ? ev._pmHandle     : null,
    retime:     ev._pmRetime     != null ? ev._pmRetime     : null,
    stabilize:  ev._pmStabilize  != null ? ev._pmStabilize  : null,
    resize:     ev._pmResize     != null ? ev._pmResize     : null,
    vfxHint:    ev._pmAiVfxHint  != null ? ev._pmAiVfxHint  : null,
  };
  // Remove empty entries to keep storage small
  if (!meta.shot && meta.handle == null && meta.retime == null && meta.stabilize == null && meta.resize == null && meta.vfxHint == null) {
    _pmMetaMap.delete(key);
  } else {
    _pmMetaMap.set(key, meta);
  }
  try {
    const obj = {};
    for (const [k, v] of _pmMetaMap) obj[k] = v;
    localStorage.setItem(_lsKey('eventMeta.v1'), JSON.stringify(obj));
  } catch {}
}

// ─── Auto-Detect Retime / Resize / Transition ────────────────────────────────
// Runs BEFORE _pmApplyMetaToEvents so user-saved overrides take precedence.
// Sets *Auto / display fields only — never touches user-set _pmRetime/_pmResize.
function _pmExtractSpeedPercent(ev) {
  if (!ev) return null;

  const normalizePct = (value) => {
    if (value == null || value === '') return null;
    const n = Number(value);
    if (!Number.isFinite(n)) return null;
    const abs = Math.abs(n);
    if (abs > 0 && abs <= 10) return n * 100;
    return n;
  };

  const parseTextPct = (text) => {
    if (!text) return null;
    const s = String(text);
    let m = s.match(/(\d+(?:\.\d+)?)\s*%/);
    if (m) return parseFloat(m[1]);
    m = s.match(/speed[_\s-]*(\d+(?:\.\d+)?)/i);
    if (m) return parseFloat(m[1]);
    m = s.match(/(\d+(?:\.\d+)?)x/i);
    if (m) return parseFloat(m[1]) * 100;
    return null;
  };

  const nums = [
    normalizePct(ev.speed),
    normalizePct(ev.speedFactor),
    normalizePct(ev?.fx?.speed?.percent)
  ].filter(Number.isFinite);

  const textPct = parseTextPct(ev.speedSummary || ev.speedComment || ev?.fx?.speed?.summary || '');
  const numericNonDefault = nums.find(n => Math.abs(n) > 0.0001 && Math.abs(n - 100) > 0.0001);
  const numericNonZero = nums.find(n => Math.abs(n) > 0.0001);
  const numericAny = nums.length ? nums[0] : null;

  if (textPct != null && Math.abs(textPct - 100) > 0.0001) {
    if (numericNonDefault == null) return textPct;
  }

  return numericNonDefault ?? textPct ?? numericNonZero ?? numericAny ?? null;
}

function _pmNormalizeTransform(tf) {
  if (!tf || typeof tf !== 'object') return null;

  const num = (value, fallback = null) => {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  };
  const normScale = (value) => {
    const n = num(value);
    if (!Number.isFinite(n)) return null;
    return Math.abs(n) > 10 ? (n / 100) : n;
  };
  const readPair = (value) => {
    if (!Array.isArray(value)) return null;
    const a = num(value[0]);
    const b = num(value[1], a);
    return (a == null || b == null) ? null : [a, b];
  };

  const scalePair = readPair(tf.scale);
  const posPair   = readPair(tf.position);
  const cropObj   = (tf.crop && typeof tf.crop === 'object') ? tf.crop : null;

  const scaleX = normScale(tf.scaleX ?? scalePair?.[0] ?? tf.scale ?? 1) ?? 1;
  const scaleY = normScale(tf.scaleY ?? scalePair?.[1] ?? tf.scale ?? 1) ?? 1;
  const posX = num(tf.posX ?? posPair?.[0] ?? 0, 0);
  const posY = num(tf.posY ?? posPair?.[1] ?? 0, 0);
  const rotation = num(tf.rotation ?? 0, 0);
  const cropL = num(tf.cropL ?? cropObj?.left ?? 0, 0);
  const cropR = num(tf.cropR ?? cropObj?.right ?? 0, 0);
  const cropT = num(tf.cropT ?? cropObj?.top ?? 0, 0);
  const cropB = num(tf.cropB ?? cropObj?.bottom ?? 0, 0);

  return { scaleX, scaleY, posX, posY, rotation, cropL, cropR, cropT, cropB };
}

function _pmAutoDetectFlags(events) {
  if (!Array.isArray(events)) return;
  for (const ev of events) {
    if (!ev) continue;

    // ── Retime auto-detect ──────────────────────────────────────────────────
    // speedFactor: parser stores it as a number (100 = normal, 50 = half-speed)
    // speedKeys: present when dynamic retime (variable speed)
    const sf = _pmExtractSpeedPercent(ev);
    const hasDynamic = Array.isArray(ev.speedKeys) && ev.speedKeys.length > 0;
    const hasConstant = Number.isFinite(sf) && Math.abs(sf - 100) > 0.5;
    if (hasConstant || hasDynamic) {
      ev._pmRetimeAuto = true;
      if (hasDynamic) {
        ev._pmSpeedDisplay = 'VarSpd';
      } else if (Number.isFinite(sf)) {
        const ratio = sf / 100;
        // Format as fraction-like string: 0.5→"0.5×", 2→"2×", 0.2534→"25%"
        if (Math.abs(ratio - Math.round(ratio)) < 0.01) {
          ev._pmSpeedDisplay = `${Math.round(ratio)}×`;
        } else if (Math.abs(ratio * 2 - Math.round(ratio * 2)) < 0.01) {
          ev._pmSpeedDisplay = `${(ratio).toFixed(1)}×`;
        } else {
          ev._pmSpeedDisplay = `${Math.round(sf)}%`;
        }
      }
    } else {
      ev._pmRetimeAuto = false;
      ev._pmSpeedDisplay = '';
    }

    // ── Resize / Transform auto-detect ─────────────────────────────────────
    // transform: object with {scaleX, scaleY, posX, posY, rotation, cropL, cropR, cropT, cropB}
    // transformSummary: human-readable string from parser
    const tf = _pmNormalizeTransform(ev.transform);
    if (tf && typeof tf === 'object') {
      const { scaleX = 1, scaleY = 1, posX = 0, posY = 0, rotation = 0,
              cropL = 0, cropR = 0, cropT = 0, cropB = 0 } = tf;
      const isIdentity =
        Math.abs(scaleX - 1) < 0.001 &&
        Math.abs(scaleY - 1) < 0.001 &&
        Math.abs(posX)       < 0.5   &&
        Math.abs(posY)       < 0.5   &&
        Math.abs(rotation)   < 0.01  &&
        Math.abs(cropL)      < 0.001 &&
        Math.abs(cropR)      < 0.001 &&
        Math.abs(cropT)      < 0.001 &&
        Math.abs(cropB)      < 0.001;
      ev._pmResizeAuto = !isIdentity;
      ev._pmTransformDisplay = !isIdentity
        ? (ev.transformSummary || _pmBuildTransformLabel(tf))
        : '';
    } else {
      ev._pmResizeAuto = false;
      ev._pmTransformDisplay = '';
    }

    // ── Handle suggestion: transition (highest priority) → retime → none ──────
    const tr = _pmParseTransition(ev);
    if (tr) {
      ev._pmTransitionHandleFrames = tr.dur;
      ev._pmRetimeHandleFrames     = 0;
      // Only auto-populate handle if not already user-set (meta apply hasn't run yet)
      if (ev._pmHandle == null || ev._pmHandle === undefined) {
        ev._pmHandleAutoSuggestion = tr.dur + 8;
      }
    } else if (ev._pmRetimeAuto) {
      // Retime detected — suggest handles so the speed ramp doesn't start exactly at the cut
      const isDynamic = Array.isArray(ev.speedKeys) && ev.speedKeys.length > 0;
      ev._pmTransitionHandleFrames = 0;
      ev._pmRetimeHandleFrames     = isDynamic ? 24 : 12;
      if (ev._pmHandle == null || ev._pmHandle === undefined) {
        ev._pmHandleAutoSuggestion = ev._pmRetimeHandleFrames;
      }
    } else {
      ev._pmTransitionHandleFrames = 0;
      ev._pmRetimeHandleFrames     = 0;
      ev._pmHandleAutoSuggestion   = undefined;
    }
  }
}

// Build a concise transform label from the transform object
function _pmBuildTransformLabel(tf) {
  tf = _pmNormalizeTransform(tf);
  if (!tf) return '';
  const parts = [];
  const { scaleX = 1, scaleY = 1, posX = 0, posY = 0, rotation = 0 } = tf;
  if (Math.abs(scaleX - 1) > 0.001 || Math.abs(scaleY - 1) > 0.001) {
    if (Math.abs(scaleX - scaleY) < 0.001) {
      parts.push(`${Math.round(scaleX * 100)}%`);
    } else {
      parts.push(`${Math.round(scaleX * 100)}%×${Math.round(scaleY * 100)}%`);
    }
  }
  if (Math.abs(posX) > 0.5 || Math.abs(posY) > 0.5) {
    parts.push(`pos${Math.round(posX)},${Math.round(posY)}`);
  }
  if (Math.abs(rotation) > 0.01) {
    parts.push(`rot${rotation > 0 ? '+' : ''}${rotation.toFixed(1)}°`);
  }
  return parts.join(' ') || 'xform';
}

function _pmApplyMetaToEvents() {
  for (const ev of _pmEvents) {
    if (!ev) continue;
    const meta = _pmMetaMap.get(_pmStatusKey(ev));
    if (!meta) continue;
    if (meta.shot      != null) ev._pmShot      = meta.shot;
    if (meta.handle    != null) {
      ev._pmHandle = meta.handle;
      // User has a saved handle — suppress auto-suggestion so placeholder doesn't conflict
      ev._pmHandleAutoSuggestion = undefined;
    }
    if (meta.retime    != null) ev._pmRetime    = meta.retime;
    if (meta.stabilize != null) ev._pmStabilize = meta.stabilize;
    if (meta.resize    != null) ev._pmResize    = meta.resize;
    if (meta.vfxHint   != null) ev._pmAiVfxHint = meta.vfxHint;
  }
}

// ─── Video seek ───────────────────────────────────────────────────────────────
function _pmSeekToEvent(idx) {
  if (!_pmEvents[idx]) return;
  const ev = _pmEvents[idx];
  const recInFrame = tcToFrames(ev.recIn || '00:00:00:00', _pmFps);
  if (pmVideo) {
    const recoveredSync = _pmMaybeRecoverMisarmedVfxSync(
      Number.isFinite(recInFrame) && recInFrame >= 0 ? { absF: recInFrame, navTarget: idx } : null,
      { silent: false }
    );
    if (!recoveredSync) _pmSeekVideoAbsFrame(recInFrame, { navTarget: idx });
  }
  _pmSetActiveRow(idx);
  _pmUpdateInspector(idx);

  // Auto-zoom: when the clip would be < 10 px wide at the current zoom (typically zoom=1 on a
  // long sequence), zoom in so the clip is visible and auto-pan has room to work.
  if (_pmTlCanvas && _pmSeqEndFrames > _pmSeqBaseFrames) {
    const _azFps   = _pmFps || 24;
    const _azTotal = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
    const _azCW    = Math.max(1, _pmTlCanvas.width / (_pmDpr || 1) - _NLE_HEADER_W);
    const _azDur   = ev.durationFrames ? Number(ev.durationFrames) : _azFps;
    const _azClipPx = (_azDur / (_azTotal / _pmTlZoom)) * _azCW;
    if (_azClipPx < 10) {
      // Show ~8 clip-durations of context, minimum 20 seconds
      const _azWin = Math.max(_azDur * 8, _azFps * 20);
      _pmTlZoom = Math.max(1, Math.min(64, _azTotal / _azWin));
      _tlClampPan();
    }
  }

  // Immediately push playhead to timeline (don't wait for timeupdate)
  _pmScheduleTimelineDraw(recInFrame);
}

function _pmSetActiveRow(idx) {
  if (idx === _pmActiveEventIdx) return;
  if (_pmActiveEventIdx >= 0) {
    const prev = pmEventBody?.querySelector(`tr[data-i="${_pmActiveEventIdx}"]`);
    if (prev) prev.classList.remove('pm-row-active');
  }
  _pmActiveEventIdx = idx;
  if (idx >= 0) {
    const row = pmEventBody?.querySelector(`tr[data-i="${idx}"]`);
    if (row) {
      row.classList.add('pm-row-active');
      if (row.offsetParent !== null) {
        const playing = pmVideo && !pmVideo.paused;
        row.scrollIntoView({ block: 'nearest', behavior: playing ? 'instant' : 'smooth' });
      }
    }
  }
  _pmUpdateBanner(idx);
  _pmAnnotDraw();
}

// ─── Now-playing banner — updates the strip below the video ──────────────────
function _pmUpdateBanner(activeIdx) {
  if (!pmClipBanner) return;
  if (activeIdx < 0 || !_pmEvents[activeIdx]) {
    pmClipBanner.style.display = 'none';
    return;
  }
  const ev      = _pmEvents[activeIdx];
  const fps     = _pmFps || 24;
  const status  = _pmStatusMap.get(_pmStatusKey(ev)) || 'none';
  const reel    = ev.reel   || '';
  const clip    = ev.clipName || reel || '—';
  const recIn   = ev.recIn  || '—';
  const recOut  = ev.recOut || '—';
  const dur     = ev.durationFrames ||
    (tcToFrames(ev.recOut || '00:00:00:00', fps) - tcToFrames(ev.recIn || '00:00:00:00', fps));

  // Camera color dot
  const camKeys = [...new Set(_pmEvents.map(e => e?.camera || e?.reel || ''))];
  const camIdx  = camKeys.indexOf(ev.camera || ev.reel || '');
  const camCol  = _CAM_COLORS[(camIdx < 0 ? 0 : camIdx) % _CAM_COLORS.length];

  const esc2 = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  // Show reel only when it differs from clip name
  const reelHtml = reel && reel !== clip
    ? `<span class="pm-banner-reel">${esc2(reel)}</span>`
    : '';
  const statusCls = `pm-status pm-status-${status}`;

  pmClipBanner.innerHTML =
    `<span class="pm-banner-dot" style="background:${camCol}"></span>` +
    `<span class="pm-banner-clip" title="${esc2(clip)}">${esc2(clip)}</span>` +
    reelHtml +
    `<span class="${statusCls}" style="pointer-events:none">${_STATUS_LABELS[status]}</span>` +
    `<span class="pm-banner-sep">|</span>` +
    `<span class="pm-banner-tc">${esc2(recIn)}</span>` +
    `<span class="pm-banner-sep">→</span>` +
    `<span class="pm-banner-tc">${esc2(recOut)}</span>` +
    `<span class="pm-banner-dur">${dur}f</span>`;
  pmClipBanner.style.display = 'flex';
}

// ─── Per-frame sync (called every rAF while playing, or on timeupdate when paused) ──
function _pmSyncFrame() {
  if (!pmVideo) return;
  const fps = _pmFps || 24;
  let currentFrame = _pmReadVideoAbsFrame();
  // Explicit seeks carry a target frame. While the browser is still seeking, or if it
  // lands within a small keyframe-snap tolerance, keep the UI pinned to the requested
  // frame instead of briefly jumping back to the previous decoded position.
  const seekSettledNearTarget = _pmSeekTargetF >= 0 && Math.abs(currentFrame - _pmSeekTargetF) <= 3;
  if (_pmSeekTargetF >= 0 && (pmVideo.seeking || seekSettledNearTarget)) {
    currentFrame = _pmSeekTargetF;
  }
  if (_pmSeekTargetF >= 0 && !pmVideo.seeking) _pmSeekTargetF = -1;
  if (pmVideo.seeking && _pmSeekTargetF < 0) return;

  // Skip redundant DOM work if the frame hasn't changed
  if (currentFrame !== _pmLastSyncedF) {
    _pmLastSyncedF = currentFrame;

    // ── Find active event ───────────────────────────────────────────────────
    // In PACK mode: only consider events that are IN the packed map.
    // Background events on other tracks can overlap the gaps between packed
    // segments, which would prevent the advance condition from ever firing.
    let activeIdx = -1;
    if (_pmTlPack && _pmPackedMap.size > 0) {
      for (const [idx, pm] of _pmPackedMap) {
        if (currentFrame >= pm.eIn && currentFrame < pm.eOut) { activeIdx = idx; break; }
      }
    } else {
      const tMap = _pmTrackOf.size > 0 ? _pmTrackOf : _pmBuildTrackOf();
      let bestAllTrack = -1, bestAllIdx = -1;
      for (let i = 0; i < _pmEvents.length; i++) {
        if (!tMap.has(i)) continue;
        const ev   = _pmEvents[i];
        if (!ev) continue;
        if (ev.disabled && !_pmShowDisabledClips) continue;
        const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
        const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
        const eOut = rOut > eIn ? rOut
                   : ev.durationFrames ? eIn + Number(ev.durationFrames)
                   : eIn + 1;
        if (currentFrame >= eIn && currentFrame < eOut) {
          const track = tMap.get(i) ?? 0;
          if (track >= bestAllTrack) { bestAllTrack = track; bestAllIdx = i; }
        }
      }
      activeIdx = bestAllIdx;
    }

    const prevActiveIdx = _pmActiveEventIdx;

    // When paused, respect the user's explicit selection: if the currently
    // selected event still covers currentFrame, don't override it with the
    // first-match scan result (which always picks V1 for comp layers).
    const keepCurrent = pmVideo.paused && _pmActiveEventIdx >= 0 && (() => {
      const ev = _pmEvents[_pmActiveEventIdx];
      if (!ev) return false;
      if (ev.disabled && !_pmShowDisabledClips) return false;
      const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
      const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
      const eOut = rOut > eIn ? rOut
                 : ev.durationFrames ? eIn + Number(ev.durationFrames)
                 : eIn + 1;
      return currentFrame >= eIn && currentFrame < eOut;
    })();

    const syncNavState = _pmGetNavProtectState(currentFrame, fps);

    if (!keepCurrent && activeIdx !== _pmActiveEventIdx) {
      // Guard: after explicit navigation (arrow keys, row click) the video may keyframe-snap
      // to a position just before the target clip's eIn, making keepCurrent=false and causing
      // _pmSyncFrame to immediately reset the row back to the previous clip.
      // _pmNavTarget stores the just-navigated-to idx; while it matches _pmActiveEventIdx,
      // skip the override regardless of play/pause state — keyframe snap affects both.
      const navProtect = syncNavState.active;
      if (!navProtect) {
        _pmNavTarget = -1;
        _pmSetActiveRow(activeIdx);
        // Skip inspector update (+ marker re-seek) while user is dragging the playhead.
        // seekAllowed=false prevents re-seek loop while video plays through a marker clip.
        if (!_pmTlDragging) {
          if (activeIdx >= 0) {
            _pmUpdateInspector(activeIdx, false);
          } else {
            _pmSelectedMarkerId = null;
            _pmSelectedMarkerIds.clear();
            _pmRenderInspector(-1);
          }
        }
      }
    }
    // Once the scan agrees with the active clip the navigation is settled; clear the lock.
    if (activeIdx === _pmActiveEventIdx) _pmNavTarget = -1;
    // VFX Marker mode: the seek goes to marker.recIn which may fall inside a DIFFERENT
    // clip's sequence range (e.g. marker placed before the clip boundary). In that case
    // activeIdx never equals _pmActiveEventIdx and the lock would stay forever.
    // Clear it once the video has settled at (or within 3 frames of) the marker's recIn.
    if (_pmNavTarget >= 0 && _pmQs('vfxmarker') && _pmSelectedMarkerId) {
      const _vfxMk = _pmClipMarkers.find(m => m.id === _pmSelectedMarkerId);
      if (_vfxMk?.recIn && Math.abs(currentFrame - tcToFrames(_vfxMk.recIn, fps)) <= 3) {
        _pmNavTarget = -1;
      }
    }

    // ── Stale nav-protect clear ──────────────────────────────────────────────
    // Problem: when the pack map contains multi-track overlay events (titles,
    // graphics) that share the same absolute [eIn, eOut) range as a V1 clip,
    // _pmPackAdvance may navigate TO the overlay event.  The scan then always
    // returns the V1 clip (first match by eIn), so activeIdx never equals
    // _pmActiveEventIdx (the overlay), and the normal clear above never fires.
    // The nav-protect becomes permanently stuck, and the advance condition
    // (_pmPackAdvance) can never fire because activeIdx never reaches -1 while
    // the video is still inside the shared absolute range.
    //
    // Fix: when we ARE in a gap (activeIdx=-1) and the video has already passed
    // the nav-target event's out-point, the lock is stale — clear it.  This
    // applies only in pack mode and only while in a gap, so it cannot interfere
    // with the keyframe-snap protection for normal clips (where the normal clear
    // already fires when the video first enters the target clip's range).
    if (_pmTlPack && _pmNavTarget >= 0 && activeIdx < 0) {
      const _staleTgt = _pmEvents[_pmNavTarget];
      if (_staleTgt) {
        const _staleIn   = tcToFrames(_staleTgt.recIn  || '00:00:00:00', fps);
        const _staleROut = tcToFrames(_staleTgt.recOut || '00:00:00:00', fps);
        const _staleOut  = _staleROut > _staleIn ? _staleROut
                         : _staleTgt.durationFrames ? _staleIn + Number(_staleTgt.durationFrames)
                         : _staleIn + 1;
        if (currentFrame >= _staleOut) _pmNavTarget = -1;
      }
    }

    // ── Drift detection ─────────────────────────────────────────────────────
    if (!pmVideo.paused) _pmCheckSyncDrift(currentFrame, activeIdx);

    // ── PACK playlist auto-advance ───────────────────────────────────────────
    // When PACK is on and the playhead exits a segment (enters a gap), jump
    // immediately to the next segment's in-point like a playlist.
    // Nav-protect guard: if _pmPackAdvance just navigated us TO prevActiveIdx
    // and the seek is still settling (keyframe snap lands slightly before eIn),
    // currentFrame can momentarily be outside any segment range even though we
    // haven't actually left the clip.  Triggering a second advance here would
    // skip the intended clip entirely.  Skip the advance while the nav-lock
    // for prevActiveIdx is still active.
    if (_pmTlPack && !pmVideo.paused && !pmVideo.ended &&
        activeIdx < 0 && prevActiveIdx >= 0 &&
        !(_pmNavTarget >= 0 && _pmNavTarget === prevActiveIdx)) {
      _pmPackAdvance(prevActiveIdx);
    }

    // ── HUD — three-clock TC model ───────────────────────────────────────────
    // Clock 1: XML Record TC — authority for all exports; never derived from video.currentTime
    const _hudMk = _pmGetSelectedMarkerForDisplay(currentFrame, fps);
    const recTc  = (_hudMk?.recIn) ? _hudMk.recIn : framesToTC(currentFrame, fps);
    const recF   = (_hudMk?.recIn) ? tcToFrames(_hudMk.recIn, fps) : currentFrame;
    if (pmHudRecTc) pmHudRecTc.textContent = `REC ${recTc}`;
    if (pmHudFrame) pmHudFrame.textContent  = `f ${recF}`;

    // Clock 2: Source TC — authority for SRC IN/OUT and OCF relink
    let srcTcStr = null;
    if (_hudMk?.tcIn && _pmQs('vfxmarker')) {
      srcTcStr = _hudMk.tcIn;
    } else if (activeIdx >= 0) {
      const ev = _pmEvents[activeIdx];
      if (ev) {
        if (ev.srcIn && ev.recIn) {
          // Source burn-in TC formatted at the clip's OWN fps so mixed-fps
          // sequences read correctly. Identical to the legacy single-fps math
          // when the clip rate matches the timeline rate (no regression).
          srcTcStr = sourceTcAtRecord({ srcIn: ev.srcIn, recIn: ev.recIn, recordFrame: currentFrame, sourceFps: ev.fps || fps, timelineFps: fps });
        } else if (ev.sync) {
          // Fallback: clip lost its src/rec TC but a precomputed sync exists.
          const localF = currentFrame - ev.sync.xmlRecInFrame;
          srcTcStr = framesToTC(Math.max(0, ev.sync.sourceInFrame + localF), fps);
        }
      }
    }
    if (pmHudSrcTc) pmHudSrcTc.textContent = srcTcStr ? `SRC ${srcTcStr}` : '—';

    // Clock 3: Reference burn-in TC — only shown when user has manually calibrated
    // NOTE: _pmNativeStartTc is the proxy file's own embedded TC (linear, sequence-level).
    // For offline edit proxies it equals the proxy's start TC (often with pre-roll), NOT
    // the per-clip camera TC. Using it here would show a constant false offset vs. REC TC.
    // Only show REF TC when the user has explicitly synced a clip via the SYNC button.
    let burninRefTc = null, burninOffsetF = null;
    if (activeIdx >= 0) {
      const ev = _pmEvents[activeIdx];
      if (ev?.sync && ev.sync.syncStatus !== 'xml_only' && typeof ev.sync.burninOffsetFrames === 'number') {
        burninOffsetF = ev.sync.burninOffsetFrames;
        burninRefTc   = framesToTC(Math.max(0, currentFrame + burninOffsetF), fps);
      }
    }

    const _showRef = burninRefTc != null && Math.abs(burninOffsetF ?? 0) > 0;
    if (pmHudBurninTc) {
      pmHudBurninTc.textContent    = _showRef ? `REF ${burninRefTc}` : '';
      pmHudBurninTc.style.display  = _showRef ? '' : 'none';
    }
    if (pmHudTcOffset) {
      if (_showRef) {
        const _sign = (burninOffsetF ?? 0) >= 0 ? '+' : '';
        pmHudTcOffset.textContent   = `${_sign}${burninOffsetF}f`;
        pmHudTcOffset.style.display = '';
      } else {
        pmHudTcOffset.style.display = 'none';
      }
    }
    // Warning chip: only when user-synced burn-in offset is non-trivial (>3f)
    const _showWarn = _showRef && Math.abs(burninOffsetF ?? 0) > 3;
    if (pmHudTcWarn) pmHudTcWarn.style.display = _showWarn ? '' : 'none';

    // [TC DEBUG] — gated by window._pmTcDebug = true in devtools; throttled to 1/s during play
    if (window._pmTcDebug && activeIdx >= 0) {
      const _dbNow = performance.now();
      if (pmVideo.paused || (_dbNow - _pmLastTcDebugMs) > 1000) {
        _pmLastTcDebugMs = _dbNow;
        const _dbEv   = _pmEvents[activeIdx];
        const _dbLocF = _dbEv?.sync ? currentFrame - _dbEv.sync.xmlRecInFrame : null;
        console.log('[TC DEBUG]',
          `clipName=${_dbEv?.clipName || _dbEv?.srcFile || '?'}`,
          `enabled=${!_dbEv?.disabled}`,
          `localFrame=${_dbLocF}`,
          `xmlRecFrame=${currentFrame}`, `xmlRecTC=${recTc}`,
          `sourceInFrame=${_dbEv?.sync?.sourceInFrame ?? '?'}`, `sourceTC=${srcTcStr ?? '—'}`,
          `burninOffsetFrames=${burninOffsetF ?? '—'}`, `refTC=${burninRefTc ?? '—'}`,
          `syncStatus=${_dbEv?.sync?.syncStatus ?? 'none'}`,
          `nativeStartTc=${_pmNativeStartTc ?? '—'}`
        );
      }
    }

    // ── QuickTime TC overlay ─────────────────────────────────────────────────
    // Always show source clock (camera TC from XML) — this matches the video burn-in
    // for any clip regardless of whether the proxy has an embedded tmcd.
    // _pmNativeStartTc is the proxy's file-level TC (sequence-level, possibly with
    // pre-roll), NOT the per-clip camera TC, so we never use it here for display.
    if (pmVidQtTcOverlay && pmVideo?.src) {
      pmVidQtTcOverlay.textContent = srcTcStr ?? framesToTC(currentFrame, fps);
      pmVidQtTcOverlay.style.display = '';
    } else if (pmVidQtTcOverlay) {
      pmVidQtTcOverlay.style.display = 'none';
    }
    // ── Now-playing banner ────────────────────────────────────────────────────
    _pmUpdateBanner(activeIdx);

    // ── Scrub bar ────────────────────────────────────────────────────────────
    if (pmScrub && !pmScrub._dragging) {
      pmScrub.value = Math.floor(_pmReadVideoMediaTimeSec() * fps + 1e-6);
    }

    // ── Burn-in canvas overlay ────────────────────────────────────────────────
    _pmUpdateBurninCanvas(activeIdx);
  }

  // ── Timeline playhead (always, every rAF) ───────────────────────────────
  // While nav-protect is active, clamp the playhead to the intended seek target.
  // In VFX Marker mode the seek went to marker.recIn (which may precede the clip's
  // recIn), so use the marker as the floor rather than the clip boundary to prevent
  // the playhead from jumping forward to the clip start.
  let phFrame = currentFrame;
  const playheadNavState = _pmGetNavProtectState(currentFrame, fps);
  if (playheadNavState.active && Number.isFinite(playheadNavState.floor) && currentFrame < playheadNavState.floor) {
    phFrame = playheadNavState.floor;
  }
  _pmScheduleTimelineDraw(phFrame);
}

// ─── rAF playback loop ──────────────────────────────────────────────────────
let _pmConfRefreshMs = 0; // throttle: update confidence display every 2s during playback
function _pmStartPlayRaf() {
  if (_pmPlayRafId) return;
  const loop = (ts) => {
    if (!pmVideo || pmVideo.paused || pmVideo.ended) {
      _pmPlayRafId = 0;
      _pmSyncFrame();
      try { window.__pmUpdateSyncDisplay?.(); } catch {} // final display refresh on stop
      return;
    }
    _pmSyncFrame();
    // Live confidence refresh every 2 s during playback
    if (_pmSyncManuallySet && ts - _pmConfRefreshMs > 2000) {
      _pmConfRefreshMs = ts;
      try { window.__pmUpdateSyncDisplay?.(); } catch {}
    }
    _pmPlayRafId = requestAnimationFrame(loop);
  };
  _pmPlayRafId = requestAnimationFrame(loop);
}

function _pmStopPlayRaf() {
  if (_pmPlayRafId) { cancelAnimationFrame(_pmPlayRafId); _pmPlayRafId = 0; }
}

// Legacy alias used by timeupdate (still fires on seek/pause for free sync)
function _pmOnVideoTimeUpdate() { _pmSyncFrame(); }

// ── Subtitle overlay — shows shot name / note from the active event in the viewer
function _pmUpdateSubOverlay(evIdx) {
  if (!pmSubOverlay) return;
  if (!_pmTlShowSub || evIdx < 0) {
    pmSubOverlay.style.display = 'none';
    return;
  }
  const ev = _pmEvents[evIdx];
  if (!ev) { pmSubOverlay.style.display = 'none'; return; }

  const mk = _pmFindFirstLinkedMarker(evIdx);
  const proj = window.__MPS_EDL_RAW?.projectName || _pmComputeStem();
  const burninEntries = _pmBuildBurninEntries(_pmGetBurninSettings(), _pmBuildBurninContext({ mk, ev, proj }));
  if (!burninEntries.length) {
    pmSubOverlay.style.display = 'none';
    return;
  }

  pmSubOverlay.style.display = 'block';
  pmSubOverlay.innerHTML = _pmBuildBurninHtml(burninEntries);
}

// ─── PACK playlist helpers ──────────────────────────────────────────────────

// Returns events sorted by recIn for pack-mode playlist ordering.
// Falls back to _pmPackedMap order when available (respects QS filters).
function _pmPackSortedEvents() {
  const fps = _pmFps || 24;
  if (_pmPackedMap.size > 0) {
    // Use packed map — already filtered (VFX Rename / VFX Marker) and sorted
    return [..._pmPackedMap.entries()]
      .sort((a, b) => a[1].pIn - b[1].pIn)
      .map(([idx]) => ({ idx, ev: _pmEvents[idx] }))
      .filter(x => x.ev);
  }
  // Fallback: all events sorted by recIn
  return _pmEvents
    .map((ev, idx) => ({ idx, ev }))
    .filter(x => x.ev)
    .sort((a, b) =>
      tcToFrames(a.ev.recIn || '00:00:00:00', fps) -
      tcToFrames(b.ev.recIn || '00:00:00:00', fps)
    );
}

// Seek to the first event in pack order, then call pmVideo.play().
// Use this instead of pmVideo.play() directly when pack mode is on.
function _pmPackPlay() {
  if (!pmVideo) return;
  const fps = _pmFps || 24;
  const sorted = _pmPackSortedEvents();
  if (!sorted.length) { pmVideo.play().catch(() => {}); return; }

  // If already sitting inside a valid event, just play from here
  if (_pmActiveEventIdx >= 0 && sorted.some(x => x.idx === _pmActiveEventIdx)) {
    pmVideo.play().catch(() => {});
    return;
  }

  // Find first event whose recIn is >= current video position (or start from top)
  const currentAbsF = _pmReadVideoAbsFrame();
  let target = sorted[0];
  for (const item of sorted) {
    const eIn = tcToFrames(item.ev.recIn || '00:00:00:00', fps);
    if (eIn >= currentAbsF) { target = item; break; }
  }

  const targetInF = tcToFrames(target.ev.recIn || '00:00:00:00', fps);
  _pmSetActiveRow(target.idx);
  _pmUpdateInspector(target.idx, false);
  // Arm nav-protect BEFORE the seek so that if the browser keyframe-snaps to
  // a position slightly before target.eIn, _pmSyncFrame won't see activeIdx=-1
  // and immediately fire _pmPackAdvance, skipping the first clip entirely.
  _pmSeekVideoAbsFrame(targetInF, { navTarget: target.idx });
  pmVideo.play().catch(() => {});
}

// Called when the playhead exits event `fromIdx` during PACK playback.
// Finds the next segment in pack order and seeks to its real recIn.
// If no next segment exists, pauses (end of playlist).
function _pmPackAdvance(fromIdx) {
  if (!pmVideo) return;
  const fps    = _pmFps || 24;
  const sorted = _pmPackSortedEvents();
  if (!sorted.length) { pmVideo.pause(); return; }

  // Find fromIdx's position in the sorted list
  const pos = sorted.findIndex(x => x.idx === fromIdx);
  if (pos < 0) { pmVideo.pause(); return; }

  // Compute fromIdx's absolute out-point.  Multi-track sequences can include
  // overlay events (titles, graphics) that share the same absolute [eIn,eOut)
  // range as the primary V1 clip.  They appear as separate entries in the pack
  // playlist immediately after the V1 clip.  If we naively take sorted[pos+1]
  // we might land on such an overlay whose recIn is identical to the clip we
  // just left, causing a re-seek to the same position and a permanent stall.
  // Instead, scan forward until we find an entry whose recIn is >= fromOut.
  const fromEv   = _pmEvents[fromIdx];
  const fromIn   = fromEv ? tcToFrames(fromEv.recIn  || '00:00:00:00', fps) : 0;
  const fromROut = fromEv ? tcToFrames(fromEv.recOut || '00:00:00:00', fps) : 0;
  const fromOut  = fromROut > fromIn ? fromROut
                 : fromEv?.durationFrames ? fromIn + Number(fromEv.durationFrames)
                 : fromIn + 1;

  let nextPos = pos + 1;
  while (nextPos < sorted.length) {
    const cIn = tcToFrames(sorted[nextPos].ev.recIn || '00:00:00:00', fps);
    if (cIn >= fromOut) break;  // found first entry that starts after fromOut
    nextPos++;                   // skip overlapping overlay
  }
  const next = nextPos < sorted.length ? sorted[nextPos] : null;

  if (next) {
    const nextInF = tcToFrames(next.ev.recIn || '00:00:00:00', fps);
    _pmSetActiveRow(next.idx);   // update row highlight immediately, don't wait for _pmSyncFrame
    _pmUpdateInspector(next.idx, false);
    _pmSeekVideoAbsFrame(nextInF, { navTarget: next.idx });
  } else {
    // Last segment finished — end of playlist
    pmVideo.pause();
  }
}

let _pmRafId        = 0;
let _pmPlayRafId    = 0;     // rAF loop running during video playback
let _pmResizeRetryId = 0;    // rAF retry when container has zero width
let _pmLastSyncedF  = -1;    // last frame we synced pull-list/HUD to (avoid redundant DOM work)
let _pmSeekTargetF  = -1;    // intended seek target frame — corrects browser keyframe-snap in _pmSyncFrame
let _pmTlDragging      = false; // true while user drags the playhead
let _pmTlDidDrag       = false; // true from mouseup until the trailing click is consumed
let _pmTlResizing      = false; // true while user drags track height
let _pmTlResizeDragY   = 0;     // mousedown Y for track resize
let _pmTlResizeStartH  = 0;     // track height at drag start
let _pmTlHoverX        = -1;    // canvas x of mouse hover (-1 = off)

// Offscreen double-buffer — all drawing goes here; visible canvas gets a single atomic blit
let _pmOfc    = null;
let _pmOfcCtx = null;
let _pmDpr    = 1;   // devicePixelRatio snapshot — set in _pmResizeTlCanvas

function _pmScheduleTimelineDraw(frame) {
  _pmTlPlayhead = frame - _pmSeqBaseFrames;

  if (_pmTlCanvas && !_pmTlDragging) {
    const totalF = _pmTlPack ? Math.max(1, _pmPackedTotal) : Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
    const visF   = totalF / Math.max(0.001, _pmTlZoom);
    const maxPan = Math.max(0, totalF - visF);

    // Resolve playhead position in pan-space (pack mode needs remapping)
    let phPanF = _pmTlPlayhead;
    if (_pmTlPack) {
      const absF = _pmTlPlayhead + _pmSeqBaseFrames;
      for (const [, pm] of _pmPackedMap) {
        if (absF >= pm.eIn && absF < pm.eOut) { phPanF = pm.pIn + (absF - pm.eIn); break; }
      }
    }

    const targetPan = Math.max(0, Math.min(maxPan, phPanF - 0.25 * visF));

    if (pmVideo && !pmVideo.paused) {
      // During playback: smooth lerp at 10%/frame → ~0.5 s settle at 60 fps
      _pmTlPanFr += (targetPan - _pmTlPanFr) * 0.10;
    } else {
      // Paused (row click / seek / scrub): snap immediately if playhead left the visible zone
      const margin = visF * 0.15;
      const phVisible = phPanF >= _pmTlPanFr + margin && phPanF <= _pmTlPanFr + visF - margin;
      if (!phVisible) _pmTlPanFr = targetPan;
    }

    _tlClampPan();
  }

  _pmScheduleDraw();
}

// Single RAF-debounced draw scheduler — all code should call this instead of _pmDrawNLE() directly.
// Guarantees exactly one _pmDrawNLE() per animation frame no matter how many callers fire.
function _pmScheduleDraw() {
  // Every call here is triggered by a view-state change (zoom, pan, toggle, scroll).
  // Queue a debounced persist BEFORE the rAF early-return, so a burst of changes
  // still results in a save (throttled to ~400 ms) instead of only the first call.
  _pmTlViewSaveSoon();
  if (_pmRafId) return;
  _pmRafId = requestAnimationFrame(() => { _pmRafId = 0; _pmDrawNLE(); _pmUpdateInfoRail(); });
}

// Scrub video + timeline to a canvas x-coordinate
function _pmTlScrubTo(x) {
  const fps     = _pmFps || 24;

  // Pack mode: map x → packed frame → find event → seek to that position in clip.
  if (_pmTlPack) {
    const packF = _tlFrameV(x);
    for (const [idx, pm] of _pmPackedMap) {
      if (packF >= pm.pIn && packF < pm.pOut) {
        const offset = packF - pm.pIn;
        const absF   = pm.eIn + offset;
        // Update active row immediately so HUD reflects the new clip without
        // waiting for timeupdate (which lags on long seeks).
        if (idx !== _pmActiveEventIdx) _pmSetActiveRow(idx);
        // Arm nav-protect BEFORE seeking.  Without this, if the browser
        // keyframe-snaps to a frame before absF (i.e. before pm.eIn), _pmSyncFrame
        // sees activeIdx=-1 and fires _pmPackAdvance, jumping to the NEXT clip
        // instead of staying on the one the user explicitly scrubbed to.
        if (pmVideo) _pmSeekVideoAbsFrame(absF, { navTarget: idx, syncNow: true });
        _pmUpdateInspector(idx, false);
        // Store seq-relative (drawing code always expects: absF - seqBase).
        // packF is pack-relative and would give a wrong absF in _pmDrawNLE.
        _pmScheduleTimelineDraw(absF);
        return;
      }
    }
    return;
  }

  const totalF  = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  let   seqF    = _tlFrame(x);

  // Snap to nearest cut point if snap is enabled
  if (_pmTlSnap && _pmEvents.length) {
    const snapRadiusPx = 8;
    const frPerPx = totalF / (_pmTlZoom * Math.max(1, (_pmTlCanvas ? _pmTlCanvas.width / (_pmDpr || 1) : 800) - _NLE_HEADER_W));
    const snapRadiusFr = snapRadiusPx * frPerPx;
    let bestDist = snapRadiusFr, bestF = null;
    for (const ev of _pmEvents) {
      if (!ev) continue;
      const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps) - _pmSeqBaseFrames;
      const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
      const eOut = (rOut > tcToFrames(ev.recIn || '00:00:00:00', fps)
        ? rOut : ev.durationFrames ? tcToFrames(ev.recIn || '00:00:00:00', fps) + Number(ev.durationFrames) : tcToFrames(ev.recIn || '00:00:00:00', fps) + 1) - _pmSeqBaseFrames;
      for (const pt of [eIn, eOut]) {
        const d = Math.abs(seqF - pt);
        if (d < bestDist) { bestDist = d; bestF = pt; }
      }
    }
    if (bestF !== null) seqF = bestF;
  }

  const clampedSeqF = Math.max(0, Math.min(totalF, seqF));
  const absF        = _pmSeqBaseFrames + clampedSeqF;
  _pmTlPlayhead     = clampedSeqF;
  if (pmVideo) _pmSeekVideoAbsFrame(absF, { syncNow: true });
  else _pmSyncFrame();
}

// ─── Auto-focus: pan + zoom NLE timeline to show an event ────────────────────
// Called on every event-row click so the timeline always frames the selected clip.
// Zoom is set so the event occupies ~60% of the visible window; the event is centred.
// Handles both normal and PACK modes.
function _pmTlFocusEvent(evIdx) {
  if (!_pmTlCanvas) return;
  const ev = _pmEvents[evIdx];
  if (!ev) return;
  const fps = _pmFps || 24;

  let eIn, eOut, totalF;

  if (_pmTlPack) {
    const pm = _pmPackedMap.get(evIdx);
    if (!pm) {
      // Map not yet built — schedule draw then retry once (draw rAF fires first, map ready for retry).
      // If map is already populated but this event has no entry, bail to avoid infinite retry.
      if (_pmPackedMap.size > 0) return;
      _pmScheduleDraw();
      requestAnimationFrame(() => _pmTlFocusEvent(evIdx));
      return;
    }
    eIn    = pm.pIn;
    eOut   = pm.pOut;
    totalF = Math.max(1, _pmPackedTotal);
  } else {
    const absIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const absROut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const absOut  = absROut > absIn ? absROut
                  : ev.durationFrames ? absIn + Number(ev.durationFrames) : absIn + 1;
    eIn    = absIn  - _pmSeqBaseFrames;
    eOut   = absOut - _pmSeqBaseFrames;
    totalF = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  }

  const evDur = Math.max(1, eOut - eIn);

  // Set zoom so the event fills ~60% of the visible area.
  // Clamp: zoom ≥ 1 (never zoom out past full-seq view), zoom ≤ 500 (very short clips).
  const newZoom  = Math.max(1, Math.min(500, totalF / (evDur / 0.6)));
  const visibleF = totalF / newZoom;

  // Pan so the event is centred in the visible window.
  const newPan = Math.max(0, Math.min(totalF - visibleF, eIn - (visibleF - evDur) / 2));

  _pmTlZoom  = newZoom;
  _pmTlPanFr = newPan;
  _pmScheduleDraw();
}

// ─── Inspector — editable marker panel ───────────────────────────────────────
function _pmSelectMarker(id, seekAllowed = true) {
  _pmSelectedMarkerIds.clear();
  _pmSelectedMarkerId = id;
  const mk = _pmClipMarkers.find(m => m.id === id);
  if (mk) {
    const evIdx = _pmLinkMap.get(id) ?? mk._eventIdx ?? -1;
    if (evIdx >= 0) {
      _pmActiveEventIdx = evIdx;
      _pmHighlightEventRow(evIdx);
      _pmTlFocusEvent(evIdx);
    }
    // Immediately pin HUD to marker's recIn (before async seeked event fires)
    const recInTc = mk.recIn || mk.tcIn;
    const recInAbsF = tcToFrames(recInTc || '', _pmFps || 24);
    const recoveredSync = _pmMaybeRecoverMisarmedVfxSync(
      Number.isFinite(recInAbsF) && recInAbsF >= 0 ? { absF: recInAbsF, navTarget: evIdx } : null,
      { silent: false }
    );
    if (recInTc && !_pmTlDragging) {
      if (pmHudRecTc) pmHudRecTc.textContent = `REC ${recInTc}`;
      if (pmHudFrame) pmHudFrame.textContent  = `f ${tcToFrames(recInTc, _pmFps)}`;
    }
    // Seek video to marker's recIn (when allowed and not scrubbing)
    if (!recoveredSync && pmVideo && recInTc && seekAllowed && !_pmTlDragging) {
      _pmSeekVideoAbsFrame(recInAbsF, { navTarget: evIdx });   // hold nav-protection so
                                                           // _pmSyncFrame won't override when
                                                           // marker recIn falls outside the linked event's TC range
      _pmScheduleTimelineDraw(recInAbsF);
    }
  }
  _pmRenderInspector();
  _pmAnnotDraw();
}

function _pmHighlightEventRow(idx) {
  pmEventBody?.querySelectorAll('tr.pm-row').forEach(tr => {
    const match = parseInt(tr.dataset.i, 10) === idx;
    tr.classList.toggle('pm-row-active', match);
    if (match && tr.offsetParent !== null) tr.scrollIntoView({ block: 'nearest' });
  });
}

function _pmMarkerMatchesEventForInspector(mk, evIdx) {
  const ev = _pmEvents[evIdx];
  const fps = _pmFps || 24;
  if (!mk || !ev) return false;

  if (mk.recIn) {
    const mkF = tcToFrames(mk.recIn, fps);
    const eIn = tcToFrames(ev.recIn || '00:00:00:00', fps);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    if (!(mkF >= eIn && mkF < eOut)) return false;
  }

  if (mk.reel && ev.reel && !_pmLinkTextOverlap(mk.reel, ev.reel)) return false;
  return true;
}

function _pmGetLinkedMarkersForEvent(evIdx) {
  if (!(evIdx >= 0)) return [];
  return _pmClipMarkers.filter(mk =>
    _pmLinkMap.get(mk.id) === evIdx && _pmMarkerMatchesEventForInspector(mk, evIdx)
  );
}

function _pmSetIdsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const id of a) if (!b.has(id)) return false;
  return true;
}

function _pmNormalizeInspectorSelection(evIdx, { autoSelectFirst = false } = {}) {
  const linkedMarkers = _pmGetLinkedMarkersForEvent(evIdx);
  const linkedIds     = new Set(linkedMarkers.map(mk => mk.id));
  let changed         = false;

  if (_pmSelectedMarkerIds.size > 0) {
    const nextIds = new Set([..._pmSelectedMarkerIds].filter(id => linkedIds.has(id)));
    if (!_pmSetIdsEqual(_pmSelectedMarkerIds, nextIds)) {
      _pmSelectedMarkerIds = nextIds;
      changed = true;
    }
    if (_pmSelectedMarkerIds.size === 1) {
      const [onlyId] = [..._pmSelectedMarkerIds];
      if (_pmSelectedMarkerId !== onlyId) {
        _pmSelectedMarkerId = onlyId;
        changed = true;
      }
      _pmSelectedMarkerIds.clear();
      // Don't unconditionally set changed = true here — the clear collapses a
      // single-item multi-select into _pmSelectedMarkerId (already done above).
      // Setting changed regardless caused 60fps inspector re-renders during
      // video playback in VFX Marker mode.
    }
  }

  if (_pmSelectedMarkerId && !linkedIds.has(_pmSelectedMarkerId)) {
    _pmSelectedMarkerId = null;
    changed = true;
  }

  if (!linkedMarkers.length) {
    if (_pmSelectedMarkerIds.size > 0) {
      _pmSelectedMarkerIds.clear();
      changed = true;
    }
    return { linkedMarkers, selectedId: null, changed };
  }

  if (autoSelectFirst && !_pmSelectedMarkerId && _pmSelectedMarkerIds.size === 0) {
    _pmSelectedMarkerId = linkedMarkers[0].id;
    changed = true;
  }

  return {
    linkedMarkers,
    selectedId: _pmSelectedMarkerIds.size > 1 ? null : _pmSelectedMarkerId,
    changed,
  };
}

// Called from row click in event table — multi-layer VFX panel
function _pmUpdateInspector(idx, seekAllowed = true) {
  _pmActiveEventIdx = idx;
  const recInAbsF = tcToFrames(_pmEvents[idx]?.recIn || '', _pmFps || 24);
  _pmMaybeRecoverMisarmedVfxSync(
    Number.isFinite(recInAbsF) && recInAbsF >= 0 ? { absF: recInAbsF, navTarget: idx } : null,
    { silent: false }
  );
  const { selectedId } = _pmNormalizeInspectorSelection(idx, { autoSelectFirst: true });
  // Auto-show the current event's first linked marker when the old selection
  // no longer matches the active clip. If the clip has no marker, the detail
  // card collapses automatically on the render below.
  if (selectedId) {
    _pmSelectMarker(selectedId, seekAllowed);
    return;
  }
  _pmRenderInspector(idx);
}

// ─── Thumbnail capture ────────────────────────────────────────────────────────

// Grab a thumbnail via the companion native helper (for ProRes and other
// browser-unsupported codecs). Fire-and-forget safe — awaiting is optional.
// attempt: internal retry counter (0 = first try; 1 = after ASSET_NOT_FOUND re-open).
async function _pmCaptureThumbnailNative(mk, onDone, attempt = 0) {
  const thumbTc = mk.tcIn || mk.recIn;
  const _captureProjectKey = _pmCurrentProjectKey;
  const _captureAssetId    = _pmNativeAssetId;
  const ownAssetId = _pmNativeAssetId;
  if (!_pmNativeAssetId || !thumbTc) {
    console.warn('[PM] grabThumb skipped: assetId=', _pmNativeAssetId, 'tc=', thumbTc);
    if (onDone) onDone();
    return;
  }
  // Detect sequence-TC fallback: when the EDL has no srcIn, tcIn === recIn and
  // the timecode is a sequence position, not a source-clip TC.  Tell the companion
  // to skip the embedded-startTimecode offset and seek to frame 0 so the user at
  // least sees the first frame of the clip rather than an ffmpeg seek-past-EOF error.
  const isSeqFallback = mk.tcIn === mk.recIn;
  console.log('[PM] grabThumb assetId:', _pmNativeAssetId, 'tc:', thumbTc, 'seekMode:', isSeqFallback ? 'sequence_fallback' : 'source_tc', 'attempt:', attempt);
  try {
    // Bound the companion seek so a hung/slow decode can't freeze the preview —
    // a timeout throws into the catch below, which clears the loading state.
    const result = await withTimeout(nativeGrabThumbnailAtTimecode(_pmNativeAssetId, thumbTc, {
      width: 320, height: 180, format: 'jpg', mode: 'fast',
      seekMode: isSeqFallback ? 'sequence_fallback' : 'source_tc',
    }), 9000, 'PM thumbnail');
    console.log('[PM] grabThumb result status:', result?.status, 'url:', result?.data?.url?.slice(0,60));
    // The bridge always resolves (never throws) for companion error envelopes.
    // Check result.status before accessing result.data to surface real error text.
    if (result?.status === 'error') {
      const code = result?.error?.code || '';
      // ASSET_NOT_FOUND after a Chrome service-worker restart: the native host process
      // was recycled and its _asset_registry is empty.  Re-open the file automatically
      // (we have the path from _pmVideoFile) and retry once — no user interaction needed.
      if (code === 'ASSET_NOT_FOUND' && attempt === 0 && _pmVideoFile?._nativePath) {
        try {
          let reopenResp = null;
          try { reopenResp = await sharedMediaOpen(_pmVideoFile._nativePath); } catch {}
          if (!reopenResp?.data?.assetId && !reopenResp?.data?.sessionId) {
            reopenResp = await nativeOpenFile(_pmVideoFile._nativePath);
          }
          const newId = reopenResp?.data?.sessionId || reopenResp?.data?.assetId;
          if (newId) {
            _pmNativeAssetId = newId;
            if (reopenResp.data.fps)            _pmNativeFps     = reopenResp.data.fps;
            if (reopenResp.data.startTimecode)  _pmNativeStartTc = reopenResp.data.startTimecode;
            return _pmCaptureThumbnailNative(mk, onDone, 1);
          }
        } catch { /* fall through to show error */ }
      }
      const errMsg = result?.error?.userMessage || result?.error?.message || 'Companion thumbnail failed';
      console.warn('[PM] companion error:', errMsg);
      mk._thumbError = errMsg;
      if (onDone) onDone(); else _pmRenderInspector();
      return;
    }
    // Prefer base64 dataUrl returned inline by companion — no HTTP round-trip needed.
    // Fall back to HTTP fetch of result.data.url for older companion versions.
    let imgSrc = result?.data?.dataUrl || result?.data?.url;
    console.log('[PM] grabThumb imgSrc type:', imgSrc?.startsWith('data:') ? 'dataUrl' : imgSrc?.startsWith('http') ? 'httpUrl' : 'none');
    if (imgSrc?.startsWith('http')) {
      try {
        const resp = await _pmCompanionFetch(imgSrc);
        if (_pmNativeAssetId !== _captureAssetId) { if (onDone) onDone(); return; }
        if (resp.ok) {
          const blob = await resp.blob();
          if (_pmNativeAssetId !== _captureAssetId) { if (onDone) onDone(); return; }
          imgSrc = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload  = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
          });
        } else {
          console.warn('[PM] companion thumb HTTP error', resp.status);
          mk._thumbError = `Thumb HTTP ${resp.status}`;
          if (onDone) onDone(); else _pmRenderInspector();
          return;
        }
      } catch (fetchErr) {
        console.warn('[PM] companion thumb fetch failed', fetchErr);
        mk._thumbError = 'Network error fetching thumbnail';
        if (onDone) onDone(); else _pmRenderInspector();
        return;
      }
    }
    // Re-find the live marker by ID — _pmLoadProjectData() may have rebuilt
    // _pmClipMarkers between the async fetch start and now, orphaning the original
    // mk reference. Writing to it would silently lose the thumbnail.
    if (_pmCurrentProjectKey !== _captureProjectKey) { if (onDone) onDone(); return; }
    const liveMk = _pmClipMarkers.find(m => m.id === mk.id) || mk;
    if (imgSrc) {
      liveMk.thumb = imgSrc;
      delete liveMk._thumbError;
      window.MPS_markProjectDirty?.();
      if (onDone) onDone();
      else _pmRenderInspector();
    } else {
      liveMk._thumbError = 'Companion returned no image';
      if (onDone) onDone(); else _pmRenderInspector();
    }
  } catch (e) {
    const msg = String(e?.message || e?.userMessage || '');
    // AssetId rejected by companion (process restarted, session expired) — clear so
    // future thumbnail requests skip immediately rather than hammering a dead session.
    if (msg.toLowerCase().includes('unknown assetid') || msg.toLowerCase().includes('asset_not_found')) {
      _pmNativeAssetId = null;
    }
    console.debug('[PM] companion thumb grab failed', msg);
    const liveMkErr = _pmClipMarkers.find(m => m.id === mk.id) || mk;
    liveMkErr._thumbError = isTimeout(e) ? 'Thumbnail timed out — companion busy or offline'
      : (e?.userMessage || e?.message || 'Companion thumbnail failed');
    if (onDone) onDone(); else _pmRenderInspector();
  }
}

function _pmCaptureThumbnail(mk, seekFirst, onDone) {
  const _canCaptureCurrentVideoFrame = () =>
    !!(pmVideo && pmVideo.readyState >= 2 && pmVideo.videoWidth && pmVideo.videoHeight);
  const _captureCurrentFrameDataUrl = () => {
    const W = Math.min(pmVideo.videoWidth || 1920, 1920);
    const H = Math.round(W * (pmVideo.videoHeight || 1080) / Math.max(1, pmVideo.videoWidth || 1920));
    const offscreen = document.createElement('canvas');
    offscreen.width  = W;
    offscreen.height = H || Math.round(W * 9 / 16);
    offscreen.getContext('2d').drawImage(pmVideo, 0, 0, W, offscreen.height);
    return offscreen.toDataURL('image/png');
  };
  const _finish = () => {
    if (onDone) onDone();
    else _pmRenderInspector();
  };

  // Primary path: HTML5 video element (H.264, H.265, VP9, etc.)
  if (_canCaptureCurrentVideoFrame()) {
    const fps = _pmFps || 24;
    const doCapture = () => {
      try {
        mk.thumb = _captureCurrentFrameDataUrl();
        delete mk._thumbError;
        window.MPS_markProjectDirty?.();
      } catch (err) {
        console.warn('[PM] thumb capture failed', err);
        mk._thumbError = err?.message || 'Thumbnail capture failed';
      }
      _finish();
    };
    if (seekFirst && mk.recIn) {
      const targetF = tcToFrames(mk.recIn, fps);
      const targetT = Math.max(0, (targetF - _pmVidZero()) / fps);
      const threshold = 0.5 / Math.max(1, fps);
      if (!pmVideo.seeking && Math.abs(Number(pmVideo.currentTime || 0) - targetT) <= threshold) {
        requestAnimationFrame(doCapture);
      } else {
        let settled = false;
        const finishSeek = () => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          try { pmVideo.removeEventListener('seeked', finishSeek); } catch {}
          doCapture();
        };
        const timer = setTimeout(finishSeek, 1200);
        pmVideo.addEventListener('seeked', finishSeek, { once: true });
        try { pmVideo.currentTime = targetT; }
        catch {
          finishSeek();
        }
      }
    } else {
      doCapture();
    }
    return;
  }

  // Fallback: companion native helper (ProRes and any codec Chrome can't decode)
  // Only when the file is NOT browser-decodable — for canPlay files the HTML5
  // video element should be used and if it wasn't ready we just skip.
  if (_pmNativeAssetId && !_pmNativeCanPlay) {
    _pmCaptureThumbnailNative(mk, onDone);
    return;
  }

  console.log('[PM] captureThumbnail skipped — readyState:', pmVideo?.readyState, 'videoWidth:', pmVideo?.videoWidth, 'native:', _pmNativeAssetId, 'canPlay:', _pmNativeCanPlay);
  _finish();
}

// Capture thumbnails for all markers linked to `evIdx` that don't have one yet.
async function _pmBatchCaptureEventThumbs(evIdx) {
  const targets = _pmClipMarkers.filter(mk =>
    !mk.thumb && !mk._thumbCapturing && !mk._thumbError && mk.recIn &&
    (_pmLinkMap.get(mk.id) === evIdx || evIdx < 0)
  );
  if (!targets.length) return;

  const fps = _pmFps || 24;
  const _batchKey = _pmCurrentProjectKey;

  // Companion path (ProRes / non-decodable)
  if (_pmNativeAssetId && !_pmNativeCanPlay) {
    for (const mk of targets) {
      mk._thumbCapturing = true;
    }
    _pmRenderInspector(evIdx);
    for (const mk of targets) {
      await new Promise(resolve => _pmCaptureThumbnailNative(mk, () => {
        mk._thumbCapturing = false;
        resolve();
      }));
    }
    _pmRenderInspector(evIdx);
    _pmRenderEventTable();
    return;
  }

  // Browser video path
  if (!pmVideo?.src || pmVideo.readyState < 2 || !pmVideo.videoWidth || !pmVideo.videoHeight) return;
  targets.forEach(mk => { mk._thumbCapturing = true; });
  _pmRenderInspector(evIdx);

  // Only capture markers whose recIn frame the video is ALREADY at.
  // Never seek pmVideo for background thumbnail capture — seeking disrupts the
  // user's current frame and causes Annotate to open at the wrong position.
  // The ↺ recapture button (seekFirst=true) handles explicit seeks when needed.
  const freshIds = new Set();
  const threshold = 0.5 / Math.max(1, fps);
  for (const mk of targets) {
    const targetT = Math.max(0, (tcToFrames(mk.recIn, fps) - _pmVidZero()) / fps);
    if (pmVideo.seeking || Math.abs(Number(pmVideo.currentTime || 0) - targetT) > threshold) {
      mk._thumbCapturing = false;
      continue;
    }
    await new Promise(resolve => {
      requestAnimationFrame(() => {
        if (_pmCurrentProjectKey !== _batchKey || !pmVideo?.src || pmVideo.readyState < 2) { mk._thumbCapturing = false; resolve(); return; }
        try {
          const W = Math.min(pmVideo.videoWidth, 1920);
          const H = Math.round(W * pmVideo.videoHeight / Math.max(1, pmVideo.videoWidth)) || Math.round(W * 9 / 16);
          const c = document.createElement('canvas');
          c.width = W; c.height = H;
          c.getContext('2d').drawImage(pmVideo, 0, 0, W, H);
          mk.thumb = c.toDataURL('image/png');
          delete mk._thumbError;
          freshIds.add(mk.id);
        } catch (err) {
          console.warn('[PM] batch thumb capture failed', err);
          mk._thumbError = err?.message || 'Thumbnail capture failed';
        }
        mk._thumbCapturing = false;
        resolve();
      });
    });
  }

  // Composite annotation overlays for freshly captured frames
  for (const mk of targets) {
    if (!freshIds.has(mk.id) || !mk.thumb) continue;
    const key = mk._annotTcKey || mk.recIn;
    const annoUrl = key ? _pmAnnotMap.get(key)?.annoDataUrl : null;
    if (annoUrl) await new Promise(resolve => _pmCompositeThumb(mk, annoUrl, resolve));
  }

  window.MPS_markProjectDirty?.();
  _pmRenderInspector(evIdx);
  _pmRenderEventTable();
}

function _pmRenderInspector(fallbackEvIdx) {
  if (!pmInspector) return;
  // Re-entry guard: openNamingTemplateStatic (called during this render) may
  // call __pmApplyShotName → _pmCommitShotNameChange → _pmRenderInspector.
  // Blocking that second entry prevents the infinite naming-template loop.
  // _pmCommitShotNameChange will defer the re-render via setTimeout when it
  // detects __pmRenderingInspector === true.
  if (__pmRenderingInspector) return;
  __pmRenderingInspector = window.__pmRenderingInspector = true;
  try {
  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  // Determine active event index
  const evIdx = (_pmActiveEventIdx >= 0) ? _pmActiveEventIdx : (fallbackEvIdx ?? -1);
  const ev = (evIdx >= 0) ? _pmEvents[evIdx] : null;

  if (!ev) {
    pmInspector.innerHTML = '<div class="pm-insp-empty">Select an event or marker</div>';
    _pmSyncFsInspOverlay();
    return;
  }

  // Multi-select batch panel
  if (_pmSelectedMarkerIds.size > 1) {
    const selMks = _pmClipMarkers.filter(mk => _pmSelectedMarkerIds.has(mk.id));
    const colorSwatches = _PM_MARKER_COLORS.map(c =>
      `<button class="pm-insp-color-swatch pm-batch-color" data-color="${esc(c.name)}"
               style="background:${c.hex}" title="${esc(c.name)} Locator"></button>`
    ).join('');
    pmInspector.innerHTML = `
      <div class="pm-batch-panel" data-evidx="${evIdx}" data-selected="" data-linkedcount="${selMks.length}">
        <div class="pm-batch-title">${selMks.length} markers selected <button class="pm-batch-clear" title="Clear selection">✕</button></div>
        <div class="pm-batch-row">
          <span class="pm-batch-label">Color</span>
          <div class="pm-insp-color-row">${colorSwatches}</div>
        </div>
        <div class="pm-batch-row">
          <span class="pm-batch-label">Status</span>
          ${_STATUSES.map(s => `<button class="pm-batch-status pm-status-${s}" data-status="${s}">${_STATUS_LABELS[s]||s}</button>`).join('')}
        </div>
      </div>`;
    // Wire batch color
    pmInspector.querySelectorAll('.pm-batch-color').forEach(btn => {
      btn.addEventListener('click', () => {
        const color = btn.dataset.color;
        for (const mk of selMks) { mk.color = color; }
        _pmSaveClipMarkers();
        window.MPS_markProjectDirty?.();
        _pmPushTimelineData();
        _pmRenderInspector(evIdx);
      });
    });
    // Wire batch status
    pmInspector.querySelectorAll('.pm-batch-status').forEach(btn => {
      btn.addEventListener('click', () => {
        const status = btn.dataset.status;
        for (const mk of selMks) {
          // Use the linked event's status key so the pull list table stays in sync.
          const _bsEi = _pmLinkMap.get(mk.id) ?? mk._eventIdx ?? -1;
          const _bsEv = _bsEi >= 0 ? _pmEvents[_bsEi] : null;
          const _bsKey = _bsEv ? _pmStatusKey(_bsEv) : `${mk.reel||''}|${mk.tcIn||''}`;
          _pmStatusMap.set(_bsKey, status);
        }
        _pmSaveStatus();
        window.MPS_markProjectDirty?.();
        _pmRenderEventTable();
        _pmRenderInspector(evIdx);
      });
    });
    // Wire clear
    pmInspector.querySelector('.pm-batch-clear')?.addEventListener('click', () => {
      _pmSelectedMarkerIds.clear();
      _pmRenderInspector(evIdx);
    });
    _pmSyncFsInspOverlay();
    return;
  }

  const { linkedMarkers, selectedId } = _pmNormalizeInspectorSelection(evIdx, { autoSelectFirst: false });

  const dur = ev.durationFrames || (
    tcToFrames(ev.recOut || '00:00:00:00', _pmFps) - tcToFrames(ev.recIn || '00:00:00:00', _pmFps)
  );

  const statusColors = { none:'#3a3a58', pulled:'#61afef', delivered:'#e5c07b', approved:'#4caf80' };

  // Build layer accordion rows
  const layerHTML = linkedMarkers.map((mk, li) => {
    const isExp  = mk.id === selectedId;
    // Status key: prefer the linked event's key (ev.reel|ev.srcIn) so that status
    // set here round-trips correctly to the pull list table. Fall back to the
    // marker's own key only for orphan markers (no linked event).
    const _mkLinkedEi = _pmLinkMap.get(mk.id) ?? mk._eventIdx ?? -1;
    const _mkLinkedEv = _mkLinkedEi >= 0 ? _pmEvents[_mkLinkedEi] : null;
    const _mkStatusKey = _mkLinkedEv ? _pmStatusKey(_mkLinkedEv) : `${mk.reel||''}|${mk.tcIn||''}`;
    const status = _pmStatusMap.get(_mkStatusKey) || 'none';
    const sc     = statusColors[status] || '#3a3a58';

    // Tiny thumbnail for collapsed header
    const xsThumb = mk.thumb
      ? `<img class="pm-layer-thumb-xs" src="${esc(mk.thumb)}" alt="" title="Frame at ${esc(mk.recIn||'')}">`
      : `<span class="pm-layer-thumb-xs pm-layer-thumb-xs-empty"></span>`;

    // ── Build annotation note list in format: "1) Rectangle — Add: Matte" ───────
    const _AK = { rect:'Rectangle', ellipse:'Circle', arrow:'Arrow', text:'Text' };
    const _kindLabel = s => {
      const k = String(s?.kind || '').toLowerCase();
      return _AK[k] || (k === 'stroke' ? (String(s?.mode||'').toLowerCase() === 'highlighter' ? 'Highlighter' : 'Pen') : 'Shape');
    };
    const _annoLine = s => {
      const group = s.g ? (s.g[0].toUpperCase() + s.g.slice(1)) : '';
      const type  = s.t || '';
      const ntPart = (group && type) ? ` ${group}: ${type}` : (type ? ` ${type}` : (group ? ` ${group}` : ''));
      return `<div class="pm-insp-anno-line">${s.idx})${esc(ntPart)}</div>`;
    };
    let annoListHtml = '';
    if (Array.isArray(mk.annotationSummary) && mk.annotationSummary.length) {
      // Primary path: pre-computed summary (set on annotation commit)
      annoListHtml = mk.annotationSummary.map(_annoLine).join('');
    } else {
      // Fallback: reconstruct from _pmAnnotMap shapes + marker's saved note type
      // Use _annotTcKey (exact key stored at annotation time) to avoid TC rounding mismatches
      const tcKey    = mk._annotTcKey || mk.recIn || null;
      // Exact lookup first; if miss, try ±1 frame (TC rounding from async seek)
      let mapEntry = tcKey ? _pmAnnotMap.get(tcKey) : null;
      if (!mapEntry?.shapes?.length && tcKey && _pmFps > 0) {
        const baseF = tcToFrames(tcKey, _pmFps);
        for (const delta of [-1, 1, -2, 2]) {
          const alt = framesToTC(baseF + delta, _pmFps);
          const e   = _pmAnnotMap.get(alt);
          if (e?.shapes?.length) { mapEntry = e; break; }
        }
      }
      const fbG      = String(mk.noteTypeGroup || '');
      const fbT      = String(mk.noteType      || '');
      if (mapEntry?.shapes?.length) {
        const lines = mapEntry.shapes
          .filter(s => s?.kind && s.kind !== 'erase')
          .map((s, i) => {
            const g = String(s?.meta?.g || fbG);
            const t = String(s?.meta?.t || fbT);
            return { idx: i + 1, kind: _kindLabel(s), g, t, sow: String(s?.meta?.sow || '') };
          });
        annoListHtml = lines.map(_annoLine).join('');
        // Cache result as annotationSummary so future renders skip fallback
        if (lines.length) mk.annotationSummary = lines;
      } else if (fbG || fbT) {
        const group  = fbG ? (fbG[0].toUpperCase() + fbG.slice(1)) : '';
        const ntPart = (group && fbT) ? `${group}: ${fbT}` : (fbT || group);
        annoListHtml = `<div class="pm-insp-anno-line">${esc(ntPart)}</div>`;
      }
    }

    let detail = '';
    if (isExp) {
      const namingQuick = _pmReadNamingTemplateQuickState(mk, _mkLinkedEv || ev, evIdx, li, linkedMarkers.length);
      const versionHasMeta = (namingQuick.versionTokens || []).length > 0;

      // Thumbnail (80×45) + TC fields side-by-side
      const thumbImg = mk.thumb
        ? `<img class="pm-layer-thumb-full" src="${esc(mk.thumb)}" alt=""
               data-mkid="${esc(mk.id)}" title="Click to seek to ${esc(mk.recIn||'')}">
           <button class="pm-layer-recapture" data-mkid="${esc(mk.id)}" title="Re-capture">↺</button>`
        : `<div class="pm-layer-thumb-full pm-layer-thumb-full-empty" data-mkid="${esc(mk.id)}">
             ${mk._thumbCapturing
               ? `<span class="pm-layer-thumb-status">capturing…</span>`
               : mk._thumbError
                 ? `<span class="pm-layer-thumb-status pm-layer-thumb-err" title="${esc(mk._thumbError)}">⚠ ${esc(mk._thumbError)}</span>
                    <button class="pm-layer-capture-btn" data-mkid="${esc(mk.id)}" title="Retry">↺</button>`
                 : `<button class="pm-layer-capture-btn" data-mkid="${esc(mk.id)}">
                      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"
                           stroke-linecap="round" stroke-linejoin="round" width="11" height="11">
                        <rect x="1" y="4" width="14" height="10" rx="1.5"/>
                        <circle cx="8" cy="9" r="2.8"/>
                        <path d="M5.5 4L6.5 2h3l1 2"/>
                      </svg>
                      📷
                    </button>`
             }
           </div>`;

      const _vfxFlagsHtml = (()=>{
        const _lev = _mkLinkedEv;
        const _rtD = _lev ? (_lev._pmRetime === true || (_lev._pmRetime == null && !!_lev._pmRetimeAuto)) : !!mk.retime;
        const _stD = _lev ? !!_lev._pmStabilize : !!mk.stabilize;
        const _rsD = _lev ? (_lev._pmResize === true || (_lev._pmResize == null && !!_lev._pmResizeAuto)) : !!mk.resize;
        return `<button class="pm-vfx-flag${_rtD ? ' active':''}" data-flag="retime"    title="Retime"    ><svg viewBox="0 0 12 12" width="10" height="10" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px"><circle cx="6" cy="6" r="4.5"/><polyline points="6,3.5 6,6 7.8,7.2"/><line x1="3.5" y1="1.2" x2="2" y2="0.2"/><line x1="8.5" y1="1.2" x2="10" y2="0.2"/></svg> Retime</button>
               <button class="pm-vfx-flag${_stD ? ' active':''}" data-flag="stabilize" title="Stabilize" >⊕ Stabilize</button>
               <button class="pm-vfx-flag${_rsD ? ' active':''}" data-flag="resize"    title="Resize"    >⤢ Resize</button>`;
      })();

      // ── De-retime merge: check if the immediately next event is the same source
      // clip, record-contiguous, and speed-retimed. If so, offer a button that
      // extends this marker's Src Out to absorb the retimed segment at normal speed.
      const _deretimeMerge = (() => {
        if (_mkLinkedEi < 0 || !mk.tcOut) return null;
        const nextEv = _pmEvents[_mkLinkedEi + 1];
        if (!nextEv?.srcIn || !nextEv?.srcOut || !nextEv?.recIn || !nextEv?.recOut) return null;
        // Must be record-contiguous (back-to-back cuts on the timeline)
        const fps_ = _pmFps || 24;
        if (Math.abs(tcToFrames(nextEv.recIn, fps_) - tcToFrames(_mkLinkedEv?.recOut || '00:00:00:00', fps_)) > 1) return null;
        // Must share the same source clip
        const sameReel = (_mkLinkedEv?.reel || '').trim().toUpperCase() === (nextEv.reel || '').trim().toUpperCase();
        const sameSrc  = (_mkLinkedEv?.srcFile || '') && (_mkLinkedEv.srcFile === nextEv.srcFile);
        if (!sameReel && !sameSrc) return null;
        // Must have a retime on the next segment
        const sf = _pmExtractSpeedPercent(nextEv);
        const hasDynamic = Array.isArray(nextEv.speedKeys) && nextEv.speedKeys.length > 0;
        const hasRetime  = nextEv._pmRetimeAuto || (sf != null && Math.abs(sf - 100) > 0.5) || hasDynamic;
        if (!hasRetime) return null;
        // Extend by the source duration of the next segment (works regardless of speed factor)
        const extFrames   = tcToFrames(nextEv.srcOut, fps_) - tcToFrames(nextEv.srcIn, fps_);
        if (extFrames <= 0) return null;
        const newTcOutF   = tcToFrames(mk.tcOut, fps_) + extFrames;
        const newTcOut    = framesToTC(newTcOutF, fps_);
        const speedLabel  = hasDynamic ? 'VarSpd' : sf != null ? `${Math.round(sf)}%` : 'RT';
        return { newTcOut, extFrames, speedLabel,
          tip: `Next segment is ${speedLabel} retimed (${extFrames}f source). Click to extend Src Out to ${newTcOut} — absorbs that shot at normal speed.\nYou can then delete the second marker.` };
      })();

      detail = `
        <div class="pm-layer-detail">
          <div class="pm-layer-thumb-wrap">
            ${thumbImg}
            <div class="pm-insp-vfx-flags pm-insp-vfx-flags--thumb">${_vfxFlagsHtml}</div>
          </div>
          <div class="pm-layer-tc-block">
            <div class="pm-insp-tc-row">
              <span class="pm-insp-lbl" title="Source Timecode — camera roll IN → OUT">SRC</span>
              <input class="pm-insp-tc" data-field="tcIn"  value="${esc(mk.tcIn ||'')}" placeholder="00:00:00:00" title="Source IN timecode">
              <span class="pm-insp-tc-sep">→</span>
              <input class="pm-insp-tc" data-field="tcOut" value="${esc(mk.tcOut||'')}" placeholder="00:00:00:00" title="Source OUT timecode">
              ${_deretimeMerge ? `<button class="pm-insp-deretime-btn" data-new-tcout="${esc(_deretimeMerge.newTcOut)}" title="${esc(_deretimeMerge.tip)}">+${_deretimeMerge.extFrames}f&nbsp;(${_deretimeMerge.speedLabel})</button>` : ''}
            </div>
            <div class="pm-insp-tc-row">
              <span class="pm-insp-lbl" title="Record Timecode — timeline position IN → OUT">REC</span>
              <input class="pm-insp-tc" data-field="recIn"  value="${esc(mk.recIn ||'')}" placeholder="00:00:00:00" title="Record IN timecode">
              <span class="pm-insp-tc-sep">→</span>
              <input class="pm-insp-tc" data-field="recOut" value="${esc(mk.recOut||'')}" placeholder="00:00:00:00" title="Record OUT timecode">
              ${mk._linkVerified === true
                  ? '<span class="pm-link-ok" title="Link verified — recIn, reel, and ALE all check out">✓</span>'
                  : mk._linkVerified === false
                    ? `<span class="pm-link-warn" title="${esc(mk._linkWarning || 'Link unverified')}">⚠</span>`
                    : ''}
            </div>
            <div class="pm-layer-note-col pm-layer-note-col--tc">
              <span class="pm-anno-inp-lbl" title="Annotation note for this marker">Note</span>
              <div class="pm-insp-anno-text">${annoListHtml}</div>
            </div>
          </div>
          <div class="pm-layer-detail-right">
            <div class="pm-nt-bar-wrap" data-mkid="${esc(mk.id)}"></div>
            <div class="pm-layer-addl-col">
              <textarea class="pm-insp-note" data-field="note" rows="1"
                placeholder="Additional note…">${esc(mk.note||'')}</textarea>
            </div>
          </div>
        </div>`;
    }

    const mkHex = _pmMarkerHex(mk.color || 'Green');
    const shotLocked = !!mk._pmShotLocked;
    return `
      <div class="pm-layer-row${isExp?' pm-layer-expanded':''}${_pmSelectedMarkerIds.has(mk.id)?' pm-layer-multi-sel':''}" data-mkid="${esc(mk.id)}">
        <div class="pm-layer-hdr" style="border-left:2px solid ${mkHex}">
          <span class="pm-layer-chevron">${isExp?'▼':'►'}</span>
          ${xsThumb}
          <span class="pm-layer-badge" style="color:${mkHex}">L${li+1}</span>
          <button class="pm-layer-color-btn" data-mkid="${esc(mk.id)}" style="background:${mkHex}" title="Change color"></button>
          <input class="pm-layer-shot${shotLocked ? ' is-locked' : ''}" data-field="shotName" data-mkid="${esc(mk.id)}"
                 value="${esc(mk.shotName||'')}" placeholder="Shot name…"
                 style="color:${mkHex}" spellcheck="false" autocomplete="off"
                 title="${shotLocked ? 'Shot name locked — unlock to edit.' : 'Click to edit shot name. Press Enter to save or Esc to cancel.'}"
                 ${shotLocked ? 'readonly aria-readonly="true"' : ''}>
          <button class="pm-shot-lock-btn${shotLocked ? ' is-locked' : ''}" data-mkid="${esc(mk.id)}" type="button" aria-pressed="${shotLocked ? 'true' : 'false'}" title="${shotLocked ? 'Unlock shot name' : 'Lock shot name'}">${shotLocked ? '🔒' : '🔓'}</button>
          <button class="pm-layer-ocr-btn" data-mkid="${esc(mk.id)}" type="button" title="OCR: read VFX shot name from video burn-in"${mk._ocrHistory?.length ? ' data-has-ocr="1"' : ''}>OCR</button>
          <button class="pm-layer-set-ocr-area-btn" data-mkid="${esc(mk.id)}" type="button" title="Draw OCR capture region on video">Set OCR Area</button>
          <button class="pm-layer-status" data-mkid="${esc(mk.id)}"
                  data-status="${status}" style="color:${sc}">${status}</button>
          <button class="pm-layer-del" data-mkid="${esc(mk.id)}" title="Delete this VFX layer">✕</button>
        </div>
        ${detail}
      </div>`;
  }).join('');

  const emptyMsg = linkedMarkers.length === 0
    ? '<div class="pm-layer-empty">No VFX layers — click <b>+ Add Layer</b> to begin</div>' : '';

  pmInspector.innerHTML = `
    <div class="pm-insp-layers" data-evidx="${evIdx}" data-selected="${esc(selectedId || '')}" data-linkedcount="${linkedMarkers.length}">
      <div class="pm-layers-list">${emptyMsg}${layerHTML}</div>
    </div>`;

  _wireInspectorEvents();
  _pmSyncFsInspOverlay();
  } finally {
    __pmRenderingInspector = window.__pmRenderingInspector = false;
  }
}

// Open the inline Naming Template chip bar bridged to a PM clip marker.
function _pmOpenNamingTemplate(mk, evIdx, buttonEl) {
  if (!mk) return;

  const linkedMks = evIdx >= 0
    ? _pmClipMarkers.filter(m => (_pmLinkMap.get(m.id) ?? m._eventIdx ?? -1) === evIdx)
    : [mk];
  const layerOrderIndex = Math.max(0, linkedMks.findIndex(m => m.id === mk.id));
  const quickBeforeOpen = _pmReadNamingTemplateQuickState(
    mk,
    evIdx >= 0 ? _pmEvents[evIdx] : null,
    evIdx >= 0 ? evIdx : 0,
    layerOrderIndex,
    linkedMks.length || 1
  );
  const keepPlateMode = !!quickBeforeOpen?.plateLike;
  if (keepPlateMode) {
    _pmPersistMarkerPlateContext(mk, {
      mode: 'plate',
      code: quickBeforeOpen.plateCode,
      num: quickBeforeOpen.plateNum,
      task: quickBeforeOpen.plateTask,
      vendor: quickBeforeOpen.plateVendor,
      ver: quickBeforeOpen.plateVer,
    });
  }

  // Inject into SM marker pool so the inline bar can find the marker
  const smPool = window.__smGetMarkersRef?.();
  const alreadyIn = Array.isArray(smPool) && smPool.some(m => m?.id === mk.id);
  if (Array.isArray(smPool) && !alreadyIn) smPool.push(mk);

  const cleanup = () => {
    if (Array.isArray(smPool) && !alreadyIn) {
      const idx = smPool.indexOf(mk);
      if (idx >= 0) smPool.splice(idx, 1);
    }
  };

  // Register callback so Apply in the inline bar syncs back to PM state
  window.__pmNamingTemplateApplied = (appliedId, newName) => {
    window.__pmNamingTemplateApplied = null;
    cleanup();
    if (!newName) return;
    const ei = evIdx >= 0 ? evIdx : (_pmLinkMap.get(mk.id) ?? -1);
    if (keepPlateMode) {
      _pmPersistMarkerPlateContext(mk, {
        mode: 'plate',
        code: quickBeforeOpen.plateCode,
        num: quickBeforeOpen.plateNum,
        task: quickBeforeOpen.plateTask,
        vendor: quickBeforeOpen.plateVendor,
        ver: quickBeforeOpen.plateVer,
      });
    }
    if (ei >= 0 && _pmEvents[ei]) _pmEvents[ei]._pmShot = newName;
    window.MPS_markProjectDirty?.();
    try { _pmSaveClipMarkers(); } catch {}
    try { _pmRenderEventTable(); } catch {}
    _pmRenderInspector(ei >= 0 ? ei : evIdx);
  };

  // Disconnect stale MutationObserver if any legacy popup was open
  if (_pmNamingTemplateObserver) {
    try { _pmNamingTemplateObserver.disconnect(); } catch {}
    _pmNamingTemplateObserver = null;
  }

  // Register marker so naming_template.js OCR chip can read mk.ocr
  window.__ntRegisterMarker?.(mk.id, mk);

  // Static mount (wrap div) = always-visible embedded bar; button = toggleable inline bar
  const isStaticMount = buttonEl?.classList?.contains('pm-nt-bar-wrap');
  try {
    if (isStaticMount) {
      window.__smOpenNamingTemplateStatic?.(mk.id, buttonEl);
    } else {
      window.__smOpenNamingTemplateInline?.(mk.id, buttonEl);
    }
  } catch (e) {
    console.warn('[PM] openNamingTemplate failed', e);
    cleanup();
    window.__pmNamingTemplateApplied = null;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// Smart OCR Shot Name — reads burn-in VFX name from video frame via Tesseract
// ═══════════════════════════════════════════════════════════════════════════

const _PM_OCR_REGIONS = {
  bottomCenter: { x: 0.25, y: 0.80, w: 0.50, h: 0.12 },
  bottomLeft:   { x: 0.00, y: 0.80, w: 0.30, h: 0.12 },
  bottomRight:  { x: 0.70, y: 0.80, w: 0.30, h: 0.12 },
  topLeft:      { x: 0.00, y: 0.02, w: 0.30, h: 0.10 },
  topRight:     { x: 0.70, y: 0.02, w: 0.30, h: 0.10 },
  fullFrame:    { x: 0.00, y: 0.00, w: 1.00, h: 1.00 },
};

function _pmGetOcrSettings() {
  try {
    const raw = localStorage.getItem(_lsKey('ocrSettings.v1'));
    const s = raw ? JSON.parse(raw) : {};
    // manualCrop is the user-drawn region saved as percentages {x,y,w,h}
    const manualCrop = s.manualCrop || s.customCrop || null;
    const detectionMode = s.detectionMode || 'vfxShotName';
    // Cleanup defaults differ by mode
    const anyTextMode = detectionMode === 'anyText';
    return {
      enabled:             s.enabled !== false,
      defaultRegion:       s.defaultRegion || (manualCrop ? 'manual' : 'bottomCenter'),
      confidenceThreshold: Number.isFinite(s.confidenceThreshold) ? s.confidenceThreshold : 0.65,
      normalizeIllegal:    s.normalizeIllegal !== undefined ? !!s.normalizeIllegal : !anyTextMode,
      replaceSpaces:       s.replaceSpaces   !== undefined ? !!s.replaceSpaces   : !anyTextMode,
      keepSpaces:          s.keepSpaces      !== undefined ? !!s.keepSpaces      :  anyTextMode,
      uppercase:           !!s.uppercase,
      customRegex:         s.customRegex || null,
      detectionMode,
      manualCrop,
      showOverlay:         s.showOverlay !== false,
      // Multi-frame consensus: sample ±N frames around the marker and vote
      // across pooled OCR passes. Default on; cost is ~1.5× single-frame.
      multiFrameOcr:       s.multiFrameOcr !== false,
      multiFrameOffsets:   Array.isArray(s.multiFrameOffsets) && s.multiFrameOffsets.length
                           ? s.multiFrameOffsets : [-2, -1, 1, 2],
      claudeApiKey:        typeof s.claudeApiKey === 'string' ? s.claudeApiKey : '',
    };
  } catch {
    return { enabled: false, defaultRegion: 'bottomCenter', confidenceThreshold: 0.65, normalizeIllegal: true, replaceSpaces: true, keepSpaces: false, uppercase: false, customRegex: null, detectionMode: 'vfxShotName', manualCrop: null, showOverlay: true, multiFrameOcr: true, multiFrameOffsets: [-2, -1, 1, 2], claudeApiKey: '' };
  }
}
function _pmSaveOcrSettings(s) {
  try { localStorage.setItem(_lsKey('ocrSettings.v1'), JSON.stringify(s)); } catch {}
}

// ROI priority: marker-specific → clip-specific → project manual → preset fallback
function _pmGetEffectiveRoi(mkId, evIdx) {
  const mk = mkId ? _pmClipMarkers.find(m => m.id === mkId) : null;
  if (mk?.ocrCrop) return { roi: mk.ocrCrop, source: 'marker' };
  const ev = (evIdx >= 0 && _pmEvents?.[evIdx]) ? _pmEvents[evIdx] : null;
  if (ev?.ocrCrop) return { roi: ev.ocrCrop, source: 'clip' };
  const s = _pmGetOcrSettings();
  if (s.manualCrop) return { roi: s.manualCrop, source: 'manual' };
  const regionKey = (s.defaultRegion && s.defaultRegion !== 'manual') ? s.defaultRegion : 'bottomCenter';
  return { roi: _PM_OCR_REGIONS[regionKey] || _PM_OCR_REGIONS.bottomCenter, source: regionKey };
}

// Compute where the video content sits within the video element (accounts for letterboxing)
function _pmOcrLetterboxInfo() {
  if (!pmVideo || !pmVideo.videoWidth) return null;
  const vw = pmVideo.videoWidth, vh = pmVideo.videoHeight;
  const rect = pmVideo.getBoundingClientRect();
  const ew = rect.width, eh = rect.height;
  if (!ew || !eh) return null;
  const videoAR = vw / vh, elemAR = ew / eh;
  let rw, rh, ox, oy;
  if (videoAR > elemAR) {
    rw = ew; rh = ew / videoAR; ox = 0; oy = (eh - rh) / 2;
  } else {
    rh = eh; rw = eh * videoAR; ox = (ew - rw) / 2; oy = 0;
  }
  return { rect, ox, oy, rw, rh };
}

// Exposed for project_setup.js "Draw OCR Area" button.
window.__pfxEnterOcrCropMode = (mkId) => _pmEnterOcrCropMode(mkId || null);

function _pmEnterOcrCropMode(mkId) {
  _pmExitOcrCropMode();
  if (!pmVideo || !pmVideo.videoWidth) {
    _pmToast('No video loaded — cannot set OCR area', 'error'); return;
  }
  _pmOcrCropMode = true; _pmOcrCropMkId = mkId;
  if (pmInspector) { pmInspector.dataset.ocrHidden = pmInspector.style.display || ''; pmInspector.style.display = 'none'; }
  const lb = _pmOcrLetterboxInfo();
  if (!lb) { _pmOcrCropMode = false; if (pmInspector) { pmInspector.style.display = pmInspector.dataset.ocrHidden || ''; delete pmInspector.dataset.ocrHidden; } return; }
  const { rect, ox, oy, rw, rh } = lb;

  const fsEl = document.fullscreenElement;
  const mountTarget = fsEl || document.body;
  let overlayLeft = rect.left, overlayTop = rect.top;
  if (fsEl) {
    const wrapRect = fsEl.getBoundingClientRect();
    overlayLeft = rect.left - wrapRect.left;
    overlayTop  = rect.top  - wrapRect.top;
  }

  // Overlay covers the entire video element at its fixed/absolute position
  const overlay = document.createElement('div');
  overlay.className = 'pm-ocr-crop-overlay' + (fsEl ? ' pm-ocr-crop-overlay--fs' : '');
  overlay.style.cssText = `left:${overlayLeft}px;top:${overlayTop}px;width:${rect.width}px;height:${rect.height}px;`;

  // Paint area = actual video content region (inside letterbox bars)
  const paint = document.createElement('div');
  paint.className = 'pm-ocr-crop-paint';
  paint.style.cssText = `left:${ox}px;top:${oy}px;width:${rw}px;height:${rh}px;`;
  overlay.appendChild(paint);

  const lbl = document.createElement('div');
  lbl.className = 'pm-ocr-crop-lbl';
  lbl.textContent = 'OCR AREA — drag to select region';
  paint.appendChild(lbl);

  const selRect = document.createElement('div');
  selRect.className = 'pm-ocr-crop-rect';
  selRect.style.display = 'none';
  paint.appendChild(selRect);

  const bar = document.createElement('div');
  bar.className = 'pm-ocr-crop-bar';
  bar.innerHTML = `<button class="pm-ocr-save-area" type="button" disabled>Save Area</button>
    <button class="pm-ocr-test-ocr" type="button" disabled>Test OCR</button>
    <button class="pm-ocr-clear-area" type="button">Clear Area</button>
    <button class="pm-ocr-crop-cancel" type="button">✕ Cancel</button>`;
  overlay.appendChild(bar);

  // Restore previously saved crop if any
  const settings = _pmGetOcrSettings();
  const savedCrop = (mkId ? _pmClipMarkers.find(m => m.id === mkId)?.ocrCrop : null) || settings.manualCrop;
  let currentPct = savedCrop ? { ...savedCrop } : null;

  function showSelFromPct(pct) {
    selRect.style.display = '';
    selRect.style.left   = (pct.x * rw) + 'px'; selRect.style.top    = (pct.y * rh) + 'px';
    selRect.style.width  = (pct.w * rw) + 'px'; selRect.style.height = (pct.h * rh) + 'px';
    bar.querySelector('.pm-ocr-save-area').disabled = false;
    bar.querySelector('.pm-ocr-test-ocr').disabled  = false;
  }
  if (currentPct) showSelFromPct(currentPct);

  // Drag to draw selection
  let dragging = false, startX = 0, startY = 0;
  paint.addEventListener('pointerdown', e => {
    if (e.button !== 0) return;
    e.preventDefault(); e.stopPropagation();
    dragging = true; startX = e.offsetX; startY = e.offsetY;
    selRect.style.display = 'none';
    paint.setPointerCapture(e.pointerId);
  });
  paint.addEventListener('pointermove', e => {
    if (!dragging) return;
    e.preventDefault();
    const x = Math.min(startX, e.offsetX), y = Math.min(startY, e.offsetY);
    const w = Math.abs(e.offsetX - startX), h = Math.abs(e.offsetY - startY);
    selRect.style.cssText = `display:block;left:${x}px;top:${y}px;width:${w}px;height:${h}px;`;
  });
  paint.addEventListener('pointerup', e => {
    if (!dragging) return; dragging = false;
    const x = Math.min(startX, e.offsetX), y = Math.min(startY, e.offsetY);
    const w = Math.max(4, Math.abs(e.offsetX - startX)), h = Math.max(4, Math.abs(e.offsetY - startY));
    // Convert to percentages of the actual video frame
    currentPct = { x: x / rw, y: y / rh, w: w / rw, h: h / rh };
    showSelFromPct(currentPct);
  });
  // Double-click selection = Test OCR
  selRect.addEventListener('dblclick', () => bar.querySelector('.pm-ocr-test-ocr')?.click());

  // Esc = cancel
  const onKey = e => { if (e.key === 'Escape') { _pmExitOcrCropMode(); document.removeEventListener('keydown', onKey, true); } };
  document.addEventListener('keydown', onKey, true);

  bar.querySelector('.pm-ocr-save-area')?.addEventListener('click', () => {
    if (!currentPct) return;
    const s = _pmGetOcrSettings();
    if (mkId) {
      const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
      if (mk) {
        mk.ocrCrop = currentPct;
        _pmSaveClipMarkers();
      }
    } else {
      s.manualCrop = currentPct;
      s.defaultRegion = 'manual';
      _pmSaveOcrSettings(s);
    }
    window.MPS_markProjectDirty?.();
    _pmToast('OCR area saved', 'info', 2000);
    _pmExitOcrCropMode();
    _pmRenderInspector(parseInt(pmInspector?.querySelector('.pm-insp-layers')?.dataset.evidx ?? '-1', 10));
  });

  bar.querySelector('.pm-ocr-test-ocr')?.addEventListener('click', async () => {
    if (!currentPct) return;
    const vc = _pmCaptureCurrentVideoCanvas();
    if (!vc) { _pmToast('Cannot capture video frame', 'error'); return; }
    const btn = bar.querySelector('.pm-ocr-test-ocr');
    btn.disabled = true; btn.textContent = '…';
    try {
      const cropData  = _pmOcrCropAndScale(vc, currentPct);
      const processed = _pmOcrPreprocess(cropData);
      const _ocrWl = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.()/:[] ';
      const rawText   = await _pmOcrRecognizeRobust(processed, cropData, _ocrWl);
      const det       = _pmOcrProcess(rawText, _pmGetOcrSettings());
      const thumbUrl  = _pmOcrCropThumbUrl(vc, currentPct);
      const mk = mkId ? _pmClipMarkers.find(m => m.id === mkId) : null;
      const evIdx = parseInt(pmInspector?.querySelector('.pm-insp-layers')?.dataset.evidx ?? '-1', 10);
      if (mk) {
        _pmShowOcrModal(mk, { ...det, regionKey: 'manual', cropThumbUrl: thumbUrl }, evIdx);
      } else {
        _pmToast(det.bestCandidate ? `Detected: ${det.bestCandidate.value}` : 'No shot name found',
          det.bestCandidate ? 'info' : 'warn', 3500);
      }
    } catch (err) {
      _pmToast(`Test OCR failed: ${err.message || err}`, 'error');
    } finally { btn.disabled = false; btn.textContent = 'Test OCR'; }
  });

  bar.querySelector('.pm-ocr-clear-area')?.addEventListener('click', () => {
    let cleared = false;
    if (mkId) {
      const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
      if (mk?.ocrCrop) {
        delete mk.ocrCrop;
        _pmSaveClipMarkers();
        cleared = true;
      }
    }
    if (!cleared) {
      const s = _pmGetOcrSettings();
      if (s.manualCrop) {
        s.manualCrop = null;
        if (s.defaultRegion === 'manual') s.defaultRegion = 'bottomCenter';
        _pmSaveOcrSettings(s);
      }
    }
    currentPct = null; selRect.style.display = 'none';
    bar.querySelector('.pm-ocr-save-area').disabled = true;
    bar.querySelector('.pm-ocr-test-ocr').disabled  = true;
    _pmToast('OCR area cleared', 'info', 2000);
  });

  bar.querySelector('.pm-ocr-crop-cancel')?.addEventListener('click', () => _pmExitOcrCropMode());
  mountTarget.appendChild(overlay);
}

function _pmExitOcrCropMode() {
  _pmOcrCropMode = false; _pmOcrCropMkId = null;
  document.querySelector('.pm-ocr-crop-overlay')?.remove();
  if (pmInspector && 'ocrHidden' in pmInspector.dataset) {
    pmInspector.style.display = pmInspector.dataset.ocrHidden || '';
    delete pmInspector.dataset.ocrHidden;
  }
}

function _pmGetOcrClient() {
  if (_pmOcrClient) return _pmOcrClient;
  const workerUrl = chrome?.runtime?.getURL
    ? chrome.runtime.getURL('scripts/ocr_burnin_worker.js')
    : 'scripts/ocr_burnin_worker.js';
  const worker = new Worker(workerUrl);
  let seq = 0;
  const pending = new Map();
  worker.onmessage = ev => {
    const msg = ev.data || {};
    const p = pending.get(msg.id);
    if (!p) return;
    pending.delete(msg.id);
    if (msg.ok) p.resolve(msg); else p.reject(new Error(msg.error || 'OCR worker error'));
  };
  worker.onerror = e => {
    console.warn('[PM OCR] worker error', e);
    for (const [, p] of pending) try { p.reject(new Error('OCR worker crashed')); } catch {}
    pending.clear();
    _pmOcrClient = null;
  };
  _pmOcrClient = {
    async recognize(imageData, opts = {}) {
      const id = `pm_ocr_${Date.now()}_${++seq}`;
      const rgba = new Uint8Array(imageData.data);
      const p = new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
      worker.postMessage(
        { id, type: 'recognize', image: { buffer: rgba.buffer, width: imageData.width, height: imageData.height },
          psm: opts.psm, whitelist: opts.whitelist },
        [rgba.buffer]
      );
      const res = await Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('OCR timeout')), 25000))]);
      return String(res.text || '').trim();
    }
  };
  return _pmOcrClient;
}

// ── Apple Vision OCR (companion-first path) ──────────────────────────────────
// Apple Vision via the macOS companion is dramatically more accurate than
// Tesseract.js on small/noisy slate burn-ins (the failure case shown in user
// screenshots). We try it FIRST and fall through to the Tesseract pipeline
// only when the companion is unavailable, on a non-macOS host, or the call
// fails. Cached capability probe means non-macOS users only pay the lookup
// cost once per session.
let _pmVisionAvailable = null; // null = unknown, true/false = cached probe

async function _pmOcrCheckVisionAvailable() {
  if (_pmVisionAvailable !== null) return _pmVisionAvailable;
  try {
    const res = await nativeOcrCapabilities();
    _pmVisionAvailable = !!(res?.ok && res.result?.available);
  } catch {
    _pmVisionAvailable = false;
  }
  return _pmVisionAvailable;
}

// Convert an ImageData buffer to a base64 PNG body (no data: URL prefix).
function _pmOcrImageDataToPngBase64(imgData) {
  if (!imgData) return '';
  try {
    const c = document.createElement('canvas');
    c.width = imgData.width; c.height = imgData.height;
    c.getContext('2d').putImageData(imgData, 0, 0);
    const url = c.toDataURL('image/png');
    const i = url.indexOf(',');
    return i >= 0 ? url.slice(i + 1) : '';
  } catch {
    return '';
  }
}

// Try Apple Vision OCR via the companion. Returns the recognised text on
// success; returns null when the companion is unavailable or the call fails
// (caller should fall through to Tesseract). Also normalises the output via
// the same _pmOcrNormalizeRaw pipeline so downstream matching is consistent
// across engines.
async function _pmOcrTryCompanion(imageData) {
  const available = await _pmOcrCheckVisionAvailable();
  if (!available) return null;
  const b64 = _pmOcrImageDataToPngBase64(imageData);
  if (!b64) return null;
  try {
    const res = await nativeOcrImage(b64, { recognitionLevel: 'accurate' });
    const info = res?.result;
    if (!info?.ok || !info?.available) return null;
    // Pick the highest-confidence single text line (Vision returns one
    // observation per visual line; for slates we want the most confident
    // glyph cluster, not all lines joined).
    const results = Array.isArray(info.results) ? info.results : [];
    if (!results.length && !info.rawText) return null;
    let best = null;
    for (const r of results) {
      if (!r?.text) continue;
      if (!best || (r.confidence || 0) > (best.confidence || 0)) best = r;
    }
    const chosen = best?.text || info.rawText || '';
    const normalised = _pmOcrNormalizeRaw(chosen);
    return normalised || null;
  } catch {
    return null;
  }
}

// Try Claude Vision OCR via the Anthropic API. Returns normalised text on success;
// returns null when no API key is configured or the request fails so the caller
// falls through to Apple Vision / Tesseract. Claude Haiku is used — it is fast,
// cheap, and dramatically more accurate than Tesseract on small burn-in text.
async function _pmOcrTryClaudeVision(imageData) {
  const apiKey = _pmGetOcrSettings().claudeApiKey?.trim();
  if (!apiKey) return null;
  const b64 = _pmOcrImageDataToPngBase64(imageData);
  if (!b64) return null;
  try {
    const body = {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 64,
      messages: [{
        role: 'user',
        content: [
          { type: 'image', source: { type: 'base64', media_type: 'image/png', data: b64 } },
          { type: 'text', text: 'Read any burn-in text visible in this image (e.g. a VFX shot name or slate). Return only the exact text, no punctuation or explanation. If multiple text lines are visible join them with a single space. If no text is present return an empty string.' },
        ],
      }],
    };
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'true',
      },
      body: JSON.stringify(body),
    });
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      console.warn('[PM OCR] Claude Vision API error', resp.status, err?.error?.message || '');
      return null;
    }
    const data = await resp.json();
    const text = (data.content?.[0]?.text || '').trim();
    if (!text || /^(empty string|no text|none)$/i.test(text)) return null;
    return _pmOcrNormalizeRaw(text) || null;
  } catch (e) {
    console.warn('[PM OCR] Claude Vision request failed:', e.message || e);
    return null;
  }
}

function _pmOcrCropAndScale(srcCanvas, roi) {
  const sw = srcCanvas.width, sh = srcCanvas.height;
  if (!sw || !sh) return null;
  const x = Math.max(0, Math.round(roi.x * sw));
  const y = Math.max(0, Math.round(roi.y * sh));
  const w = Math.max(2, Math.min(sw - x, Math.round(roi.w * sw)));
  const h = Math.max(2, Math.min(sh - y, Math.round(roi.h * sh)));
  const maxDim = Math.max(w, h);
  const scale  = maxDim < 1600 ? Math.min(6.0, 1600 / Math.max(1, maxDim)) : 1;
  const outW   = Math.round(w * scale), outH = Math.round(h * scale);

  // ── Sample the crop's mean luminance to pick a matching padding tone ──
  // Tesseract's auto-invert relies on the post-binarize white/black ratio
  // across the whole image. If we always pad with white, dark-banded slates
  // (white text on black band — the exact failure case in user screenshots)
  // end up white-padding-dominant, so the binarize doesn't invert, and
  // Tesseract is fed white text on black inside a huge white frame.
  // Padding with the dominant tone keeps the foreground/background ratio
  // truthful.
  const probe = document.createElement('canvas');
  const probeW = Math.max(8, Math.min(64, w));
  const probeH = Math.max(8, Math.min(64, h));
  probe.width = probeW; probe.height = probeH;
  const pg = probe.getContext('2d');
  pg.drawImage(srcCanvas, x, y, w, h, 0, 0, probeW, probeH);
  let lumSum = 0; let lumCount = 0;
  try {
    const probeData = pg.getImageData(0, 0, probeW, probeH).data;
    for (let i = 0; i < probeData.length; i += 4) {
      lumSum += 0.2126 * probeData[i] + 0.7152 * probeData[i + 1] + 0.0722 * probeData[i + 2];
      lumCount++;
    }
  } catch { /* getImageData can throw on cross-origin canvases — fall back to white */ }
  const meanLum = lumCount > 0 ? lumSum / lumCount : 255;
  const padIsDark = meanLum < 110;   // <110/255 → dominant tone is dark
  const padColor  = padIsDark ? '#000000' : '#ffffff';

  // Add padding around the crop — Tesseract accuracy improves significantly
  // when characters are not flush against the image edge
  const pad = Math.max(20, Math.round(outH * 0.25));
  const tmp = document.createElement('canvas');
  tmp.width = outW + pad * 2; tmp.height = outH + pad * 2;
  const g = tmp.getContext('2d');
  g.fillStyle = padColor;
  g.fillRect(0, 0, tmp.width, tmp.height);
  g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';
  g.drawImage(srcCanvas, x, y, w, h, pad, pad, outW, outH);
  return g.getImageData(0, 0, tmp.width, tmp.height);
}

function _pmOcrGrayscaleBuf(src, len) {
  const g = new Uint8ClampedArray(len);
  for (let i = 0; i < len; i += 4) {
    const lum = 0.2126 * src[i] + 0.7152 * src[i + 1] + 0.0722 * src[i + 2];
    g[i] = g[i + 1] = g[i + 2] = lum; g[i + 3] = 255;
  }
  return g;
}

function _pmOcrBoxBlur(buf, W, H, radius) {
  const out = new Uint8ClampedArray(buf.length);
  for (let py = 0; py < H; py++) {
    for (let px = 0; px < W; px++) {
      let sum = 0, cnt = 0;
      for (let dy = -radius; dy <= radius; dy++) {
        for (let dx = -radius; dx <= radius; dx++) {
          const ny = py + dy, nx = px + dx;
          if (ny >= 0 && ny < H && nx >= 0 && nx < W) {
            sum += buf[((ny * W + nx) << 2)]; cnt++;
          }
        }
      }
      const bi = (py * W + px) << 2;
      out[bi] = out[bi + 1] = out[bi + 2] = sum / cnt; out[bi + 3] = 255;
    }
  }
  return out;
}

function _pmOcrOtsuThreshold(buf) {
  const hist = new Uint32Array(256);
  for (let i = 0; i < buf.length; i += 4) hist[buf[i] | 0]++;
  const total = buf.length >> 2;
  let sum = 0; for (let t = 0; t < 256; t++) sum += t * hist[t];
  let sumB = 0, wB = 0, varMax = 0, threshold = 140;
  for (let t = 0; t < 256; t++) {
    wB += hist[t]; if (!wB) continue;
    const wF = total - wB; if (!wF) break;
    sumB += t * hist[t];
    const mB = sumB / wB, mF = (sum - sumB) / wF;
    const v = wB * wF * (mB - mF) ** 2;
    if (v > varMax) { varMax = v; threshold = t; }
  }
  return threshold;
}

function _pmOcrBinarize(buf, threshold) {
  let white = 0, black = 0;
  const d = new Uint8ClampedArray(buf.length);
  for (let i = 0; i < buf.length; i += 4) {
    const v = buf[i] > threshold ? 255 : 0;
    d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255;
    v === 255 ? white++ : black++;
  }
  if (black > white) {
    for (let i = 0; i < d.length; i += 4) d[i] = d[i + 1] = d[i + 2] = d[i] === 255 ? 0 : 255;
  }
  return d;
}

// Unsharp mask: sharpens edges so thin strokes are clearer
function _pmOcrUnsharpMask(buf, W, H, amount) {
  const blurred = _pmOcrBoxBlur(buf, W, H, 1);
  const out = new Uint8ClampedArray(buf.length);
  for (let i = 0; i < buf.length; i += 4) {
    const v = Math.max(0, Math.min(255, buf[i] + amount * (buf[i] - blurred[i])));
    out[i] = out[i + 1] = out[i + 2] = v; out[i + 3] = 255;
  }
  return out;
}

// Local contrast normalization — stretch 5×5 local range to 0-255
function _pmOcrLocalContrast(buf, W, H) {
  const out = new Uint8ClampedArray(buf.length);
  const r = 5;
  for (let py = 0; py < H; py++) {
    for (let px = 0; px < W; px++) {
      let lo = 255, hi = 0;
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          const ny = Math.max(0, Math.min(H - 1, py + dy));
          const nx = Math.max(0, Math.min(W - 1, px + dx));
          const val = buf[((ny * W + nx) << 2)];
          if (val < lo) lo = val; if (val > hi) hi = val;
        }
      }
      const range = hi - lo || 1;
      const bi = (py * W + px) << 2;
      const v = Math.round((buf[bi] - lo) / range * 255);
      out[bi] = out[bi + 1] = out[bi + 2] = v; out[bi + 3] = 255;
    }
  }
  return out;
}

function _pmOcrPreprocess(img) {
  if (!img) return null;
  const W = img.width, H = img.height;
  const gray = _pmOcrGrayscaleBuf(img.data, img.data.length);
  // Unsharp mask to sharpen thin strokes before blur/threshold
  const sharpened = _pmOcrUnsharpMask(gray, W, H, 1.5);
  // Gentle blur to smooth noise while preserving edges
  const blurred = _pmOcrBoxBlur(sharpened, W, H, 1);
  const threshold = _pmOcrOtsuThreshold(blurred);
  const d = _pmOcrBinarize(blurred, threshold);
  return new ImageData(d, W, H);
}

// Secondary variant: local-contrast-enhanced grayscale (no binarize) — better for LSTM
function _pmOcrPreprocessLcn(img) {
  if (!img) return null;
  const W = img.width, H = img.height;
  const gray = _pmOcrGrayscaleBuf(img.data, img.data.length);
  const lc = _pmOcrLocalContrast(gray, W, H);
  return new ImageData(lc, W, H);
}

// Tertiary variant: lower threshold (Otsu - 20) — recovers faint light text on dark bg
function _pmOcrPreprocessLowThresh(img) {
  if (!img) return null;
  const W = img.width, H = img.height;
  const gray = _pmOcrGrayscaleBuf(img.data, img.data.length);
  const blurred = _pmOcrBoxBlur(gray, W, H, 1);
  const threshold = Math.max(60, _pmOcrOtsuThreshold(blurred) - 20);
  const d = _pmOcrBinarize(blurred, threshold);
  return new ImageData(d, W, H);
}

// Sharp variant: no blur at all — best for crisp burn-in text already at high res
function _pmOcrPreprocessSharp(img) {
  if (!img) return null;
  const W = img.width, H = img.height;
  const gray = _pmOcrGrayscaleBuf(img.data, img.data.length);
  const threshold = _pmOcrOtsuThreshold(gray);
  const d = _pmOcrBinarize(gray, threshold);
  return new ImageData(d, W, H);
}

// Adaptive (Sauvola-style) threshold using local mean + std-dev in a sliding
// window. Each pixel's threshold is mean_window * (1 + k*(stddev/R - 1)),
// where R is the dynamic range constant (128) and k is a sensitivity tuning
// (0.5 is a standard value). Far better than Otsu on slates with uneven
// lighting — shadows, gradients, partial occlusion — because each region
// gets its own threshold. ~3× slower than Otsu but cheap relative to OCR.
function _pmOcrPreprocessAdaptive(img) {
  if (!img) return null;
  const W = img.width, H = img.height;
  if (W < 16 || H < 16) return null;
  const gray = _pmOcrGrayscaleBuf(img.data, img.data.length);

  // Window radius scaled to image size — bigger for big images, but capped
  const r = Math.min(20, Math.max(4, Math.round(Math.min(W, H) * 0.04)));
  const k = 0.5;
  const R = 128;

  // ── Integral images for fast window-sum and squared-window-sum ──
  // sum[y][x] = sum of all gray values in the rect from (0,0) to (x-1,y-1)
  // sumSq[y][x] = sum of squared values in the same rect
  // Stored 1D row-major with (W+1) row width to simplify edge math.
  const stride = W + 1;
  const sum   = new Float64Array(stride * (H + 1));
  const sumSq = new Float64Array(stride * (H + 1));
  for (let y = 0; y < H; y++) {
    let rs = 0, rsSq = 0;
    for (let x = 0; x < W; x++) {
      const v = gray[((y * W + x) << 2)];
      rs += v; rsSq += v * v;
      const idx = (y + 1) * stride + (x + 1);
      sum[idx]   = sum[y * stride + (x + 1)]   + rs;
      sumSq[idx] = sumSq[y * stride + (x + 1)] + rsSq;
    }
  }

  const d = new Uint8ClampedArray(gray.length);
  let white = 0, black = 0;
  for (let y = 0; y < H; y++) {
    const y0 = Math.max(0, y - r), y1 = Math.min(H - 1, y + r);
    for (let x = 0; x < W; x++) {
      const x0 = Math.max(0, x - r), x1 = Math.min(W - 1, x + r);
      const area = (x1 - x0 + 1) * (y1 - y0 + 1);
      // Integral image lookups (Sum of rect from (x0,y0) to (x1,y1) inclusive)
      const A  = sum[y0 * stride + x0];
      const B  = sum[y0 * stride + (x1 + 1)];
      const C  = sum[(y1 + 1) * stride + x0];
      const D  = sum[(y1 + 1) * stride + (x1 + 1)];
      const sA = sumSq[y0 * stride + x0];
      const sB = sumSq[y0 * stride + (x1 + 1)];
      const sC = sumSq[(y1 + 1) * stride + x0];
      const sD = sumSq[(y1 + 1) * stride + (x1 + 1)];
      const winSum   = D - B - C + A;
      const winSumSq = sD - sB - sC + sA;
      const mean = winSum / area;
      const variance = Math.max(0, (winSumSq / area) - (mean * mean));
      const stddev = Math.sqrt(variance);
      const thr = mean * (1 + k * (stddev / R - 1));
      const idx = (y * W + x) << 2;
      const v = gray[idx];
      const out = v > thr ? 255 : 0;
      d[idx] = d[idx + 1] = d[idx + 2] = out; d[idx + 3] = 255;
      out === 255 ? white++ : black++;
    }
  }
  // Auto-invert if foreground turned out lighter than background (white > black
  // means the inverse — text was light, but typical Tesseract input has black
  // text on white). Same heuristic as _pmOcrBinarize uses.
  if (black > white) {
    for (let i = 0; i < d.length; i += 4) {
      d[i] = d[i + 1] = d[i + 2] = d[i] === 255 ? 0 : 255;
    }
  }
  return new ImageData(d, W, H);
}

// Grayscale only — no binarization; LSTM handles grayscale well for styled fonts
function _pmOcrToGrayscale(img) {
  if (!img) return null;
  const src = img.data;
  const d = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    const lum = 0.2126 * src[i] + 0.7152 * src[i + 1] + 0.0722 * src[i + 2];
    d[i] = d[i + 1] = d[i + 2] = lum; d[i + 3] = 255;
  }
  return new ImageData(d, img.width, img.height);
}

// Normalize OCR output: collapse underscore-as-space misreads + camera filename corrections
function _pmOcrNormalizeRaw(text) {
  if (!text) return text;
  return text.split(/[\r\n]+/).map(line => {
    let t = line.trim();

    // Pass 0: bracket/punctuation → letter, only when followed by digits.
    // Catches the very common R→[ misread on slate burn-ins like "R01_0120"
    // that Tesseract reads as "[0101200". Never rewrites mid-string — only the
    // leading char — to avoid mangling legitimate brackets inside the text.
    t = t.replace(/^[\[(\{]+(\d)/, 'R$1');
    t = t.replace(/^[|/!\\]+(\d{2,})/, 'I$1');

    // Pass A: space → underscore between filename-segment chars
    for (let pass = 0; pass < 8; pass++) {
      const next = t.replace(/([A-Za-z0-9._-]+) ([A-Za-z0-9._-]+)/g, (match, a, b) => {
        const hasDigit = /\d/.test(a) || /\d/.test(b);
        const hasExt   = /\.[a-zA-Z]{2,4}$/.test(b) || /\.[a-zA-Z]{2,4}$/.test(a);
        const looksVfx = /^[A-Z]\d{2,}/.test(a) || /^[A-Z]\d{2,}/.test(b);
        if (hasDigit || hasExt || looksVfx) return a + '_' + b;
        return match;
      });
      if (next === t) break;
      t = next;
    }

    // Pass B: remove spurious underscores inside pure digit runs
    // e.g. "25030_194" → "25030194", "250_301_94" → "25030194"
    t = t.replace(/(\d+)_(\d+)/g, (match, a, b) => {
      // Only join if neither segment looks like it should be a standalone date/reel segment
      // (i.e. join when a+b together form a plausible continuous number)
      if (a.length + b.length <= 12) return a + b;
      return match;
    });

    // Pass C: camera roll L/1 confusion fix
    // Pattern: [A-Z][0-9]{3}_1[0-9]{3} → [A-Z][0-9]{3}L[0-9]{3}
    // Tesseract reads the capital L in "A001L002" as underscore+1
    t = t.replace(/([A-Z]\d{3})_1(\d{3}(?:[_.]|$))/g, (match, roll, rest) => {
      return roll + 'L' + rest;
    });
    // Also fix when it reads L as |1, I1, or l1
    t = t.replace(/([A-Z]\d{3})[|Il](\d{3})/g, (match, roll, clip) => {
      return roll + 'L' + clip;
    });

    // Pass D: fix trailing segment confusion — e.g. "A001L002_25030194_94.mxf" where
    // the last _94 is a duplicate split of the previous digit run
    t = t.replace(/(_\d{6,})_(\d{2,4})(\.[a-zA-Z]{2,4})/g, (match, main, suffix, ext) => {
      if ((main.replace('_', '').length + suffix.length) <= 10) return main + suffix + ext;
      return match;
    });

    // Pass E: character-level corrections for common camera filename OCR errors
    // Spurious leading '4' before camera roll letter (4A001L... → A001L...)
    t = t.replace(/^4([A-Z]\d{3})/,  '$1');
    t = t.replace(/^4(\d{3}[A-Z_])/, 'A$1');
    // Extension corruption: .mxTE/.mxTi → .mxf
    t = t.replace(/\.[Mm][Xx][TtIi][EeFf]$/i, '.mxf');
    t = t.replace(/\.[Mm][Oo][VvBb]$/i,        '.mov');
    // 0/O confusion inside digit runs
    t = t.replace(/(\d)[Oo](\d)/g,    '$10$2');
    t = t.replace(/(\d)[Oo]([._-])/g, '$10$2');
    // l/1 confusion in digit runs
    t = t.replace(/(\d)l(\d)/g, '$11$2');

    return t;
  }).join('\n');
}

// Score a normalized OCR result for "best pass" selection
function _pmOcrResultScore(text) {
  if (!text) return 0;
  const t = text.trim();
  if (!t) return 0;
  let sc = t.length * 0.5;
  if (/\.[a-zA-Z]{2,4}/.test(t)) sc += 40;  // has file extension
  if (/[A-Z]\d{3}[A-Z_]\d{3}/.test(t)) sc += 40; // camera roll pattern (A001L002 or A001_L002)
  if (/_/.test(t)) sc += 15;                 // has underscore
  if (/[A-Z]\d{3}/.test(t)) sc += 20;       // VFX reel/cam segment
  if (/\s/.test(t)) sc -= 25;               // residual spaces = bad
  if (/\d{6,}/.test(t)) sc += 20;           // long digit run = clip/date ID
  // Penalise if digits are broken by spurious underscores (e.g. 250301_94)
  const digitRunsWithUnder = (t.match(/\d{2,}_\d{2,}/g) || []).length;
  sc -= digitRunsWithUnder * 15;
  return sc;
}

// Multi-pass OCR: tries multiple PSMs and preprocessing variants; picks best result
async function _pmOcrRecognizeRobust(processed, rawCropData, whitelist) {
  const client = _pmGetOcrClient();
  const results = [];

  // Pass 1: sharp binarize + PSM 7 — best for crisp burn-ins (no blur artifacts)
  const sharp = _pmOcrPreprocessSharp(rawCropData);
  if (sharp) {
    const t0 = await client.recognize(sharp, { psm: 7, whitelist });
    if (t0) results.push(t0);
    const t0b = await client.recognize(sharp, { psm: 13, whitelist });
    if (t0b) results.push(t0b);
  }

  // Pass 2: PSM 7 (single line) — standard binarized
  const t1 = await client.recognize(processed, { psm: 7, whitelist });
  if (t1) results.push(t1);

  // Pass 3: PSM 13 (raw line, no layout analysis) — standard binarized
  const t2 = await client.recognize(processed, { psm: 13, whitelist });
  if (t2) results.push(t2);

  // Pass 4: LCN grayscale + PSM 7 — LSTM handles continuous-tone well
  const lcn = _pmOcrPreprocessLcn(rawCropData);
  if (lcn) {
    const t3 = await client.recognize(lcn, { psm: 7, whitelist });
    if (t3) results.push(t3);
    const t3b = await client.recognize(lcn, { psm: 13, whitelist });
    if (t3b) results.push(t3b);
  }

  // Pass 5: Lower-threshold binarize + PSM 7 — catches faint text
  const lt = _pmOcrPreprocessLowThresh(rawCropData);
  if (lt) {
    const t4 = await client.recognize(lt, { psm: 7, whitelist });
    if (t4) results.push(t4);
  }

  // Pass 6: Adaptive (Sauvola) threshold + PSM 7 — handles uneven lighting,
  // shadows, gradient burn-ins where Otsu's global threshold gives up.
  const adapt = _pmOcrPreprocessAdaptive(rawCropData);
  if (adapt) {
    const t5 = await client.recognize(adapt, { psm: 7, whitelist });
    if (t5) results.push(t5);
    const t5b = await client.recognize(adapt, { psm: 13, whitelist });
    if (t5b) results.push(t5b);
  }

  // Pass 7: Raw grayscale + PSM 11 (sparse text) — last resort
  if (!results.length || results.every(r => !r.trim())) {
    const gray = _pmOcrToGrayscale(rawCropData);
    if (gray) {
      const t6 = await client.recognize(gray, { psm: 11, whitelist });
      if (t6) results.push(t6);
    }
  }

  // Normalize spaces→underscores in all candidates
  const normalized = results.map(_pmOcrNormalizeRaw).filter(Boolean);
  if (!normalized.length) return '';
  // Stash the per-pass normalized results so multi-frame voting can pool
  // them across frames before picking the final consensus. Cleared on next
  // call; only the immediate caller reads this.
  _pmOcrLastPassResults = normalized.slice();
  return _pmOcrPickConsensus(normalized);
}

// Per-pass results from the most recent _pmOcrRecognizeRobust call.
// Multi-frame voting reads this immediately after each frame's OCR so it can
// pool every pass from every frame before picking a single consensus.
let _pmOcrLastPassResults = [];

// Pick the consensus result from multiple OCR passes.
// Strategy:
//   1. Strict consensus — if any non-empty result appears in ≥ ceil(N/2) passes,
//      it wins. This handles "4 of 6 say R01_0220, 2 are garbage" cleanly.
//   2. Loose consensus on alphanum form — if a single alphanum-stripped form
//      dominates, pick the result with that form that scores highest. Catches
//      "4 say R01_0220 but 1 says R010220, 1 says R-01-0220" — same content,
//      different separators; the separator-rich version wins.
//   3. Fallback — original highest-scoring pick. Keeps existing behaviour
//      when passes genuinely disagree.
function _pmOcrPickConsensus(normalized) {
  if (!normalized?.length) return '';
  if (normalized.length === 1) return normalized[0];

  // Score every result up-front so all tiers can weight by it. We add 1 so
  // even a zero-score entry contributes some weight (counted as a present
  // vote) and well-formed entries can still dominate.
  const scoreOf = (t) => Math.max(0, _pmOcrResultScore(t)) + 1;

  // Tier 1: exact agreement — sum scores per identical string. The exact
  // string with the highest *weighted* vote wins if its share is ≥ 50% of
  // total weight. This means a single well-formed reading can overcome
  // several malformed ones agreeing on garbage.
  const exactWeights = new Map();
  let totalWeight = 0;
  for (const t of normalized) {
    const w = scoreOf(t);
    exactWeights.set(t, (exactWeights.get(t) || 0) + w);
    totalWeight += w;
  }
  const halfWeight = totalWeight / 2;
  let exactWinner = null; let exactWinnerWeight = 0;
  for (const [t, w] of exactWeights) if (w > exactWinnerWeight) { exactWinnerWeight = w; exactWinner = t; }
  if (exactWinner && exactWinnerWeight >= halfWeight) return exactWinner;

  // Tier 2: alphanum agreement — collapse to alphanum form, weight-sum per
  // group, pick the richest variant of the dominant form.
  const alnumGroups = new Map(); // alnumKey → { weight, variants[] }
  for (const t of normalized) {
    const key = t.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!key) continue;
    let g = alnumGroups.get(key);
    if (!g) { g = { weight: 0, variants: [] }; alnumGroups.set(key, g); }
    g.weight += scoreOf(t);
    g.variants.push(t);
  }
  let bestKey = null; let bestKeyWeight = 0;
  for (const [k, g] of alnumGroups) if (g.weight > bestKeyWeight) { bestKeyWeight = g.weight; bestKey = k; }
  if (bestKey && bestKeyWeight >= halfWeight) {
    const variants = alnumGroups.get(bestKey).variants.slice();
    variants.sort((a, b) => _pmOcrResultScore(b) - _pmOcrResultScore(a));
    return variants[0];
  }

  // Tier 3: original score-based fallback (the single highest-scoring entry)
  return [...normalized].sort((a, b) => _pmOcrResultScore(b) - _pmOcrResultScore(a))[0];
}

// Seek the video to a target absolute frame, wait for the new frame to be
// presented, then capture and return its canvas. Restores nothing on its own —
// the caller is responsible for seeking back when done. Returns null if the
// video isn't ready or the seek times out.
function _pmSeekAndCapture(absF, timeoutMs = 700) {
  if (!pmVideo) return Promise.resolve(null);
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      pmVideo.removeEventListener('seeked', onSeeked);
      if (timer) clearTimeout(timer);
      // Give one rAF for the seeked frame to actually paint to the element
      requestAnimationFrame(() => {
        requestAnimationFrame(() => resolve(_pmCaptureCurrentVideoCanvas()));
      });
    };
    const onSeeked = () => finish();
    pmVideo.addEventListener('seeked', onSeeked);
    try { _pmSeekVideoAbsFrame(absF); } catch { finish(); return; }
    const timer = setTimeout(finish, timeoutMs);
  });
}

// Pool OCR pass results across multiple frames sampled around the marker.
// Slate burn-ins typically stay on screen for many frames, so even when one
// frame's OCR returns garbage, the consensus across ±N neighbors recovers
// the true text. Returns the consensus string from the pooled passes.
//
// The center frame runs the full robust pipeline (6 preprocessing × PSM
// variants); each neighbor runs a single lightweight pass to keep the total
// cost bounded. With offsets [-2, -1, 0, 1, 2] the cost is ~6 + 4 OCR calls
// vs the original 6 — roughly 1.5× per marker.
async function _pmOcrRecognizeMultiFrame({
  centerAbsF, roi, whitelist, offsets, restoreToFrame,
}) {
  const client = _pmGetOcrClient();
  const pooled = [];

  // Center frame uses the existing robust runner so we still get the full
  // 6-pass cross-pass voting at the actual marker frame.
  const centerCanvas = _pmCaptureCurrentVideoCanvas();
  if (centerCanvas) {
    const cropData = _pmOcrCropAndScale(centerCanvas, roi);
    if (cropData) {
      const processed = _pmOcrPreprocess(cropData);
      if (processed) {
        await _pmOcrRecognizeRobust(processed, cropData, whitelist);
        // Pool ALL per-pass results from the center, not just its consensus pick
        if (Array.isArray(_pmOcrLastPassResults)) pooled.push(..._pmOcrLastPassResults);
      }
    }
  }

  // Neighbor frames — single PSM 7 pass each, fast.
  for (const off of (offsets || [])) {
    if (!off) continue;
    const absF = centerAbsF + off;
    if (!Number.isFinite(absF) || absF < 0) continue;
    const canvas = await _pmSeekAndCapture(absF);
    if (!canvas) continue;
    const cropData = _pmOcrCropAndScale(canvas, roi);
    if (!cropData) continue;
    const processed = _pmOcrPreprocess(cropData);
    if (!processed) continue;
    try {
      const t = await client.recognize(processed, { psm: 7, whitelist });
      const n = _pmOcrNormalizeRaw(t || '');
      if (n) pooled.push(n);
    } catch { /* skip this frame */ }
  }

  // Always return to the marker frame so the user's view is restored.
  if (Number.isFinite(restoreToFrame)) {
    try { _pmSeekVideoAbsFrame(restoreToFrame); } catch {}
  }

  if (!pooled.length) return '';
  return _pmOcrPickConsensus(pooled);
}

function _pmOcrCropThumbUrl(srcCanvas, roi) {
  if (!srcCanvas || !roi) return null;
  const x = Math.max(0, Math.round(roi.x * srcCanvas.width));
  const y = Math.max(0, Math.round(roi.y * srcCanvas.height));
  const w = Math.max(2, Math.min(srcCanvas.width  - x, Math.round(roi.w * srcCanvas.width)));
  const h = Math.max(2, Math.min(srcCanvas.height - y, Math.round(roi.h * srcCanvas.height)));
  const tmp = document.createElement('canvas');
  tmp.width = w; tmp.height = h;
  tmp.getContext('2d').drawImage(srcCanvas, x, y, w, h, 0, 0, w, h);
  try { return tmp.toDataURL('image/jpeg', 0.85); } catch { return null; }
}

const _PM_OCR_PLATE_RE = /\b(PL|LG|FG|BG|EL|RF|CP|RO|FX|VX|CG|GR|AT|PT|PO)\d{2}\b/i;
const _PM_OCR_VER_RE   = /\bv\d{3,4}\b/i;
const _PM_OCR_TC_RE    = /^\d{1,2}:\d{2}:\d{2}[:;]\d{2}$/;
const _PM_OCR_FRAME_RE = /^\d{1,8}$/;

function detectVfxShotName(rawText, options = {}) {
  const { customRegex, normalizeIllegal = true, replaceSpaces = true, uppercase = false } = options;

  function clean(s) {
    if (replaceSpaces)    s = s.replace(/\s+/g, '_');
    if (normalizeIllegal) s = s.replace(/[^A-Za-z0-9_\-.]/g, '').replace(/_+/g, '_').replace(/^_+|_+$/g, '');
    if (uppercase)        s = s.toUpperCase();
    return s;
  }
  function score(s) {
    if (!s || s.length < 5)         return 0;
    if (_PM_OCR_TC_RE.test(s))      return 0;
    if (_PM_OCR_FRAME_RE.test(s))   return 0;
    const segs = s.split(/[_\-.]/);
    if (segs.length < 2)            return 0;
    let sc = 0;
    sc += Math.min(segs.length, 7) * 0.08;
    if (_PM_OCR_PLATE_RE.test(s))   sc += 0.30;
    if (_PM_OCR_VER_RE.test(s))     sc += 0.15;
    if (/[A-Z]{2,4}_\d{3}/.test(s)) sc += 0.20;
    if (s.includes('_'))            sc += 0.10;
    const aRatio = (s.match(/[A-Za-z]/g) || []).length / Math.max(1, s.length);
    if (aRatio > 0.2 && aRatio < 0.85) sc += 0.10;
    sc -= Math.max(0, s.length - 60) * 0.01;
    return Math.min(1, sc);
  }

  const candidates = [];
  const illegalFound = rawText !== rawText.replace(/[^A-Za-z0-9_\-.\s\r\n]/g, '');

  for (const line of rawText.split(/[\r\n]+/)) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (customRegex) {
      try {
        const re = new RegExp(customRegex, 'g');
        let m;
        while ((m = re.exec(trimmed)) !== null) {
          const v = clean(m[0]);
          if (v.length >= 5) candidates.push({ value: v, confidence: 0.90, reason: 'custom-regex', sourceRegion: '' });
        }
      } catch {}
    }
    for (const tok of [trimmed, ...trimmed.split(/\s+/)]) {
      if (tok.length < 5 || _PM_OCR_TC_RE.test(tok.trim())) continue;
      const v = clean(tok);
      if (!v || v.length < 5) continue;
      const c = score(v);
      if (c > 0) candidates.push({ value: v, confidence: c, reason: 'pattern-match', sourceRegion: '' });
    }
  }

  const seen = new Map();
  for (const c of candidates) {
    const ex = seen.get(c.value);
    if (!ex || c.confidence > ex.confidence) seen.set(c.value, c);
  }
  const deduped = [...seen.values()].sort((a, b) => b.confidence - a.confidence);
  return { rawText, candidates: deduped, bestCandidate: deduped[0] || null, illegalCharsCleaned: illegalFound };
}

// Apply user-selected text cleanup to a raw OCR string
function _pmCleanOcrText(text, settings) {
  let s = String(text || '').trim();
  if (settings.keepSpaces) return s; // keep-spaces wins; skip all other transforms
  if (settings.replaceSpaces) s = s.replace(/\s+/g, '_');
  if (settings.normalizeIllegal) s = s.replace(/[^A-Za-z0-9_\-.]/g, '').replace(/_+/g, '_').replace(/^_+|_+$/g, '');
  if (settings.uppercase) s = s.toUpperCase();
  return s;
}

// Mode-aware OCR result processor — wraps detectVfxShotName with Any Text / Custom Regex modes
function _pmOcrProcess(rawText, settings) {
  const mode = settings.detectionMode || 'vfxShotName';
  const vfxResult = detectVfxShotName(rawText, settings);
  const isVfxMatch = !!vfxResult.bestCandidate;

  // Raw-line candidates: every non-empty OCR line as a usable option
  const rawLines = rawText.split(/[\r\n]+/).map(l => l.trim()).filter(l => l.length >= 2);
  const rawCandidates = rawLines.map(line => ({
    value: line,
    confidence: 0.30,
    reason: 'raw-text',
    sourceRegion: '',
    isRaw: true,
  }));

  if (mode === 'anyText') {
    // Merge VFX hits + raw lines (prefer VFX if found)
    const vfxVals = new Set(vfxResult.candidates.map(c => c.value));
    const merged  = [...vfxResult.candidates,
                     ...rawCandidates.filter(r => !vfxVals.has(r.value))];
    const best = merged[0] || null;
    return { rawText, candidates: merged, bestCandidate: best, isVfxMatch, detectionMode: mode, rawCandidates };
  }

  if (mode === 'customRegex') {
    const customCands = vfxResult.candidates.filter(c => c.reason === 'custom-regex');
    const all  = customCands.length > 0 ? customCands : rawCandidates;
    const best = all[0] || null;
    return { rawText, candidates: all, bestCandidate: best, isVfxMatch: customCands.length > 0, detectionMode: mode, rawCandidates };
  }

  // VFX Shot Name mode — include raw lines as fallback candidates (never block apply)
  const vfxVals = new Set(vfxResult.candidates.map(c => c.value));
  const augmented = [...vfxResult.candidates, ...rawCandidates.filter(r => !vfxVals.has(r.value))];
  return { ...vfxResult, candidates: augmented, isVfxMatch, detectionMode: mode, rawCandidates };
}

// ── OCR Dictionary, Fuzzy-Match & Confidence ─────────────────────────────

function _pmBuildOcrDictionary() {
  const dict = new Set();
  for (const mk of (_pmClipMarkers || [])) {
    if (mk.shotName?.trim().length >= 3)  dict.add(mk.shotName.trim());
    if (mk.clipName?.trim().length >= 3)  dict.add(mk.clipName.trim());
    if (mk.reel?.trim().length >= 3)      dict.add(mk.reel.trim());
    // ── Bare slate text from previous OCR runs on this project ──
    // After auto-apply, mk.shotName is the FULL template-built name
    // (e.g. "STB_101_R01_0220_0000") which won't match raw OCR "R010220"
    // via separator-blind. We also need the bare OCR text so the matcher
    // can recover the slate-style entries.
    if (mk.ocr?.verifiedText?.trim().length >= 3) dict.add(mk.ocr.verifiedText.trim());
    if (mk.ocr?.cleanText?.trim().length    >= 3) dict.add(mk.ocr.cleanText.trim());
    if (mk.template?.ocrText?.trim().length >= 3) dict.add(mk.template.ocrText.trim());
  }
  if (Array.isArray(_pmEvents)) {
    for (const ev of _pmEvents) {
      if (ev.clipName?.trim().length >= 3) dict.add(ev.clipName.trim());
      if (ev.clip?.trim().length >= 3)     dict.add(ev.clip.trim());
    }
  }
  try {
    const key = _lsKey('ocrDict.v1');
    const raw = localStorage.getItem(key);
    const arr = raw ? JSON.parse(raw) : [];
    // One-time pollution sweep: drop entries whose confirmed text contains
    // slate-illegal chars (whitespace, /, etc.). Rewrite the saved list so
    // poisoned entries vanish permanently. Recovery for users who got hit
    // by garbage auto-applies before the gate was tightened.
    const clean = [];
    let removed = 0;
    for (const e of (arr || [])) {
      const c = e?.confirmed?.trim();
      if (!c || c.length < 3) continue;
      if (!_pmOcrIsCleanSlateEntry(c)) { removed++; continue; }
      clean.push(e);
      dict.add(c);
    }
    if (removed > 0 && clean.length !== (arr || []).length) {
      try { localStorage.setItem(key, JSON.stringify(clean)); } catch {}
      try { console.info(`[PM OCR] purged ${removed} poisoned dictionary entr${removed === 1 ? 'y' : 'ies'}`); } catch {}
    }
  } catch {}
  return [...dict].filter(s => s.length >= 3);
}

function _pmOcrSaveDictEntry(rawOcr, confirmed) {
  if (!rawOcr || !confirmed || rawOcr === confirmed) return;
  // Refuse to save OCR-corruption artifacts. Slate / shot names are always
  // filename-safe; any whitespace, /, \, : etc. in the confirmed value is
  // almost certainly a bad auto-apply (we've seen "SR 01/02_80", "IR 01/02_50"
  // get through before the dict pollution fix). Saving such entries causes a
  // feedback loop: the abstract-shape inference picks up the dirty pattern
  // and produces more garbage on future markers.
  if (!_pmOcrIsCleanSlateEntry(confirmed)) return;
  try {
    const key = _lsKey('ocrDict.v1');
    const arr = JSON.parse(localStorage.getItem(key) || '[]');
    // Dedup by rawOcr — update existing entry if present
    const idx = arr.findIndex(e => e?.raw === rawOcr);
    const entry = { raw: rawOcr, confirmed, ts: Date.now() };
    if (idx >= 0) arr[idx] = entry; else arr.push(entry);
    // Keep most recent 500 entries
    if (arr.length > 500) arr.splice(0, arr.length - 500);
    localStorage.setItem(key, JSON.stringify(arr));
  } catch {}
}

function _pmLevenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({ length: m + 1 }, (_, i) => [i, ...Array(n).fill(0)]);
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i-1] === b[j-1]
        ? dp[i-1][j-1]
        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
    }
  }
  return dp[m][n];
}

// Strip separators and punctuation that OCR commonly drops; keep only [a-z0-9].
// This lets "R010280" (raw OCR) match "R01_0280" (dictionary) exactly.
function _pmOcrAlphanum(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Apply a small character-confusion table that handles the most common
// Tesseract glyph swaps in alphanumeric VFX shot names. Only used as a
// last-resort comparison — never permanently rewrites the text.
const _PM_OCR_CONFUSION = {
  'o': '0', '0': '0',
  'i': '1', 'l': '1', '|': '1', '1': '1',
  's': '5', '5': '5',
  'b': '8', '8': '8',
  'z': '2', '2': '2',
  'd': '0',
  'q': '0',
};
function _pmOcrCanonical(s) {
  const lc = _pmOcrAlphanum(s);
  let out = '';
  for (const ch of lc) out += (_PM_OCR_CONFUSION[ch] || ch);
  return out;
}

// Derive a "shape" describing where separators sit inside a dictionary entry.
// E.g. "R01_0280" → { alphanum: "r010280", template: "r01_0280", separators: [{pos:3,ch:'_'}] }.
// Used to reconstruct the underscore in raw OCR like "R010280" when the
// dictionary has consistent reel-style entries.
function _pmOcrShape(entry) {
  const lc = String(entry || '').toLowerCase();
  const separators = [];
  let alphanum = '';
  for (let i = 0; i < lc.length; i++) {
    const ch = lc[i];
    if (/[a-z0-9]/.test(ch)) {
      alphanum += ch;
    } else {
      // Position is where this separator falls in the alphanum-stripped form
      separators.push({ pos: alphanum.length, ch: lc[i] });
    }
  }
  // template re-built from alphanum with separators applied; useful for display
  let template = '';
  let cursor = 0;
  for (let i = 0; i < alphanum.length; i++) {
    while (cursor < separators.length && separators[cursor].pos === i) {
      template += separators[cursor].ch; cursor++;
    }
    template += alphanum[i];
  }
  while (cursor < separators.length) { template += separators[cursor].ch; cursor++; }
  return { alphanum, separators, template };
}

// Apply a shape's separator pattern to a raw OCR alphanum string. Returns the
// reconstructed text (e.g. shape from "R01_0280" applied to "r010290" → "r01_0290").
// Returns null if the alphanum length doesn't match — pattern is shape-specific.
function _pmOcrApplyShape(shape, rawAlphanum) {
  if (!shape || !shape.separators.length) return null;
  if (rawAlphanum.length !== shape.alphanum.length) return null;
  let out = '';
  let sepIdx = 0;
  for (let i = 0; i < rawAlphanum.length; i++) {
    while (sepIdx < shape.separators.length && shape.separators[sepIdx].pos === i) {
      out += shape.separators[sepIdx].ch; sepIdx++;
    }
    out += rawAlphanum[i];
  }
  while (sepIdx < shape.separators.length) { out += shape.separators[sepIdx].ch; sepIdx++; }
  return out;
}

// Find the dominant shape in the dictionary — i.e. the most common (alphanumLen,
// separatorSignature) combination. Returns null if no consistent shape exists.
// Slate / shot-name entries should only contain filename-safe chars. Anything
// with whitespace, /, \, :, or other illegal-filename punctuation is almost
// always an OCR-corruption artifact from a previous bad auto-apply. We exclude
// such entries from the abstract-shape inference so a single bad apply can't
// poison the shape for future markers.
function _pmOcrIsCleanSlateEntry(s) {
  const t = String(s || '');
  if (!t) return false;
  // Reject whitespace, /, \, :, *, ?, ", <, >, |, brackets, parens, braces.
  // Allow A-Z, a-z, 0-9, _, -, .
  if (/[\s\/\\:*?"<>|()\[\]{}]/.test(t)) return false;
  return true;
}

function _pmOcrDominantShape(dictionary) {
  const counts = new Map();
  let bestKey = null; let bestCount = 0; let bestShape = null;
  for (const e of dictionary) {
    if (!_pmOcrIsCleanSlateEntry(e)) continue;
    const sh = _pmOcrShape(e);
    if (!sh.separators.length) continue;
    const key = sh.alphanum.length + ':' + sh.separators.map(s => `${s.pos}${s.ch}`).join('|');
    const next = (counts.get(key) || 0) + 1;
    counts.set(key, next);
    if (next > bestCount) { bestCount = next; bestKey = key; bestShape = sh; }
  }
  // Require the dominant shape to be backed by at least 2 entries OR be the only shape
  if (bestShape && (bestCount >= 2 || counts.size === 1)) return bestShape;
  return null;
}

// Build an *abstract* shape that records, for each alphanum position, whether
// the dictionary consistently expects a letter or a digit there, and what the
// canonical character at that position is. Used to recover OCR mis-reads of
// letters as similarly-shaped digits or punctuation (e.g. R→[, R→0, B→8).
//
// Returns: { alphanumLen, abstract: ['letter'|'digit'|'mixed', ...],
//            canonicalChar: ['R','0','1', ...], separators, dictHits }
function _pmOcrAbstractShape(dictionary) {
  // Filter out OCR-corruption artifacts BEFORE deriving any shape. Dirty
  // entries get skipped here even if they outnumber clean ones — they should
  // never influence the pattern that future markers get fit to.
  const cleanDict = (dictionary || []).filter(_pmOcrIsCleanSlateEntry);
  const shapes = cleanDict.map(e => _pmOcrShape(e)).filter(s => s.alphanum.length >= 4);
  if (!shapes.length) return null;
  // Group by (alphanum length, separator signature) — same as dominant shape grouping
  const groups = new Map();
  for (const sh of shapes) {
    const key = sh.alphanum.length + ':' + sh.separators.map(s => `${s.pos}${s.ch}`).join('|');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(sh);
  }
  let bestArr = null; let bestCount = 0;
  for (const arr of groups.values()) if (arr.length > bestCount) { bestCount = arr.length; bestArr = arr; }
  if (!bestArr || (bestCount < 2 && groups.size > 1)) return null;

  const len = bestArr[0].alphanum.length;
  const abstract = []; const canonical = [];
  for (let i = 0; i < len; i++) {
    let letters = 0, digits = 0;
    const counts = new Map();
    for (const sh of bestArr) {
      const ch = sh.alphanum[i];
      counts.set(ch, (counts.get(ch) || 0) + 1);
      if (/\d/.test(ch)) digits++; else if (/[a-z]/.test(ch)) letters++;
    }
    abstract.push(letters > digits ? 'letter' : digits > letters ? 'digit' : 'mixed');
    // Pick the most-common char at this position as the canonical fallback
    let mc = ''; let mcCount = 0;
    for (const [ch, n] of counts) if (n > mcCount) { mcCount = n; mc = ch; }
    canonical.push(mc);
  }
  return {
    alphanumLen: len,
    abstract,
    canonicalChar: canonical,
    separators: bestArr[0].separators,
    dictHits: bestCount,
  };
}

// Digit-shape characters that Tesseract commonly returns when a letter was the
// actual glyph. Used at "letter" positions to swap garbage back to letters.
const _PM_OCR_DIGIT_TO_LETTER = {
  '0':'O', '1':'I', '5':'S', '8':'B', '2':'Z',
  '[':'R', '(':'R', '{':'R', '|':'I', '/':'I', '\\':'I', '!':'I',
};
const _PM_OCR_LETTER_TO_DIGIT = {
  'O':'0','o':'0','I':'1','l':'1','S':'5','s':'5','B':'8','b':'8','Z':'2','z':'2','D':'0','d':'0','Q':'0','q':'0',
};

// Strip just the non-alphanum chars from rawOcr while preserving case.
function _pmOcrStripNonAlnumCased(raw) {
  return String(raw || '').replace(/[^A-Za-z0-9]/g, '');
}

// Try to fit a raw OCR string into an abstract shape derived from the dictionary.
// Allows ±1 length tolerance (handles single hallucinated/missing chars). At
// letter positions, OCR digits are converted via the digit→letter table; at
// digit positions, OCR letters are converted via the letter→digit table; chars
// that don't have a confusion mapping fall back to the canonical char from the
// dict. Returns the best-fit string or null.
function _pmOcrFitToAbstractShape(rawOcr, abs) {
  if (!abs || !abs.alphanumLen) return null;
  const stripped = _pmOcrStripNonAlnumCased(rawOcr);
  if (!stripped) return null;
  const target = abs.alphanumLen;

  // Build length-tolerant variants (preserve case)
  const variants = [];
  if (stripped.length === target) variants.push(stripped);
  if (stripped.length === target + 1) { variants.push(stripped.slice(1), stripped.slice(0, -1)); }
  if (stripped.length === target + 2) { variants.push(stripped.slice(1, -1)); }
  if (stripped.length === target - 1) {
    // Insert the canonical letter at position 0 (handles "OCR dropped the leading letter")
    variants.push(abs.canonicalChar[0].toUpperCase() + stripped);
  }
  if (!variants.length) return null;

  // Score each variant — count how many chars match the expected type natively
  let bestText = null; let bestScore = -Infinity;
  for (const v of variants) {
    if (v.length !== target) continue;
    let fitted = '';
    let score = 0;
    for (let i = 0; i < target; i++) {
      const ch = v[i];
      const expect = abs.abstract[i];
      if (expect === 'letter') {
        if (/[A-Za-z]/.test(ch))      { fitted += ch.toUpperCase(); score += 2; }
        else if (_PM_OCR_DIGIT_TO_LETTER[ch]) { fitted += _PM_OCR_DIGIT_TO_LETTER[ch]; score += 1; }
        else                          { fitted += abs.canonicalChar[i].toUpperCase(); /* score 0 */ }
      } else if (expect === 'digit') {
        if (/\d/.test(ch))            { fitted += ch; score += 2; }
        else if (_PM_OCR_LETTER_TO_DIGIT[ch]) { fitted += _PM_OCR_LETTER_TO_DIGIT[ch]; score += 1; }
        else                          { fitted += abs.canonicalChar[i] || '0'; /* score 0 */ }
      } else {
        fitted += ch; score += 1;
      }
    }
    if (score > bestScore) { bestScore = score; bestText = fitted; }
  }
  if (!bestText) return null;

  // Stitch separators back in at their positions
  let out = ''; let sepIdx = 0;
  for (let i = 0; i < bestText.length; i++) {
    while (sepIdx < abs.separators.length && abs.separators[sepIdx].pos === i) {
      out += abs.separators[sepIdx].ch; sepIdx++;
    }
    out += bestText[i];
  }
  while (sepIdx < abs.separators.length) { out += abs.separators[sepIdx].ch; sepIdx++; }
  return out;
}

function _pmOcrDictMatch(ocrText, dictionary) {
  if (!ocrText || !dictionary.length) return null;
  const norm = s => s.toLowerCase().replace(/[^a-z0-9._-]/g, '');
  const ocrN     = norm(ocrText);
  const ocrAlpha = _pmOcrAlphanum(ocrText);
  const ocrCanon = _pmOcrCanonical(ocrText);
  if (!ocrN.length) return null;

  let best = null;
  let secondBest = null;
  let alphaExact = null;   // exact match after stripping all separators
  let canonExact = null;   // exact match after applying confusion table

  for (const entry of dictionary) {
    const entryN     = norm(entry);
    if (!entryN.length) continue;
    const entryAlpha = _pmOcrAlphanum(entry);
    const entryCanon = _pmOcrCanonical(entry);

    // ── Tier 1: exact match after separator stripping (handles dropped _ - .)
    if (ocrAlpha && entryAlpha === ocrAlpha && !alphaExact) {
      alphaExact = { matched: entry, distance: 0, ratio: 0, unique: true, mode: 'separator-blind' };
    }
    // ── Tier 2: exact match after confusion table (O↔0, I↔1, …)
    if (!canonExact && ocrCanon && entryCanon === ocrCanon && entry !== ocrText) {
      canonExact = { matched: entry, distance: 0, ratio: 0, unique: true, mode: 'confusion-canonical' };
    }

    // ── Tier 3: classic Levenshtein on separator-preserving normalised forms
    const maxLen = Math.max(ocrN.length, entryN.length);
    const dist   = _pmLevenshtein(ocrN, entryN);
    const ratio  = dist / maxLen;
    if (!best || dist < best.distance) {
      secondBest = best;
      best = { matched: entry, distance: dist, ratio, unique: true, mode: 'levenshtein' };
    } else if (!secondBest || dist < secondBest.distance) {
      secondBest = { matched: entry, distance: dist, ratio, unique: true, mode: 'levenshtein' };
    }
  }

  // Prefer the strictest exact match available.
  if (alphaExact) return alphaExact;
  if (canonExact) return canonExact;
  if (!best) return null;
  if (best.ratio > 0.30) return null;
  if (secondBest && (secondBest.distance - best.distance) < 2) best.unique = false;
  return best;
}

// Build a Tesseract character whitelist from the dominant abstract pattern.
// When the project's slate text follows a consistent shape (e.g. R##_####),
// restrict the OCR engine to just the alphabet that pattern uses. This stops
// Tesseract from returning [, /, brackets etc. that can never be legitimate
// for THIS project. Returns null if no pattern is established yet — the
// caller should fall back to the wide whitelist in that case.
function _pmOcrBuildPatternWhitelist(dictionary) {
  const abs = _pmOcrAbstractShape(dictionary);
  if (!abs || !abs.dictHits || abs.dictHits < 2) return null;

  const letters = new Set();
  const digits = new Set();
  const seps = new Set();
  let hasDigitPosition = false;
  let hasLetterPosition = false;

  for (let i = 0; i < abs.canonicalChar.length; i++) {
    const ch = abs.canonicalChar[i];
    if (abs.abstract[i] === 'digit') hasDigitPosition = true;
    if (abs.abstract[i] === 'letter') hasLetterPosition = true;
    if (/[a-z]/.test(ch)) letters.add(ch.toUpperCase());
    if (/\d/.test(ch))    digits.add(ch);
  }
  for (const sep of abs.separators) seps.add(sep.ch);

  // If the pattern has digit positions, allow all digits (the canonical char
  // might be just one of many digits used across entries) and similarly include
  // standard ambiguity-survivors for letter positions.
  let alphabet = '';
  if (hasDigitPosition) alphabet += '0123456789';
  if (hasLetterPosition) {
    // Include common letters that appear in any dict entry's letter positions
    const allLetters = new Set();
    for (const d of dictionary) {
      for (const ch of String(d).toUpperCase()) {
        if (/[A-Z]/.test(ch)) allLetters.add(ch);
      }
    }
    if (allLetters.size) alphabet += [...allLetters].join('');
    else alphabet += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  }
  for (const s of seps) alphabet += s;
  return alphabet || null;
}

// Predict the next slate text from the project's recent confirmed entries.
// Detects a numeric series in the recent markers (e.g. R01_0210, R01_0220,
// R01_0230) and projects forward or backward depending on where the new marker
// sits in the timeline. Returns null when no consistent series is detected
// (e.g. <2 prior samples, mismatched prefixes, inconsistent step).
function _pmOcrPredictFromMarkerSeries(newMarker) {
  if (!newMarker) return null;
  const allMarkers = (_pmClipMarkers || []).filter(m => m && m.id !== newMarker.id);
  if (allMarkers.length < 2) return null;

  // Collect prior markers that have a bare slate text (not the full
  // template-built shotName, which contains show/ep prefixes that confuse the
  // series detector).
  const samples = [];
  for (const mk of allMarkers) {
    const text = (mk.ocr?.verifiedText || mk.ocr?.cleanText || mk.template?.ocrText || '').trim();
    if (text.length < 3) continue;
    samples.push({ text, recIn: mk.recIn || '', frame: mk.frame || 0 });
  }
  if (samples.length < 2) return null;

  // Sort by timeline position (recIn lex-sorts correctly for HH:MM:SS:FF;
  // frame index is the tiebreaker).
  samples.sort((a, b) => {
    if (a.recIn && b.recIn && a.recIn !== b.recIn) return a.recIn.localeCompare(b.recIn);
    return (a.frame || 0) - (b.frame || 0);
  });

  // Need the two most recent samples to share a prefix and suffix around a
  // trailing number — that's the "series" signature.
  const tail = samples.slice(-2);
  const reTrailing = /^(.*?)(\d+)([^\d]*)$/;
  const aM = tail[0].text.match(reTrailing);
  const bM = tail[1].text.match(reTrailing);
  if (!aM || !bM) return null;
  if (aM[1] !== bM[1] || aM[3] !== bM[3]) return null;
  if (aM[2].length !== bM[2].length) return null; // padding must match

  const aNum = parseInt(aM[2], 10);
  const bNum = parseInt(bM[2], 10);
  const step = bNum - aNum;
  if (step === 0) return null;
  // Steps tend to be multiples of 10 in VFX projects. Allow anything in
  // [1, 100] but be suspicious of weird steps.
  if (Math.abs(step) > 100) return null;

  // Direction: where does the new marker fall in the timeline relative to the
  // latest sample? If after → continue the series forward; before → go back.
  const newRecIn = newMarker.recIn || '';
  let direction = 1;
  if (newRecIn && tail[1].recIn) {
    direction = newRecIn.localeCompare(tail[1].recIn) >= 0 ? 1 : -1;
  } else if (Number.isFinite(newMarker.frame) && Number.isFinite(tail[1].frame)) {
    direction = (newMarker.frame || 0) >= (tail[1].frame || 0) ? 1 : -1;
  }

  const predictedNum = bNum + (step * direction);
  if (predictedNum < 0) return null;
  const padding = bM[2].length;
  return bM[1] + String(predictedNum).padStart(padding, '0') + bM[3];
}

// Build a list of reconstruction candidates from the raw OCR text using the
// dictionary's dominant shape AND abstract pattern. Ordered most→least
// confident. Empty arr is fine — the modal will fall back to raw OCR.
//
// Three reconstruction strategies (most→least content-changing):
//   1. Series prediction — extrapolate from the project's recent confirmed
//      entries. Only used when the prediction is *close* to the raw OCR
//      (within a small edit distance) so we don't override genuine readings.
//   2. Abstract fit — uses the dict's letter/digit positions + canonical chars
//      to recover OCR-mangled letters (R→[, R→0) and tolerates ±1 length drift
//      from hallucinated leading/trailing chars. Strong: changes content.
//   3. Separator insertion — only inserts the missing separators into raw
//      OCR's alphanum, preserving content. Weaker: trusts OCR content fully.
function _pmOcrReconstructions(rawOcr, dictionary, options = {}) {
  if (!rawOcr || !dictionary?.length) return [];
  const out = [];
  const seen = new Set();
  const push = (v) => { if (v && !seen.has(v)) { seen.add(v); out.push(v); } };

  // ── Strategy 1: series prediction from recent confirmed markers
  // Only added when it's *close* to the raw OCR — guards against a clean OCR
  // reading of a non-series shot getting silently overridden by extrapolation.
  if (options.predictedNext) {
    const pred = String(options.predictedNext);
    const predAlpha = _pmOcrAlphanum(pred);
    const rawAlpha  = _pmOcrAlphanum(rawOcr);
    if (predAlpha && rawAlpha) {
      const dist = _pmLevenshtein(predAlpha.toLowerCase(), rawAlpha.toLowerCase());
      const maxLen = Math.max(predAlpha.length, rawAlpha.length);
      // Accept when ≤ 30% of length differs from raw OCR alphanum — close
      // enough that OCR likely read this exact shot but with mis-read digits.
      if (maxLen > 0 && (dist / maxLen) <= 0.30) push(pred);
    }
  }

  // ── Strategy 2: abstract-pattern fit (replaces wrong letters at letter positions)
  const abs = _pmOcrAbstractShape(dictionary);
  if (abs) {
    const fitted = _pmOcrFitToAbstractShape(rawOcr, abs);
    if (fitted) push(fitted);
  }

  // ── Strategy 3: separator-only insertion (preserves OCR content)
  const ocrAlpha = _pmOcrAlphanum(rawOcr);
  const shape = _pmOcrDominantShape(dictionary);
  if (ocrAlpha && shape) {
    const reconstructed = _pmOcrApplyShape(shape, ocrAlpha);
    if (reconstructed) {
      // Preserve original case for letter chars in the OCR
      const original = String(rawOcr || '').replace(/[^A-Za-z0-9]/g, '');
      let cased = '';
      if (original.length === ocrAlpha.length) {
        let alphaIdx = 0;
        for (const ch of reconstructed) {
          if (/[a-z0-9]/.test(ch)) { cased += original[alphaIdx] || ch; alphaIdx++; }
          else cased += ch;
        }
        push(cased);
      } else {
        push(reconstructed);
      }
    }
  }

  return out;
}

function _pmOcrComputeConfidence(rawOcr, dictMatch, reconstructions = []) {
  if (!dictMatch) {
    // No fuzzy dict match, but if we can reconstruct a separator-aware form
    // from the dominant pattern, surface that as the suggestion instead of raw.
    if (reconstructions.length) {
      return {
        level: 'HIGH',
        reason: `Pattern reconstruction: "${reconstructions[0]}" (separators inferred from project)`,
        finalText: reconstructions[0],
        source: 'reconstruction',
      };
    }
    return { level: 'LOW', reason: 'No matching filename in project dictionary', finalText: rawOcr };
  }
  const { matched, distance, unique, mode } = dictMatch;
  if (mode === 'separator-blind') {
    return {
      level: 'VERIFIED',
      reason: `Separator-blind match: "${matched}" (OCR dropped a separator)`,
      finalText: matched,
      source: 'separator-blind',
    };
  }
  if (mode === 'confusion-canonical') {
    return {
      level: 'HIGH',
      reason: `Glyph-canonical match: "${matched}" (after O↔0 / I↔1 / S↔5 correction)`,
      finalText: matched,
      source: 'confusion',
    };
  }
  if (distance <= 2 && unique) {
    return { level: 'VERIFIED', reason: `Exact/near-exact match: "${matched}" (edit dist ${distance})`, finalText: matched };
  }
  if (distance <= 4 && unique) {
    return { level: 'HIGH', reason: `Close match: "${matched}" (edit dist ${distance})`, finalText: matched };
  }
  // REVIEW used to auto-fill the input — that silently applied the wrong shot
  // when OCR'ing a new reel. Now: keep the REVIEW level for context, but if a
  // pattern reconstruction is available, prefer it; otherwise fall back to raw.
  if (distance <= 6) {
    const finalText = reconstructions[0] || rawOcr;
    const recHint = reconstructions[0] ? ` · suggestion: "${reconstructions[0]}"` : '';
    return {
      level: 'REVIEW',
      reason: `Possible match: "${matched}" (edit dist ${distance})${unique ? '' : ', not unique'}${recHint}`,
      finalText,
      source: reconstructions[0] ? 'reconstruction' : 'raw',
      altMatched: matched,
    };
  }
  return { level: 'LOW', reason: `Weak match: "${matched}" (edit dist ${distance})`, finalText: reconstructions[0] || rawOcr };
}

function _pmCaptureCurrentVideoCanvas() {
  if (!pmVideo || pmVideo.readyState < 2 || !pmVideo.videoWidth) return null;
  const W = pmVideo.videoWidth, H = pmVideo.videoHeight;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  try { c.getContext('2d').drawImage(pmVideo, 0, 0, W, H); return c; } catch { return null; }
}

// Parse OCR burn-in text into naming-template field values.
// Handles common VFX burn-in formats: SHOW_EP_SEQ_SCENE, vendor prefixes, version suffixes.
function _pmParseOcrTextToFields(text) {
  if (!text) return {};
  const result = {};
  const t = text.trim().replace(/\s+/g, ' ');

  // Version: v001, v01, V001, _v1, _V1 etc.
  const verMatch = t.match(/[_\s]?[vV](\d{1,4})\b/);
  if (verMatch) result.ver = 'v' + verMatch[1].padStart(3, '0');

  // Vendor: common 2-4 letter codes in all-caps at start or after underscore
  const vendorMatch = t.match(/(?:^|[_\s])([A-Z]{2,5})(?=[_\s]|$)/);
  if (vendorMatch && !['VFX','OCR','INT','EXT','DAY','NGT'].includes(vendorMatch[1])) {
    result.vendor = vendorMatch[1];
  }

  // Split on common delimiters to find positional tokens
  const parts = t.split(/[_\-\s\.\/]+/).filter(Boolean);

  // Heuristics: EP = digits 3 chars or Exx, SEQ = 3+ alpha chars, SCENE = Sxx or 3 chars
  for (const part of parts) {
    if (!result.ep && /^[Ee]\d{2,3}$/.test(part)) result.ep = part.toUpperCase();
    if (!result.seq && /^[A-Z]{2,4}$/.test(part) && part !== result.vendor) result.seq = part;
    if (!result.scene && /^[Ss]\d{2,4}$/.test(part)) result.scene = part.toUpperCase();
    if (!result.show && /^[A-Z]{3,6}$/.test(part) && !result.seq) result.show = part;
  }

  return result;
}

// Auto-OCR path: runs on marker creation when OCR is enabled in project settings.
// Auto-applies when confidence meets the threshold; shows the modal for review otherwise.
async function _pmAutoOcrAndApply(mkId) {
  if (_pmOcrRunning) return;
  const mk = _pmClipMarkers.find(m => m.id === mkId);
  if (!mk) return;
  const settings = _pmGetOcrSettings();
  const evIdx    = mk._eventIdx ?? -1;
  const { roi, source: regionKey } = _pmGetEffectiveRoi(mkId, evIdx);
  const videoCanvas = _pmCaptureCurrentVideoCanvas();
  if (!videoCanvas) return; // no video — silently skip
  _pmOcrRunning = true;
  try {
    const cropData  = _pmOcrCropAndScale(videoCanvas, roi);
    if (!cropData) throw new Error('Crop failed');
    const processed = _pmOcrPreprocess(cropData);
    if (!processed) throw new Error('Preprocess failed');
    // Build dict first so we can derive a pattern-constrained whitelist. When
    // the project's slate text follows a consistent shape (e.g. R##_####), we
    // restrict the OCR alphabet to characters that pattern actually uses so
    // Tesseract can't return [, /, brackets that pollute matching.
    const _ocrDict = _pmBuildOcrDictionary();
    const _patternWl = (settings.detectionMode !== 'anyText')
                       ? _pmOcrBuildPatternWhitelist(_ocrDict) : null;
    const _ocrWl  = _patternWl || 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.()/:[] ';

    // ── OCR engine cascade ─────────────────────────────────────────────────
    // Priority: Claude Vision API → Apple Vision (companion) → Tesseract.
    // Each step returns null when unavailable and we fall through to the next.
    let rawText = '';
    let _ocrAiSource = '';
    const claudeText = await _pmOcrTryClaudeVision(cropData);
    if (claudeText) {
      rawText = claudeText;
      _ocrAiSource = 'claude-vision';
    } else {
      const visionText = await _pmOcrTryCompanion(cropData);
      if (visionText) {
        rawText = visionText;
        _ocrAiSource = 'apple-vision';
      } else if (settings.multiFrameOcr && pmVideo && pmVideo.readyState >= 2) {
        const centerAbsF = _pmReadVideoAbsFrame();
        rawText = await _pmOcrRecognizeMultiFrame({
          centerAbsF,
          roi,
          whitelist: _ocrWl,
          offsets: settings.multiFrameOffsets,
          restoreToFrame: centerAbsF,
        });
      } else {
        rawText = await _pmOcrRecognizeRobust(processed, cropData, _ocrWl);
      }
    }
    const result  = _pmOcrProcess(rawText, settings);
    result.regionKey    = regionKey;
    result.aiSource     = _ocrAiSource;
    result.cropThumbUrl = _pmOcrCropThumbUrl(videoCanvas, roi);
    const _predicted = _pmOcrPredictFromMarkerSeries(mk);
    const _dictMatch = _pmOcrDictMatch(rawText, _ocrDict);
    const _recon     = _pmOcrReconstructions(rawText, _ocrDict, { predictedNext: _predicted });
    const _conf      = _pmOcrComputeConfidence(rawText, _dictMatch, _recon);
    result.dictMatch       = _dictMatch;
    result.dictConf        = _conf;
    result.reconstructions = _recon;
    result.seriesPredicted = _predicted || null;

    // Pick best text to apply.
    // Auto-apply ONLY when we're confident:
    //   • Dict match is VERIFIED or HIGH (covers separator-blind and glyph-canonical hits)
    //   • Pattern reconstruction is available (separators inferred from project)
    // Otherwise — including when VFX detection found a non-pattern candidate —
    // open the modal so the user can confirm. The first few markers in a project
    // typically pass through the modal; their confirmations seed the dictionary
    // and subsequent markers can auto-apply via reconstruction.
    const dictLevel = _conf?.level || 'LOW';
    const best      = result.bestCandidate;
    const bestConf  = (best && result.isVfxMatch) ? (best.confidence ?? 0) : 0;
    const reconText = _recon[0] || '';
    const hasStrongMatch = dictLevel === 'VERIFIED' || dictLevel === 'HIGH';

    let applyText = '';
    let applySource = '';
    if (hasStrongMatch && _conf.finalText) {
      applyText = _conf.finalText;
      applySource = _conf.source || (dictLevel === 'VERIFIED' ? 'verified' : 'high');
    } else if (reconText) {
      applyText = reconText;
      applySource = 'reconstruction';
    }
    // Note: removed the "bestConf >= threshold" fallback. A high-confidence VFX
    // candidate that doesn't match the project's pattern (e.g. raw OCR "R0 18/02_20"
    // → garbage with illegal chars) used to silently apply, polluting the dict.

    if (applyText) {
      // Route through the template apply path (same as the modal's "Apply" button)
      // so we populate BOTH mk.ocr.{rawText,cleanText,verifiedText} (so the
      // inspector OCR badge stops showing "Not Set") AND mk.template.ocrText
      // (so the template auto-name pipeline runs and the shotName is rebuilt
      // from the template — _pmApplyOcrTextToMarkers only writes shotName).
      _pmApplyOcrToTemplate([mkId], applyText, rawText, {
        confidence: bestConf,
        region: regionKey,
        detectionMode: settings.detectionMode,
      });
      // Save (rawText → applyText) to the project dictionary so subsequent
      // markers can pattern-match against this confirmed text. Without this,
      // the dict only grows from modal Apply clicks and the abstract pattern
      // reconstruction degrades over time. Skip if raw == applyText (no useful
      // mapping to record).
      try { _pmOcrSaveDictEntry(rawText, applyText); } catch {}
      // Treat the applied text as user-verified for auto-applied high-confidence
      // cases so the OCR field shows green instead of "review" amber.
      const mkRef = _pmClipMarkers.find(m => m.id === mkId);
      if (mkRef?.ocr && (dictLevel === 'VERIFIED' || applySource === 'separator-blind')) {
        mkRef.ocr.verifiedText = applyText;
        mkRef.ocr.status = 'verified';
      }
      // Surface what happened so silent corrections aren't invisible. The toast
      // labels distinguish reconstructed text from straight dictionary hits so
      // the user can verify the fix matched their intent.
      const tag = applySource === 'separator-blind' ? 'separator fix'
                : applySource === 'confusion'       ? 'glyph fix'
                : applySource === 'reconstruction'  ? 'pattern fix'
                : applySource === 'verified'        ? 'matched'
                : applySource === 'high'            ? 'matched'
                : 'auto';
      _pmToast(`OCR → ${applyText} (${tag})`, 'info');
    } else {
      // Low confidence — do not open modal automatically; user can click OCR to review
    }
  } catch (err) {
    console.warn('[PM auto-OCR]', err);
  } finally {
    _pmOcrRunning = false;
  }
}

async function _pmRunOcrOnMarker(mkId, triggerBtn) {
  if (_pmOcrRunning) { _pmToast('OCR is already running…', 'info'); return; }
  const mk = _pmClipMarkers.find(m => m.id === mkId);
  if (!mk) return;
  const settings = _pmGetOcrSettings();
  const evIdx    = parseInt(pmInspector?.querySelector('.pm-insp-layers')?.dataset.evidx ?? '-1', 10);
  const { roi, source: regionKey } = _pmGetEffectiveRoi(mkId, evIdx);
  const videoCanvas = _pmCaptureCurrentVideoCanvas();
  if (!videoCanvas) { _pmToast('Cannot capture video frame. Is a video loaded?', 'error'); return; }
  _pmOcrRunning = true;
  if (triggerBtn) { triggerBtn.disabled = true; triggerBtn.textContent = '…'; }
  try {
    const cropData = _pmOcrCropAndScale(videoCanvas, roi);
    if (!cropData) throw new Error('Crop failed');
    const processed = _pmOcrPreprocess(cropData);
    if (!processed) throw new Error('Preprocess failed');
    // Build dict first so we can derive a pattern-constrained whitelist when
    // the project's slate text follows a consistent shape; otherwise fall back
    // to the wide whitelist (parens/slash kept for "TO COMPOSED (WIP)" etc.).
    const _ocrDict = _pmBuildOcrDictionary();
    const _patternWl = (settings.detectionMode !== 'anyText')
                       ? _pmOcrBuildPatternWhitelist(_ocrDict) : null;
    const _ocrWl = _patternWl || 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.()/:[] ';
    // Engine cascade: Claude Vision API → Apple Vision (companion) → Tesseract.
    let _rawText = '';
    let _aiSource = '';
    const _claudeText = await _pmOcrTryClaudeVision(cropData);
    if (_claudeText) {
      _rawText = _claudeText;
      _aiSource = 'claude-vision';
    } else {
      const _visionText = await _pmOcrTryCompanion(cropData);
      if (_visionText) { _rawText = _visionText; _aiSource = 'apple-vision'; }
      else _rawText = await _pmOcrRecognizeRobust(processed, cropData, _ocrWl);
    }
    const rawText = _rawText;
    const result = _pmOcrProcess(rawText, settings);
    result.regionKey    = regionKey;
    result.aiSource     = _aiSource;
    result.cropThumbUrl = _pmOcrCropThumbUrl(videoCanvas, roi);
    // Dictionary matching & confidence
    const _predicted = _pmOcrPredictFromMarkerSeries(mk);
    const _dictMatch = _pmOcrDictMatch(rawText, _ocrDict);
    const _recon     = _pmOcrReconstructions(rawText, _ocrDict, { predictedNext: _predicted });
    const _conf      = _pmOcrComputeConfidence(rawText, _dictMatch, _recon);
    result.dictMatch       = _dictMatch;
    result.dictConf        = _conf;
    result.reconstructions = _recon;
    result.seriesPredicted = _predicted || null;
    _pmShowOcrModal(mk, result, evIdx);
  } catch (err) {
    console.warn('[PM OCR]', err);
    _pmToast(`OCR failed: ${err.message || err}`, 'error');
  } finally {
    _pmOcrRunning = false;
    if (triggerBtn) { triggerBtn.disabled = false; triggerBtn.textContent = 'OCR'; }
  }
}

function _pmShowOcrModal(mk, result, evIdx) {
  document.querySelector('.pm-ocr-modal')?.remove();
  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const settings     = _pmGetOcrSettings();
  const detMode      = result.detectionMode || settings.detectionMode || 'vfxShotName';
  const best         = result.bestCandidate;
  const isVfxMatch   = !!result.isVfxMatch;
  const conf         = (best && isVfxMatch) ? best.confidence : 0;
  const confLabel    = conf >= 0.85 ? 'High' : conf >= 0.65 ? 'Medium' : 'Low';
  const confCls      = conf >= 0.85 ? 'pm-ocr-conf-high' : conf >= 0.65 ? 'pm-ocr-conf-med' : 'pm-ocr-conf-low';

  // Dictionary confidence (from spec: VERIFIED/HIGH/REVIEW/LOW)
  const dictConf     = result.dictConf  || null;
  const dictMatch    = result.dictMatch || null;
  const dictLevel    = dictConf?.level  || 'LOW';
  const dictIsLow    = dictLevel === 'LOW';
  const dictLevelCls = { VERIFIED: 'pm-ocr-dict-verified', HIGH: 'pm-ocr-dict-high',
                          REVIEW: 'pm-ocr-dict-review', LOW: 'pm-ocr-dict-low' }[dictLevel] || 'pm-ocr-dict-low';

  // Initial text for the editable input.
  // Priority order:
  //   1. VERIFIED or HIGH dict match (high-confidence — separator-blind, glyph-canonical, or low edit-dist)
  //   2. Pattern reconstruction (separators inferred from project's dominant shape)
  //   3. REVIEW-level dict suggestion is shown in the UI but NEVER auto-fills —
  //      that's the silent-wrong-shot bug we just fixed
  //   4. VFX candidate / raw best line / empty
  const firstRawLine    = (result.rawCandidates || [])[0]?.value || '';
  const reconstructions = result.reconstructions || [];
  const dictLevel_      = dictConf?.level || 'LOW';
  const initialText =
    (dictConf && (dictLevel_ === 'VERIFIED' || dictLevel_ === 'HIGH')) ? dictConf.finalText :
    reconstructions[0] ? reconstructions[0] :
    (best?.value || firstRawLine || '');

  // Region dropdown
  const _hasManual    = !!settings.manualCrop;
  const _regionLabels = { manual:'Manual Area', bottomCenter:'Bottom Center', bottomLeft:'Bottom Left',
    bottomRight:'Bottom Right', topLeft:'Top Left', topRight:'Top Right', fullFrame:'Full Frame' };
  const selectedRegionKey = (result.regionKey === 'marker' || result.regionKey === 'clip' || result.regionKey === 'manual')
    ? 'manual'
    : result.regionKey;
  const regionOpts = [
    ...(_hasManual ? [['manual','Manual Area']] : []),
    ...Object.keys(_PM_OCR_REGIONS).map(k => [k, _regionLabels[k] || k])
  ].map(([k, label]) => `<option value="${k}"${k === selectedRegionKey ? ' selected' : ''}>${label}</option>`).join('');

  // VFX candidates section
  const vfxCands    = result.candidates.filter(c => !c.isRaw).slice(0, 4);
  const rawCands    = (result.rawCandidates || []).slice(0, 3);
  const vfxCandsHtml = vfxCands.map((c, i) =>
    `<button class="pm-ocr-cand-btn${i === 0 ? ' is-best' : ''}" data-value="${esc(c.value)}" type="button">
       <span class="pm-ocr-cand-val">${esc(c.value)}</span>
       <span class="pm-ocr-cand-pct">${Math.round(c.confidence * 100)}%</span>
     </button>`).join('');
  const rawCandsHtml = rawCands.map((c, i) =>
    `<button class="pm-ocr-cand-btn pm-ocr-cand-raw${!vfxCands.length && i === 0 && !reconstructions.length ? ' is-best' : ''}" data-value="${esc(c.value)}" type="button">
       <span class="pm-ocr-cand-val">${esc(c.value)}</span>
       <span class="pm-ocr-cand-pct is-raw">raw</span>
     </button>`).join('');
  // Pattern-reconstructed candidate — shown when raw OCR is missing separators
  // that the dictionary's dominant shape implies. Highlighted as best when no
  // VFX candidate exists, so user sees the corrected form first.
  const reconCandsHtml = reconstructions.map((v, i) =>
    `<button class="pm-ocr-cand-btn pm-ocr-cand-recon${!vfxCands.length && i === 0 ? ' is-best' : ''}" data-value="${esc(v)}" type="button" title="Reconstructed from raw OCR using the project's dominant naming pattern">
       <span class="pm-ocr-cand-val">${esc(v)}</span>
       <span class="pm-ocr-cand-pct is-recon">fixed</span>
     </button>`).join('');

  // Mode-specific top warning
  const noVfxWarn = !isVfxMatch && detMode === 'vfxShotName'
    ? `<div class="pm-ocr-warn pm-ocr-warn--nowrap">No VFX-style shot name found. You can still apply OCR text manually.</div>` : '';
  const tcWarn = result.rawText && _PM_OCR_TC_RE.test(result.rawText.trim())
    ? `<div class="pm-ocr-warn pm-ocr-warn-yellow">OCR text looks like a timecode. Verify before applying.</div>` : '';

  const modal = document.createElement('div');
  modal.className = 'pm-ocr-modal';
  modal.innerHTML = `
    <div class="pm-ocr-modal-inner">
      <div class="pm-ocr-modal-hdr">
        <span class="pm-ocr-modal-title">OCR — Apply to Template</span>
        <button class="pm-ocr-modal-close" type="button" title="Close">✕</button>
      </div>
      <div class="pm-ocr-modal-body">
        ${result.cropThumbUrl ? `<img class="pm-ocr-crop-preview" src="${esc(result.cropThumbUrl)}" alt="OCR crop region">` : ''}

        <div class="pm-ocr-mode-row">
          <label class="pm-ocr-mode-lbl">Detection Mode:</label>
          <select class="pm-ocr-mode-sel">
            <option value="vfxShotName"${detMode==='vfxShotName'?' selected':''}>VFX Shot Name</option>
            <option value="anyText"${detMode==='anyText'?' selected':''}>Any Text</option>
            <option value="customRegex"${detMode==='customRegex'?' selected':''}>Custom Regex</option>
          </select>
        </div>

        <div class="pm-ocr-raw-wrap">
          <span class="pm-ocr-raw-lbl">Raw OCR:</span>
          <span class="pm-ocr-raw-text">${esc(result.rawText || '(no text detected)')}</span>
        </div>

        ${dictConf ? `
        <div class="pm-ocr-dict-row">
          <span class="pm-ocr-dict-lbl">Source match:</span>
          <span class="pm-ocr-dict-badge ${dictLevelCls}">${dictLevel}</span>
          ${dictMatch ? `<button class="pm-ocr-dict-use-btn" type="button" data-value="${esc(dictConf.finalText)}" title="Use matched filename">${esc(dictConf.finalText)}</button>` : ''}
          <span class="pm-ocr-dict-reason">${esc(dictConf.reason)}</span>
        </div>` : ''}

        ${noVfxWarn}${tcWarn}

        ${(vfxCands.length || rawCands.length || reconstructions.length) ? `
          <div class="pm-ocr-cands-lbl">Candidates:
            ${reconstructions.length ? `<span class="pm-ocr-cands-type-tag pm-ocr-cands-type-tag--recon">Pattern-fixed</span>` : ''}
            ${vfxCands.length ? `<span class="pm-ocr-cands-type-tag">VFX</span>` : ''}
            ${rawCands.length && !vfxCands.length && !reconstructions.length ? `<span class="pm-ocr-cands-type-tag pm-ocr-cands-type-tag--raw">Raw text</span>` : ''}
          </div>
          <div class="pm-ocr-cands">${reconCandsHtml}${vfxCandsHtml || (reconstructions.length ? '' : rawCandsHtml)}</div>
          ${(vfxCands.length || reconstructions.length) && rawCands.length ? `
            <div class="pm-ocr-raw-cands-lbl">Raw OCR lines:</div>
            <div class="pm-ocr-cands pm-ocr-cands--raw">${rawCandsHtml}</div>` : ''}
        ` : '<div class="pm-ocr-no-cand">No text detected. Try a different OCR area or region.</div>'}

        <div class="pm-ocr-sel-row">
          <label class="pm-ocr-sel-lbl">Use OCR Text:</label>
          <div class="pm-ocr-sel-line">
            <input class="pm-ocr-sel-input" data-role="ocr-use-text" type="text" value="${esc(initialText)}" placeholder="Edit or type shot name…" spellcheck="false" autocomplete="off">
            ${isVfxMatch && conf > 0 ? `<span class="pm-ocr-conf-badge ${confCls}">${confLabel} ${Math.round(conf * 100)}%</span>` : ''}
          </div>
        </div>

        <div class="pm-ocr-cleanup-row">
          <span class="pm-ocr-cleanup-lbl">Cleanup:</span>
          <label class="pm-ocr-cleanup-opt"><input type="checkbox" class="pm-ocr-chk pm-ocr-chk-spaces"${settings.replaceSpaces?' checked':''}> Spaces → _</label>
          <label class="pm-ocr-cleanup-opt"><input type="checkbox" class="pm-ocr-chk pm-ocr-chk-illegal"${settings.normalizeIllegal?' checked':''}> Remove illegal chars</label>
          <label class="pm-ocr-cleanup-opt"><input type="checkbox" class="pm-ocr-chk pm-ocr-chk-upper"${settings.uppercase?' checked':''}> Uppercase</label>
          <label class="pm-ocr-cleanup-opt"><input type="checkbox" class="pm-ocr-chk pm-ocr-chk-keepspaces"${settings.keepSpaces?' checked':''}> Keep spaces</label>
        </div>

        <div class="pm-ocr-current-row">Shot Name: <span class="pm-ocr-cur-val">${esc(mk.shotName || '(empty)')}</span>${mk.template && Object.keys(mk.template).length ? `<span class="pm-ocr-tmpl-hint"> · Template: ${esc(Object.entries(mk.template).filter(([,v])=>v).map(([k,v])=>`${k.toUpperCase()}=${v}`).join(' '))}</span>` : ''}</div>

        <div class="pm-ocr-nonvfx-warn" style="display:none">
          ⚠ This does not look like a VFX shot name. Apply anyway?
        </div>

        <div class="pm-ocr-region-row">
          <label class="pm-ocr-region-lbl">Region:</label>
          <select class="pm-ocr-region-sel">${regionOpts}</select>
          <button class="pm-ocr-retry-btn" type="button">Retry</button>
        </div>

        <div class="pm-ocr-ai-row">
          <label class="pm-ocr-ai-lbl" title="Anthropic Claude Vision API — much more accurate than Tesseract for burn-in text">AI OCR:</label>
          ${settings.claudeApiKey
            ? `<span class="pm-ocr-ai-badge pm-ocr-ai-badge--on">Claude Vision${result.aiSource === 'claude-vision' ? ' ✓ Used' : ' (key set)'}</span>
               <button class="pm-ocr-ai-clear-key" type="button" title="Remove Claude API key">Remove key</button>`
            : `<input class="pm-ocr-ai-key-input" type="password" placeholder="Paste Anthropic API key to enable AI OCR…" autocomplete="off" spellcheck="false">
               <button class="pm-ocr-ai-save-key" type="button">Save key</button>`
          }
        </div>

        ${dictIsLow ? `<div class="pm-ocr-warn pm-ocr-warn-dict-low" data-role="dict-low-warn">⚠ No matching filename found in project. Edit the text above to enable Apply.</div>` : ''}

        <div class="pm-ocr-actions">
          <button class="pm-ocr-apply-cur" type="button"${dictIsLow && !initialText ? ' disabled' : ''}>Apply to Current Template</button>
          <button class="pm-ocr-apply-sel" type="button"${dictIsLow && !initialText ? ' disabled' : ''}>Apply to Selected Templates (${_pmSelectedMarkerIds.size || 1})</button>
          <button class="pm-ocr-cancel" type="button">Cancel</button>
        </div>
      </div>
    </div>`;
  const _ocrFsEl = document.fullscreenElement;
  if (_ocrFsEl) modal.classList.add('pm-ocr-modal--fs');
  (_ocrFsEl || document.body).appendChild(modal);

  const selInput    = modal.querySelector('.pm-ocr-sel-input');
  const nonVfxWarn  = modal.querySelector('.pm-ocr-nonvfx-warn');
  const applyBtns   = [modal.querySelector('.pm-ocr-apply-cur'), modal.querySelector('.pm-ocr-apply-sel')];
  const modeSel     = modal.querySelector('.pm-ocr-mode-sel');
  const dictLowWarn = modal.querySelector('[data-role="dict-low-warn"]');

  // Dict "Use match" button
  modal.querySelector('.pm-ocr-dict-use-btn')?.addEventListener('click', function() {
    selInput.value = this.dataset.value;
    _updateNonVfxWarn();
  });

  // LOW confidence: enable Apply once user has typed something
  function _updateLowApplyState() {
    if (!dictIsLow) return;
    const hasText = selInput.value.trim().length > 0;
    applyBtns.forEach(b => { if (b) b.disabled = !hasText; });
  }

  // Live: check if current input text looks like VFX pattern
  function _updateNonVfxWarn() {
    const val = selInput.value.trim();
    if (!val) { nonVfxWarn.style.display = 'none'; return; }
    const looksVfx = detectVfxShotName(val, {}).bestCandidate !== null;
    const isAnyMode = modeSel.value === 'anyText';
    const show = !looksVfx && !isAnyMode && val.length >= 2;
    nonVfxWarn.style.display = show ? '' : 'none';
    applyBtns.forEach(b => { if (b) b.textContent = (b.classList.contains('pm-ocr-apply-cur')
      ? `Apply to Current Template${show ? ' Anyway' : ''}`
      : `Apply to Selected Templates (${_pmSelectedMarkerIds.size || 1})${show ? ' Anyway' : ''}`); });
  }
  selInput.addEventListener('input', () => { _updateNonVfxWarn(); _updateLowApplyState(); });
  _updateNonVfxWarn();
  _updateLowApplyState();

  // Candidate buttons set input value
  modal.querySelectorAll('.pm-ocr-cand-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      selInput.value = btn.dataset.value;
      modal.querySelectorAll('.pm-ocr-cand-btn').forEach(b => b.classList.toggle('is-best', b === btn));
      _updateNonVfxWarn();
    });
  });

  // Cleanup checkboxes — live-reformat the current input value
  const chkSpaces  = modal.querySelector('.pm-ocr-chk-spaces');
  const chkIllegal = modal.querySelector('.pm-ocr-chk-illegal');
  const chkUpper   = modal.querySelector('.pm-ocr-chk-upper');
  const chkKeep    = modal.querySelector('.pm-ocr-chk-keepspaces');
  function _applyCleanup() {
    // Keep-spaces and replace-spaces are mutually exclusive
    if (this === chkKeep && chkKeep.checked)   chkSpaces.checked  = false;
    if (this === chkSpaces && chkSpaces.checked) chkKeep.checked   = false;
    const cs = { replaceSpaces: chkSpaces.checked, normalizeIllegal: chkIllegal.checked,
                 uppercase: chkUpper.checked, keepSpaces: chkKeep.checked };
    // Save to settings
    const s = _pmGetOcrSettings();
    Object.assign(s, cs); _pmSaveOcrSettings(s);
    // Re-clean the raw source (best candidate raw value) if available
    const src = best?.value || firstRawLine || selInput.value;
    selInput.value = _pmCleanOcrText(src, cs) || selInput.value;
    _updateNonVfxWarn();
  }
  [chkSpaces, chkIllegal, chkUpper, chkKeep].forEach(c => c?.addEventListener('change', _applyCleanup));

  // Detection Mode change — persist and re-run OCR
  modeSel?.addEventListener('change', async () => {
    const s = _pmGetOcrSettings(); s.detectionMode = modeSel.value; _pmSaveOcrSettings(s);
    modal.remove();
    await _pmRunOcrOnMarker(mk.id, pmInspector?.querySelector(`.pm-layer-ocr-btn[data-mkid="${mk.id}"]`));
  });

  const dismiss = e => { if (!modal.contains(e.target)) { modal.remove(); document.removeEventListener('pointerdown', dismiss, true); } };
  modal.querySelector('.pm-ocr-modal-close')?.addEventListener('click', () => modal.remove());
  modal.querySelector('.pm-ocr-cancel')?.addEventListener('click', () => modal.remove());
  setTimeout(() => document.addEventListener('pointerdown', dismiss, true), 0);

  modal.querySelector('.pm-ocr-retry-btn')?.addEventListener('click', async () => {
    const newRegion = modal.querySelector('.pm-ocr-region-sel')?.value;
    const s = _pmGetOcrSettings(); s.defaultRegion = newRegion; _pmSaveOcrSettings(s);
    modal.remove();
    await _pmRunOcrOnMarker(mk.id, pmInspector?.querySelector(`.pm-layer-ocr-btn[data-mkid="${mk.id}"]`));
  });

  // AI OCR key save / clear — re-run OCR after save so the user immediately
  // sees the Claude Vision result in the updated modal.
  modal.querySelector('.pm-ocr-ai-save-key')?.addEventListener('click', async () => {
    const keyInput = modal.querySelector('.pm-ocr-ai-key-input');
    const key = keyInput?.value?.trim() || '';
    if (!key) { _pmToast('Enter an API key first', 'warn'); return; }
    const s = _pmGetOcrSettings(); s.claudeApiKey = key; _pmSaveOcrSettings(s);
    modal.remove();
    await _pmRunOcrOnMarker(mk.id, pmInspector?.querySelector(`.pm-layer-ocr-btn[data-mkid="${mk.id}"]`));
  });
  modal.querySelector('.pm-ocr-ai-clear-key')?.addEventListener('click', async () => {
    const s = _pmGetOcrSettings(); s.claudeApiKey = ''; _pmSaveOcrSettings(s);
    modal.remove();
    await _pmRunOcrOnMarker(mk.id, pmInspector?.querySelector(`.pm-layer-ocr-btn[data-mkid="${mk.id}"]`));
  });

  const doApply = (ids) => {
    const name = modal.querySelector('[data-role="ocr-use-text"]')?.value?.trim() || '';
    if (!name) { _pmToast('No OCR text to apply', 'warn'); return; }
    _pmOcrSaveDictEntry(result.rawText, name);
    const target = _pmResolveActivePullTarget(ids);
    const applyIds = (Array.isArray(ids) && ids.length)
      ? ids
      : (target.markerIds.length ? target.markerIds : ids);
    _pmApplyOcrToTemplate(applyIds, name, result.rawText, {
      confidence: conf, region: result.regionKey, detectionMode: modeSel.value,
    });
    modal.remove();
  };
  modal.querySelector('.pm-ocr-apply-cur')?.addEventListener('click', () => {
    // Prefer live _pmSelectedMarkerId so we always apply to the currently expanded marker,
    // not the one that was open when the modal launched.
    const curId = _pmSelectedMarkerId || mk.id;
    doApply([curId]);
  });
  modal.querySelector('.pm-ocr-apply-sel')?.addEventListener('click', () => {
    const ids = _pmSelectedMarkerIds.size > 0 ? [..._pmSelectedMarkerIds] : (_pmSelectedMarkerId ? [_pmSelectedMarkerId] : [mk.id]);
    doApply(ids);
  });
}

// Canonical OCR apply — mirrors the exact same write path as manual shot-name editing:
//   inspector pm-layer-shot input  →  mk.shotName + ev._pmShot + DOM sync
//   pull-list pm-shot-input        →  _pmSaveShotInput (ev._pmShot + _pmSaveMeta + mk.shotName)
// Both paths must be exercised here so every UI surface stays consistent.
function _pmApplyOcrTextToMarkers(mkIds, name, ocrMeta) {
  const text = String(name || '').trim();
  if (!text) { _pmToast('No name to apply', 'warn'); return; }
  _pmSlySnapshot(`OCR: ${text.slice(0, 24)}`);

  // Resolve event indices from marker IDs via the link map (stable ID only — no DOM events, no double-apply).
  const resolvedMkIds = [];
  const eventIndices = [];
  for (const mkId of (mkIds || [])) {
    const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
    if (!mk) continue;
    resolvedMkIds.push(mk.id);
    const ei = _pmLinkMap.get(mk.id) ?? _pmLinkMap.get(Number(mk.id)) ?? mk._eventIdx ?? -1;
    if (ei >= 0 && !eventIndices.includes(ei)) eventIndices.push(ei);
  }
  // Fallback: use the currently active event if no link-map entry was found.
  if (!eventIndices.length && _pmActiveEventIdx >= 0) eventIndices.push(_pmActiveEventIdx);

  console.log('[OCR] applying', { text, mkIds, resolvedMkIds, eventIndices });

  const commit = _pmCommitShotNameChange({
    name: text,
    eventIndices,
    markerIds: resolvedMkIds.length ? resolvedMkIds : (mkIds || []),
    source: 'ocr',
    ocrMeta,
    expandEventMarkers: false,
    markerNameMode: 'shot',
    notifyLocked: true,
  });

  if (!commit?.ok) return;

  console.log('[SHOT_NAME] committed', { applied: commit.applied, renderEi: commit.renderEi, touchedEi: commit.touchedEi });

  window.dispatchEvent(new CustomEvent('pfx:marker-updated', {
    detail: { markerIds: commit.applied || [], source: 'ocr' },
  }));

  const count = (commit.applied || []).length;
  _pmToast(`OCR applied "${text}" to ${count || mkIds?.length || 1} marker${(count || 1) !== 1 ? 's' : ''}`, 'info', 2500);
}

// Alias so any remaining call sites that still use the old name continue to work.
const _pmApplyOcrName = _pmApplyOcrTextToMarkers;

// ── OCR → Template (staging area, not shot name) ───────────────────────────

function _pmApplyOcrToTemplate(mkIds, ocrText, rawText, meta) {
  const text = String(ocrText || '').trim();
  if (!text) { _pmToast('No OCR text to apply', 'warn'); return; }
  const parsed = _pmParseOcrTextToFields(text);
  let appliedCount = 0;
  for (const mkId of (mkIds || [])) {
    const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
    if (!mk) continue;
    mk.ocr = {
      rawText: rawText || text,
      cleanText: text,
      verifiedText: mk.ocr?.verifiedText || null,
      confidence: meta?.confidence || 0,
      status: 'review',
      updatedAt: Date.now(),
    };
    if (!mk.template) mk.template = {};
    mk.template.ocrText = text;
    // Fill empty template fields from parsed values only
    for (const [key, val] of Object.entries(parsed)) {
      if (val && !mk.template[key]) mk.template[key] = val;
    }
    appliedCount++;
  }
  if (appliedCount) {
    // Auto-name runs first so the commit + UI update happen before the save flush
    for (const mkId of (mkIds || [])) {
      _pmAutoNameFromTemplate(mkId, { silent: true });
    }
    _pmSaveClipMarkers();
    try { window.MPS_markProjectDirty?.(); } catch {}
    for (const mkId of (mkIds || [])) {
      const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
      if (mk) window.__ntRegisterMarker?.(mkId, mk);
      try { window.__ntRefreshMarkerBar?.(mkId); } catch {}
    }
    _pmToast(`OCR applied to template for ${appliedCount} marker${appliedCount !== 1 ? 's' : ''}`, 'info', 2500);
  }
}

// Pure function — builds shot name from template fields, no side effects.
function buildShotNameFromTemplate(template) {
  const t = template || {};
  const keyVals = {
    show:   t.show,
    ep:     t.ep   ?? t.episode,
    seq:    t.seq  ?? t.sequence,
    scene:  t.scene,
    shot:   t.shot,
    ocr:    t.ocr  || t.ocrText,  // 'ocr' from displayed values, 'ocrText' from template storage
    plate:  t.plate,
    vendor: t.vendor,
    ver:    t.ver  ?? t.version,
  };
  // Follow chip order from mibar settings (same key as naming_template.js)
  let order = ['show','ep','seq','scene','shot','ocr','plate','vendor','ver'];
  try {
    const s = JSON.parse(localStorage.getItem('pfx_mibar_settings_v1') || '{}');
    if (Array.isArray(s.order) && s.order.length) order = s.order;
  } catch {}
  return order
    .map(k => keyVals[k])
    .filter(v => v && String(v).trim())
    .map(v => String(v).trim().replace(/\s+/g, '_'))
    .join('_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '');
}

// Per-marker debounce for save flushes (UI updates are immediate via _pmCommitShotNameChange).
const _pmAutoNameTimers = new Map();

// Re-entry guards — break the naming-template ↔ inspector-render feedback loop.
// The loop: _pmRenderInspector → openNamingTemplateStatic → renderBar / _ntApplyShotNameToMarker
//           → __pmAutoNameFromTemplate → _pmCommitShotNameChange → _pmRenderInspector (repeat).
let __pmRenderingInspector = false;
let __pmApplyingTemplate   = false;

function _pmAutoNameFromTemplate(mkId, { silent = true } = {}) {
  // Guard: do not recurse while a render is in progress or while we're already
  // inside a template apply — this is the primary break for the
  // _pmRenderInspector ↔ openNamingTemplateStatic ↔ _pmCommitShotNameChange loop.
  if (__pmRenderingInspector || __pmApplyingTemplate) return;

  const mk = _pmClipMarkers.find(m => String(m.id) === String(mkId));
  if (!mk) return;
  if (mk._pmAutoName === false) return;
  // Build name only from ACTIVE chips. For each active key:
  // use marker.template value if set, otherwise fall back to displayed (localStorage) value.
  const displayed = window.__ntGetMarkerDisplayValues?.(String(mkId)) || {};
  const tmpl = mk.template || {};
  const merged = {};
  for (const k of Object.keys(displayed)) {
    merged[k] = (k === 'ocr' ? (tmpl.ocrText || tmpl.ocr || displayed[k]) : (tmpl[k] || displayed[k]));
  }
  const name = buildShotNameFromTemplate(merged);
  if (!name || mk.shotName === name) return;
  const ei = _pmLinkMap.get(mk.id) ?? _pmLinkMap.get(Number(mk.id)) ?? mk._eventIdx ?? -1;
  try {
    __pmApplyingTemplate = true;
    _pmCommitShotNameChange({
      name,
      eventIndices: ei >= 0 ? [ei] : [],
      markerIds: [mk.id],
      source: 'template',
      expandEventMarkers: false,
      markerNameMode: 'plate',
      notifyLocked: false,
    });
  } finally {
    __pmApplyingTemplate = false;
  }
  // Debounced persist (commit already updates in-memory state immediately)
  clearTimeout(_pmAutoNameTimers.get(String(mkId)));
  _pmAutoNameTimers.set(String(mkId), setTimeout(() => {
    _pmAutoNameTimers.delete(String(mkId));
    _pmSaveClipMarkers();
    try { window.MPS_markProjectDirty?.(); } catch {}
  }, 350));
  if (!silent) _pmToast(`Shot name: ${name}`, 'info', 1500);
}

// Keep old name as an alias for any remaining internal call sites.
const _pmGenerateShotNameFromTemplate = (mkId) => _pmAutoNameFromTemplate(mkId, { silent: false });

// ── Batch OCR ──────────────────────────────────────────────────────────────

async function _pmBatchOcr(evIdx) {
  const targets = evIdx >= 0
    ? _pmClipMarkers.filter(mk => (_pmLinkMap.get(mk.id) ?? mk._eventIdx ?? -1) === evIdx)
    : _pmClipMarkers;
  if (!targets.length) { _pmToast('No markers to OCR', 'info'); return; }
  if (!pmVideo || pmVideo.readyState < 2 || !pmVideo.videoWidth) {
    _pmToast('No video loaded for OCR', 'error'); return;
  }
  _pmOcrBatchAbort = false;
  const settings  = _pmGetOcrSettings();
  const fps       = _pmFps || 24;
  const _batchRoiSourceLabel = s => s === 'marker' ? 'Marker' : s === 'clip' ? 'Clip' : s === 'manual' ? 'Manual' : 'Preset';
  const rows = targets.map(mk => {
    const { roi, source } = _pmGetEffectiveRoi(mk.id, evIdx);
    return { mk, roi, regionSource: source, status: 'pending', detected: null, confidence: 0, rawText: '', apply: false, errMsg: '' };
  });

  // Build modal
  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  document.querySelector('.pm-ocr-batch-modal')?.remove();
  const modal = document.createElement('div');
  modal.className = 'pm-ocr-batch-modal';
  modal.innerHTML = `
    <div class="pm-ocr-batch-inner">
      <div class="pm-ocr-batch-hdr">
        <span>Batch OCR Shot Names</span>
        <span class="pm-ocr-batch-prog">0 / ${rows.length}</span>
        <button class="pm-ocr-batch-abort" type="button">Cancel</button>
      </div>
      <div class="pm-ocr-batch-table-wrap">
        <table class="pm-ocr-batch-table">
          <thead><tr><th>Marker</th><th>Current Name</th><th>OCR Detected</th><th>Conf</th><th>Region</th><th>Apply</th></tr></thead>
          <tbody>
            ${rows.map((r, i) => `
              <tr data-bidx="${i}">
                <td class="pm-obt-id">${esc(r.mk.id?.slice(-4) || String(i + 1))}</td>
                <td class="pm-obt-cur">${esc(r.mk.shotName || '—')}</td>
                <td class="pm-obt-det">…</td>
                <td class="pm-obt-conf">—</td>
                <td class="pm-obt-reg">${esc(_batchRoiSourceLabel(r.regionSource))}</td>
                <td class="pm-obt-chk"><input type="checkbox" disabled></td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
      <div class="pm-ocr-batch-footer" style="display:none">
        <button class="pm-ocr-batch-apply-all" type="button">Apply Checked</button>
        <button class="pm-ocr-batch-close" type="button">Close</button>
      </div>
    </div>`;
  document.body.appendChild(modal);
  modal.querySelector('.pm-ocr-batch-abort')?.addEventListener('click', () => { _pmOcrBatchAbort = true; });

  const progEl = modal.querySelector('.pm-ocr-batch-prog');
  const updateRow = (i) => {
    const row = rows[i];
    const tr  = modal.querySelector(`tr[data-bidx="${i}"]`);
    if (!tr) return;
    const pct   = row.confidence ? Math.round(row.confidence * 100) : 0;
    const ccls  = pct >= 85 ? 'pm-ocr-conf-high' : pct >= 65 ? 'pm-ocr-conf-med' : 'pm-ocr-conf-low';
    tr.querySelector('.pm-obt-det').textContent = row.detected || (row.status === 'error' ? `⚠ ${row.errMsg}` : (row.status === 'cancelled' ? 'cancelled' : '—'));
    tr.querySelector('.pm-obt-conf').innerHTML  = row.detected ? `<span class="${ccls}">${pct}%</span>` : '—';
    const chk = tr.querySelector('input[type="checkbox"]');
    if (chk) { chk.disabled = !row.detected; chk.checked = !!row.apply; chk.addEventListener('change', () => { row.apply = chk.checked; }); }
    if (progEl) {
      const done = rows.filter(r => r.status !== 'pending').length;
      progEl.textContent = `${done} / ${rows.length}`;
    }
  };

  for (let i = 0; i < rows.length; i++) {
    if (_pmOcrBatchAbort) { rows[i].status = 'cancelled'; updateRow(i); continue; }
    const row = rows[i];
    try {
      if (row.mk.recIn) {
        const targetT = Math.max(0, (tcToFrames(row.mk.recIn, fps) - _pmVidZero()) / fps);
        if (Math.abs((pmVideo.currentTime || 0) - targetT) > 0.5 / fps) {
          await new Promise(resolve => {
            const t = setTimeout(resolve, 1200);
            pmVideo.addEventListener('seeked', () => { clearTimeout(t); resolve(); }, { once: true });
            try { pmVideo.currentTime = targetT; } catch { resolve(); }
          });
        }
        await new Promise(r => requestAnimationFrame(r));
      }
      const vc = _pmCaptureCurrentVideoCanvas();
      if (!vc) throw new Error('frame capture failed');
      const cropData = _pmOcrCropAndScale(vc, row.roi);
      if (!cropData) throw new Error('crop failed');
      const processed = _pmOcrPreprocess(cropData);
      const _ocrWl = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.()/:[] ';
      const rawText   = await _pmOcrRecognizeRobust(processed, cropData, _ocrWl);
      const det       = _pmOcrProcess(rawText, settings);
      const best      = det.bestCandidate;
      row.detected    = best?.value  || null;
      row.confidence  = best?.confidence || 0;
      row.rawText     = rawText;
      row.isVfxMatch  = det.isVfxMatch;
      row.apply       = row.confidence >= 0.85 && det.isVfxMatch;
      row.status      = 'done';
    } catch (err) {
      row.status = 'error'; row.errMsg = String(err?.message || err);
    }
    updateRow(i);
    await new Promise(r => setTimeout(r, 30));
  }

  const footer = modal.querySelector('.pm-ocr-batch-footer');
  if (footer) footer.style.display = '';
  const abortBtn = modal.querySelector('.pm-ocr-batch-abort');
  if (abortBtn) { abortBtn.textContent = 'Close'; abortBtn.onclick = () => modal.remove(); }
  modal.querySelector('.pm-ocr-batch-apply-all')?.addEventListener('click', () => {
    for (const row of rows) {
      if (!row.apply || !row.detected) continue;
      _pmApplyOcrTextToMarkers([row.mk.id], row.detected, { rawText: row.rawText, confidence: row.confidence,
        region: row.regionSource, detectionMode: settings.detectionMode, isVfxMatch: row.isVfxMatch });
    }
    modal.remove();
  });
  modal.querySelector('.pm-ocr-batch-close')?.addEventListener('click', () => modal.remove());
}

// ══════════════════════════════════════════════════════════════════════════
function _wireInspectorEvents() {
  if (!pmInspector) return;
  const wrap = pmInspector.querySelector('.pm-insp-layers');
  if (!wrap) return;
  const evIdx = parseInt(wrap.dataset.evidx, 10);
  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  // Layer header click → expand/collapse (Shift+click = multi-select)
  wrap.querySelectorAll('.pm-layer-hdr').forEach(hdr => {
    hdr.addEventListener('click', e => {
      if (e.target.closest('input, button, textarea, select')) return;
      const row  = hdr.closest('.pm-layer-row');
      const mkId = row?.dataset.mkid;
      if (!mkId) return;
      if (e.shiftKey) {
        // Toggle multi-select; clear single-expand when entering batch mode
        if (_pmSelectedMarkerIds.has(mkId)) _pmSelectedMarkerIds.delete(mkId);
        else _pmSelectedMarkerIds.add(mkId);
        if (_pmSelectedMarkerIds.size > 0) _pmSelectedMarkerId = null;
        _pmRenderInspector(evIdx);
      } else {
        // Normal click: clear multi-select, then route through the real marker
        // selection path so inspector, viewer, HUD, and timeline all land on the
        // same marker frame instead of only expanding the accordion row.
        _pmSelectedMarkerIds.clear();
        if (_pmSelectedMarkerId === mkId) {
          _pmSelectedMarkerId = null;
          _pmRenderInspector(evIdx);
        } else {
          _pmSelectMarker(mkId);
        }
        return;
      }
    });
  });

  // Shot name input — stop click from toggling expand
  wrap.querySelectorAll('.pm-layer-shot').forEach(inp => {
    const _commitShotInput = () => {
      const mkId = inp.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => String(m.id) === String(mkId));
      if (_pmIsShotNameLocked(mk)) {
        _pmNotifyShotNameLocked(mk, { source: 'manual' });
        inp.value = String(mk?.shotName || '');
        return;
      }
      const ei   = mk ? (_pmLinkMap.get(mkId) ?? _pmLinkMap.get(Number(mkId)) ?? mk._eventIdx ?? -1) : -1;
      _pmCommitShotNameChange({
        name: inp.value,
        eventIndices: ei >= 0 ? [ei] : [],
        markerIds: mkId ? [mkId] : [],
        source: 'manual',
        expandEventMarkers: false,
        markerNameMode: 'shot',
        notifyLocked: true,
      });
      inp.dataset.prevValue = String(inp.value || '');
    };
    inp.addEventListener('pointerdown', e => e.stopPropagation());
    inp.addEventListener('click', e => e.stopPropagation());
    inp.addEventListener('focus', e => {
      e.stopPropagation();
      inp.dataset.prevValue = String(inp.value || '');
      requestAnimationFrame(() => {
        try { inp.select(); } catch {}
      });
    });
    inp.addEventListener('dblclick', e => {
      e.stopPropagation();
      try { inp.select(); } catch {}
    });
    inp.addEventListener('input', () => {
      const mkId = inp.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => String(m.id) === String(mkId));
      if (!mk) return;
      if (_pmIsShotNameLocked(mk)) {
        inp.value = String(mk.shotName || '');
        return;
      }
      mk.shotName = inp.value;
      // Mirror back to the linked event so pull list stays in sync
      const ei = _pmLinkMap.get(mkId) ?? mk._eventIdx ?? -1;
      if (ei >= 0 && _pmEvents[ei]) {
        _pmEvents[ei]._pmShot = inp.value;
        _pmEvents[ei].shotName = inp.value;
        // Update only the shot input in the pull list row (lightweight, no full re-render)
        const row = pmEventBody?.querySelector(`tr[data-i="${ei}"] .pm-shot-input`);
        if (row && document.activeElement !== row) row.value = inp.value;
      }
      window.MPS_markProjectDirty?.();
    });
    inp.addEventListener('keydown', e => {
      e.stopPropagation();
      if (e.key === 'Enter') {
        e.preventDefault();
        _commitShotInput();
        inp.blur();
        return;
      }
      if (e.key === 'Escape') {
        e.preventDefault();
        const prev = inp.dataset.prevValue ?? '';
        inp.value = prev;
        const mkId = inp.dataset.mkid;
        const mk   = _pmClipMarkers.find(m => String(m.id) === String(mkId));
        const ei   = mk ? (_pmLinkMap.get(mkId) ?? _pmLinkMap.get(Number(mkId)) ?? mk._eventIdx ?? -1) : -1;
        if (ei >= 0 && _pmEvents[ei]) {
          _pmEvents[ei]._pmShot = prev;
          _pmEvents[ei].shotName = prev;
          const row = pmEventBody?.querySelector(`tr[data-i="${ei}"] .pm-shot-input`);
          if (row && document.activeElement !== row) row.value = prev;
        }
        if (mk) mk.shotName = prev;
        inp.blur();
      }
    });
    inp.addEventListener('change', () => {
      _commitShotInput();
    });
  });

  wrap.querySelectorAll('.pm-shot-lock-btn').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const mkId = btn.dataset.mkid;
      const locked = !_pmIsShotNameLocked(mkId);
      _pmSetShotNameLocked(mkId, locked);
    });
  });

  // OCR button — smart shot name from video burn-in
  wrap.querySelectorAll('.pm-layer-ocr-btn').forEach(btn => {
    btn.addEventListener('click', async e => {
      e.stopPropagation();
      const mkId = btn.dataset.mkid;
      await _pmRunOcrOnMarker(mkId, btn);
    });
  });

  // Set OCR Area button — enter interactive crop-draw mode on the video viewer
  wrap.querySelectorAll('.pm-layer-set-ocr-area-btn').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      _pmEnterOcrCropMode(btn.dataset.mkid);
    });
  });

  // Status badge click (per layer)
  wrap.querySelectorAll('.pm-layer-status').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const mkId = btn.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => m.id === mkId);
      if (!mk) return;
      // Use the same event-keyed lookup as the pull list table so status stays in sync.
      const _btnLinkedEi = _pmLinkMap.get(mkId) ?? mk._eventIdx ?? -1;
      const _btnLinkedEv = _btnLinkedEi >= 0 ? _pmEvents[_btnLinkedEi] : null;
      const key  = _btnLinkedEv ? _pmStatusKey(_btnLinkedEv) : `${mk.reel||''}|${mk.tcIn||''}`;
      const cur  = _pmStatusMap.get(key) || 'none';
      const next = _STATUSES[(_STATUSES.indexOf(cur) + 1) % _STATUSES.length];
      _pmStatusMap.set(key, next);
      _pmSaveStatus();
      window.MPS_markProjectDirty?.();
      _pmRenderEventTable();
      _pmRenderInspector(evIdx);
    });
  });

  // Delete layer
  wrap.querySelectorAll('.pm-layer-del').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const mkId = btn.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => m.id === mkId);
      if (mk) {
        _pmSlySnapshot(`Delete ${mk.shotName || mk.id}`);
        const mkSpliceIdx = _pmClipMarkers.indexOf(mk);
        if (mkSpliceIdx >= 0) _pmClipMarkers.splice(mkSpliceIdx, 1);
        window.__ntUnregisterMarker?.(mkId);
        _pmSaveClipMarkers();
      }
      if (_pmSelectedMarkerId === mkId) _pmSelectedMarkerId = null;
      _pmSelectedMarkerIds.delete(mkId);
      _pmRunAutoLink();
      _pmClearOrphanedShotNames();
      _pmRenderEventTable();
      _pmPushTimelineData();
      _pmRenderInspector(evIdx);
      if (pmCtxMarkers) pmCtxMarkers.textContent = `${_pmClipMarkers.length} marker${_pmClipMarkers.length === 1 ? '' : 's'}`;
      _pmScheduleDraw();
    });
  });

  // Color circle button → inline swatch popup
  wrap.querySelectorAll('.pm-layer-color-btn').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      document.querySelector('.pm-layer-color-popup')?.remove();
      const mkId = btn.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => m.id === mkId);
      if (!mk) return;
      const popup = document.createElement('div');
      popup.className = 'pm-layer-color-popup';
      popup.innerHTML = _PM_MARKER_COLORS.map(c =>
        `<button class="pm-layer-color-swatch${mk.color===c.name?' active':''}" data-color="${esc(c.name)}">` +
          `<span class="pm-lcp-dot" style="background:${c.hex}"></span>` +
          `<span class="pm-lcp-label">${esc(c.name)} Locator</span>` +
        `</button>`
      ).join('');
      // Position with fixed coords so it's never clipped by inspector overflow
      const btnRect = btn.getBoundingClientRect();
      popup.style.cssText = `position:fixed;top:${btnRect.bottom+4}px;left:${btnRect.left}px;`;
      document.body.appendChild(popup);
      popup.querySelectorAll('.pm-layer-color-swatch').forEach(sw => {
        sw.addEventListener('click', e2 => {
          e2.stopPropagation();
          _pmSlySnapshot(`Color: ${mk.shotName || mk.id}`);
          mk.color = sw.dataset.color;
          _pmSaveClipMarkers();
          window.MPS_markProjectDirty?.();
          _pmPushTimelineData();
          popup.remove();
          _pmRenderInspector(evIdx);
        });
      });
      setTimeout(() => {
        const dismiss = ev => {
          if (!popup.contains(ev.target) && ev.target !== btn) {
            popup.remove();
            document.removeEventListener('pointerdown', dismiss, true);
          }
        };
        document.addEventListener('pointerdown', dismiss, true);
      }, 0);
    });
  });

  // Right-click on layer row → Edit / Delete context menu
  wrap.querySelectorAll('.pm-layer-row').forEach(row => {
    row.addEventListener('contextmenu', e => {
      if (e.shiftKey) return;
      const mkId = row.dataset.mkid;
      const mk   = _pmClipMarkers.find(m => m.id === mkId);
      if (!mk) return;
      e.preventDefault();
      e.stopPropagation();
      _pmShowContextMenu(e.clientX, e.clientY, _pmMarkerContextItems(mk));
    });
  });

  // Select All button — enters batch mode for all linked layers
  wrap.querySelector('.pm-sel-all-btn')?.addEventListener('click', () => {
    const linkedIds = _pmClipMarkers
      .filter(mk => _pmLinkMap.get(mk.id) === evIdx)
      .map(mk => mk.id);
    _pmSelectedMarkerIds = new Set(linkedIds);
    _pmSelectedMarkerId  = null;
    _pmRenderInspector(evIdx);
  });

  // Batch capture button — capture all missing thumbnails for this event's markers
  wrap.querySelector('.pm-batch-capture-btn')?.addEventListener('click', async () => {
    await _pmBatchCaptureEventThumbs(evIdx);
  });

  // Add Layer button — marks at current playhead, linked to this event
  wrap.querySelector('.pm-layer-add-btn')?.addEventListener('click', () => {
    if (!_pmEvents[evIdx]) return;
    _pmAddMarker(evIdx);
    setTimeout(() => {
      pmInspector?.querySelector('.pm-layer-expanded .pm-layer-shot')?.focus();
    }, 30);
  });

  // ── Expanded layer detail events ──────────────────────────────────────────
  const expanded = wrap.querySelector('.pm-layer-row.pm-layer-expanded');
  if (!expanded) return;
  const expMkId = expanded.dataset.mkid;
  const expMk   = _pmClipMarkers.find(m => m.id === expMkId);
  if (!expMk) return;

  // ── Thumbnail: Seek & Capture button ──────────────────────────────────────
  expanded.querySelector('.pm-layer-capture-btn, .pm-layer-recapture')
    ?.addEventListener('click', e => {
      e.stopPropagation();
      const btn = e.currentTarget;
      btn.disabled = true;
      btn.textContent = '…';
      // Clear error/in-flight state so a retry is allowed
      delete expMk._thumbError;
      expMk._thumbCapturing = false;
      _pmCaptureThumbnail(expMk, true, () => {
        _pmRenderInspector(evIdx);
        _pmRenderEventTable();
      });
    });

  // ── Thumbnail: click to seek to marker recIn ──────────────────────────────
  expanded.querySelector('img.pm-layer-thumb-full')?.addEventListener('click', () => {
    if (pmVideo && expMk.recIn) {
      _pmSeekVideoAbsFrame(tcToFrames(expMk.recIn, _pmFps), { syncNow: true });
    }
  });

  // Auto-capture on marker select: seek to recIn and grab silently.
  // _thumbCapturing guard prevents duplicate requests on inspector re-renders.
  const canAutoCaptureBrowserThumb = !!(pmVideo && pmVideo.readyState >= 2 && pmVideo.videoWidth && pmVideo.videoHeight);
  if (!expMk.thumb && !expMk._thumbCapturing && !expMk._thumbError && canAutoCaptureBrowserThumb && expMk.recIn) {
    expMk._thumbCapturing = true;
    _pmRenderInspector(evIdx); // show "capturing…" immediately
    // seekFirst=false: never seek the main reference video for an automatic background
    // thumbnail capture. Seeking pmVideo here moves the video away from the user's
    // current frame, causing annotate to open at the wrong position.
    _pmCaptureThumbnail(expMk, false, () => {
      expMk._thumbCapturing = false;
      _pmRenderInspector(evIdx);
      _pmRenderEventTable();
    });
  }
  // Companion mode auto-capture: only for ProRes/MXF/non-decodable files.
  // Skip when canPlay=true — those files use the HTML5 video + canvas path.
  // In-flight guard prevents duplicate requests when the inspector re-renders.
  // _thumbError guard prevents infinite retry after a failed attempt (user must click retry).
  if (!expMk.thumb && !expMk._thumbCapturing && !expMk._thumbError && _pmNativeAssetId && !_pmNativeCanPlay && expMk.recIn) {
    expMk._thumbCapturing = true;
    // Re-render now so the user sees "capturing…" instead of 📷 while waiting.
    _pmRenderInspector(evIdx);
    _pmCaptureThumbnailNative(expMk, () => {
      expMk._thumbCapturing = false;
      _pmRenderInspector(evIdx);
    });
  } else if (!expMk.thumb && _pmNativeAssetId) {
    // Companion is set but auto-capture blocked — log why.
    console.log('[PM] auto-capture blocked:', {
      hasThumb: !!expMk.thumb,
      capturing: expMk._thumbCapturing,
      hasError: !!expMk._thumbError,
      assetId: !!_pmNativeAssetId,
      canPlay: _pmNativeCanPlay,
      recIn: expMk.recIn,
    });
  }

  // Per-marker color swatches
  // Color picker dropdown toggle
  expanded.querySelectorAll('.pm-color-pick-btn').forEach(pickBtn => {
    pickBtn.addEventListener('click', e => {
      e.stopPropagation();
      const popup = pickBtn.nextElementSibling;
      const wasHidden = popup.classList.contains('is-hidden');
      document.querySelectorAll('.pm-color-pick-popup').forEach(p => p.classList.add('is-hidden'));
      if (wasHidden) {
        const r = pickBtn.getBoundingClientRect();
        popup.style.position = 'fixed';
        popup.style.top  = (r.bottom + 5) + 'px';
        popup.style.right = (window.innerWidth - r.right) + 'px';
        popup.style.left = 'auto';
        popup.classList.remove('is-hidden');
      }
    });
  });

  expanded.querySelectorAll('.pm-insp-color-swatch').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const colorName = btn.dataset.color;
      _pmSlySnapshot(`Color: ${expMk.shotName || expMk.id}`);
      expMk.color = colorName;
      const newHex = _pmMarkerHex(colorName);
      // Update swatch selection state
      expanded.querySelectorAll('.pm-insp-color-swatch').forEach(b =>
        b.classList.toggle('pm-insp-color-sel', b.dataset.color === colorName));
      // Update picker button appearance
      const pickBtn = expanded.querySelector('.pm-color-pick-btn');
      if (pickBtn) {
        const dot = pickBtn.querySelector('.pm-color-pick-dot');
        const lbl = pickBtn.querySelector('.pm-color-pick-name');
        if (dot) dot.style.background = newHex;
        if (lbl) lbl.textContent = colorName;
      }
      // Close popup
      expanded.querySelectorAll('.pm-color-pick-popup').forEach(p => p.classList.add('is-hidden'));
      // Update header inline colors in real time
      const hdr = expanded.querySelector('.pm-layer-hdr');
      if (hdr) hdr.style.borderLeftColor = newHex;
      const badge = expanded.querySelector('.pm-layer-badge');
      if (badge) badge.style.color = newHex;
      const shotInput = expanded.querySelector('.pm-layer-shot');
      if (shotInput) shotInput.style.color = newHex;
      // Update the linked event table row's color dot and shot name text in real time
      const evIdx = _pmLinkMap.get(expMk.id);
      if (evIdx != null) {
        const evRow = document.querySelector(`#main-prepmark tr.pm-row[data-i="${evIdx}"]`);
        if (evRow) {
          const dot = evRow.querySelector('.pm-dot');
          if (dot) dot.style.background = newHex;
          const shotTxt = evRow.querySelector('.pm-shot-input');
          if (shotTxt) shotTxt.style.color = newHex;
        }
      }
      _pmSaveClipMarkers();
      _pmScheduleDraw();
      window.MPS_markProjectDirty?.();
    });
  });

  // VFX flag toggles (Retime / Stabilize / Resize)
  expanded.querySelectorAll('.pm-vfx-flag').forEach(btn => {
    btn.addEventListener('click', () => {
      const flag = btn.dataset.flag;
      // Read effective state from linked event (covers auto-detected retime/resize)
      const evIdx = _pmLinkMap.get(expMk.id) ?? -1;
      const _lev  = evIdx >= 0 ? _pmEvents[evIdx] : null;
      if (_lev) {
        const _rtEff = _lev._pmRetime === true || (_lev._pmRetime == null && !!_lev._pmRetimeAuto);
        const _rsEff = _lev._pmResize === true || (_lev._pmResize == null && !!_lev._pmResizeAuto);
        if (flag === 'retime')    expMk.retime    = _rtEff;
        if (flag === 'stabilize') expMk.stabilize = !!_lev._pmStabilize;
        if (flag === 'resize')    expMk.resize    = _rsEff;
      }
      _pmSlySnapshot(`${flag} ${expMk[flag] ? 'off' : 'on'}: ${expMk.shotName || expMk.id}`);
      expMk[flag] = !expMk[flag];
      btn.classList.toggle('active', !!expMk[flag]);
      _pmSaveClipMarkers();      // persist — flags were silently lost on reload
      // Sync card flag back to linked event
      if (_lev) {
        if (flag === 'retime')    _lev._pmRetime    = !!expMk.retime;
        if (flag === 'stabilize') _lev._pmStabilize = !!expMk.stabilize;
        if (flag === 'resize')    _lev._pmResize    = !!expMk.resize;
        _pmSaveMeta(_lev);
      }
      _pmRenderEventTable();     // refresh VFX chips in the pull list table row
      window.MPS_markProjectDirty?.();
    });
  });

  // TC and SoW inputs
  expanded.querySelectorAll('input[data-field], textarea[data-field]').forEach(el => {
    let _fieldSnapDone = false;
    el.addEventListener('focus', () => { _fieldSnapDone = false; });
    el.addEventListener('input', () => {
      if (!_fieldSnapDone) {
        _pmSlySnapshot(`Edit ${el.dataset.field}: ${expMk.shotName || expMk.id}`);
        _fieldSnapDone = true;
      }
      const f = el.dataset.field;
      expMk[f] = el.value;
      if (f === 'tcIn' || f === 'tcOut' || f === 'recIn' || f === 'recOut') {
        const linkedIdx = _pmLinkMap.get(expMk.id) ?? expMk._eventIdx ?? -1;
        const linkedEv  = linkedIdx >= 0 ? _pmEvents[linkedIdx] : null;
        const timing    = linkedEv ? _pmMarkerTimingFromEvent(linkedEv, _pmFps || 24) : null;
        const matchesEventTiming = !!timing &&
          String(expMk.recIn  || '').trim() === String(timing.recIn  || '').trim() &&
          String(expMk.recOut || '').trim() === String(timing.recOut || '').trim() &&
          String(expMk.tcIn   || '').trim() === String(timing.tcIn   || '').trim() &&
          String(expMk.tcOut  || '').trim() === String(timing.tcOut  || '').trim();
        if (matchesEventTiming) delete expMk._timingEdited;
        else expMk._timingEdited = true;
      }
      window.MPS_markProjectDirty?.();
      _pmSaveClipMarkers();
      _pmScheduleDraw(); // refresh subtitle track immediately
    });
    if (el.tagName === 'INPUT' && (el.dataset.field === 'tcIn' || el.dataset.field === 'tcOut' || el.dataset.field === 'recIn' || el.dataset.field === 'recOut')) {
      el.addEventListener('change', () => {
        _pmRunAutoLink();
        _pmRenderEventTable();
        _pmPushTimelineData();
        _pmRenderInspector(evIdx);
      });
    }
  });

  // De-retime merge — extend Src Out to absorb the adjacent retimed segment at normal speed
  expanded.querySelector('.pm-insp-deretime-btn')?.addEventListener('click', function () {
    const newTcOut = this.dataset.newTcout;
    if (!newTcOut) return;
    _pmSlySnapshot(`De-retime: ${expMk.shotName || expMk.id}`);
    expMk.tcOut = newTcOut;
    expMk._timingEdited = true;
    const tcOutInp = expanded.querySelector('input[data-field="tcOut"]');
    if (tcOutInp) tcOutInp.value = newTcOut;
    window.MPS_markProjectDirty?.();
    _pmSaveClipMarkers();
    _pmRunAutoLink();
    _pmRenderEventTable();
    _pmPushTimelineData();
    _pmRenderInspector(evIdx);
  });

  // NAMING TEMPLATE — always-visible chip bar mounted into the wrap div
  const ntWrap = expanded.querySelector('.pm-nt-bar-wrap');
  if (ntWrap) _pmOpenNamingTemplate(expMk, evIdx, ntWrap);


  // Annotate — pre-load marker note/SoW and sync back on Done
  expanded.querySelector('.pm-insp-annotate')?.addEventListener('click', () => {
    if (pmVideo && expMk.recIn) {
      _pmSeekVideoAbsFrame(tcToFrames(expMk.recIn, _pmFps), { syncNow: true });
    }
    setTimeout(() => _pmOpenAnnotateModal('pen', expMk, evIdx), 80);
  });

  // → Markers tab
  expanded.querySelector('.pm-insp-goto')?.addEventListener('click', () => {
    try {
      document.querySelector('.tab[data-main="shotmarker"]')?.click();
      setTimeout(() => { try { window.__smSetActiveFromPopup?.(expMk.id); } catch {} }, 200);
    } catch {}
  });

  // Close color picker popup on outside click (one-time listener, self-removing)
  const _closeColorPopup = e => {
    if (!e.target.closest('.pm-color-drop-wrap')) {
      document.querySelectorAll('.pm-color-pick-popup').forEach(p => p.classList.add('is-hidden'));
    }
  };
  document.removeEventListener('click', _closeColorPopup);
  document.addEventListener('click', _closeColorPopup);
}


// ─── Prep & Mark NLE Timeline (canvas) ───────────────────────────────────────

const _NLE_RULER_H      = 18;
const _NLE_PIN_H        = 14;   // pin row height (diamond + label)
const _NLE_TRACK_H_FULL = 26;
const _NLE_TRACK_H_CMP  = 14;   // compact mode
const _NLE_TRACK_H_MIN  = 12;
const _NLE_TRACK_H_MAX  = 80;
const _NLE_MIN_H        = 72;
const _NLE_MAX_H        = 400;
const _NLE_SUB_H        = 32; // subtitle track row height (3 text rows: shot name, note, add note)
const _NLE_HEADER_W     = 36;   // track header sidebar width
const _NLE_PACK_GAP_THRESH = 24; // base threshold for intelligent pack smart-gap calc only
let   _pmTlTrackH       = _NLE_TRACK_H_FULL; // user-adjustable track height
const _nleTrackH = () => _pmTlCompact ? _NLE_TRACK_H_CMP : _pmTlTrackH;

// Coordinate helpers — all coordinates are in CSS pixels
function _tlX(seqFrame) {
  const cssW   = _pmTlCanvas ? _pmTlCanvas.width / (_pmDpr || 1) : 0;
  const CW     = cssW - _NLE_HEADER_W;
  const totalF = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  return _NLE_HEADER_W + ((seqFrame - _pmTlPanFr) / (totalF / _pmTlZoom)) * CW;
}
function _tlFrame(x) {
  const cssW   = _pmTlCanvas ? _pmTlCanvas.width / (_pmDpr || 1) : 0;
  const CW     = cssW - _NLE_HEADER_W;
  if (!CW) return 0;
  const totalF = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  return Math.round(((x - _NLE_HEADER_W) / CW) * (totalF / _pmTlZoom) + _pmTlPanFr);
}
/// Pack-aware coordinate helpers — pack applies in all modes including VFX Marker.
function _tlXv(seqF) {
  const cssW   = _pmTlCanvas ? _pmTlCanvas.width / (_pmDpr || 1) : 0;
  const CW     = cssW - _NLE_HEADER_W;
  const totalF = _pmTlPack ? Math.max(1, _pmPackedTotal) : Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  return _NLE_HEADER_W + ((seqF - _pmTlPanFr) / (totalF / _pmTlZoom)) * CW;
}
function _tlFrameV(x) {
  const cssW   = _pmTlCanvas ? _pmTlCanvas.width / (_pmDpr || 1) : 0;
  const CW     = cssW - _NLE_HEADER_W;
  if (!CW) return 0;
  const totalF = _pmTlPack ? Math.max(1, _pmPackedTotal) : Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  return Math.round(((x - _NLE_HEADER_W) / CW) * (totalF / _pmTlZoom) + _pmTlPanFr);
}
function _tlClampPan() {
  const totalF  = _pmTlPack ? Math.max(1, _pmPackedTotal) : Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  const visible = totalF / _pmTlZoom;
  _pmTlPanFr = Math.max(0, Math.min(totalF - visible, _pmTlPanFr));
}
function _pmResizeTlCanvas() {
  if (!_pmTlCanvas || !_pmTlCanvas.parentElement) return;
  const { width } = _pmTlCanvas.parentElement.getBoundingClientRect();
  if (width <= 0) {
    // Container hidden/transitioning — keep retrying up to 30 frames (~500ms)
    if (!_pmResizeRetryId) {
      let _retryCount = 0;
      const _retry = () => {
        if (!_pmTlCanvas) { _pmResizeRetryId = 0; return; }
        const w = _pmTlCanvas.parentElement?.getBoundingClientRect().width || 0;
        if (w > 0) {
          _pmResizeRetryId = 0;
          _pmResizeTlCanvas();
        } else if (++_retryCount < 30) {
          _pmResizeRetryId = requestAnimationFrame(_retry);
        } else {
          _pmResizeRetryId = 0; // give up after ~500ms
        }
      };
      _pmResizeRetryId = requestAnimationFrame(_retry);
    }
    return;
  }
  _pmResizeRetryId = 0;
  _pmDpr = Math.round(window.devicePixelRatio || 1) || 1;
  const newW  = Math.round(width);
  const physW = newW * _pmDpr;
  if (_pmTlCanvas.width !== physW) {
    _pmTlCanvas.width = physW;
    _pmTlCanvas.style.width = newW + 'px';
  }
  _pmDrawNLE(); // immediate (not scheduled) — canvas was just cleared by width assignment
}

// Public trigger: called whenever data changes (data already in module state)
function _pmPushTimelineData() {
  if (!_pmTlCanvas || !_pmTlCtx) return;
  // Estimate track count via greedy packing (same logic as _pmDrawNLE)
  const fps = _pmFps || 24;
  const trackEnds = [];
  const byStart = _pmEvents.map((ev, i) => {
    if (!ev) return null;
    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    return { i, eIn, eOut };
  }).filter(Boolean).sort((a, b) => a.eIn - b.eIn);
  // VFX modes ignore the flatten flag for canvas sizing (see _pmDrawNLE)
  const _tlflatten  = _pmQs('flatten') && !_pmQs('vfxmarker') && !_pmQs('vfxrename');
  const _tlVfxMark  = _pmQs('vfxmarker');
  // VFX Marker: all events sequential on single track — same logic as _pmDrawNLE
  const vfxSeqOfPtd = new Map();
  if (_tlVfxMark && byStart.length > 0) {
    const vfxOrder = [...byStart].sort((a, b) => a.eIn !== b.eIn ? a.eIn - b.eIn : a.i - b.i);
    let cursor = vfxOrder[0].eIn;
    for (const ev of vfxOrder) {
      const dur = Math.max(1, ev.eOut - ev.eIn);
      vfxSeqOfPtd.set(ev.i, { seqIn: cursor, seqOut: cursor + dur });
      cursor += dur;
    }
  }
  for (const { i, eIn, eOut } of byStart) {
    const packIn  = _tlVfxMark && vfxSeqOfPtd.has(i) ? vfxSeqOfPtd.get(i).seqIn  : eIn;
    const packOut = _tlVfxMark && vfxSeqOfPtd.has(i) ? vfxSeqOfPtd.get(i).seqOut : eOut;
    if (_tlflatten) {
      if (trackEnds.length === 0) trackEnds.push(0);
      trackEnds[0] = Math.max(trackEnds[0], packOut);
    } else {
      let t = 0;
      while (t < trackEnds.length && trackEnds[t] > packIn) t++;
      if (t >= trackEnds.length) trackEnds.push(0);
      trackEnds[t] = packOut;
    }
  }
  const nTracks = _tlflatten ? 1 : Math.max(1, trackEnds.length);

  // Sum per-track heights (respects individual overrides)
  let totalTrackPx = 0;
  for (let t = 0; t < nTracks; t++) {
    totalTrackPx += _pmTrackHeights.has(t) ? _pmTrackHeights.get(t) : _nleTrackH();
  }

  const newH  = Math.max(_NLE_MIN_H,
                Math.min(_NLE_MAX_H,
                  _NLE_RULER_H + _NLE_PIN_H + totalTrackPx + (_pmTlShowSub ? _NLE_SUB_H : 0) + 4));
  const physH = newH * (_pmDpr || 1);
  if (_pmTlCanvas.height !== physH) {
    _pmTlCanvas.height = physH;
    _pmTlCanvas.style.height = newH + 'px';
  }
  _pmDrawNLE(); // immediate — canvas height change clears the canvas
}

// Full canvas redraw — Pro NLE timeline
// Returns null for cuts, or { type, dur, raw } for real transitions
function _pmParseTransition(ev) {
  const raw = (ev?.transition || 'C').trim().toUpperCase();
  if (!raw || raw === 'C') return null;
  const DEFAULT_TR_DUR = 25; // fallback frames when duration not specified
  if (raw.startsWith('FI')) {
    const dur = parseInt(raw.slice(2).trim()) || DEFAULT_TR_DUR;
    return { type: 'fadein', dur, raw };
  }
  if (raw.startsWith('FO')) {
    const dur = parseInt(raw.slice(2).trim()) || DEFAULT_TR_DUR;
    return { type: 'fadeout', dur, raw };
  }
  if (raw.startsWith('D')) {
    const dur = parseInt(raw.slice(1).trim()) || DEFAULT_TR_DUR;
    return { type: 'dissolve', dur, raw };
  }
  if (raw.startsWith('W')) {
    const parts = raw.slice(1).trim().split(/\s+/);
    const dur = parseInt(parts[1] ?? parts[0]) || DEFAULT_TR_DUR;
    return { type: 'wipe', dur, raw };
  }
  if (raw.startsWith('KB') || raw.startsWith('KO')) {
    const dur = parseInt(raw.slice(2).trim()) || DEFAULT_TR_DUR;
    return { type: 'key', dur, raw };
  }
  return { type: 'unknown', dur: DEFAULT_TR_DUR, raw };
}

// Compute eventIndex → trackIndex using the same greedy algorithm as _pmDrawNLE.
// Called on-demand by click handlers when multiple events share a frame range.
function _pmBuildTrackOf() {
  const fps2 = _pmFps || 24;
  const _flOn     = _pmQs('flatten')   && !_pmQs('vfxmarker') && !_pmQs('vfxrename');
  const _vfxMk    = _pmQs('vfxmarker');
  const _linkedSet = new Set([..._pmLinkMap.values()]);
  const m = new Map();
  const sorted2 = _pmEvents.map((ev, i) => {
    if (!ev) return null;
    // Mirror the same filters _pmDrawNLE uses so track indices stay in sync
    if (_pmGetUnscriptedNoActionKind(ev)) return null;
    if (_vfxMk  && _linkedSet.size > 0 && !_linkedSet.has(i)) return null;
    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps2);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps2);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    return { i, eIn, eOut };
  }).filter(Boolean).sort((a, b) => a.eIn - b.eIn);
  const tEnds = [];
  for (const { i, eIn, eOut } of sorted2) {
    if (_flOn) {
      m.set(i, 0);
      if (tEnds.length === 0) tEnds.push(0);
      tEnds[0] = Math.max(tEnds[0], eOut);
    } else if (_vfxMk) {
      // VFX Marker: greedy packing of sequential positions
      let t = 0;
      while (t < tEnds.length && tEnds[t] > eIn) t++;
      if (t >= tEnds.length) tEnds.push(0);
      tEnds[t] = eOut;
      m.set(i, t);
    } else {
      // Normal / VFX Rename: use XML trackIndex directly (mirrors _pmDrawNLE)
      const t = _pmEvents[i]?.trackIndex ?? 0;
      while (tEnds.length <= t) tEnds.push(0);
      tEnds[t] = Math.max(tEnds[t], eOut);
      m.set(i, t);
    }
  }
  _pmTrackOf = m;  // keep cached copy in sync
  return m;
}

// ── Marker position helper (pack + non-pack) ──────────────────────────────────
// Returns the seq-relative (non-pack) or pack-relative frame for a marker,
// ready to pass to _tlXv(). Returns -1 in pack mode when the linked event has no pack entry.
function _pmMarkerSeqF(mk, fps) {
  if (_pmTlPack) return _pmMarkerPackF(mk, fps);
  const mIn = tcToFrames(mk.recIn || mk.tcIn || '00:00:00:00', fps);
  return mIn - _pmSeqBaseFrames;
}

// ── Pack-mode marker frame helper ─────────────────────────────────────────────
// Returns the pack-relative frame at which a marker should be drawn / hit-tested.
// Returns -1 when the marker should be skipped (unlinked or no pack entry covers mIn).
//
// Overlapping overlay events (titles/graphics sharing the same absolute [eIn,eOut)
// as a V1 clip) are assigned the same pIn/pOut pack slot as the primary event.
// So the direct _pmPackedMap lookup handles both V1 clips and their overlays.
function _pmMarkerPackF(mk, fps) {
  const evIdx = _pmLinkMap.get(mk.id);
  if (evIdx === undefined) return -1;
  const mIn = tcToFrames(mk.recIn || mk.tcIn || '00:00:00:00', fps);
  // Fast path: linked event has a pack entry (covers both V1 clips and overlays)
  const pm = _pmPackedMap.get(evIdx);
  if (pm) {
    const offs = Math.max(0, Math.min(mIn - pm.eIn, pm.eOut - pm.eIn - 1));
    return pm.pIn + offs;
  }
  // Fallback: event not in pack map (e.g. filtered out by VFX mode) —
  // find any pack entry whose absolute [eIn, eOut) covers mIn.
  let best = null;
  for (const [, entry] of _pmPackedMap) {
    if (mIn >= entry.eIn && mIn < entry.eOut) {
      if (!best || entry.pIn < best.pIn) best = entry;
    }
  }
  if (!best) return -1;
  const offs = Math.max(0, Math.min(mIn - best.eIn, best.eOut - best.eIn - 1));
  return best.pIn + offs;
}

function _pmDrawNLE() {
  if (!_pmTlCtx || !_pmTlCanvas) return;
  // Guard: zero-size canvas produces no visible output — skip until sized
  if (_pmTlCanvas.width < 10 || _pmTlCanvas.height < 4) return;

  // ── Offscreen double-buffer setup ─────────────────────────────────────────
  // All painting goes to _pmOfc; visible canvas gets one atomic drawImage blit
  // at the end. This eliminates partial-paint flicker entirely.
  if (!_pmOfc) {
    _pmOfc    = document.createElement('canvas');
    _pmOfcCtx = _pmOfc.getContext('2d', { alpha: false });
  }
  if (_pmOfc.width  !== _pmTlCanvas.width)  _pmOfc.width  = _pmTlCanvas.width;
  if (_pmOfc.height !== _pmTlCanvas.height) _pmOfc.height = _pmTlCanvas.height;

  try {
  const ctx    = _pmOfcCtx;
  const dpr    = _pmDpr || 1;
  // All draw coordinates are in CSS pixels — scale context so they map to physical pixels
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const W      = _pmTlCanvas.width / dpr;   // CSS pixels
  const H      = _pmTlCanvas.height / dpr;  // CSS pixels
  const fps    = _pmFps || 24;
  const totalF = Math.max(1, _pmSeqEndFrames - _pmSeqBaseFrames);
  const HW     = _NLE_HEADER_W;   // track header sidebar width
  const CW     = W - HW;          // content (timeline) width

  // ── Greedy NLE track packing (or single-track if Flatten is ON) ──────────
  // VFX modes use raw events with natural multi-track layout regardless of
  // the flatten QS flag (flatten applies to Pull Prep pipeline, not the canvas).
  const camKeys    = [...new Set(_pmEvents.map(ev => ev?.camera || ev?.reel || ''))];
  const trackOf    = new Map();
  const trackEnds  = [];
  const camOfTrack = new Map();   // track index → primary camera key
  const _flattenOn = _pmQs('flatten') && !_pmQs('vfxmarker') && !_pmQs('vfxrename');
  const subOf      = new Map();   // eventIndex → { slot, total } for micro-strip in flatten mode

  const _tlVfxRename = _pmQs('vfxrename');
  const _tlVfxMarker = _pmQs('vfxmarker');
  const _tlPullOnly  = _tlVfxRename || _tlVfxMarker;
  const _tlLinkedSet = new Set([..._pmLinkMap.values()]); // for VFX Marker mode filter

  const sorted = _pmEvents.map((ev, i) => {
    if (!ev) return null;
    if (_pmGetUnscriptedNoActionKind(ev)) return null; // graphic/title clips excluded from track layout
    // VFX Marker: only lay out clips that have a linked marker
    if (_tlVfxMarker && _tlLinkedSet.size > 0 && !_tlLinkedSet.has(i)) return null;
    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    return { i, eIn, eOut };
  }).filter(Boolean).sort((a, b) => a.eIn - b.eIn);

  // VFX Marker mode: all linked events laid out sequentially on a single track.
  // Sort by recIn TC, then by event index for same-TC ties (comp layers).
  const vfxSeqOf = new Map(); // evIdx → { seqIn, seqOut }
  if (_tlVfxMarker && sorted.length > 0) {
    const vfxOrder = [...sorted].sort((a, b) => a.eIn !== b.eIn ? a.eIn - b.eIn : a.i - b.i);
    let cursor = vfxOrder[0].eIn;
    for (const ev of vfxOrder) {
      const dur = Math.max(1, ev.eOut - ev.eIn);
      vfxSeqOf.set(ev.i, { seqIn: cursor, seqOut: cursor + dur });
      cursor += dur;
    }
  }

  for (const ev of sorted) {
    const { i } = ev;
    const packIn  = _tlVfxMarker && vfxSeqOf.has(i) ? vfxSeqOf.get(i).seqIn  : ev.eIn;
    const packOut = _tlVfxMarker && vfxSeqOf.has(i) ? vfxSeqOf.get(i).seqOut : ev.eOut;
    if (_flattenOn) {
      // Flatten ON: everything goes to track 0 (V1)
      trackOf.set(i, 0);
      if (trackEnds.length === 0) { trackEnds.push(0); camOfTrack.set(0, _pmEvents[i]?.camera || _pmEvents[i]?.reel || ''); }
      trackEnds[0] = Math.max(trackEnds[0], packOut);
    } else if (_tlVfxMarker) {
      // VFX Marker mode: greedy-pack the sequential positions so comp-layers on different XML
      // tracks that share the same recIn don't collide in the sequential display.
      let t = 0;
      while (t < trackEnds.length && trackEnds[t] > packIn) t++;
      if (t >= trackEnds.length) {
        trackEnds.push(0);
        camOfTrack.set(t, _pmEvents[i]?.camera || _pmEvents[i]?.reel || '');
      }
      trackEnds[t] = packOut;
      trackOf.set(i, t);
    } else {
      // Normal / VFX Rename: honour ev.trackIndex (XML track V1=0, V2=1 …)
      // so the visual row layout mirrors the original NLE structure.
      const t = _pmEvents[i]?.trackIndex ?? 0;
      while (trackEnds.length <= t) {
        const slot = trackEnds.length;
        trackEnds.push(0);
        camOfTrack.set(slot, '');
      }
      if (!camOfTrack.get(t)) camOfTrack.set(t, _pmEvents[i]?.camera || _pmEvents[i]?.reel || '');
      trackEnds[t] = Math.max(trackEnds[t], packOut);
      trackOf.set(i, t);
    }
  }
  const nTracks = _flattenOn ? 1 : Math.max(1, trackEnds.length);

  // ── Flatten micro-strip assignment ────────────────────────────────────────
  // For each point in time, find all events that overlap → sort by clipName → assign slot
  if (_flattenOn && sorted.length > 0) {
    // Build overlap groups: for each event, find all others it overlaps with
    const evData = sorted; // already has { i, eIn, eOut }
    for (const cur of evData) {
      const overlapping = evData
        .filter(o => o.eIn < cur.eOut && o.eOut > cur.eIn)
        .sort((a, b) => {
          const na = _pmEvents[a.i]?.clipName || _pmEvents[a.i]?.reel || '';
          const nb = _pmEvents[b.i]?.clipName || _pmEvents[b.i]?.reel || '';
          return na.localeCompare(nb);
        });
      const total = overlapping.length;
      const slot  = overlapping.findIndex(o => o.i === cur.i);
      subOf.set(cur.i, { slot, total });
    }
  }

  // ── Pack mode: pre-compute contiguous (no-gap) event positions ─────────────
  // Intelligent pack: sort by reel+srcTC, smart gap threshold, group separators.
  // Normal pack: sequence order, gaps ≤ threshold preserved, larger collapsed.
  _pmPackedMap.clear();
  _pmPackedTotal   = 0;
  _pmPackDensityPct = 0;
  if (_pmTlPack && sorted.length > 0) {
    // ── Smart gap threshold ───────────────────────────────────────────────────
    let effectiveGapThresh = _NLE_PACK_GAP_THRESH;
    if (_pmPackIntelligent && sorted.length > 1) {
      const gaps = [];
      const seqOrd = [...sorted].sort((a, b) => a.eIn - b.eIn);
      let prevOut = seqOrd[0].eOut;
      for (let j = 1; j < seqOrd.length; j++) {
        const g = seqOrd[j].eIn - prevOut;
        if (g > 0) gaps.push(g);
        prevOut = Math.max(prevOut, seqOrd[j].eOut);
      }
      if (gaps.length > 0) {
        gaps.sort((a, b) => a - b);
        const p25 = gaps[Math.floor(gaps.length * 0.25)] ?? gaps[0];
        effectiveGapThresh = Math.round(Math.max(fps / 2, Math.min(p25 * 0.5, fps * 12)));
      }
    }

    // ── Sort order ────────────────────────────────────────────────────────────
    // VFX Marker mode: use sequential positions so comp groups don't collapse to same pack slot
    const packSorted = _tlVfxMarker && vfxSeqOf.size > 0
      ? sorted.map(ev => ({
          i: ev.i,
          eIn:  vfxSeqOf.has(ev.i) ? vfxSeqOf.get(ev.i).seqIn  : ev.eIn,
          eOut: vfxSeqOf.has(ev.i) ? vfxSeqOf.get(ev.i).seqOut : ev.eOut,
        })).sort((a, b) => a.eIn - b.eIn)
      : sorted;
    const packOrder = _pmPackIntelligent
      ? [...packSorted].sort((a, b) => {
          const ra = _pmEvents[a.i]?.reel || _pmEvents[a.i]?.camera || '';
          const rb = _pmEvents[b.i]?.reel || _pmEvents[b.i]?.camera || '';
          if (ra !== rb) return ra.localeCompare(rb);
          const sA = tcToFrames(_pmEvents[a.i]?.srcIn  || _pmEvents[a.i]?.recIn  || '00:00:00:00', fps);
          const sB = tcToFrames(_pmEvents[b.i]?.srcIn  || _pmEvents[b.i]?.recIn  || '00:00:00:00', fps);
          return sA - sB;
        })
      : packSorted;

    let cursor  = 0;
    let packEnd = 0;
    let slotPIn = 0, slotPOut = 0;
    let lastReel = null;

    for (const { i, eIn, eOut } of packOrder) {
      if (_pmPackIntelligent) {
        const reel = _pmEvents[i]?.reel || _pmEvents[i]?.camera || '';
        const isNewGroup = reel !== lastReel;
        // 1-second separator between reel groups
        if (isNewGroup && lastReel !== null) { cursor += Math.round(fps); packEnd = cursor; }
        lastReel = reel;
        const dur = Math.max(1, eOut - eIn);
        slotPIn  = cursor;
        slotPOut = cursor + dur;
        _pmPackedMap.set(i, { pIn: slotPIn, pOut: slotPOut, eIn, eOut, collapsedGap: 0,
                              _iGroup: reel, _iGroupStart: isNewGroup });
        cursor  += dur;
        packEnd  = cursor;
      } else {
        if (eIn < packEnd) {
          // Overlapping event — assign same pack slot.
          if (eOut > packEnd) {
            const extra = eOut - packEnd;
            slotPOut += extra;
            cursor   += extra;
            packEnd   = eOut;
          }
          _pmPackedMap.set(i, { pIn: slotPIn, pOut: slotPOut, eIn, eOut, collapsedGap: 0 });
        } else {
          // New non-overlapping slot — collapse all gaps, pull clips flush.
          const collapsed = Math.max(0, eIn - packEnd);
          const dur = Math.max(1, eOut - eIn);
          slotPIn  = cursor;
          slotPOut = cursor + dur;
          _pmPackedMap.set(i, { pIn: slotPIn, pOut: slotPOut, eIn, eOut, collapsedGap: collapsed });
          cursor  += dur;
          packEnd  = eOut;
        }
      }
    }
    _pmPackedTotal = cursor || 1;

    // ── Density score ─────────────────────────────────────────────────────────
    const _totalClipF = [..._pmPackedMap.values()].reduce((s, pm) => s + Math.max(0, pm.eOut - pm.eIn), 0);
    _pmPackDensityPct = _pmPackedTotal > 0 ? Math.round(_totalClipF / _pmPackedTotal * 100) : 0;
    // Update density badges in the toolbar (main PACK btn + iPACK btn)
    const _densEl  = document.getElementById('pmPackDensityBadge');
    const _densEl2 = document.getElementById('pmPackDensityBadgeMain');
    if (_densEl)  _densEl.textContent  = _pmPackDensityPct + '%';
    if (_densEl2) _densEl2.textContent = _pmPackDensityPct + '%';
  }
  const _tlDrawPack = _pmTlPack;
  // Draw-local total (pack-aware) — governs ruler interval and coordinate scale
  const drawTotalF = _tlDrawPack ? Math.max(1, _pmPackedTotal) : totalF;

  const camColor = ev => {
    const key = ev?.camera || ev?.reel || '';
    const idx = camKeys.indexOf(key);
    return _CAM_COLORS[(idx < 0 ? 0 : idx) % _CAM_COLORS.length] || '#555';
  };
  // Darken a hex color for minimal solid block fill (factor 0–1)
  const darkHex = (hex, factor) => {
    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    const f = h => Math.round(h * factor).toString(16).padStart(2,'0');
    return `#${f(r)}${f(g)}${f(b)}`;
  };
  const tracksTop    = _NLE_RULER_H + _NLE_PIN_H;
  const subY         = _pmTlShowSub ? (H - _NLE_SUB_H) : -1;
  const tracksBottom = _pmTlShowSub ? (subY - 1) : (H - 1);

  // ── Per-track Y map (with vertical scroll) ──────────────────────────────
  // Builds top-down: highest track index (VN) at top, V1 at bottom.
  // Applies _pmTlScrollY so all event handlers read scroll-corrected positions.
  // Publishes to module-level _pmTlYMap for hit-testing.
  {
    // Compute totalTrackPx first so we can clamp the scroll offset before building yMap
    let totalTrackPx = 0;
    for (let t = 0; t < nTracks; t++)
      totalTrackPx += _pmTrackHeights.has(t) ? _pmTrackHeights.get(t) : _nleTrackH();
    // Use the container's visible height — the canvas (sized by _pmPushTimelineData) grows to
    // fit all tracks up to _NLE_MAX_H, but the .pm-tl-wrap container can be smaller due to the
    // page flex layout. Scrolling must be measured against what the user actually sees.
    const _visH      = Math.min(H, pmTlWrap?.clientHeight || H);
    const _viewH     = Math.max(0, _visH - tracksTop - (_pmTlShowSub ? _NLE_SUB_H : 0));
    _pmTlMaxScrollY  = Math.max(0, totalTrackPx - _viewH);
    _pmTlScrollY     = Math.max(0, Math.min(_pmTlScrollY, _pmTlMaxScrollY));
    _pmTlTotalTrackH = totalTrackPx;

    let cy = tracksTop;
    const yMap = new Map();
    for (let t = nTracks - 1; t >= 0; t--) {
      const h = _pmTrackHeights.has(t) ? _pmTrackHeights.get(t) : _nleTrackH();
      yMap.set(t, { y: cy - _pmTlScrollY, h });
      cy += h;
    }
    _pmTlYMap      = yMap;
    _pmTlNTracks   = nTracks;
    _pmTlTracksTop = tracksTop;
    _pmTrackOf     = trackOf;
  }
  const _tY = t => _pmTlYMap.get(t)?.y ?? tracksTop;
  const _tH = t => _pmTlYMap.get(t)?.h ?? _nleTrackH();

  // Rounded-rect helper (Chrome MV3 extension → roundRect is available, polyfill just in case)
  const rr = (x, y, w, h, r) => {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); }
    else {
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y,     x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x,     y + h, r);
      ctx.arcTo(x,     y + h, x,     y,     r);
      ctx.arcTo(x,     y,     x + w, y,     r);
      ctx.closePath();
    }
  };

  // ── Background ─────────────────────────────────────────────────────────────
  ctx.fillStyle = '#07070f';
  ctx.fillRect(0, 0, W, H);

  // ── Track lane stripes ─────────────────────────────────────────────────────
  for (let t = 0; t < nTracks; t++) {
    const ty = _tY(t);
    ctx.fillStyle = t % 2 === 0 ? '#090916' : '#0b0b1d';
    ctx.fillRect(HW, ty, CW, _tH(t));
  }

  // ── Track header sidebar ───────────────────────────────────────────────────
  ctx.fillStyle = '#060613';
  ctx.fillRect(0, 0, HW, H);
  // Right divider
  ctx.fillStyle = '#1c1c34';
  ctx.fillRect(HW - 1, 0, 1, H);
  // Ruler area top block
  ctx.fillStyle = '#080818';
  ctx.fillRect(0, 0, HW, tracksTop);

  // Clip count per track (for header badge) — only count clips that appear in trackOf
  // (i.e. those not filtered as graphics/titles by _pmGetUnscriptedNoActionKind)
  const _clipsPerTrack = new Map();
  for (let i = 0; i < _pmEvents.length; i++) {
    const ev = _pmEvents[i];
    if (!ev) continue;
    const tr = trackOf.get(i);
    if (tr === undefined) continue;
    _clipsPerTrack.set(tr, (_clipsPerTrack.get(tr) || 0) + 1);
  }

  // V-labels + resize grip in header
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 8.5px "SF Mono", ui-monospace, monospace';
  for (let t = 0; t < nTracks; t++) {
    const th  = _tH(t);
    const ty0 = _tY(t);
    const ty  = ty0 + th / 2;
    const camK  = camOfTrack.get(t) || '';
    const ci    = camKeys.indexOf(camK);
    const col   = _CAM_COLORS[(ci < 0 ? t : ci) % _CAM_COLORS.length] || '#555';
    // Colored dot
    ctx.beginPath();
    ctx.arc(8, ty, 3, 0, Math.PI * 2);
    ctx.fillStyle = col;
    ctx.fill();
    // Track label
    const vLabel = 'V' + (t + 1);
    ctx.fillStyle = 'rgba(180,185,220,0.65)';
    ctx.fillText(vLabel, 17, ty);
    // Clip count badge (dim, shown when track is tall enough)
    const cnt = _clipsPerTrack.get(t) || 0;
    if (cnt > 0 && th >= 20) {
      ctx.font = '7px "SF Mono", ui-monospace, monospace';
      ctx.fillStyle = 'rgba(100,105,150,0.38)';
      ctx.fillText('×' + cnt, 17, ty0 + th - 7);
      ctx.font = 'bold 8.5px "SF Mono", ui-monospace, monospace';
    }
    // Resize grip (3 horizontal dots near bottom of track, visible when tall enough)
    if (th >= 14) {
      const gx = HW / 2;
      const gy = ty0 + th - 4;
      ctx.fillStyle = 'rgba(140,145,180,0.30)';
      for (let di = -1; di <= 1; di++) {
        ctx.beginPath();
        ctx.arc(gx + di * 4, gy, 1.2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    // Highlight bottom boundary when this track is being resized or hovered
    if (_pmTlResizeTrack === t) {
      ctx.fillStyle = 'rgba(100,120,255,0.5)';
      ctx.fillRect(0, ty0 + th - 1, HW, 2);
    }
  }

  // Repaint header ruler block so scrolled V-labels don't bleed into ruler area
  ctx.fillStyle = '#080818';
  ctx.fillRect(0, 0, HW, tracksTop);
  ctx.fillStyle = '#1c1c34';
  ctx.fillRect(HW - 1, 0, 1, tracksTop);

  // ── Ruler ─────────────────────────────────────────────────────────────────
  ctx.fillStyle = '#0b0b1e';
  ctx.fillRect(HW, 0, CW, _NLE_RULER_H);
  ctx.fillStyle = '#1e1e38';
  ctx.fillRect(HW, _NLE_RULER_H - 1, CW, 1);

  const visF      = drawTotalF / Math.max(0.001, _pmTlZoom);
  const rawSecs   = (visF / 6) / fps;
  const niceC     = [1, 2, 5, 10, 15, 30, 60, 120, 300];
  let   niceSecs  = niceC[niceC.length - 1];
  for (const c of niceC) { if (c >= rawSecs) { niceSecs = c; break; } }
  const tickInt   = Math.round(niceSecs * fps);
  const subInt    = Math.max(1, Math.round(tickInt / 5));
  const firstTick = Math.floor(_pmTlPanFr / tickInt) * tickInt;
  const firstSub  = Math.floor(_pmTlPanFr / subInt)  * subInt;

  // Sub-ticks
  for (let f = firstSub; f <= _pmTlPanFr + visF + subInt; f += subInt) {
    if (f % tickInt === 0) continue;
    const x = Math.round(_tlXv(f));
    if (x < HW || x > W) continue;
    ctx.fillStyle = '#1e1e36';
    ctx.fillRect(x, _NLE_RULER_H - 4, 1, 3);
  }

  // Main ticks + grid + labels
  ctx.font = '8.5px system-ui, -apple-system, sans-serif';
  ctx.textBaseline = 'bottom';
  for (let f = firstTick; f <= _pmTlPanFr + visF + tickInt; f += tickInt) {
    const x = Math.round(_tlXv(f));
    if (x < HW - 2 || x > W + 2) continue;
    // Tick
    ctx.fillStyle = '#363660';
    ctx.fillRect(x, _NLE_RULER_H - 7, 1, 6);
    // Grid line
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + 0.5, tracksTop);
    ctx.lineTo(x + 0.5, tracksBottom);
    ctx.stroke();
    // Label
    if (x >= HW && x < W - 4) {
      ctx.fillStyle = 'rgba(190,195,225,0.5)';
      // Pack mode (non-VFX Marker): show elapsed seconds; all other modes: show TC
      const label = _tlDrawPack
        ? `${Math.round(f / fps * 10) / 10}s`
        : framesToTC(f + _pmSeqBaseFrames, fps);
      ctx.fillText(label, x + 3, _NLE_RULER_H - 2);
    }
  }

  // ── Pack mode: clip-boundary accent ticks + REC TC labels ────────────────
  if (_tlDrawPack && _pmPackedMap.size > 0) {
    const sortedPmBnd = [..._pmPackedMap.entries()].sort((a, b) => a[1].pIn - b[1].pIn);
    ctx.font = '6.5px "SF Mono", ui-monospace, monospace';
    ctx.textBaseline = 'top';
    let prevX = -999;
    for (const [idx, pm] of sortedPmBnd) {
      const x = Math.round(_tlXv(pm.pIn));
      if (x < HW - 1 || x > W + 1) continue;
      // Full-height amber accent tick at clip start
      ctx.fillStyle = 'rgba(255,195,50,0.45)';
      ctx.fillRect(x, 0, 1, _NLE_RULER_H - 1);
      // REC TC chip — only if enough horizontal room since previous label
      if (x >= HW && x < W - 45 && x - prevX > 48) {
        const ev = _pmEvents[idx];
        const tc = ev?.recIn || '';
        if (tc) {
          ctx.fillStyle = 'rgba(255,195,50,0.80)';
          ctx.fillText(tc, x + 2, 2);
          prevX = x;
        }
      }
    }
  }

  // ── Hover cursor + TC tooltip ──────────────────────────────────────────────
  if (_pmTlHoverX >= HW && !_pmTlDragging) {
    const hF = _tlFrameV(_pmTlHoverX);
    ctx.strokeStyle = 'rgba(200,205,255,0.12)';
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 4]);
    ctx.beginPath();
    ctx.moveTo(_pmTlHoverX + 0.5, tracksTop);
    ctx.lineTo(_pmTlHoverX + 0.5, tracksBottom);
    ctx.stroke();
    ctx.setLineDash([]);
    // TC chip — in pack mode convert pack-frame → real absolute TC
    let tcH;
    if (_tlDrawPack) {
      let absHF = -1;
      for (const [, pm] of _pmPackedMap) {
        if (hF >= pm.pIn && hF < pm.pOut) { absHF = pm.eIn + (hF - pm.pIn); break; }
      }
      tcH = absHF >= 0 ? framesToTC(absHF, fps) : `${Math.round(hF / fps * 10) / 10}s`;
    } else {
      tcH = framesToTC(hF + _pmSeqBaseFrames, fps);
    }
    let trLabel = '';
    for (let i = 0; i < _pmEvents.length; i++) {
      const ev = _pmEvents[i];
      if (!ev) continue;
      const tr = _pmParseTransition(ev);
      if (!tr) continue;
      const eIn = tcToFrames(ev.recIn || '00:00:00:00', fps);
      // Use the same virtual (pack-aware) coordinate space as hF for the comparison
      const trBase = _tlDrawPack ? (_pmPackedMap.get(i)?.pIn ?? -1) : (eIn - _pmSeqBaseFrames);
      if (trBase >= 0 && hF >= trBase && hF < trBase + Math.max(1, tr.dur)) {
        const labels = { dissolve: 'Dissolve', wipe: 'Wipe', fadein: 'Fade In', fadeout: 'Fade Out', key: 'Key' };
        trLabel = ' · ' + (labels[tr.type] || tr.raw || '') + (tr.dur ? ` ${tr.dur}f` : '');
        break;
      }
    }
    ctx.font = '7.5px "SF Mono", ui-monospace, monospace';
    const chipTxt = tcH + trLabel;
    const tw = ctx.measureText(chipTxt).width;
    const cx = Math.max(HW + 2, Math.min(W - tw - 10, _pmTlHoverX - tw / 2 - 4));
    ctx.fillStyle = trLabel ? 'rgba(30,10,40,0.92)' : 'rgba(14,14,30,0.88)';
    rr(cx - 2, 1, tw + 10, _NLE_RULER_H - 3, 2);
    ctx.fill();
    ctx.fillStyle = trLabel ? 'rgba(210,160,255,0.90)' : 'rgba(200,210,245,0.75)';
    ctx.textBaseline = 'bottom';
    ctx.fillText(chipTxt, cx + 3, _NLE_RULER_H - 3);
  }

  // ── Clip content lane to track area ─────────────────────────────────────
  // Prevents scrolled clip blocks and separator lines from overwriting the ruler
  // or subtitle row when tracks are scrolled toward either edge.
  ctx.save();
  ctx.beginPath();
  ctx.rect(HW, tracksTop, CW, tracksBottom - tracksTop);
  ctx.clip();

  // ── Clip blocks ────────────────────────────────────────────────────────────
  _pmClipHitMap.clear();  // rebuilt fresh every draw
  const linkedEvSet    = new Set([..._pmLinkMap.values()]);
  const layerCount     = new Map();
  const evFirstMkColor = new Map();
  const evFirstMk      = new Map();   // evIdx → first marker object (for exact TC positioning)
  for (const [mkId, evIdx] of _pmLinkMap) {
    layerCount.set(evIdx, (layerCount.get(evIdx) || 0) + 1);
    if (!evFirstMkColor.has(evIdx)) {
      const mk = _pmClipMarkers.find(m => m.id === mkId);
      if (mk) {
        evFirstMkColor.set(evIdx, _pmMarkerHex(mk.color || 'Green'));
        evFirstMk.set(evIdx, mk);
      }
    }
  }

  const _vfxRename   = _pmQs('vfxrename');
  const _vfxMarker   = _pmQs('vfxmarker');
  const _vfxPullOnly = _vfxRename || _vfxMarker;

  for (let i = 0; i < _pmEvents.length; i++) {
    const ev = _pmEvents[i];
    if (!ev) continue;

    // VFX Marker: skip events with no linked markers
    if (_vfxMarker && linkedEvSet.size > 0 && !linkedEvSet.has(i)) continue;

    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;
    const eDur = eOut - eIn;

    // VFX Marker: comp-layer sequential display positions
    const dispIn  = _vfxMarker && vfxSeqOf.has(i) ? vfxSeqOf.get(i).seqIn  : eIn;
    const dispOut = _vfxMarker && vfxSeqOf.has(i) ? vfxSeqOf.get(i).seqOut : eOut;

    let eF1, eF2;
    if (_tlDrawPack) {
      const pm = _pmPackedMap.get(i);
      if (!pm) continue;
      eF1 = pm.pIn; eF2 = pm.pOut;
    } else {
      eF1 = dispIn - _pmSeqBaseFrames; eF2 = dispOut - _pmSeqBaseFrames;
    }
    const x1  = _tlXv(eF1);
    const x2  = _tlXv(eF2);
    const px1 = Math.round(Math.max(HW, x1));
    let   px2 = Math.round(Math.min(W,  x2));
    if (px2 < HW || px1 > W) continue;
    px2 = Math.max(px1 + 2, px2); // min 2px visual width for dense clips at full zoom

    // Graphic/Title/Generator clips are hidden from the timeline
    if (_pmGetUnscriptedNoActionKind(ev)) continue;

    const track   = trackOf.get(i) ?? 0;
    const baseY   = _tY(track);
    const linked   = linkedEvSet.has(i);
    const active   = i === _pmActiveEventIdx;
    const skipped       = !!ev._pmConformSkip;
    const fullTlDis     = !!ev._pmFullTimelineDisabled;
    const parserDisabled = !!ev.disabled;  // clip muted/disabled in original timeline
    const disabled = fullTlDis;
    const col      = (skipped || parserDisabled) ? '#2a2a38' : camColor(ev);
    const clipW    = px2 - px1;
    const fullH    = _tH(track) - 3;

    const isGraphicClip = false; // reserved; graphics are skipped above

    // Micro-strip layout inside single flatten lane
    const sub     = _flattenOn ? (subOf.get(i) || { slot: 0, total: 1 }) : { slot: 0, total: 1 };
    const baseClipH = _flattenOn && sub.total > 1 ? Math.max(4, Math.floor(fullH / sub.total)) : fullH;
    const clipH   = isGraphicClip ? Math.max(4, Math.floor(baseClipH * 0.5)) : baseClipH;
    const baseClipY = _flattenOn && sub.total > 1 ? baseY + sub.slot * baseClipH : baseY;
    const ty      = isGraphicClip ? baseClipY + Math.floor((baseClipH - clipH) / 2) : baseClipY;
    const layers  = layerCount.get(i) || 0;
    // Record canvas bounds for direct hit-testing in event handlers
    _pmClipHitMap.set(i, { x1: px1, x2: px2, y1: ty + 1, y2: ty + 1 + clipH });

    // Minimal solid block fill
    ctx.globalAlpha = isGraphicClip ? 0.45 : 1;
    if (disabled) {
      // Disabled/full-timeline clip: dark grey fill, no accent stripe
      ctx.fillStyle = '#181820';
      rr(px1, ty + 1, clipW, clipH, 2);
      ctx.fill();
      // Diagonal hatch to signal "disabled"
      if (clipW >= 6) {
        ctx.save();
        ctx.beginPath(); rr(px1, ty + 1, clipW, clipH, 2); ctx.clip();
        ctx.strokeStyle = '#2a2a38';
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.7;
        for (let dx = -clipH; dx < clipW + clipH; dx += 6) {
          ctx.beginPath();
          ctx.moveTo(px1 + dx, ty + 1);
          ctx.lineTo(px1 + dx + clipH, ty + 1 + clipH);
          ctx.stroke();
        }
        ctx.restore();
        ctx.globalAlpha = 1;
      }
    } else {
      ctx.fillStyle = skipped ? '#1c1c28' : darkHex(col, linked ? 0.45 : 0.28);
      rr(px1, ty + 1, clipW, clipH, 2);
      ctx.fill();
      // Thin left-edge accent stripe (2px solid cam color)
      if (clipW >= 3 && !skipped) {
        ctx.fillStyle = col;
        ctx.fillRect(px1, ty + 1, 2, clipH);
      }
    }
    ctx.globalAlpha = 1;

    // ── Resize / Stabilize visualization (top bar, purple / teal) ────────
    if (!disabled && !skipped && !isGraphicClip && clipH >= 5 && clipW >= 6 &&
        (ev._pmResizeAuto || ev._pmResize === true || ev._pmStabilize)) {
      const _barH = Math.min(4, Math.max(2, Math.floor(clipH * 0.16)));
      ctx.save();
      ctx.beginPath(); rr(px1, ty + 1, clipW, clipH, 2); ctx.clip();
      if (ev._pmStabilize) {
        ctx.fillStyle = active ? 'rgba(40,200,155,0.60)' : 'rgba(40,200,155,0.32)';
      } else {
        ctx.fillStyle = active ? 'rgba(180,110,234,0.70)' : 'rgba(180,110,234,0.40)';
      }
      ctx.fillRect(px1, ty + 1, clipW, _barH);
      ctx.restore();
    }

    // ── Speed ramp / keyframe visualization ─────────────────────────────
    // Show for any event with non-default speed, regardless of _pmRetimeAuto flag
    const _tlSpeedPct = _pmExtractSpeedPercent(ev);
    const _tlHasSpeed = ev._pmRetimeAuto ||
      (Array.isArray(ev.speedKeys) && ev.speedKeys.length > 0) ||
      (Number.isFinite(_tlSpeedPct) && Math.abs(_tlSpeedPct - 100) > 0.1);
    if (!disabled && !skipped && !isGraphicClip && _tlHasSpeed && clipH >= 5 && clipW >= 6) {
      const sf       = _tlSpeedPct ?? 100;
      const _isDyn   = Array.isArray(ev.speedKeys) && ev.speedKeys.length > 1;
      const _isFrz   = !_isDyn && Number.isFinite(sf) && Math.abs(sf) < 0.5;
      const _isRev   = !_isDyn && !_isFrz && Number.isFinite(sf) && sf < 0;
      const _isFast  = !_isDyn && !_isFrz && !_isRev && Number.isFinite(sf) && sf > 100;
      // Bar: prominent ~30% of clip height, at least 8px
      const _barH    = Math.min(20, Math.max(8, Math.floor(clipH * 0.32)));
      const _barY    = ty + 1 + clipH - _barH;

      ctx.save();
      ctx.beginPath(); rr(px1, ty + 1, clipW, clipH, 2); ctx.clip();
      ctx.textBaseline = 'middle';

      // ── Helper: draw a small pill badge inside the bar ────────────────
      const _speedBadge = (txt, textCol, bgCol) => {
        if (clipW < 36 || _barH < 7) return;
        const bFont = `bold ${Math.min(8, _barH - 3)}px "SF Mono",ui-monospace,monospace`;
        ctx.font = bFont;
        const bw = ctx.measureText(txt).width + 7;
        const bx = Math.max(px1 + 3, Math.min(px2 - bw - 3, (px1 + px2) / 2 - bw / 2));
        const bh = Math.min(11, _barH - 2);
        const by = _barY + (_barH - bh) / 2;
        ctx.fillStyle = bgCol;
        rr(bx, by, bw, bh, 2); ctx.fill();
        ctx.fillStyle = textCol;
        ctx.fillText(txt, bx + 3.5, by + bh / 2);
      };

      if (_isDyn) {
        // ── Dynamic (variable) speed ──────────────────────────────────────
        const _keys = ev.speedKeys;
        // Background
        const bgGrd = ctx.createLinearGradient(px1, _barY, px1, _barY + _barH);
        bgGrd.addColorStop(0, 'rgba(255,160,30,0.14)');
        bgGrd.addColorStop(1, 'rgba(255,110,10,0.42)');
        ctx.fillStyle = bgGrd;
        ctx.fillRect(px1, _barY, clipW, _barH);

        if (_keys.length >= 2 && clipW >= 14) {
          // Filled speed-curve area
          ctx.beginPath();
          ctx.moveTo(px1, _barY + _barH);
          _keys.forEach((kf, ki) => {
            const pos  = ki / (_keys.length - 1);
            const spPct = Math.min(400, Math.max(0, kf.pct ?? kf.value ?? 100));
            const norm  = Math.min(1, spPct / 200);
            ctx.lineTo(px1 + pos * clipW, _barY + _barH - Math.round((_barH - 2) * norm));
          });
          ctx.lineTo(px2, _barY + _barH);
          ctx.closePath();
          const fillGrd = ctx.createLinearGradient(px1, _barY, px1, _barY + _barH);
          fillGrd.addColorStop(0, 'rgba(255,210,60,0.55)');
          fillGrd.addColorStop(1, 'rgba(255,130,20,0.18)');
          ctx.fillStyle = fillGrd;
          ctx.fill();

          // Curve line
          if (clipW >= 20) {
            ctx.beginPath();
            _keys.forEach((kf, ki) => {
              const pos  = ki / (_keys.length - 1);
              const spPct = Math.min(400, Math.max(0, kf.pct ?? kf.value ?? 100));
              const norm  = Math.min(1, spPct / 200);
              const lx = px1 + pos * clipW;
              const ly = _barY + _barH - Math.round((_barH - 2) * norm);
              ki === 0 ? ctx.moveTo(lx, ly) : ctx.lineTo(lx, ly);
            });
            ctx.strokeStyle = active ? 'rgba(255,220,80,0.95)' : 'rgba(255,200,60,0.78)';
            ctx.lineWidth = 1.5;
            ctx.stroke();
          }

          // Interior keyframe diamonds
          _keys.forEach((kf, ki) => {
            if (ki === 0 || ki === _keys.length - 1) return;
            const spPct = Math.min(400, Math.max(0, kf.pct ?? kf.value ?? 100));
            const norm  = Math.min(1, spPct / 200);
            const kfX = Math.round(px1 + (ki / (_keys.length - 1)) * clipW);
            const kfY = Math.round(_barY + _barH - (_barH - 2) * norm);
            const sz  = Math.min(3.5, _barH / 3);
            ctx.beginPath();
            ctx.moveTo(kfX, kfY - sz); ctx.lineTo(kfX + sz, kfY);
            ctx.lineTo(kfX, kfY + sz); ctx.lineTo(kfX - sz, kfY);
            ctx.closePath();
            ctx.fillStyle = active ? '#fff' : 'rgba(255,235,120,0.95)';
            ctx.fill();
          });
        }
        // Derive speed range for label
        const allPcts = _keys.map(k => k.pct ?? k.value ?? 100);
        const minP = Math.round(Math.min(...allPcts));
        const maxP = Math.round(Math.max(...allPcts));
        const varLabel = minP === maxP ? `${minP}%` : `${minP}–${maxP}%`;
        _speedBadge('VAR ' + varLabel, active ? '#ffd050' : 'rgba(255,210,80,0.9)', 'rgba(10,6,0,0.62)');

        // Keyframe accuracy tick marks — vertical lines at each KF position through full clip height
        if (clipW >= 16 && clipH >= 10) {
          ctx.strokeStyle = active ? 'rgba(255,220,80,0.55)' : 'rgba(255,200,60,0.32)';
          ctx.lineWidth = 1;
          _keys.forEach((kf, ki) => {
            if (ki === 0 || ki === _keys.length - 1) return;
            const kfX = Math.round(px1 + (ki / (_keys.length - 1)) * clipW);
            ctx.beginPath(); ctx.moveTo(kfX, ty + 1); ctx.lineTo(kfX, ty + 1 + clipH); ctx.stroke();
          });
        }

      } else if (_isFrz) {
        // ── Freeze frame ──────────────────────────────────────────────────
        ctx.fillStyle = active ? 'rgba(232,70,70,0.50)' : 'rgba(220,60,60,0.38)';
        ctx.fillRect(px1, _barY, clipW, _barH);
        // Cross-hatch texture
        ctx.strokeStyle = active ? 'rgba(240,90,90,0.45)' : 'rgba(220,80,80,0.32)';
        ctx.lineWidth = 1;
        for (let dx = -_barH; dx < clipW + _barH; dx += 5) {
          ctx.beginPath(); ctx.moveTo(px1 + dx, _barY); ctx.lineTo(px1 + dx + _barH, _barY + _barH); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(px1 + dx + _barH, _barY); ctx.lineTo(px1 + dx, _barY + _barH); ctx.stroke();
        }
        _speedBadge('FREEZE', active ? '#ff9090' : 'rgba(240,110,110,0.92)', 'rgba(16,0,0,0.65)');

      } else if (_isRev) {
        // ── Reverse motion ────────────────────────────────────────────────
        const rGrd = ctx.createLinearGradient(px1, _barY, px2, _barY);
        rGrd.addColorStop(0, active ? 'rgba(60,150,255,0.60)' : 'rgba(60,140,245,0.45)');
        rGrd.addColorStop(1, active ? 'rgba(60,100,230,0.35)' : 'rgba(60,100,220,0.25)');
        ctx.fillStyle = rGrd;
        ctx.fillRect(px1, _barY, clipW, _barH);
        // ← arrows
        if (clipW >= 24 && _barH >= 6) {
          ctx.strokeStyle = active ? 'rgba(150,210,255,0.85)' : 'rgba(120,190,255,0.55)';
          ctx.lineWidth = 1.5;
          const cy = _barY + _barH / 2;
          const ah = Math.min(_barH - 4, 6) / 2;
          for (let ax = px2 - 10; ax > px1 + 8; ax -= 16) {
            ctx.beginPath(); ctx.moveTo(ax + 5, cy - ah); ctx.lineTo(ax, cy); ctx.lineTo(ax + 5, cy + ah); ctx.stroke();
          }
        }
        const revAbs = Math.abs(Math.round(sf ?? 0));
        _speedBadge(`REV ${revAbs}%`, active ? '#90c8ff' : 'rgba(130,190,255,0.9)', 'rgba(0,4,18,0.65)');

      } else {
        // ── Constant speed (slow-mo or fast-mo) ───────────────────────────
        const spd     = sf ?? 100;
        const _isSlow = spd < 100;
        const c1 = _isSlow ? 'rgba(245,200,60,0.58)' : 'rgba(245,120,40,0.58)';
        const c2 = _isSlow ? 'rgba(245,180,40,0.22)' : 'rgba(245,80,15,0.22)';
        const spGrd = ctx.createLinearGradient(px1, _barY, px2, _barY);
        spGrd.addColorStop(0, c1); spGrd.addColorStop(1, c2);
        ctx.fillStyle = spGrd;
        ctx.fillRect(px1, _barY, clipW, _barH);

        // Directional speed lines (converging for fast, spreading for slow)
        if (_barH >= 6 && clipW >= 20) {
          ctx.strokeStyle = _isSlow
            ? (active ? 'rgba(255,215,70,0.35)' : 'rgba(245,200,60,0.20)')
            : (active ? 'rgba(255,140,50,0.35)' : 'rgba(245,120,40,0.20)');
          ctx.lineWidth = 1;
          const cx = (px1 + px2) / 2;
          const spread = _isSlow ? 0.5 : 0.3; // slow spreads more, fast converges more
          for (let li = 0; li < 4; li++) {
            const t0 = (li - 1.5) / 3;
            const startX = px1 + (0.5 + t0 * spread) * clipW;
            const endX   = px1 + (0.5 + t0) * clipW;
            ctx.beginPath();
            ctx.moveTo(Math.max(px1, Math.min(px2, startX)), _barY + 2);
            ctx.lineTo(Math.max(px1, Math.min(px2, endX)),   _barY + _barH - 2);
            ctx.stroke();
          }
        }

        // Speed % badge
        const pctLabel = spd % 1 === 0 ? `${Math.round(spd)}%` : `${spd.toFixed(1)}%`;
        const typeTag  = _isSlow ? '↓' : '↑';
        _speedBadge(typeTag + ' ' + pctLabel,
          _isSlow ? (active ? '#ffd050' : 'rgba(255,210,80,0.90)') : (active ? '#ffaa50' : 'rgba(255,175,70,0.90)'),
          'rgba(10,6,0,0.62)');
      }

      ctx.restore();
    }

    // Clip text label
    if (clipW > 14) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(px1 + 5, ty + 1, clipW - 8 - (layers > 0 ? 22 : 0), clipH);
      ctx.clip();
      ctx.font = '8px "SF Mono", ui-monospace, monospace';
      ctx.textBaseline = 'top';
      ctx.fillStyle = (disabled || parserDisabled)
        ? 'rgba(255,255,255,0.18)'
        : skipped
          ? 'rgba(255,255,255,0.15)'
          : active
            ? 'rgba(255,255,255,0.97)'
            : (linked ? 'rgba(255,255,255,0.80)' : 'rgba(255,255,255,0.45)');
      ctx.fillText(ev.reel || ev.clipName || '', px1 + 5, ty + 5);
      // Second line: speed badge (amber) > transform badge (purple) > duration + seconds (dim)
      if (!isGraphicClip && clipH > 17 && clipW > 44) {
        ctx.font = '7px "SF Mono", ui-monospace, monospace';
        const speedDisp = !disabled && !skipped && ev._pmRetimeAuto && ev._pmSpeedDisplay;
        const xformDisp = !disabled && !skipped && ev._pmResizeAuto && ev._pmTransformDisplay;
        if (speedDisp) {
          ctx.fillStyle = active ? '#f5c542' : 'rgba(245,197,66,0.72)';
          ctx.fillText(ev._pmSpeedDisplay, px1 + 5, ty + 15);
        } else if (xformDisp) {
          ctx.fillStyle = active ? '#c792ea' : 'rgba(199,146,234,0.68)';
          ctx.fillText(ev._pmTransformDisplay, px1 + 5, ty + 15);
        } else {
          const durAlpha = disabled ? 0.08 : skipped ? 0.08 : (linked ? 0.42 : 0.20);
          // Show duration in seconds alongside frames when clip is wide enough
          const durSecs = clipW > 72 && fps > 0 ? ` · ${(eDur / fps).toFixed(1)}s` : '';
          ctx.fillStyle = `rgba(255,255,255,${durAlpha})`;
          ctx.fillText(eDur + 'f' + durSecs, px1 + 5, ty + 15);
        }
      }
      // Third line: scene/take metadata (for tall, wide clips when available)
      if (!isGraphicClip && clipH > 28 && clipW > 72) {
        const aleMeta3 = _pmAleMap?.get?.(_pmStatusKey(ev));
        const scene3   = ev._scene ?? ev.scene ?? aleMeta3?.Scene ?? aleMeta3?.scene ?? '';
        const take3    = ev._take  ?? ev.take  ?? aleMeta3?.Take  ?? aleMeta3?.take  ?? '';
        const meta3    = scene3 && take3 ? `Sc${scene3} Tk${take3}` : scene3 ? `Sc${scene3}` : take3 ? `Tk${take3}` : '';
        if (meta3) {
          ctx.font = '6.5px "SF Mono", ui-monospace, monospace';
          ctx.fillStyle = disabled ? 'rgba(255,255,255,0.04)' : 'rgba(255,255,255,0.15)';
          ctx.fillText(meta3, px1 + 5, ty + 25);
        }
      }
      ctx.restore();
    }

    // VFX layer count badge (top-right of clip)
    if (!isGraphicClip && layers > 0 && clipW > 24) {
      const badge = 'L' + layers;
      ctx.font = 'bold 7px "SF Mono", ui-monospace, monospace';
      const bw  = ctx.measureText(badge).width + 5;
      const bx  = Math.min(W, px2) - bw - 3;
      const by  = ty + 3;
      if (bx > px1 + 8) {
        ctx.globalAlpha = 0.92;
        ctx.fillStyle = '#4caf80';
        rr(bx, by, bw, 9, 2);
        ctx.fill();
        ctx.globalAlpha = 1;
        ctx.fillStyle = '#00180a';
        ctx.textBaseline = 'middle';
        ctx.fillText(badge, bx + 2, by + 4.5);
      }
    }

    // Active selection outline (amber, 1.5px)
    if (active) {
      ctx.strokeStyle = '#f5c542';
      ctx.lineWidth   = 1.5;
      ctx.globalAlpha = 0.88;
      rr(px1 + 0.75, ty + 1.75, clipW - 1.5, clipH - 1.5, 3);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // Linked-marker indicator: downward pin chevron — in VFX Marker mode positioned at
    // the marker's exact recIn TC; otherwise centered on the clip.
    if (linked && clipW >= 10) {
      const iW     = active ? 7 : 6;
      let cxv;
      if (_vfxMarker) {
        const firstMk = evFirstMk.get(i);
        if (firstMk?.recIn) {
          const mkAbsF = tcToFrames(firstMk.recIn, fps);
          let mkF;
          if (_tlDrawPack) {
            const pm = _pmPackedMap.get(i);
            if (pm) mkF = pm.pIn + Math.min(Math.max(0, mkAbsF - pm.eIn), Math.max(0, pm.pOut - pm.pIn - 1));
          } else {
            mkF = mkAbsF - _pmSeqBaseFrames;
          }
          if (Number.isFinite(mkF)) {
            const mx = _tlXv(mkF);
            cxv = Math.round(Math.max(px1 + iW + 2, Math.min(px2 - iW - 2, mx)));
          }
        }
      }
      if (cxv == null) cxv = Math.round((Math.max(px1, HW) + Math.min(px2, W)) / 2);
      const iH     = active ? 9 : 8;
      const iR     = 2;
      const iTp    = active ? 4 : 3;
      const iTop   = ty + 1;
      const mkCol  = evFirstMkColor.get(i) || '#5b7ef5';

      const _mkPath = () => {
        ctx.beginPath();
        ctx.moveTo(cxv - iW + iR, iTop);
        ctx.lineTo(cxv + iW - iR, iTop);
        ctx.arcTo(cxv + iW, iTop, cxv + iW, iTop + iR, iR);
        ctx.lineTo(cxv + iW, iTop + iH);
        ctx.lineTo(cxv, iTop + iH + iTp);
        ctx.lineTo(cxv - iW, iTop + iH);
        ctx.arcTo(cxv - iW, iTop, cxv - iW + iR, iTop, iR);
        ctx.closePath();
      };

      // Fill: always marker color
      ctx.globalAlpha = active ? 1 : 0.88;
      ctx.fillStyle   = mkCol;
      _mkPath(); ctx.fill();

      // White outline when active
      if (active) {
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth   = 1.5;
        ctx.globalAlpha = 0.9;
        _mkPath(); ctx.stroke();
      }

      ctx.globalAlpha = 1;
    }

    // VFX Marker mode: 2px verification-status strip at clip bottom edge
    // Green = all sources verified | Amber = warning | dim = not yet checked
    if (_vfxMarker && linked) {
      const mk0 = evFirstMk.get(i);
      ctx.globalAlpha = 0.85;
      ctx.fillStyle = mk0?._linkVerified === true  ? '#4caf80'
                    : mk0?._linkVerified === false ? '#f5c542'
                    :                                '#383850';
      ctx.fillRect(px1, ty + 1 + clipH - 2, clipW, 2);
      ctx.globalAlpha = 1;
    }

    // Edge gap
    ctx.fillStyle = '#07070f';
    ctx.fillRect(Math.min(px2, W - 1), ty + 1, 1, clipH);

    // Cut-point indicator: small diagonal tick at the right edge of each clip
    if (_pmTlShowTr && clipW >= 4 && !disabled) {
      const cx = Math.min(px2, W - 1);
      const notchH = Math.min(8, clipH);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth   = 1;
      ctx.beginPath();
      ctx.moveTo(cx - 3, ty + 1);
      ctx.lineTo(cx + 1, ty + 1 + notchH);
      ctx.stroke();
    }
  }

  // ── Transitions (dissolve, wipe, fade) ── only when TR toggle is on ─────────
  // Helper: parse hex color → rgba string
  const _rgba = (hex, a) => {
    const h = hex.replace('#','');
    const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
    return `rgba(${r},${g},${b},${a.toFixed(3)})`;
  };
  // Helper: draw centered label with shadow, returns measured width
  const _trLabel = (text, x, y, size, col) => {
    ctx.font = `bold ${size}px "SF Mono",ui-monospace,monospace`;
    ctx.textBaseline = 'middle';
    ctx.fillStyle = col || 'rgba(255,255,255,0.96)';
    ctx.shadowColor = 'rgba(0,0,0,0.92)'; ctx.shadowBlur = 3;
    const w = ctx.measureText(text).width;
    ctx.fillText(text, x - w / 2, y);
    ctx.shadowBlur = 0;
    return w;
  };
  // Helper: find outgoing event color (last event on same track before index i)
  const _outgoingCol = (i, track) => {
    for (let j = i - 1; j >= 0; j--) {
      if (_pmEvents[j] && !_pmGetUnscriptedNoActionKind(_pmEvents[j]) && (trackOf.get(j) ?? 0) === track)
        return camColor(_pmEvents[j]);
    }
    return '#808080';
  };

  if (_pmTlShowTr) for (let i = 0; i < _pmEvents.length; i++) {
    const ev = _pmEvents[i];
    if (!ev) continue;
    if (_pmGetUnscriptedNoActionKind(ev)) continue; // skip graphics — no track slot, no transition overlay
    const tr = _pmParseTransition(ev);
    if (!tr) continue;

    const eIn   = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const track = trackOf.get(i) ?? 0;
    const ty    = _tY(track);
    const clipH = _tH(track) - 3;

    // Center the transition overlay ON the cut point so it spans both clips
    const halfDur = Math.max(1, Math.round(tr.dur / 2));
    const trBase  = _tlDrawPack ? (_pmPackedMap.get(i)?.pIn ?? -1) : (eIn - _pmSeqBaseFrames);
    if (trBase < 0) continue;
    const tx1  = _tlXv(trBase - halfDur);
    const tx2  = _tlXv(trBase + halfDur);
    const ptx1 = Math.max(HW, Math.round(tx1));
    const ptx2 = Math.min(W,  Math.round(tx2));
    if (ptx2 < HW || ptx1 > W) continue;
    const trX1 = Math.max(HW, ptx1);
    const trX2 = Math.max(trX1 + 5, ptx2);
    const tw   = trX2 - trX1;
    const cx   = trX1 + tw / 2;          // exact cut-point x
    const cy   = ty + 1 + clipH / 2;     // vertical center of clip
    const top  = ty + 1;
    const bot  = ty + 1 + clipH;

    ctx.save();
    ctx.beginPath(); ctx.rect(trX1, top, tw, clipH); ctx.clip();

    if (tr.type === 'dissolve') {
      const outCol = _outgoingCol(i, track);
      const inCol  = camColor(ev);

      // Outgoing: strong at far-left → transparent at far-right (S-curve ease-out)
      const gOut = ctx.createLinearGradient(trX1, 0, trX2, 0);
      gOut.addColorStop(0,    _rgba(outCol, 0.52));
      gOut.addColorStop(0.18, _rgba(outCol, 0.45));
      gOut.addColorStop(0.42, _rgba(outCol, 0.24));
      gOut.addColorStop(0.65, _rgba(outCol, 0.08));
      gOut.addColorStop(0.85, _rgba(outCol, 0.02));
      gOut.addColorStop(1,    _rgba(outCol, 0.0));
      ctx.fillStyle = gOut; ctx.fillRect(trX1, top, tw, clipH);

      // Incoming: transparent at far-left → strong at far-right (S-curve ease-in)
      const gIn = ctx.createLinearGradient(trX1, 0, trX2, 0);
      gIn.addColorStop(0,    _rgba(inCol, 0.0));
      gIn.addColorStop(0.15, _rgba(inCol, 0.02));
      gIn.addColorStop(0.35, _rgba(inCol, 0.08));
      gIn.addColorStop(0.58, _rgba(inCol, 0.24));
      gIn.addColorStop(0.82, _rgba(inCol, 0.45));
      gIn.addColorStop(1,    _rgba(inCol, 0.52));
      ctx.fillStyle = gIn; ctx.fillRect(trX1, top, tw, clipH);

      // X cross — diagonal lines from opposite corners
      const xLw = tw < 20 ? 1 : tw < 40 ? 1.5 : 2;
      ctx.strokeStyle = 'rgba(255,255,255,0.70)';
      ctx.lineWidth = xLw; ctx.lineCap = 'round';
      ctx.shadowColor = 'rgba(0,0,0,0.70)'; ctx.shadowBlur = 2;
      ctx.beginPath();
      ctx.moveTo(trX1 + 1, top + 1);   ctx.lineTo(trX2 - 1, bot - 1);  // ↘
      ctx.moveTo(trX2 - 1, top + 1);   ctx.lineTo(trX1 + 1, bot - 1);  // ↙
      ctx.stroke();
      ctx.shadowBlur = 0;

      // Vertical cut-point line at exact cx
      ctx.strokeStyle = 'rgba(255,255,255,0.55)';
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 2]);
      ctx.beginPath(); ctx.moveTo(cx, top + 1); ctx.lineTo(cx, bot - 1); ctx.stroke();
      ctx.setLineDash([]);

      // Outgoing/incoming color swatches on outer edges
      ctx.fillStyle = _rgba(outCol, 0.75);
      ctx.fillRect(trX1, top, 2, clipH);
      ctx.fillStyle = _rgba(inCol, 0.75);
      ctx.fillRect(trX2 - 2, top, 2, clipH);

      // Center pip at exact cut point
      if (clipH >= 6) {
        const pipR = Math.min(4, clipH * 0.22);
        ctx.beginPath(); ctx.arc(cx, cy, pipR, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(255,255,255,0.95)';
        ctx.shadowColor = 'rgba(255,255,255,0.55)'; ctx.shadowBlur = 6;
        ctx.fill(); ctx.shadowBlur = 0;
      }

      // Label — centered, always at cy
      if (tw >= 10) {
        const durS = (tr.dur / Math.max(1, fps)).toFixed(1);
        const lbl  = tw >= 56 ? `DIS ${tr.dur}f · ${durS}s` : tw >= 36 ? `DIS ${tr.dur}f` : tw >= 20 ? `D${tr.dur}` : 'D';
        _trLabel(lbl, cx, cy, tw < 20 ? 7 : 8);
      }

    } else if (tr.type === 'wipe') {
      const outCol = _outgoingCol(i, track);
      const inCol  = camColor(ev);

      // Left (outgoing) solid tint
      ctx.fillStyle = _rgba(outCol, 0.28);
      ctx.fillRect(trX1, top, tw / 2, clipH);
      // Right (incoming) solid tint
      ctx.fillStyle = _rgba(inCol, 0.28);
      ctx.fillRect(cx, top, tw / 2, clipH);

      // Hard wipe edge — filled diagonal transition zone clipped to a chevron shape
      const slant = Math.min(clipH * 0.35, tw * 0.22);
      ctx.beginPath();
      ctx.moveTo(cx - slant, top);
      ctx.lineTo(cx + slant, top);
      ctx.lineTo(cx + slant, bot);
      ctx.lineTo(cx - slant, bot);
      ctx.closePath();
      const gEdge = ctx.createLinearGradient(cx - slant, 0, cx + slant, 0);
      gEdge.addColorStop(0, _rgba(outCol, 0.40));
      gEdge.addColorStop(0.5, 'rgba(100,235,215,0.55)');
      gEdge.addColorStop(1, _rgba(inCol, 0.40));
      ctx.fillStyle = gEdge; ctx.fill();

      // Bright wipe edge line
      ctx.strokeStyle = 'rgba(100,235,215,0.98)';
      ctx.lineWidth = tw < 16 ? 1 : 1.8; ctx.lineCap = 'round';
      ctx.shadowColor = 'rgba(80,220,200,0.65)'; ctx.shadowBlur = 5;
      ctx.beginPath();
      ctx.moveTo(cx + slant, top + 1);
      ctx.lineTo(cx - slant, bot - 1);
      ctx.stroke(); ctx.shadowBlur = 0;

      // Direction arrows — two "> >" pointing right
      if (tw >= 28 && clipH >= 8) {
        const arS = Math.min(4, clipH * 0.20);
        ctx.strokeStyle = 'rgba(100,235,215,0.75)';
        ctx.lineWidth = 1.2; ctx.lineCap = 'round';
        for (const ax of [trX1 + tw * 0.22, trX1 + tw * 0.78]) {
          ctx.beginPath();
          ctx.moveTo(ax - arS, cy - arS); ctx.lineTo(ax + arS, cy); ctx.lineTo(ax - arS, cy + arS);
          ctx.stroke();
        }
      }

      if (tw >= 12) {
        const lbl = tw >= 36 ? `WPE ${tr.dur}f` : tw >= 20 ? `W${tr.dur}` : 'W';
        _trLabel(lbl, cx, cy, tw < 20 ? 7 : 8, 'rgba(160,240,225,0.98)');
      }

    } else if (tr.type === 'fadein') {
      // Fade from black: S-curve ease-in (slow start → fast finish)
      const gFI = ctx.createLinearGradient(trX1, 0, trX2, 0);
      gFI.addColorStop(0,    'rgba(0,0,0,0.92)');
      gFI.addColorStop(0.20, 'rgba(0,0,0,0.82)');
      gFI.addColorStop(0.45, 'rgba(0,0,0,0.55)');
      gFI.addColorStop(0.70, 'rgba(0,0,0,0.22)');
      gFI.addColorStop(0.88, 'rgba(0,0,0,0.06)');
      gFI.addColorStop(1,    'rgba(0,0,0,0.0)');
      ctx.fillStyle = gFI; ctx.fillRect(trX1, top, tw, clipH);

      // Filled triangle wedge (tip points right = direction of reveal)
      ctx.beginPath();
      ctx.moveTo(trX1 + 1, top + 1);
      ctx.lineTo(trX1 + 1, bot - 1);
      ctx.lineTo(trX2 - 1, cy);
      ctx.closePath();
      ctx.fillStyle = 'rgba(245,220,100,0.12)'; ctx.fill();
      ctx.strokeStyle = 'rgba(245,220,100,0.85)';
      ctx.lineWidth = 1; ctx.lineCap = 'round';
      ctx.shadowColor = 'rgba(245,220,100,0.40)'; ctx.shadowBlur = 3;
      ctx.stroke(); ctx.shadowBlur = 0;

      // Left black edge bar
      ctx.fillStyle = 'rgba(0,0,0,0.85)';
      ctx.fillRect(trX1, top, 2, clipH);

      if (tw >= 14) {
        const lbl = tw >= 36 ? `FI ${tr.dur}f` : 'FI';
        _trLabel(lbl, trX1 + tw * 0.30, cy, 7, 'rgba(255,235,120,0.96)');
      }

    } else if (tr.type === 'fadeout') {
      // Fade to black: S-curve ease-out (fast start → slow finish)
      const gFO = ctx.createLinearGradient(trX1, 0, trX2, 0);
      gFO.addColorStop(0,    'rgba(0,0,0,0.0)');
      gFO.addColorStop(0.12, 'rgba(0,0,0,0.06)');
      gFO.addColorStop(0.30, 'rgba(0,0,0,0.22)');
      gFO.addColorStop(0.55, 'rgba(0,0,0,0.55)');
      gFO.addColorStop(0.80, 'rgba(0,0,0,0.82)');
      gFO.addColorStop(1,    'rgba(0,0,0,0.92)');
      ctx.fillStyle = gFO; ctx.fillRect(trX1, top, tw, clipH);

      // Filled triangle wedge (tip points left = direction of disappear)
      ctx.beginPath();
      ctx.moveTo(trX2 - 1, top + 1);
      ctx.lineTo(trX2 - 1, bot - 1);
      ctx.lineTo(trX1 + 1, cy);
      ctx.closePath();
      ctx.fillStyle = 'rgba(245,220,100,0.12)'; ctx.fill();
      ctx.strokeStyle = 'rgba(245,220,100,0.85)';
      ctx.lineWidth = 1; ctx.lineCap = 'round';
      ctx.shadowColor = 'rgba(245,220,100,0.40)'; ctx.shadowBlur = 3;
      ctx.stroke(); ctx.shadowBlur = 0;

      // Right black edge bar
      ctx.fillStyle = 'rgba(0,0,0,0.85)';
      ctx.fillRect(trX2 - 2, top, 2, clipH);

      if (tw >= 14) {
        const lbl = tw >= 36 ? `FO ${tr.dur}f` : 'FO';
        _trLabel(lbl, trX1 + tw * 0.70, cy, 7, 'rgba(255,235,120,0.96)');
      }

    } else {
      // Unknown / key — subtle bordered tint
      ctx.fillStyle = 'rgba(200,200,200,0.07)';
      ctx.fillRect(trX1, top, tw, clipH);
      ctx.strokeStyle = 'rgba(200,200,200,0.45)';
      ctx.lineWidth = 1;
      ctx.strokeRect(trX1 + 0.5, top + 0.5, tw - 1, clipH - 1);
      if (tw >= 10)
        _trLabel(tr.raw?.slice(0,4) || '?', cx, cy, 7, 'rgba(210,210,210,0.85)');
    }

    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.setLineDash([]);

  // ── Subtitle track (shot name · note · additional note) ───────────────────
  if (_pmTlShowSub && subY > 0) {
    const subRowH = H - subY;

    // Precompute event → first linked marker (O(n) lookup)
    const _mkById   = new Map(_pmClipMarkers.map(m => [m.id, m]));
    const _evFirstMk = new Map();
    for (const [mkId, evIdx] of _pmLinkMap) {
      if (!_evFirstMk.has(evIdx)) {
        const mk = _mkById.get(mkId);
        if (mk) _evFirstMk.set(evIdx, mk);
      }
    }

    // Row background
    ctx.fillStyle = '#060618';
    ctx.fillRect(HW, subY, CW, subRowH);
    // Top border
    ctx.fillStyle = '#1e1e3c';
    ctx.fillRect(0, subY, W, 1);
    // Header sidebar
    ctx.fillStyle = '#07071e';
    ctx.fillRect(0, subY, HW, subRowH);
    ctx.fillStyle = '#1c1c36';
    ctx.fillRect(HW - 1, subY, 1, subRowH);
    // Header label "SUB"
    ctx.font = 'bold 7px "SF Mono", ui-monospace, monospace';
    ctx.fillStyle = '#4848a0';
    ctx.textBaseline = 'middle';
    ctx.fillText('SUB', 5, subY + subRowH / 2);

    // Per-event subtitle segments
    ctx.font = '7.5px "SF Mono", ui-monospace, monospace';
    ctx.textBaseline = 'middle';
    const subMidY = subY + subRowH / 2;

    for (let i = 0; i < _pmEvents.length; i++) {
      const ev = _pmEvents[i];
      if (!ev || !trackOf.has(i)) continue;

      const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
      const rOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
      const eOut = rOut > eIn ? rOut : ev.durationFrames ? eIn + Number(ev.durationFrames) : eIn + 1;

      let eF1, eF2;
      if (_tlDrawPack) {
        const pm = _pmPackedMap.get(i);
        if (!pm) continue;
        eF1 = pm.pIn; eF2 = pm.pOut;
      } else {
        eF1 = eIn - _pmSeqBaseFrames; eF2 = eOut - _pmSeqBaseFrames;
      }
      const sx1  = Math.round(_tlXv(eF1));
      const sx2  = Math.round(_tlXv(eF2));
      const cpx1 = Math.max(HW, sx1);
      const cpx2 = Math.min(W,  sx2);
      const sw   = cpx2 - cpx1;
      if (sw < 4 || cpx2 <= HW || cpx1 > W) continue;

      // Gather text: shot name + note type label + additional note
      const mk = _evFirstMk.get(i);
      const shotName  = ev._pmShot || ev.shotName || mk?.shotName || '';
      // "Note" in inspector = annotation note type (noteTypeGroup + noteType)
      const noteGroup = mk?.noteTypeGroup || '';
      const noteType  = mk?.noteType      || '';
      const note      = noteGroup && noteType ? `${noteGroup}: ${noteType}`
                      : (noteType || noteGroup || '');
      // "Additional note" in inspector = mk.note (free-form textarea)
      const addNote   = mk?.note || mk?.scopeOfWork || '';
      const parts     = [shotName, note, addNote].filter(Boolean);
      if (!parts.length) continue;

      // Tinted segment background
      ctx.fillStyle = darkHex(camColor(ev), 0.18);
      ctx.fillRect(cpx1, subY + 1, sw, subRowH - 2);

      // Clipped text
      ctx.save();
      ctx.beginPath();
      ctx.rect(cpx1, subY, sw, subRowH);
      ctx.clip();

      ctx.font = '6.5px "SF Mono", ui-monospace, monospace';
      if (parts.length === 1 || subRowH < 18) {
        // Single line — not enough height for multi-row
        ctx.fillStyle = 'rgba(210,210,255,0.72)';
        ctx.fillText(parts[0], cpx1 + 3, subMidY);
      } else if (parts.length === 2 || subRowH < 26) {
        // Two rows: shot name + one note line
        ctx.fillStyle = 'rgba(220,218,255,0.80)';
        ctx.fillText(parts[0], cpx1 + 3, subY + subRowH * 0.30);
        ctx.fillStyle = 'rgba(180,180,230,0.55)';
        ctx.fillText(parts[1], cpx1 + 3, subY + subRowH * 0.72);
      } else {
        // Three rows: shot name / note / additional note
        ctx.fillStyle = 'rgba(220,218,255,0.85)';
        ctx.fillText(shotName || parts[0], cpx1 + 3, subY + subRowH * 0.20);
        ctx.fillStyle = 'rgba(170,210,255,0.65)';
        ctx.fillText(note,    cpx1 + 3, subY + subRowH * 0.52);
        ctx.fillStyle = 'rgba(150,190,230,0.50)';
        ctx.fillText(addNote, cpx1 + 3, subY + subRowH * 0.82);
      }

      ctx.restore();
    }
  }

  // ── Track separator lines ──────────────────────────────────────────────────
  ctx.fillStyle = '#0e0e22';
  for (let t = 1; t < nTracks; t++) {
    const ty = _tY(t);
    ctx.fillRect(HW, ty, CW, 1);
  }

  ctx.restore(); // ── end track lane content clip ──────────────────────────

  // ── Intelligent pack: reel group separators + labels ─────────────────────
  if (_tlDrawPack && _pmPackIntelligent && _pmPackedMap.size > 0) {
    ctx.font = 'bold 7px "SF Mono", ui-monospace, monospace';
    ctx.textBaseline = 'middle';
    const pinMidY = _NLE_RULER_H + _NLE_PIN_H / 2;
    for (const [idx, pm] of _pmPackedMap) {
      if (!pm._iGroupStart) continue;
      const x = Math.round(_tlXv(pm.pIn));
      if (x > W) continue;
      const reel = pm._iGroup || '';
      const col  = camColor(_pmEvents[idx]);
      // Full-height group separator line
      if (x >= HW) {
        ctx.strokeStyle = col + '55';
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(x + 0.5, tracksTop);
        ctx.lineTo(x + 0.5, tracksBottom);
        ctx.stroke();
        ctx.setLineDash([]);
      }
      // Reel label chip in pin row
      const lx = Math.max(HW + 2, x + 2);
      if (lx < W - 8 && reel) {
        const tw = ctx.measureText(reel).width;
        if (lx + tw + 8 <= W) {
          ctx.fillStyle = darkHex(col, 0.45);
          rr(lx, _NLE_RULER_H + 2, tw + 6, _NLE_PIN_H - 4, 2);
          ctx.fill();
          ctx.fillStyle = col;
          ctx.fillText(reel, lx + 3, pinMidY);
        }
      }
    }
  }

  // ── Pack mode: collapsed-gap separator lines + gap labels ─────────────────
  if (_tlDrawPack && _pmPackedMap.size > 0) {
    const sortedPmGap = [..._pmPackedMap.values()].sort((a, b) => a.pIn - b.pIn);
    for (const pm of sortedPmGap) {
      if (!pm.collapsedGap || pm.pIn <= 0) continue;
      const x = Math.round(_tlXv(pm.pIn));
      if (x < HW || x > W) continue;
      // Dashed amber separator through track area
      ctx.strokeStyle = 'rgba(255,180,40,0.30)';
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(x + 0.5, tracksTop);
      ctx.lineTo(x + 0.5, tracksBottom);
      ctx.stroke();
      ctx.setLineDash([]);
      // Gap duration label in the pin row
      const gapSec = pm.collapsedGap / fps;
      const gapStr = gapSec < 60
        ? `↔${gapSec < 10 ? gapSec.toFixed(1) : Math.round(gapSec)}s`
        : `↔${Math.floor(gapSec / 60)}m${String(Math.round(gapSec % 60)).padStart(2,'0')}s`;
      ctx.font = '6.5px system-ui, sans-serif';
      ctx.fillStyle = 'rgba(255,180,40,0.60)';
      ctx.textBaseline = 'middle';
      ctx.fillText(gapStr, x + 2, _NLE_RULER_H + _NLE_PIN_H / 2);
    }
  }

  // Bottom border — full canvas width, drawn outside clip
  ctx.fillStyle = '#131328';
  ctx.fillRect(0, H - 1, W, 1);

  // ── Scrollbar thumb in header gutter ─────────────────────────────────────
  if (_pmTlMaxScrollY > 0) {
    const _sbViewH = Math.min(H, pmTlWrap?.clientHeight || H) - tracksTop - (_pmTlShowSub ? _NLE_SUB_H : 0);
    const _sbThH   = Math.max(16, Math.round((_sbViewH / _pmTlTotalTrackH) * _sbViewH));
    const _sbThY   = tracksTop + Math.round(
      (_pmTlScrollY / _pmTlMaxScrollY) * Math.max(0, _sbViewH - _sbThH));
    // Track groove
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(1, tracksTop, 3, _sbViewH);
    // Thumb
    ctx.fillStyle = 'rgba(160,165,220,0.40)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(1, _sbThY, 3, _sbThH, 1.5);
    else               ctx.rect(1, _sbThY, 3, _sbThH);
    ctx.fill();
  }


  // ── Playhead ────────────────────────────────────────────────────────────────
  if (_pmTlPlayhead >= 0) {
    let phSeqF = _pmTlPlayhead;
    if (_tlDrawPack) {
      const absF = _pmTlPlayhead + _pmSeqBaseFrames;
      phSeqF = -1;
      for (const [, pm] of _pmPackedMap) {
        if (absF >= pm.eIn && absF < pm.eOut) { phSeqF = pm.pIn + (absF - pm.eIn); break; }
      }
    }
    const x = phSeqF >= 0 ? Math.round(_tlXv(phSeqF)) : -999;
    const tcStr = framesToTC(_pmTlPlayhead + _pmSeqBaseFrames, fps);
    ctx.font = '7.5px "SF Mono", ui-monospace, monospace';
    ctx.textBaseline = 'bottom';
    const tw = ctx.measureText(tcStr).width;

    const inView = x >= HW - 1 && x <= W + 1;
    const offLeft  = x < HW - 1;
    const offRight = x > W + 1;

    if (inView) {
      // ── In-view: full playhead ──────────────────────────────────────────────
      // Wide glow halo
      ctx.fillStyle = 'rgba(255,50,80,0.13)';
      ctx.fillRect(x - 5, tracksTop, 11, H - tracksTop);
      // Thin accent line alongside stem (left)
      ctx.fillStyle   = 'rgba(255,80,100,0.35)';
      ctx.fillRect(x - 3, tracksTop, 1, H - tracksTop);
      // Main stem — 2px solid
      ctx.fillStyle   = '#ff3355';
      ctx.globalAlpha = 1;
      ctx.fillRect(x - 1, tracksTop, 2, H - tracksTop);
      // Diamond head on ruler (slightly larger, more visible)
      ctx.fillStyle = '#f5c542';
      ctx.beginPath();
      ctx.moveTo(x,      _NLE_RULER_H - 11);
      ctx.lineTo(x + 6,  _NLE_RULER_H - 5);
      ctx.lineTo(x,      _NLE_RULER_H);
      ctx.lineTo(x - 6,  _NLE_RULER_H - 5);
      ctx.closePath();
      ctx.fill();
      // TC label pill — clamped to stay inside ruler
      const tx = Math.max(HW + 2, Math.min(W - tw - 10, x - tw / 2 - 3));
      ctx.fillStyle = 'rgba(10,10,20,0.90)';
      rr(tx - 2, 1, tw + 8, _NLE_RULER_H - 5, 2);
      ctx.fill();
      ctx.fillStyle = '#f5c542';
      ctx.fillText(tcStr, tx + 2, _NLE_RULER_H - 3);

    } else if (offLeft || offRight) {
      // ── Off-screen: edge indicator so playhead is never invisible ────────────
      const edgeX  = offLeft ? HW + 1 : W - 1;
      const arrowW = 6;
      const arrowH = 10;
      const midY   = tracksTop + (H - tracksTop) * 0.5;

      // Colored edge strip
      ctx.fillStyle = 'rgba(255,51,85,0.28)';
      ctx.fillRect(offLeft ? HW : W - 3, tracksTop, 3, H - tracksTop);

      // Triangle arrow pointing toward playhead direction
      ctx.fillStyle = '#ff3355';
      ctx.beginPath();
      if (offLeft) {
        ctx.moveTo(edgeX,          midY);
        ctx.lineTo(edgeX + arrowW, midY - arrowH / 2);
        ctx.lineTo(edgeX + arrowW, midY + arrowH / 2);
      } else {
        ctx.moveTo(edgeX,          midY);
        ctx.lineTo(edgeX - arrowW, midY - arrowH / 2);
        ctx.lineTo(edgeX - arrowW, midY + arrowH / 2);
      }
      ctx.closePath();
      ctx.fill();

      // TC label pill — always on-screen, near the edge
      const pillX = offLeft ? HW + arrowW + 4 : W - tw - arrowW - 12;
      const clampedPillX = Math.max(HW + 2, Math.min(W - tw - 10, pillX));
      ctx.fillStyle = 'rgba(10,10,20,0.88)';
      rr(clampedPillX - 2, 1, tw + 8, _NLE_RULER_H - 5, 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(245,197,66,0.75)';
      ctx.fillText(tcStr, clampedPillX + 2, _NLE_RULER_H - 3);
    }
  }
  // ── Atomic blit: copy offscreen → visible in one GPU operation ───────────
  _pmTlCtx.drawImage(_pmOfc, 0, 0);
  } catch (e) {
    // Restore offscreen canvas state so future frames can draw cleanly
    try { _pmOfcCtx?.restore(); } catch {}
    try { if (_pmOfcCtx) { _pmOfcCtx.globalAlpha = 1; _pmOfcCtx.setLineDash([]); } } catch {}
    // Still blit whatever rendered before the error
    try { _pmTlCtx.drawImage(_pmOfc, 0, 0); } catch {}
    console.warn('[PrepMark] _pmDrawNLE error', e);
  }
}

// ─── Info rail (persistent strip below timeline canvas) ───────────────────────
function _pmUpdateInfoRail() {
  const idle   = document.getElementById('pmTlIrIdle');
  const detail = document.getElementById('pmTlIrDetail');
  if (!idle && !detail) return;

  const fps = Math.max(1, _pmFps || 24);
  const esc = s => String(s || '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  // ── Always sync marker-dependent UI (runs in both detail and idle mode) ───
  const _mkCountNow = _pmClipMarkers?.length || 0;
  const _rmBtnIr  = document.getElementById('pmIrRemoveAllMkBtn');
  const _rmBtnHdr = document.getElementById('pmRemoveAllMkBtn');
  if (_rmBtnIr) {
    _rmBtnIr.style.display = _mkCountNow > 0 ? '' : 'none';
    if (!_mkCountNow) { _rmBtnIr.dataset.confirm = ''; _rmBtnIr.textContent = '✕ Remove All Markers'; _rmBtnIr.classList.remove('pm-tl-ir-rm-all-mk--confirm'); }
  }
  if (_rmBtnHdr) {
    _rmBtnHdr.style.display = _mkCountNow > 0 ? '' : 'none';
    if (!_mkCountNow) { _rmBtnHdr.dataset.confirm = ''; _rmBtnHdr.textContent = '✕ Markers'; _rmBtnHdr.classList.remove('pm-hdr-btn--rm-mk-confirm'); }
  }

  // ── Selected clip mode ────────────────────────────────────────────────────
  if (_pmActiveEventIdx >= 0 && _pmEvents[_pmActiveEventIdx]) {
    const ev       = _pmEvents[_pmActiveEventIdx];
    const durF     = ev.durationFrames ||
      (tcToFrames(ev.recOut || '00:00:00:00', fps) - tcToFrames(ev.recIn || '00:00:00:00', fps));
    const durSec   = fps > 0 ? (durF / fps).toFixed(1) + 's' : '';
    const aleMeta  = _pmAleMap?.get?.(_pmStatusKey(ev));
    const scene    = esc(ev._scene ?? ev.scene ?? aleMeta?.Scene ?? aleMeta?.scene ?? '');
    const take     = esc(ev._take  ?? ev.take  ?? aleMeta?.Take  ?? aleMeta?.take  ?? '');
    const cam      = ev.camera && ev.camera !== ev.reel ? esc(ev.camera) : '';
    const isSkip   = !!ev._pmConformSkip;
    const trackLbl = Number.isFinite(ev.trackIndex) ? 'V' + (ev.trackIndex + 1) : 'V1';
    const shotName = ev._pmShot || _pmClipMarkers.find(mk => _pmLinkMap.get(mk.id) === _pmActiveEventIdx)?.shotName || '';

    // ── Speed detail for info rail ─────────────────────────────────────────
    const irSpeedN   = _pmExtractSpeedPercent(ev);
    const irSpeedOk  = irSpeedN != null && !isNaN(Number(irSpeedN));
    const irIsDyn    = Array.isArray(ev.speedKeys) && ev.speedKeys.length > 0;
    const irHasSpeed = irIsDyn || (irSpeedOk && Math.abs(irSpeedN - 100) > 0.5);
    let speedBadgeHtml = '';
    let speedFieldHtml = '';
    if (irHasSpeed) {
      const irIsFrz  = !irIsDyn && irSpeedOk && Math.abs(irSpeedN) < 0.5;
      const irIsRev  = !irIsDyn && !irIsFrz && irSpeedOk && irSpeedN < 0;
      const irIsFast = !irIsDyn && !irIsFrz && !irIsRev && irSpeedOk && irSpeedN > 100;
      const irIsSlow = !irIsDyn && !irIsFrz && !irIsRev && irSpeedOk;
      const typeStr  = irIsDyn ? 'DYNAMIC' : irIsFrz ? 'FREEZE' : irIsRev ? 'REVERSE' : irIsFast ? 'FAST-MO' : 'SLOW-MO';
      const badgeCls = irIsFrz ? 'pm-tl-ir-badge-speed-frz' : irIsRev ? 'pm-tl-ir-badge-speed-rev' : irIsFast ? 'pm-tl-ir-badge-speed-fast' : irIsDyn ? 'pm-tl-ir-badge-speed-var' : 'pm-tl-ir-badge-speed-slow';
      speedBadgeHtml = `<span class="pm-tl-ir-badge ${badgeCls}" style="margin-left:6px">${typeStr}</span>`;

      if (!irIsDyn && irSpeedOk && !irIsFrz) {
        const srcF   = Math.round(durF * (Math.abs(irSpeedN) / 100));
        const srcSec = fps > 0 ? (srcF / fps).toFixed(1) + 's' : '';
        speedFieldHtml =
          `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">Speed</span>` +
          `<span class="pm-tl-ir-field-val pm-tl-ir-speed-val">${Math.abs(irSpeedN)}%${irIsRev ? ' REV' : ''}</span></span>` +
          `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">Src</span>` +
          `<span class="pm-tl-ir-field-val">${srcF}f <span class="pm-tl-ir-field-dim">${esc(srcSec)}</span></span></span>` +
          `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">Ratio</span>` +
          `<span class="pm-tl-ir-field-val pm-tl-ir-speed-val">${irIsFast ? '×' + (Math.abs(irSpeedN)/100).toFixed(2) + ' fast' : '×' + (100/Math.max(0.01,Math.abs(irSpeedN))).toFixed(2) + ' slow'}</span></span>`;
      } else if (irIsDyn) {
        const allPcts = ev.speedKeys.map(k => k.pct ?? k.value ?? 100);
        const minP = Math.round(Math.min(...allPcts));
        const maxP = Math.round(Math.max(...allPcts));
        speedFieldHtml =
          `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">Speed</span>` +
          `<span class="pm-tl-ir-field-val pm-tl-ir-speed-val">${minP}–${maxP}%</span></span>` +
          `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">Keys</span>` +
          `<span class="pm-tl-ir-field-val">${ev.speedKeys.length}</span></span>`;
      }
    }

    const field = (lbl, val) => val
      ? `<span class="pm-tl-ir-field"><span class="pm-tl-ir-field-lbl">${lbl}</span><span class="pm-tl-ir-field-val">${val}</span></span>`
      : '';

    if (idle)   idle.style.display   = 'none';
    if (detail) {
      detail.style.display = 'flex';
      detail.innerHTML =
        `<span class="pm-tl-ir-badge pm-tl-ir-badge-track">${esc(trackLbl)}</span>` +
        `<span class="pm-tl-ir-clip-name" title="${esc(ev.clipName || ev.reel || '')}">${esc(ev.clipName || ev.reel || '—')}</span>` +
        (isSkip ? `<span class="pm-tl-ir-badge pm-tl-ir-badge-skip" style="margin-left:4px">SKIP</span>` : '') +
        speedBadgeHtml +
        field('Rec In',  esc(ev.recIn  || '—')) +
        field('Rec Out', esc(ev.recOut || '—')) +
        field('Dur',     `${durF}f <span class="pm-tl-ir-field-dim">${esc(durSec)}</span>`) +
        speedFieldHtml +
        (ev.srcIn  ? field('Src In',  esc(ev.srcIn))  : '') +
        (ev.srcOut ? field('Src Out', esc(ev.srcOut)) : '') +
        (cam       ? field('Cam',   cam)   : '') +
        (scene     ? field('Sc',    scene) : '') +
        (take      ? field('Tk',    take)  : '') +
        (shotName  ? field('Shot',  esc(shotName)) : '');
    }
    return;
  }

  // ── Idle mode: timeline stats ─────────────────────────────────────────────
  if (idle)   idle.style.display   = 'flex';
  if (detail) detail.style.display = 'none';

  const totalClips = _pmEvents.filter(Boolean).length;
  const skipCount  = _pmEvents.filter(ev => ev && ev._pmConformSkip).length;
  const mkCount    = _pmClipMarkers?.length || 0;

  // Sum durations across all events
  let totalDurF = 0;
  for (const ev of _pmEvents) {
    if (!ev) continue;
    const eIn  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
    const eOut = tcToFrames(ev.recOut || '00:00:00:00', fps);
    const dur  = ev.durationFrames ? Number(ev.durationFrames) : Math.max(0, eOut - eIn);
    totalDurF += dur;
  }
  const totalSec = fps > 0 ? totalDurF / fps : 0;
  const durStr = totalSec <= 0 ? '—'
    : totalSec >= 3600 ? `${Math.floor(totalSec/3600)}h ${Math.floor((totalSec%3600)/60)}m`
    : totalSec >= 60   ? `${Math.floor(totalSec/60)}m ${Math.round(totalSec%60)}s`
    : `${totalSec.toFixed(1)}s`;

  const _set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };
  _set('pmIrClips', `<strong>${totalClips}</strong> clip${totalClips === 1 ? '' : 's'}`);
  _set('pmIrDur',   totalClips > 0 ? `<strong>${esc(durStr)}</strong>` : '<span style="color:#222238">—</span>');
  _set('pmIrMk',    `<strong>${mkCount}</strong> marker${mkCount === 1 ? '' : 's'}`);


  const skipEl    = document.getElementById('pmIrSkip');
  const skipDotEl = document.getElementById('pmIrSkipDot');
  if (skipEl) {
    skipEl.innerHTML    = `<strong>${skipCount}</strong> skipped`;
    skipEl.style.display    = skipCount > 0 ? '' : 'none';
  }
  if (skipDotEl) skipDotEl.style.display = skipCount > 0 ? '' : 'none';
}

// ─── Video player wiring ──────────────────────────────────────────────────────
function _wireVideoPlayer() {
  if (!pmVideo) return;

  // timeupdate covers seeks, steps, and paused state (free, no rAF needed)
  pmVideo.addEventListener('timeupdate', () => {
    _pmPresentedMediaTimeSec = NaN;
    _pmRememberVideoMediaTimeSec(Number(pmVideo.currentTime));
    _pmOnVideoTimeUpdate();
  });
  pmVideo.addEventListener('seeked', () => {
    _pmPresentedMediaTimeSec = NaN;
    _pmRememberVideoMediaTimeSec(Number(pmVideo.currentTime));
    _pmLastSyncedF = -1;
    _pmOnVideoTimeUpdate();
  });

  // play → start per-frame rAF loop; pause/ended → stop it
  pmVideo.addEventListener('play', () => {
    if (pmPlayBtn) pmPlayBtn.textContent = '⏸';
    _pmLastSyncedF      = -1; // force full sync on first rAF frame
    _pmSyncDriftFrames  = 0;  // reset drift counter for this playback session
    _pmSyncDriftAlerted = false;
    _pmStartPlayRaf();
    _pmStartVideoFrameClock();
  });
  pmVideo.addEventListener('pause', () => {
    if (pmPlayBtn) pmPlayBtn.textContent = '▶';
    _pmStopPlayRaf();
    _pmStopVideoFrameClock({ clearPresented: false });
    _pmRememberVideoMediaTimeSec(Number(pmVideo.currentTime));
    _pmSyncFrame();
    if (_pmActiveEventIdx >= 0) _pmUpdateInspector(_pmActiveEventIdx, false);
  });
  pmVideo.addEventListener('ended', () => {
    if (pmPlayBtn) pmPlayBtn.textContent = '▶';
    _pmStopPlayRaf();
    _pmStopVideoFrameClock();
  });

  pmVideo.addEventListener('loadedmetadata', () => {
    _pmDurationSec = pmVideo.duration || 0;
    _pmPresentedMediaTimeSec = NaN;
    _pmRememberVideoMediaTimeSec(Number(pmVideo.currentTime));
    if (pmScrub) { pmScrub.max = Math.round(_pmDurationSec * (_pmFps || 24)); pmScrub.step = 1; }
    if (pmVideoHint) pmVideoHint.style.display = 'none';
    if (pmVideoFileInput) pmVideoFileInput.value = '';
    _pmSyncFrame();
    // Seek slightly off 0 to force Chrome to decode and display the first frame.
    // With preload="metadata" Chrome only buffers headers; without a seek the
    // video element shows black until the user interacts.
    if (pmVideo.duration > 0) pmVideo.currentTime = 0.001;

    // ── Auto-apply default sync from pull list (no user action needed) ────────
    if (!_pmSyncManuallySet && _pmEvents.length > 0) {
      const guessedTc = _pmGuessTcFromFilename(_pmVideoFile?.name || '');
      const nativeTcIsGuessOnly = !_pmCompanionMode && !!guessedTc && _pmNativeStartTc === guessedTc;
      const smartConf = nativeTcIsGuessOnly
        ? 0
        : _pmMaybeSmartSyncFromFileTc({ minConfidence: 60, focusSelection: true, silent: false });
      if (!smartConf) {
        _pmVideoZeroAbsF = _pmSeqBaseFrames;
        window.__pmUpdateSyncDisplay?.();
      }
    }
  });

  // Retry thumbnail capture when video becomes playable — handles the race where
  // the inspector rendered before the video was ready (readyState < 2 at select time).
  pmVideo.addEventListener('canplay', () => {
    const _cpKey = _pmCurrentProjectKey;
    if (_pmActiveEventIdx >= 0) {
      if (_pmCurrentProjectKey !== _cpKey) return;
      _pmBatchCaptureEventThumbs(_pmActiveEventIdx);
    }
    // Also capture for any selected-but-thumbnailless marker (companion path handles its own guard).
    if (_pmCurrentProjectKey !== _cpKey) return;
    if (_pmSelectedMarkerId) {
      const mk = _pmClipMarkers.find(m => m.id === _pmSelectedMarkerId);
      if (mk && !mk.thumb && !mk._thumbCapturing && !mk._thumbError && mk.recIn) {
        const evIdx = _pmLinkMap.get(mk.id) ?? -1;
        mk._thumbCapturing = true;
        _pmRenderInspector(evIdx);
        // seekFirst=false — never seek pmVideo in an automatic capture path
        _pmCaptureThumbnail(mk, false, () => {
          mk._thumbCapturing = false;
          _pmRenderInspector(evIdx);
          _pmRenderEventTable();
        });
      }
    }
  });

  // Drag-drop onto player area
  if (pmPlayerWrap) {
    pmPlayerWrap.addEventListener('dragover', (e) => { e.preventDefault(); pmPlayerWrap.classList.add('pm-drag-over'); });
    pmPlayerWrap.addEventListener('dragleave', () => pmPlayerWrap.classList.remove('pm-drag-over'));
    pmPlayerWrap.addEventListener('dragend',   () => pmPlayerWrap.classList.remove('pm-drag-over'));
    pmPlayerWrap.addEventListener('drop', async (e) => {
      e.preventDefault();
      pmPlayerWrap.classList.remove('pm-drag-over');
      const item = e.dataTransfer?.items?.[0];
      const f    = e.dataTransfer?.files?.[0];
      const isVideo = f && (f.type.startsWith('video/') || /\.(mov|mp4|mxf|avi|r3d|mts|m2t)$/i.test(f.name));
      if (isVideo) {
        let handle = null;
        if (item?.getAsFileSystemHandle) {
          try { const h = await item.getAsFileSystemHandle(); if (h?.kind === 'file') handle = h; } catch {}
        }
        await _pmLoadVideo(f, handle);
      } else {
        // Treat as timeline import (EDL / FCPXML / etc.)
        await _pmHandleDroppedTimeline(e.dataTransfer);
      }
    });
  }

  const _pmTokenizedCompanionUrl = (url) => {
    const token = window.__pfxCompanionHttpToken || window.__pfxCompanionHttp?.token || '';
    if (!url || !token || /[?&]token=/.test(url)) return url;
    return `${url}${url.includes('?') ? '&' : '?'}token=${encodeURIComponent(token)}`;
  };

  const _pmSetVideoSource = (videoEl, url) => {
    if (!videoEl) return;
    const src = String(url || '');
    if (/^https?:\/\//i.test(src)) {
      videoEl.crossOrigin = 'anonymous';
    } else {
      try { videoEl.removeAttribute('crossorigin'); } catch {}
      try { videoEl.crossOrigin = null; } catch {}
    }
    videoEl.src = src;
  };

  const _pmStartCompanionProxyPreview = async ({ captureId, proxyId, filePath = '', label = 'media' } = {}) => {
    if (!captureId || !proxyId || !pmVideo) return false;
    let ownId = captureId;
    let buildId = proxyId;
    _pmNativeCanPlay = false;
    try { pmVideo.pause(); } catch {}
    try { pmVideo.removeAttribute('src'); pmVideo.load(); } catch {}
    if (pmVideoHint) {
      pmVideoHint.style.display = '';
      pmVideoHint.style.backgroundImage = '';
      _pmSetVideoStatus('Building preview... this may take a minute');
    }

    if (filePath) {
      try {
        const reopenResp = await nativeOpenFile(filePath);
        const reopened = reopenResp?.data || {};
        if ((reopenResp?.status || 'ok') !== 'error' && reopened.assetId) {
          ownId = reopened.assetId;
          buildId = reopened.assetId;
          _pmNativeAssetId = ownId;
          if (reopened.fps) _pmNativeFps = reopened.fps;
          if (reopened.startTimecode) _pmNativeStartTc = reopened.startTimecode;
          _pmCompanionMode = true;
        }
      } catch {}
    }

    (async () => {
      try {
        let r = null;
        try { r = await withTimeout(sharedMediaGetFrame(ownId, 0, { quality: 'half', width: 640, height: 360 }), 6000, 'placeholder frame'); } catch {}
        if (!r) {
          r = await withTimeout(nativeGrabThumbnailAtTimecode(ownId, '00:00:00:00', {
            width: 640, height: 360, format: 'jpg', mode: 'fast', seekMode: 'sequence_fallback',
          }), 8000, 'placeholder thumb');
        }
        if (_pmNativeAssetId !== ownId || r?.status === 'error' || !pmVideoHint) return;
        let src = r?.data?.dataUrl || r?.data?.url;
        if (!src) return;
        if (src.startsWith('http')) {
          try {
            const resp = await fetch(_pmTokenizedCompanionUrl(src), {
              headers: window.__pfxCompanionHttpToken ? { 'X-PFX-Token': window.__pfxCompanionHttpToken } : {},
            });
            if (!resp.ok) return;
            const blob = await resp.blob();
            src = await new Promise((res, rej) => {
              const rd = new FileReader();
              rd.onload = () => res(rd.result);
              rd.onerror = rej;
              rd.readAsDataURL(blob);
            });
          } catch { return; }
        }
        if (_pmNativeAssetId !== ownId || !pmVideoHint) return;
        pmVideoHint.style.backgroundImage = `url("${src}")`;
        pmVideoHint.style.backgroundSize = 'contain';
        pmVideoHint.style.backgroundRepeat = 'no-repeat';
        pmVideoHint.style.backgroundPosition = 'center';
      } catch {}
    })();

    try {
      const proxyResp = await nativeBuildMediaProxy(buildId);
      if (_pmNativeAssetId !== ownId || proxyResp?.status === 'error') return false;
      const { sessionId, progressUrl, streamUrl } = proxyResp?.data || {};
      if (!sessionId || !progressUrl || !streamUrl) return false;
      let attempts = 0, lastPct = -1, staleTicks = 0;
      while (_pmNativeAssetId === ownId && attempts < 600) {
        attempts++;
        await new Promise(r => setTimeout(r, 1000));
        let prog;
        try {
          const res = await fetch(_pmTokenizedCompanionUrl(progressUrl), {
            headers: window.__pfxCompanionHttpToken ? { 'X-PFX-Token': window.__pfxCompanionHttpToken } : {},
          });
          prog = res.ok ? await res.json() : null;
        } catch { continue; }
        if (!prog) continue;
        if (_pmNativeAssetId === ownId) _pmProxyBarShow(prog.pct || 0);
        if (prog.pct === lastPct) { if (++staleTicks >= 60) break; } else { staleTicks = 0; lastPct = prog.pct; }
        if (prog.done && !prog.error) {
          if (_pmNativeAssetId !== ownId || !pmVideo) return false;
          _pmNativeCanPlay = true;
          _pmSetVideoSource(pmVideo, _pmTokenizedCompanionUrl(streamUrl));
          pmVideo.load();
          _pmForcePreviewVisible('proxy-ready');
          _pmProxyBarHide();
          if (pmVideoHint) {
            pmVideoHint.style.backgroundImage = '';
            pmVideoHint.style.display = 'none';
          }
          return true;
        }
        if (prog.done && prog.error) {
          _pmProxyBarHide();
          if (pmVideoHint && _pmNativeAssetId === ownId) _pmSetProxyError(prog.error);
          return false;
        }
      }
      _pmProxyBarHide();
      if (_pmNativeAssetId === ownId) _pmSetVideoStatus(`${label} preview took too long - try re-opening the file`);
    } catch (err) {
      console.debug('[PM] companion proxy preview failed:', err?.message);
    }
    return false;
  };

  // Browse button — uses companion native dialog when available (gives full path for ProRes support),
  // falls back to File System Access API or classic file input.
  const _pmBrowseVideo = async () => {
    // eslint-disable-next-line no-use-before-define
    // ── Companion path (ProRes-capable) ─────────────────────────────────────────
    // Reset companion state first — if the user cancels or companion fails we
    // fall through to the browser picker with a clean slate.
    _pmCompanionMode = false;
    _pmNativeAssetId = null;
    _pmNativeFps     = null;
    _pmNativeStartTc = null;
    _pmNativeCanPlay = false;
    try {
      const ping = await nativeHelperPing();
      if (ping?.data?.httpToken) try { window.__pfxCompanionHttpToken = ping.data.httpToken; } catch {}
      if (ping?.data?.ready) {
        const pickResp = await _pmWithPreviewSuppressed(
          () => nativePickMediaFile('Select media file for Pull Prep'),
          'media-picker'
        );
        if (pickResp?.data?.filePath) {
          const filePath = pickResp.data.filePath;
          console.log('[PM] openFile →', filePath);
          // Use shared media runtime — proper backend selection (ProRes VideoToolbox on macOS)
          const openResp = await sharedMediaOpen(filePath).catch(async (e) => {
            // Fall back to legacy openFile if shared runtime not yet available
            console.debug('[PM] sharedMediaOpen falling back to openFile:', e?.message);
            return nativeOpenFile(filePath);
          });
          const openStatus = openResp?.status ?? (openResp?.ok !== false ? 'ok' : 'error');
          console.log('[PM] mediaOpen result:', openStatus, 'sessionId:', openResp?.data?.sessionId ?? openResp?.data?.assetId);
          if (openStatus === 'error') {
            const errMsg = openResp?.error?.userMessage || openResp?.error?.message || 'Companion could not open file';
            console.warn('[PM] mediaOpen error:', errMsg, openResp?.error?.code);
            if (pmVideoHint) {
              pmVideoHint.style.display = '';
              _pmSetVideoStatus(`⚠ Companion error: ${errMsg}`);
            }
            return;
          }
          if (openResp?.data?.assetId || openResp?.data?.sessionId) {
            const d = openResp.data;
            console.log('[PM] mediaOpen codec:', d.codec, 'canPlay:', d.canPlay, 'backend:', d.backend, 'fps:', d.fps);
            _pmNativeAssetId = d.sessionId || d.assetId;
            _pmNativeFps     = d.fps || null;
            _pmNativeStartTc = d.startTimecode || null;
            _pmCompanionMode = true;
            _pmNativeCanPlay = !!(d.canPlay);

            // Release previous playable-media state (revokes blob URL, cancels proxy).
            if (pmVideo) releasePlayableVideo(pmVideo);

            const fname = filePath.split(/[/\\]/).pop() || 'media';
            _pmVideoFile = { name: fname, _nativePath: filePath };
            localStorage.setItem(_lsKey('lastVideoName.v1'), fname);
            try { localStorage.setItem(_lsKey('lastVideoNativePath.v1'), filePath); } catch {}
            try { window.__PFX_PULLPREP_MEDIA = { proxyVideoNativePath: filePath, proxyVideoName: fname }; } catch {}
            _pmForcePreviewVisible('media-open');

            if (d.canPlay && d.streamUrl && pmVideo) {
              // Browser-decodable codec (H.264, VP9, ProRes on macOS, …) — stream
              // via companion HTTP server so the browser element works for scrubbing.
              // <video src> cannot send custom headers, so append the auth token as
              // a query param (?token=…) — the companion HTTP server accepts both forms.
              const _httpTok = window.__pfxCompanionHttpToken || '';
              const _streamWithToken = _httpTok
                ? `${d.streamUrl}?token=${encodeURIComponent(_httpTok)}`
                : d.streamUrl;
              _pmSetVideoSource(pmVideo, _streamWithToken);
              pmVideo.load();
              if (pmVideoHint) {
                pmVideoHint.style.display = 'none';
              }
              const proxyAssetId = d.sessionId || d.assetId;  // capture before async boundary

              // Black-frame guard: even when canPlay=true, some codec variants
              // (ProRes profile, 10-bit H.264, HDR) load without error but render
              // only black frames.  Wait for metadata, seek to 5% of duration (avoids
              // pre-roll black), sample luma, and proxy if still black.
              (async () => {
                // Wait for loadedmetadata so we have duration + dimensions
                if (pmVideo.readyState < 1) {
                  await new Promise(res => pmVideo.addEventListener('loadedmetadata', res, { once: true }));
                }
                if (_pmNativeAssetId !== proxyAssetId || !pmVideo || !pmVideoHint) return;
                if (pmVideo.videoWidth === 0 || pmVideo.videoHeight === 0) {
                  console.debug('[PM] canPlay stream has no decoded dimensions, routing to proxy:', d.codec);
                  await _pmStartCompanionProxyPreview({
                    captureId: proxyAssetId,
                    proxyId: d.assetId || proxyAssetId,
                    filePath,
                    label: fname,
                  });
                  return;
                }

                // Sample luma at 5%, 25%, and 50% of duration.
                // All three must be black (<8 avg luma) before triggering a proxy build —
                // a single dark frame could be legitimate content (night scene, fade-in).
                const _dur = pmVideo.duration || 10;
                const _checkPoints = [0.05, 0.25, 0.50].map(f => Math.max(0.5, _dur * f));
                let _allBlack = true;
                const _bfc = document.createElement('canvas');
                const _bfw = Math.min(pmVideo.videoWidth || 320, 320);
                const _bfh = Math.round(_bfw * (pmVideo.videoHeight || 180) / Math.max(1, pmVideo.videoWidth || 320));
                _bfc.width = _bfw; _bfc.height = _bfh || 180;
                const _bfx = _bfc.getContext('2d');
                for (const _checkAt of _checkPoints) {
                  pmVideo.currentTime = _checkAt;
                  await new Promise(res => pmVideo.addEventListener('seeked', res, { once: true }));
                  await new Promise(r => setTimeout(r, 300));
                  if (_pmNativeAssetId !== proxyAssetId || !pmVideo || !pmVideoHint) return;
                  try {
                    _bfx.drawImage(pmVideo, 0, 0, _bfc.width, _bfc.height);
                    const _bfd = _bfx.getImageData(0, 0, _bfc.width, _bfc.height).data;
                    let _bfl = 0;
                    for (let _i = 0; _i < _bfd.length; _i += 4)
                      _bfl += 0.299 * _bfd[_i] + 0.587 * _bfd[_i + 1] + 0.114 * _bfd[_i + 2];
                    if (_bfl / (_bfd.length / 4) >= 8) { _allBlack = false; break; }
                  } catch (e) {
                    console.debug('[PM] black-frame canvas check failed (will not proxy):', e?.message);
                    return; // canvas error = unknown state, don't proxy
                  }
                }
                if (!_allBlack) return; // at least one sample had real content
                // Black frame — the codec rendered but Chrome can't show it.
                // Fall through to companion proxy build (same as canPlay=false path).
                console.debug('[PM] canPlay codec produced black frames, routing to proxy:', d.codec);
                _pmNativeCanPlay = false;
                pmVideo.removeAttribute('src'); pmVideo.load();
                if (pmVideoHint) {
                  pmVideoHint.style.display = '';
                  pmVideoHint.style.backgroundImage = '';
                  _pmSetVideoStatus('Building preview… this may take a minute');
                }
                // Grab first frame for preview while proxy builds
                (async () => {
                  try {
                    let r = null;
                    try { r = await withTimeout(sharedMediaGetFrame(proxyAssetId, 0, { quality: 'half', width: 640, height: 360 }), 6000, 'placeholder frame'); } catch {}
                    if (!r) r = await withTimeout(nativeGrabThumbnailAtTimecode(proxyAssetId, '00:00:00:00', { width: 640, height: 360, format: 'jpg', mode: 'fast', seekMode: 'sequence_fallback' }), 8000, 'placeholder thumb');
                    if (_pmNativeAssetId !== proxyAssetId || r?.status === 'error' || !pmVideoHint) return;
                    let src = r?.data?.dataUrl || r?.data?.url;
                    if (!src) return;
                    if (src.startsWith('http')) {
                      try { const resp = await _pmCompanionFetch(src); if (!resp.ok) return; const blob = await resp.blob(); src = await new Promise((res, rej) => { const rd = new FileReader(); rd.onload = () => res(rd.result); rd.onerror = rej; rd.readAsDataURL(blob); }); } catch { return; }
                    }
                    if (_pmNativeAssetId !== proxyAssetId || !pmVideoHint) return;
                    pmVideoHint.style.backgroundImage = `url("${src}")`; pmVideoHint.style.backgroundSize = 'contain'; pmVideoHint.style.backgroundRepeat = 'no-repeat'; pmVideoHint.style.backgroundPosition = 'center';
                  } catch {}
                })();
                // Build proxy
                (async () => {
                  try {
                    const proxyResp = await nativeBuildMediaProxy(d.assetId);
                    if (_pmNativeAssetId !== proxyAssetId || proxyResp?.status === 'error') return;
                    const { sessionId, progressUrl, streamUrl: proxyUrl } = proxyResp?.data || {};
                    if (!sessionId || !progressUrl || !proxyUrl) return;
                    let attempts = 0, lastPct = -1, staleTicks = 0;
                    while (_pmNativeAssetId === proxyAssetId && attempts < 600) {
                      attempts++;
                      await new Promise(r => setTimeout(r, 1000));
                      let prog; try { const res = await fetch(progressUrl, { headers: { 'X-PFX-Token': window.__pfxCompanionHttpToken || '' } }); prog = res.ok ? await res.json() : null; } catch { continue; }
                      if (!prog) continue;
                      if (_pmNativeAssetId === proxyAssetId) _pmProxyBarShow(prog.pct || 0);
                      if (prog.pct === lastPct) { if (++staleTicks >= 60) break; } else { staleTicks = 0; lastPct = prog.pct; }
                      if (prog.done && !prog.error) {
                        if (_pmNativeAssetId !== proxyAssetId || !pmVideo) return;
                        const _ptok = window.__pfxCompanionHttpToken || '';
                        _pmNativeCanPlay = true; _pmSetVideoSource(pmVideo, _ptok ? `${proxyUrl}?token=${encodeURIComponent(_ptok)}` : proxyUrl); pmVideo.load();
                        _pmProxyBarHide();
                        if (pmVideoHint) { pmVideoHint.style.backgroundImage = ''; pmVideoHint.style.display = 'none'; }
                        return;
                      }
                      if (prog.done && prog.error) { _pmProxyBarHide(); if (pmVideoHint && _pmNativeAssetId === proxyAssetId) _pmSetProxyError(prog.error); return; }
                    }
                    _pmProxyBarHide();
                    if (_pmNativeAssetId === proxyAssetId) _pmSetVideoStatus('Preview took too long — try again by re-opening the file');
                  } catch (err) { console.debug('[PM] black-frame proxy:', err?.message); }
                })();
              })();
              // If Chrome errors on the stream URL for a browser-decodable codec,
              // do NOT build a proxy (H.264→H.264 is pointless).
              // Strategy: re-open the file via companion to get a fresh assetId +
              // fresh token, then retry.  This handles 403 (stale token) and 404
              // (evicted assetId) without any user interaction.
              pmVideo.addEventListener('error', () => {
                if (!pmVideo || !pmVideoHint) return;
                if (d.canPlay) {
                  console.debug('[PM] streamUrl error on canPlay codec — re-opening for fresh URL:', d.codec);
                  (async () => {
                    try {
                      // Get fresh token + fresh assetId by re-opening the same file.
                      // Handles both 403 (stale/missing token) and 404 (evicted assetId).
                      const pingR = await nativeHelperPing().catch(() => null);
                      if (pingR?.data?.httpToken) window.__pfxCompanionHttpToken = pingR.data.httpToken;
                      if (_pmNativeAssetId !== proxyAssetId || !pmVideo) return;
                      const reopen = await sharedMediaOpen(filePath).catch(() => null);
                      const rd = reopen?.data;
                      if (!rd?.canPlay || !rd?.streamUrl || _pmNativeAssetId !== proxyAssetId || !pmVideo) {
                        throw new Error('reopen failed');
                      }
                      _pmNativeAssetId = rd.sessionId || rd.assetId;
                      const _tok2 = window.__pfxCompanionHttpToken || '';
                      _pmSetVideoSource(pmVideo, _tok2
                        ? `${rd.streamUrl}?token=${encodeURIComponent(_tok2)}`
                        : rd.streamUrl);
                      pmVideo.load();
                      pmVideo.addEventListener('error', () => {
                        if (!pmVideo || !pmVideoHint) return;
                        _pmNativeCanPlay = false;
                        pmVideo.removeAttribute('src'); pmVideo.load();
                        pmVideoHint.style.display = '';
                        _pmSetVideoStatus(`${fname}  — stream failed, try re-opening the file`);
                      }, { once: true });
                    } catch {
                      if (pmVideoHint) {
                        pmVideoHint.style.display = '';
                        _pmSetVideoStatus(`${fname}  — stream failed, try re-opening the file`);
                      }
                    }
                  })();
                  return;
                }
                console.debug('[PM] streamUrl not decodable, routing to companion proxy', d.codec);
                _pmNativeCanPlay = false;
                pmVideo.removeAttribute('src'); pmVideo.load();
                pmVideoHint.style.display = '';
                pmVideoHint.style.backgroundImage = '';
                _pmSetVideoStatus('Building preview… this may take a minute');
                // Preview frame
                (async () => {
                  try {
                    let r = null;
                    try { r = await withTimeout(sharedMediaGetFrame(proxyAssetId, 0, { quality: 'half', width: 640, height: 360 }), 6000, 'placeholder frame'); } catch {}
                    if (!r) r = await withTimeout(nativeGrabThumbnailAtTimecode(proxyAssetId, '00:00:00:00', { width: 640, height: 360, format: 'jpg', mode: 'fast', seekMode: 'sequence_fallback' }), 8000, 'placeholder thumb');
                    if (_pmNativeAssetId !== proxyAssetId || r?.status === 'error' || !pmVideoHint) return;
                    let src = r?.data?.dataUrl || r?.data?.url;
                    if (!src) return;
                    if (src.startsWith('http')) { try { const resp = await _pmCompanionFetch(src); if (!resp.ok) return; if (_pmNativeAssetId !== proxyAssetId) return; const blob = await resp.blob(); if (_pmNativeAssetId !== proxyAssetId) return; src = await new Promise((res, rej) => { const rd = new FileReader(); rd.onload = () => res(rd.result); rd.onerror = rej; rd.readAsDataURL(blob); }); } catch { return; } }
                    if (_pmNativeAssetId !== proxyAssetId || !pmVideoHint) return;
                    pmVideoHint.style.backgroundImage = `url("${src}")`; pmVideoHint.style.backgroundSize = 'contain'; pmVideoHint.style.backgroundRepeat = 'no-repeat'; pmVideoHint.style.backgroundPosition = 'center';
                  } catch (err) { console.debug('[PM] preview frame (non-fatal)', err?.message); }
                })();
                // Proxy build — same as non-canPlay path
                (async () => {
                  try {
                    const proxyResp = await nativeBuildMediaProxy(proxyAssetId);
                    if (_pmNativeAssetId !== proxyAssetId || proxyResp?.status === 'error') return;
                    const { sessionId, progressUrl, streamUrl: proxyUrl } = proxyResp?.data || {};
                    if (!sessionId || !progressUrl || !proxyUrl) return;
                    let attempts = 0, lastPct = -1, staleTicks = 0;
                    while (_pmNativeAssetId === proxyAssetId && attempts < 600) {
                      attempts++;
                      await new Promise(r => setTimeout(r, 1000));
                      let prog; try { const res = await fetch(progressUrl, { headers: { 'X-PFX-Token': window.__pfxCompanionHttpToken || '' } }); prog = res.ok ? await res.json() : null; } catch { continue; }
                      if (!prog) continue;
                      if (_pmNativeAssetId === proxyAssetId) _pmProxyBarShow(prog.pct || 0);
                      if (prog.pct === lastPct) { if (++staleTicks >= 60) break; } else { staleTicks = 0; lastPct = prog.pct; }
                      if (prog.done && !prog.error) {
                        if (_pmNativeAssetId !== proxyAssetId || !pmVideo) return;
                        const _ptok = window.__pfxCompanionHttpToken || '';
                        _pmNativeCanPlay = true; _pmSetVideoSource(pmVideo, _ptok ? `${proxyUrl}?token=${encodeURIComponent(_ptok)}` : proxyUrl); pmVideo.load();
                        _pmProxyBarHide();
                        if (pmVideoHint) { pmVideoHint.style.backgroundImage = ''; pmVideoHint.style.display = 'none'; }
                        return;
                      }
                      if (prog.error) { if (pmVideoHint && _pmNativeAssetId === proxyAssetId) _pmSetProxyError(prog.error); return; }
                    }
                    _pmProxyBarHide();
                    if (_pmNativeAssetId === proxyAssetId) _pmSetVideoStatus('Preview took too long — try again by re-opening the file');
                  } catch (err) { console.debug('[PM] companion proxy (non-fatal)', err?.message); }
                })();
              }, { once: true });
            } else if (d.canPlay) {
              // Browser-decodable codec (H.264, VP9…) but companion returned no
              // streamUrl — the HTTP file-registry failed to register the asset.
              // Do NOT build a proxy (H.264 → H.264 transcode is pointless).
              // Instead fall back to loading the file via the browser's File API
              // so the user can still scrub without a pointless re-encode.
              console.debug('[PM] canPlay codec but no streamUrl — falling back to File API:', d.codec);
              const fallbackFile = Object.assign(
                new File([], fname, { type: 'video/mp4' }),
                { _nativePath: filePath }
              );
              await _pmLoadVideo(fallbackFile, null);
              // Re-apply companion state so thumbnail capture still works
              _pmNativeAssetId  = d.sessionId || d.assetId;
              _pmNativeFps      = d.fps || null;
              _pmNativeStartTc  = d.startTimecode || null;
              _pmNativeCanPlay  = false;
              _pmCompanionMode  = true;
            } else {
              // Non-browser-decodable codec (ProRes, MXF, DNxHD, ARRIRAW, …):
              // Step 1 — show first frame immediately as a static preview so the
              //           player area is not black while the proxy builds.
              // Step 2 — ask the companion to transcode a low-res H.264 proxy via
              //           ffmpeg in the background.  Poll /progress until done,
              //           then load the proxy into the <video> element for full scrubbing.
              if (pmVideo) { pmVideo.removeAttribute('src'); pmVideo.load(); }
              if (pmVideoHint) {
                pmVideoHint.style.display = '';
                pmVideoHint.style.backgroundImage = '';
                _pmSetVideoStatus('Building preview… this may take a minute');
              }

              const captureId = d.sessionId || d.assetId;  // sharedMedia / thumbnail ops
              const proxyId   = d.assetId;                  // nativeBuildMediaProxy requires native assetId

              // ── Step 1: grab first frame via shared runtime (ProRes direct) ─
              (async () => {
                try {
                  // Try shared media runtime frame first (no proxy required for ProRes)
                  let r = null;
                  try {
                    const fr = await withTimeout(sharedMediaGetFrame(captureId, 0, { quality: 'half', width: 640, height: 360 }), 6000, 'placeholder frame');
                    if (fr?.data?.dataUrl || fr?.data?.previewImagePath) r = fr;
                  } catch {}
                  // Fallback to legacy thumbnail grab
                  if (!r) {
                    r = await withTimeout(nativeGrabThumbnailAtTimecode(captureId, '00:00:00:00', {
                      width: 640, height: 360, format: 'jpg', mode: 'fast',
                      seekMode: 'sequence_fallback',
                    }), 8000, 'placeholder thumb');
                  }
                  console.log('[PM] grabFirstFrame →', r?.status,
                    r?.data?.dataUrl?.length ? 'dataUrl ok' : r?.data?.url ? 'url ok' : 'no src',
                    r?.error?.message || '');
                  if (_pmNativeAssetId !== captureId || r?.status === 'error' || !pmVideoHint) return;
                  let src = r?.data?.dataUrl || r?.data?.url;
                  if (!src) return;
                  if (src.startsWith('http')) {
                    try {
                      const resp = await _pmCompanionFetch(src);
                      if (!resp.ok) return;
                      const blob = await resp.blob();
                      src = await new Promise((res, rej) => {
                        const rd = new FileReader(); rd.onload = () => res(rd.result); rd.onerror = rej;
                        rd.readAsDataURL(blob);
                      });
                    } catch { return; }
                  }
                  if (_pmNativeAssetId !== captureId || !pmVideoHint) return;
                  pmVideoHint.style.backgroundImage    = `url("${src}")`;
                  pmVideoHint.style.backgroundSize     = 'contain';
                  pmVideoHint.style.backgroundRepeat   = 'no-repeat';
                  pmVideoHint.style.backgroundPosition = 'center';
                } catch (err) { console.debug('[PM] grabFirstFrame (non-fatal)', err?.message); }
              })();

              // ── Step 2: build H.264 proxy and load it when ready ────────────
              (async () => {
                try {
                  const proxyResp = await nativeBuildMediaProxy(proxyId);
                  console.log('[PM] buildMediaProxy →', proxyResp?.status, proxyResp?.data?.sessionId);
                  if (_pmNativeAssetId !== captureId || proxyResp?.status === 'error') return;
                  const { sessionId, progressUrl, streamUrl } = proxyResp?.data || {};
                  if (!sessionId || !progressUrl || !streamUrl) return;

                  // Poll /progress until done; break early if progress stalls for 60s
                  let attempts = 0, lastPct = -1, staleTicks = 0;
                  while (_pmNativeAssetId === captureId && attempts < 600) {
                    attempts++;
                    await new Promise(r => setTimeout(r, 1000));
                    let prog;
                    try {
                      const res = await fetch(progressUrl, { headers: { 'X-PFX-Token': window.__pfxCompanionHttpToken || '' } });
                      prog = res.ok ? await res.json() : null;
                    } catch { continue; }
                    if (!prog) continue;
                    console.log('[PM] proxy progress', prog.pct + '%', prog.stage);
                    if (_pmNativeAssetId === captureId) _pmProxyBarShow(prog.pct || 0);
                    if (prog.pct === lastPct) { if (++staleTicks >= 60) break; } else { staleTicks = 0; lastPct = prog.pct; }
                    if (prog.done && !prog.error) {
                      // Proxy ready — load into video element
                      if (_pmNativeAssetId !== captureId || !pmVideo) return;
                      const _ptok = window.__pfxCompanionHttpToken || '';
                      _pmNativeCanPlay = true;
                      _pmSetVideoSource(pmVideo, _ptok ? `${streamUrl}?token=${encodeURIComponent(_ptok)}` : streamUrl);
                      pmVideo.load();
                      _pmProxyBarHide();
                      if (pmVideoHint) {
                        pmVideoHint.style.backgroundImage = '';
                        pmVideoHint.style.display = 'none';
                      }
                      console.log('[PM] proxy ready, loading', streamUrl);
                      return;
                    }
                    if (prog.done && prog.error) {
                      console.warn('[PM] proxy build failed:', prog.error);
                      _pmProxyBarHide();
                      if (pmVideoHint && _pmNativeAssetId === captureId)
                        _pmSetProxyError(prog.error);
                      return;
                    }
                  }
                  _pmProxyBarHide();
                  if (_pmNativeAssetId === captureId) _pmSetVideoStatus('Preview took too long — try again by re-opening the file');
                } catch (err) { console.warn('[PM] buildMediaProxy exception', err); }
              })();
            }

            // Keep embedded/file TC separate from sequence sync. The SYNC controls map
            // the video to timeline REC, while _pmNativeStartTc drives the on-video TC overlay.
            window.__pmUpdateSyncDisplay?.();
            _pmPushTimelineData();
            return;
          }
        }
        // Companion pick was cancelled (CANCELLED code) — stop, don't show browser dialog
        return;
      }
    } catch (e) {
      // Companion not installed / unavailable — fall through to browser file picker
      _pmCompanionMode = false;
      _pmNativeAssetId = null;
      _pmNativeCanPlay = false;
    }

    // ── Browser fallback (File System Access API or classic input) ────────────
    if (window.showOpenFilePicker) {
      try {
        const [handle] = await _pmWithPreviewSuppressed(() => window.showOpenFilePicker({
          types: [{ description: 'Video', accept: { 'video/*': ['.mov', '.mp4', '.mxf', '.avi', '.r3d', '.mts', '.m2t'] } }],
          multiple: false
        }), 'browser-video-picker');
        const file = await handle.getFile();
        _pmCompanionMode = false;
        _pmNativeAssetId = null;
        _pmNativeCanPlay = false;
        await _pmLoadVideo(file, handle);
      } catch(e) { if (!(e instanceof DOMException)) console.warn('[PM] open picker:', e); }
    } else if (pmVideoFileInput) {
      _pmClickFileInputWithPreviewGuard(pmVideoFileInput);
    }
  };
  if (pmVideoBrowseBtn) pmVideoBrowseBtn.addEventListener('click', _pmBrowseVideo);
  if (pmVideoImportBtn) pmVideoImportBtn.addEventListener('click', _pmBrowseVideo);

  _pmBrowseVideoFn = _pmBrowseVideo; // expose for _pmShowRestoreBtn
  if (pmVideoFileInput) {
    pmVideoFileInput.addEventListener('change', async () => {
      const f = pmVideoFileInput.files?.[0];
      if (f) await _pmLoadVideo(f, null);
    });
  }

  // Try to restore the last loaded video from IndexedDB handle
  _pmTryRestoreVideo();
}

async function _pmTryRestoreVideo() {
  // Capture current project key — if the project changes while we await, abort.
  const restoreKey = _pmCurrentProjectKey;

  // No project context yet — nothing to restore.
  if (!_pmCurrentProjectKey) return;

  const handle = await _pmIdbGetHandle(_pmIdbProjectKey());
  if (_pmCurrentProjectKey !== restoreKey) return; // project changed while awaiting IDB

  // Video name saved per-project (set in _pmLoadVideo). Fall back to the media
  // descriptor restored from the project file when localStorage has no entry.
  const savedName = localStorage.getItem(_lsKey('lastVideoName.v1'))
    || window.__PFX_PULLPREP_MEDIA?.proxyVideoName || handle?.name || '';

  // ── Ensure HTTP token is cached before setting video.src ───────────────────
  // At startup the token may not yet be in window.__pfxCompanionHttpToken.
  // A quick ping grabs it so the /file/{id} stream request is authenticated.
  if (!window.__pfxCompanionHttpToken) {
    try {
      const pingR = await nativeHelperPing().catch(() => null);
      if (pingR?.data?.httpToken) window.__pfxCompanionHttpToken = pingR.data.httpToken;
    } catch {}
  }

  // ── Try companion auto-restore first (no user gesture needed) ──────────────
  let nativePath = localStorage.getItem(_lsKey('lastVideoNativePath.v1')) || '';
  if (!nativePath && window.__PFX_PULLPREP_MEDIA?.proxyVideoNativePath) {
    // Project file carried the proxy path but the per-project localStorage key
    // wasn't present (per-tab load / fresh session). Adopt it and re-seed the
    // key so subsequent restores find it via the normal path.
    nativePath = window.__PFX_PULLPREP_MEDIA.proxyVideoNativePath;
    try { localStorage.setItem(_lsKey('lastVideoNativePath.v1'), nativePath); } catch {}
    if (savedName) { try { localStorage.setItem(_lsKey('lastVideoName.v1'), savedName); } catch {} }
  }
  if (nativePath) {
    try {
      const openResp = await sharedMediaOpen(nativePath).catch(() => null);
      if (_pmCurrentProjectKey !== restoreKey) return;
      const d = openResp?.data;
      if (d && (d.canPlay || d.sessionId || d.assetId)) {
        const fname = nativePath.split(/[/\\]/).pop() || savedName || 'media';
        _pmNativeAssetId  = d.sessionId || d.assetId;
        _pmNativeFps      = d.fps || null;
        _pmNativeStartTc  = d.startTimecode || null;
        _pmNativeCanPlay  = !!(d.canPlay);
        _pmCompanionMode  = true;
        _pmVideoFile      = { name: fname, _nativePath: nativePath };
        _pmForcePreviewVisible('restore-video');
        if (pmVideo) pmVideo.style.display = '';
        if (pmVideo) pmVideo.style.visibility = '';
        if (pmVideoHint) pmVideoHint.style.display = 'none';
        if (d.canPlay && d.streamUrl && pmVideo) {
          releasePlayableVideo(pmVideo);
          const _rt = window.__pfxCompanionHttpToken || '';
          _pmSetVideoSource(pmVideo, _rt ? `${d.streamUrl}?token=${encodeURIComponent(_rt)}` : d.streamUrl);
          pmVideo.load();
          let restoreProxyStarted = false;
          const restoreProxyIfBlind = async () => {
            if (restoreProxyStarted) return;
            await new Promise(r => setTimeout(r, 250));
            if (_pmCurrentProjectKey !== restoreKey || _pmNativeAssetId !== (d.sessionId || d.assetId) || !pmVideo) return;
            if (pmVideo.videoWidth > 0 && pmVideo.videoHeight > 0) return;
            restoreProxyStarted = true;
            console.debug('[PM] restored stream has no decoded dimensions, routing to proxy:', d.codec);
            if (typeof _pmStartCompanionProxyPreview === 'function') {
              await _pmStartCompanionProxyPreview({
                captureId: d.sessionId || d.assetId,
                proxyId: d.assetId || d.sessionId,
                filePath: nativePath,
                label: fname,
              });
            } else {
              console.debug('[PM] companion proxy preview unavailable in this context, skipping restore');
            }
          };
          pmVideo.addEventListener('loadedmetadata', restoreProxyIfBlind, { once: true });
          pmVideo.addEventListener('error', restoreProxyIfBlind, { once: true });
          setTimeout(restoreProxyIfBlind, 600);
        } else {
          // Not directly playable — trigger proxy via file object
          const fakeFile = Object.assign(
            new File([], fname, { type: 'video/quicktime' }),
            { _nativePath: nativePath }
          );
          await _pmLoadVideo(fakeFile, null);
          // Re-apply companion state — _pmLoadVideo resets it but companion session is still live
          _pmNativeAssetId  = d.sessionId || d.assetId;
          _pmNativeFps      = d.fps || null;
          _pmNativeStartTc  = d.startTimecode || null;
          _pmNativeCanPlay  = false;
          _pmCompanionMode  = true;
        }
        return;
      }
    } catch {}
    if (_pmCurrentProjectKey !== restoreKey) return;
  }

  // ── Try IDB FileSystemHandle ────────────────────────────────────────────────
  if (handle) {
    try {
      const perm = await handle.queryPermission({ mode: 'read' });
      if (perm === 'granted') {
        const file = await handle.getFile();
        if (_pmCurrentProjectKey !== restoreKey) return;
        await _pmLoadVideo(file, handle);
        return;
      }
    } catch {}
  }

  // ── Last resort: direct local-file streaming (no companion, no IDB handle) ──
  // When the companion media engine is unavailable/"Limited" AND there's no
  // granted FileSystemHandle, the restore would otherwise show nothing. Route a
  // path-only descriptor through the unified playable layer: browser-decodable
  // codecs (H.264/HEVC) stream via pfx-media:// straight from the main process,
  // and ProRes .mov routes to the native AVFoundation engine — neither needs the
  // companion. A plain object (no Blob) makes pfxAcquireObjectUrl fall through to
  // the pfx-media:// path; an empty File() would defeat that, so don't use one.
  if (nativePath) {
    if (_pmCurrentProjectKey !== restoreKey) return;
    const fname = savedName || nativePath.split(/[/\\]/).pop() || 'media';
    try { await _pmLoadVideo({ name: fname, _nativePath: nativePath }, null); } catch {}
  }
}

function _pmShowRestoreBtn(_name, _onclick) {
  // restore button removed — user drops or browses for proxy manually
}

function _pmSetVideoStatus(msg, asHtml = false) {
  const el = document.getElementById('pmVideoStatusMsg');
  if (!el) return;
  if (msg) {
    // asHtml=true only for hardcoded strings (e.g. the Settings link below).
    // Never pass user-controlled content (filenames, companion errors) with asHtml=true
    // — that would allow HTML injection from a maliciously named file.
    if (asHtml) el.innerHTML = msg;
    else el.textContent = msg;
    el.style.display = '';
  } else {
    el.innerHTML = '';
    el.style.display = 'none';
  }
}

// ── Native engine diagnostic badge ───────────────────────────────────────────

const _PM_BADGE_ID = 'pmNativeEngineBadge';

function _pmShowNativeEngineBadge(info, engine, container, smartClassification) {
  _pmRemoveNativeEngineBadge();
  const wrap = pmPlayerWrap || document.querySelector('.pm-player-wrap');
  if (!wrap) return;

  // ── Prefer Smart Engine classification when available ──────────────────────
  let engineLabel, codecLabel, modeLabel, containerLabel, fpsStr, statusStr;

  if (smartClassification?.engine) {
    const _ENGINE_DISPLAY = {
      avfoundation: 'Native macOS / AVFoundation',
      mpv:          'MPV',
      ffmpeg:       'FFmpeg Frame Server',
      imf:          'IMF Engine',
      imagesequence:'Image Sequence',
      resolve:      'DaVinci Resolve',
      proxy:        'Proxy (H.264)',
      browser:      'Chromium (fallback)',
    };
    const eId  = (smartClassification.engine || '').toLowerCase();
    engineLabel    = _ENGINE_DISPLAY[eId] || smartClassification.engine;
    codecLabel     = smartClassification.codec || info?.codec || '';
    if (!codecLabel && info?.codec) codecLabel = _PRORES_LABEL[(info.codec || '').toLowerCase()] || info.codec.toUpperCase();
    modeLabel      = smartClassification.mode || (eId === 'avfoundation' ? 'Direct Canvas' : eId === 'mpv' ? 'MPV Playback' : 'Frame Server');
    const fps      = smartClassification.fps || info?.fps;
    fpsStr         = fps ? ` · ${_pmFormatFps(fps)} fps` : '';
    containerLabel = (container || smartClassification.container || '').toUpperCase().replace('MOV', 'QuickTime .mov') || '—';
    statusStr      = smartClassification.routingReason || '';
  } else {
    // Fallback to legacy behaviour
    const codec  = (info?.codec || '').toLowerCase();
    codecLabel   = _PRORES_LABEL[codec] || (codec ? codec.toUpperCase() : 'ProRes');
    fpsStr       = info?.fps ? ` · ${_pmFormatFps(info.fps)} fps` : '';
    const engineName = typeof engine === 'string' ? engine : (engine?.constructor?.name || '');
    const resMpv = (engineName === 'MPVPlayerEngine');
    engineLabel  = resMpv ? 'MPV (fallback)' : 'Native macOS / AVFoundation';
    modeLabel    = resMpv ? 'MPV Window Playback' : 'Direct Canvas Playback';
    containerLabel = (container || 'QuickTime').toUpperCase().replace('MOV', 'QuickTime .mov');
    statusStr    = '';
  }

  // ── Build badge DOM ────────────────────────────────────────────────────────
  const badge = document.createElement('div');
  badge.id    = _PM_BADGE_ID;
  badge.style.cssText = [
    'position:absolute', 'top:8px', 'left:8px', 'z-index:10',
    'background:rgba(0,0,0,0.72)', 'backdrop-filter:blur(6px)',
    'border:1px solid rgba(255,255,255,0.14)', 'border-radius:6px',
    'padding:6px 10px', 'font:11px/1.5 monospace',
    'color:#e8e8e8', 'pointer-events:none', 'white-space:nowrap',
  ].join(';');

  // All values come from trusted codec maps, constructor names, or hardcoded strings — safe as innerHTML
  badge.innerHTML =
    `<span style="color:#9cf;font-weight:700">Engine:</span> ${engineLabel}<br>` +
    `<span style="color:#9cf;font-weight:700">Codec:</span> ${codecLabel}${fpsStr}<br>` +
    `<span style="color:#9cf;font-weight:700">Container:</span> ${containerLabel}<br>` +
    `<span style="color:#9cf;font-weight:700">Mode:</span> ${modeLabel}` +
    (statusStr ? `<br><span style="color:#9cf;font-weight:700">Route:</span> <span style="color:rgba(255,255,255,.55)">${statusStr}</span>` : '');

  wrap.style.position = wrap.style.position || 'relative';
  wrap.appendChild(badge);
}

function _pmRemoveNativeEngineBadge() {
  document.getElementById(_PM_BADGE_ID)?.remove();
}

// Codec → display name map (mirrors playbackRouter.js PRORES_LABELS)
const _PRORES_LABEL = {
  apch:   'Apple ProRes 422 HQ',
  apcn:   'Apple ProRes 422',
  apcs:   'Apple ProRes 422 LT',
  apco:   'Apple ProRes 422 Proxy',
  ap4h:   'Apple ProRes 4444',
  ap4x:   'Apple ProRes 4444 XQ',
  apns:   'Apple ProRes RAW',
  prores: 'Apple ProRes',
};

// Returns a plain-text label for a proxy error code (no HTML, safe for textContent / toast).
function _pmFriendlyProxyError(errorCode) {
  const map = {
    'ARRIRAW_NO_TOOL':       'ARRI RAW — install DaVinci Resolve (or ARRI Reference Tool) to enable preview',
    'ARRIRAW_DECODE_FAILED': 'Couldn\'t open this ARRI camera file — try re-opening it',
    'RED_NO_TOOL':           'RED RAW — install REDCINE-X PRO (or REDline) to enable preview',
    'RED_DECODE_FAILED':     'Couldn\'t open this RED camera file — try re-opening it',
    'SONY_NO_TOOL':          'Sony RAW — transcode to ProRes first using Sony RAW Viewer',
    'BRAW_NO_TOOL':          'Blackmagic RAW — install DaVinci Resolve (free) to enable preview',
  };
  return map[errorCode] || 'Preview not available — try re-opening the file';
}

const _LINK = 'color:#c0a8ff;text-decoration:underline;';

// Sets the video status area with a rich HTML message (download links where applicable).
// All strings below are hardcoded — no user data, safe to set as innerHTML.
function _pmSetProxyError(errorCode) {
  if (errorCode === 'ARRIRAW_NO_TOOL') {
    _pmSetVideoStatus(
      'ARRI RAW file — if <strong>DaVinci Resolve</strong> or <strong>Final Cut Pro</strong> ' +
      'is installed, restart the companion and try again. Otherwise ' +
      '<a href="https://www.arri.com/en/learn-help/learn-help-camera-system/tools/arri-reference-tool" ' +
      `target="_blank" rel="noopener" style="${_LINK}">download the free ARRI Reference Tool →</a>`,
      true
    );
  } else if (errorCode === 'ARRIRAW_DECODE_FAILED') {
    _pmSetVideoStatus('Couldn\'t open this ARRI camera file — try closing and re-opening it');
  } else if (errorCode === 'RED_NO_TOOL') {
    _pmSetVideoStatus(
      'RED RAW file — if <strong>REDCINE-X PRO</strong> is installed, restart the companion ' +
      'and try again. Otherwise ' +
      '<a href="https://www.red.com/download/redline" ' +
      `target="_blank" rel="noopener" style="${_LINK}">download the free REDline tool →</a>`,
      true
    );
  } else if (errorCode === 'RED_DECODE_FAILED') {
    _pmSetVideoStatus('Couldn\'t open this RED camera file — try closing and re-opening it');
  } else if (errorCode === 'SONY_NO_TOOL') {
    _pmSetVideoStatus(
      'Sony RAW file — transcode to ProRes first using ' +
      '<a href="https://www.sony.com/en/articles/sony-raw-viewer" ' +
      `target="_blank" rel="noopener" style="${_LINK}">Sony RAW Viewer</a>`,
      true
    );
  } else if (errorCode === 'BRAW_NO_TOOL') {
    _pmSetVideoStatus(
      'Blackmagic RAW file — if <strong>DaVinci Resolve</strong> is installed, restart ' +
      'the companion and try again. Otherwise ' +
      '<a href="https://www.blackmagicdesign.com/products/davinciresolve" ' +
      `target="_blank" rel="noopener" style="${_LINK}">download DaVinci Resolve (free) →</a>`,
      true
    );
  } else {
    _pmSetVideoStatus('Preview not available — try re-opening the file');
  }
}

function _makeProxyEta() {
  let _t0 = 0; // set on first non-zero pct; never reset by zeros
  return {
    update(pct) {
      if (pct <= 0) return ''; // skip zeros — do NOT reset _t0
      const now = Date.now();
      if (!_t0) { _t0 = now; return ''; } // first non-zero call: establish baseline, no estimate yet
      const elapsedSec = (now - _t0) / 1000;
      if (elapsedSec < 0.3) return ''; // need at least one poll cycle
      const rate = pct / elapsedSec; // avg %/sec since first non-zero call
      if (!rate || !isFinite(rate)) return '';
      const remSec = Math.max(0, (100 - pct) / rate);
      if (remSec < 5) return ''; // skip if nearly done
      if (remSec < 60) return `~${Math.ceil(remSec)}s left`;
      const m = Math.floor(remSec / 60);
      const s = Math.round(remSec % 60);
      return s > 0 ? `~${m}m ${s}s left` : `~${m}m left`;
    },
    reset() { _t0 = 0; },
  };
}

function _pmProxyElapsedTick() {
  const etaEl = document.getElementById('pmProxyEta');
  if (!etaEl || !_pmProxyTimerT0) return;
  if (etaEl.dataset.hasEta === 'true') return; // rate-based ETA is showing — don't overwrite
  const sec = Math.floor((Date.now() - _pmProxyTimerT0) / 1000);
  if (sec < 4) return; // wait 4 s before showing elapsed
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  etaEl.textContent = m > 0 ? `${m}m ${s}s elapsed` : `${s}s elapsed`;
  etaEl.style.display = 'block';
}

function _pmProxyBarShow(pct) {
  const wrap = document.getElementById('pmProxyProgress');
  const bar  = document.getElementById('pmProxyBar');
  const lbl  = document.getElementById('pmProxyLabel');
  if (!wrap) return;
  if (pmVideoHint) { pmVideoHint.style.display = ''; pmVideoHint.classList.add('pm-proxying'); }
  _pmSetVideoStatus(null);
  wrap.style.display = 'flex';

  // Start the elapsed-time ticker on first call
  if (!_pmProxyTimerT0) {
    _pmProxyTimerT0 = Date.now();
    _pmProxyTimerHandle = setInterval(_pmProxyElapsedTick, 1000);
  }

  if (bar) {
    const p = Math.min(100, Math.max(0, pct));
    if (p <= 0) {
      bar.classList.add('pm-proxy-indeterminate');
      bar.style.width = '';
    } else {
      bar.classList.remove('pm-proxy-indeterminate');
      bar.style.width = `${p}%`;
    }
  }
  const etaEl = document.getElementById('pmProxyEta');
  if (lbl) {
    if (pct >= 100) {
      lbl.textContent = 'Finalizing…';
      if (etaEl) { etaEl.dataset.hasEta = ''; etaEl.textContent = ''; etaEl.style.display = 'none'; }
    } else if (pct > 0) {
      lbl.textContent = `Generating proxy…  ${Math.round(pct)}%`;
      if (!_pmProxyEtaTracker) _pmProxyEtaTracker = _makeProxyEta();
      const eta = _pmProxyEtaTracker.update(pct);
      if (etaEl) {
        if (eta) {
          etaEl.dataset.hasEta = 'true';
          etaEl.textContent = `⏱ ${eta}`;
          etaEl.style.display = 'block';
        } else {
          etaEl.dataset.hasEta = '';
          // elapsed ticker will keep updating
        }
      }
    } else {
      lbl.textContent = 'Generating proxy…';
      // elapsed ticker keeps running — don't touch etaEl here
    }
  }
}

function _pmProxyBarHide() {
  const wrap = document.getElementById('pmProxyProgress');
  if (!wrap) return;
  wrap.style.display = 'none';
  const bar = document.getElementById('pmProxyBar');
  if (bar) { bar.classList.remove('pm-proxy-indeterminate'); bar.style.width = ''; }
  const etaEl = document.getElementById('pmProxyEta');
  if (etaEl) { etaEl.dataset.hasEta = ''; etaEl.textContent = ''; etaEl.style.display = 'none'; }
  if (pmVideoHint) pmVideoHint.classList.remove('pm-proxying');
  if (_pmProxyEtaTracker) { _pmProxyEtaTracker.reset(); _pmProxyEtaTracker = null; }
  if (_pmProxyTimerHandle) { clearInterval(_pmProxyTimerHandle); _pmProxyTimerHandle = null; }
  _pmProxyTimerT0 = 0;
}

// Try to parse a start TC from the video filename.
// Matches patterns like: 01_00_00_00  01-00-00-00  01;00;00;00  010000+00  01:00:00:00
function _pmGuessTcFromFilename(name) {
  const s = (name || '').replace(/\.[^.]+$/, ''); // strip extension
  const m = s.match(/(\d{2})[\s\-_:;,](\d{2})[\s\-_:;,](\d{2})[\s\-_:;,+](\d{2})/);
  if (!m) return null;
  const [, hh, mm, ss, ff] = m.map(Number);
  // Validate against known fps: ff must be < fps (e.g. 0–23 at 24fps, 0–29 at 30fps)
  const maxFf = Math.max(24, _pmFps || 24);
  if (hh > 23 || mm > 59 || ss > 59 || ff >= maxFf) return null;
  return `${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}:${String(ff).padStart(2,'0')}`;
}

function _pmQtReadU64Be(dv, off) {
  try {
    if (typeof dv.getBigUint64 === 'function') return Number(dv.getBigUint64(off, false));
  } catch {}
  const hi = dv.getUint32(off, false);
  const lo = dv.getUint32(off + 4, false);
  return (hi * 0x100000000) + lo;
}

function _pmQtFourCC(bytes, off) {
  if (!bytes || off < 0 || (off + 4) > bytes.byteLength) return '';
  return String.fromCharCode(bytes[off], bytes[off + 1], bytes[off + 2], bytes[off + 3]);
}

function _pmQtListAtoms(bytes, start = 0, end = null) {
  const u8 = (bytes instanceof Uint8Array) ? bytes : new Uint8Array(bytes || 0);
  const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
  const max = Math.min(u8.byteLength, Math.max(0, Number(end == null ? u8.byteLength : end) || 0));
  const out = [];
  let off = Math.max(0, Number(start) || 0);
  while ((off + 8) <= max) {
    let size = dv.getUint32(off, false);
    const type = _pmQtFourCC(u8, off + 4);
    let header = 8;
    if (size === 1) {
      if ((off + 16) > max) break;
      size = _pmQtReadU64Be(dv, off + 8);
      header = 16;
    } else if (size === 0) {
      size = max - off;
    }
    if (!Number.isFinite(size) || size < header || (off + size) > max) break;
    out.push({
      type,
      start: off,
      size,
      header,
      payloadStart: off + header,
      payloadEnd: off + size,
    });
    off += size;
  }
  return out;
}

function _pmQtFindChildAtom(bytes, parentAtom, type) {
  if (!parentAtom) return null;
  const kids = _pmQtListAtoms(bytes, parentAtom.payloadStart, parentAtom.payloadEnd);
  return kids.find(a => a.type === type) || null;
}

async function _pmQtReadFileSlice(file, start, len) {
  if (!file || len <= 0) return new Uint8Array(0);
  const s = Math.max(0, Number(start) || 0);
  const e = Math.min(Number(file.size) || 0, s + Math.max(0, Number(len) || 0));
  if (e <= s) return new Uint8Array(0);
  const ab = await file.slice(s, e).arrayBuffer();
  return new Uint8Array(ab);
}

// ── Project fps chip ─────────────────────────────────────────────────────────
// Common fps rates shown in the fps override popover.
const _PM_FPS_PRESETS = [23.976, 24, 25, 29.97, 30, 50, 59.94, 60, 120];

function _pmInitFpsChip() {
  if (!pmCtxFps) return;
  let popover = null;

  function _closePop() {
    if (popover) { popover.remove(); popover = null; }
  }

  pmCtxFps.addEventListener('click', (e) => {
    e.stopPropagation();
    if (popover) { _closePop(); return; }

    popover = document.createElement('div');
    popover.className = 'pm-fps-popover';

    for (const fps of _PM_FPS_PRESETS) {
      const btn = document.createElement('button');
      btn.textContent = `${_pmFormatFps(fps)} fps`;
      if (fps === (_pmDisplayFps || _pmFps)) btn.classList.add('pm-fps-active');
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        _pmFps = Math.max(1, Math.round(fps));  // integer tcBase
        _pmDisplayFps = fps;                    // actual fps for display
        { const _r = _pmFpsToRational(fps);
          _pmFrameClock.playNum = _r.num;
          _pmFrameClock.playDen = _r.den;
          _pmFrameClock.tcBase  = _pmFps; }
        if (pmCtxFps) pmCtxFps.textContent = _pmFormatFpsBadge();
        _pmNativeFps = fps;
        _closePop();
        try { _pmSyncFrame(); } catch {}
        try { window.__pmUpdateSyncDisplay?.(); } catch {}
      });
      popover.appendChild(btn);
    }

    const rect = pmCtxFps.getBoundingClientRect();
    popover.style.cssText = `top:${rect.bottom + 4}px;left:${rect.left}px`;
    document.body.appendChild(popover);
  });

  document.addEventListener('click', _closePop);
}

function _pmFormatFpsBadge() {
  const dfps = _pmFormatFps(_pmDisplayFps || _pmFps) || String(_pmFps);
  const tc   = _pmFrameClock.tcBase;
  const fmt  = _pmFrameClock.displayFormat || 'NDF';
  if (_pmDisplayFps && Math.abs(_pmDisplayFps - tc) > 0.01) {
    return `${dfps} fps / ${tc} TC / ${fmt}`;
  }
  return `${dfps} fps`;
}

// Format a fps value for display: integer rates → "24", fractional → "23.976" (3dp, no trailing zeros).
function _pmFormatFps(fpsVal) {
  const f = parseFloat(fpsVal);
  if (!Number.isFinite(f) || f <= 0) return '';
  if (Number.isInteger(f)) return String(f);
  return f.toFixed(3).replace(/0+$/, '').replace(/\.$/, '');
}

// Snap a timeScale/frameDuration rational to the nearest known NTSC fractional fps.
// Returns 23.976 / 29.97 / etc. instead of rounding to the nearest integer.
function _pmSnapFpsFromRational(timeScale, frameDuration) {
  if (!timeScale || !frameDuration) return 0;
  const r = timeScale / frameDuration;
  if (Math.abs(r - 23.976023976) < 0.01) return 23.976;
  if (Math.abs(r - 29.97002997)  < 0.01) return 29.97;
  if (Math.abs(r - 47.952047952) < 0.01) return 47.952;
  if (Math.abs(r - 59.94005994)  < 0.01) return 59.94;
  if (Math.abs(r - 119.88011988) < 0.01) return 119.88;
  return Math.round(r);
}

async function _pmProbeQuickTimeTmcd(file) {
  try {
    if (!file || !Number.isFinite(Number(file.size)) || Number(file.size) <= 0) return null;
    const lower = String(file.name || '').toLowerCase();
    if (!/\.(mov|mp4|m4v|qt)$/i.test(lower)) return null;

    let moov = null;
    let off = 0;
    let guard = 0;
    while ((off + 8) <= file.size && guard < 128) {
      guard++;
      const head = await _pmQtReadFileSlice(file, off, 16);
      if (head.byteLength < 8) break;
      const dv = new DataView(head.buffer, head.byteOffset, head.byteLength);
      let size = dv.getUint32(0, false);
      const type = _pmQtFourCC(head, 4);
      let header = 8;
      if (size === 1) {
        if (head.byteLength < 16) break;
        size = _pmQtReadU64Be(dv, 8);
        header = 16;
      } else if (size === 0) {
        size = file.size - off;
      }
      if (!Number.isFinite(size) || size < header || (off + size) > file.size) break;
      if (type === 'moov') {
        moov = { offset: off, size, header };
        break;
      }
      off += size;
    }
    if (!moov || moov.size <= moov.header) return null;

    const moovBytes = await _pmQtReadFileSlice(file, moov.offset + moov.header, moov.size - moov.header);
    if (!moovBytes.byteLength) return null;
    const moovDv = new DataView(moovBytes.buffer, moovBytes.byteOffset, moovBytes.byteLength);
    const traks = _pmQtListAtoms(moovBytes).filter(a => a.type === 'trak');
    for (const trak of traks) {
      const mdia = _pmQtFindChildAtom(moovBytes, trak, 'mdia');
      const hdlr = _pmQtFindChildAtom(moovBytes, mdia, 'hdlr');
      if (!hdlr || (hdlr.payloadStart + 12) > moovBytes.byteLength) continue;
      const handlerType = _pmQtFourCC(moovBytes, hdlr.payloadStart + 8);
      if (handlerType !== 'tmcd') continue;

      const minf = _pmQtFindChildAtom(moovBytes, mdia, 'minf');
      const stbl = _pmQtFindChildAtom(moovBytes, minf, 'stbl');
      const stsd = _pmQtFindChildAtom(moovBytes, stbl, 'stsd');
      const stco = _pmQtFindChildAtom(moovBytes, stbl, 'stco');
      const co64 = stco ? null : _pmQtFindChildAtom(moovBytes, stbl, 'co64');
      if (!stsd || (!stco && !co64)) continue;
      if ((stsd.payloadStart + 16) > moovBytes.byteLength) continue;

      const entryCount = moovDv.getUint32(stsd.payloadStart + 4, false);
      if (entryCount < 1) continue;
      const entryStart = stsd.payloadStart + 8;
      if ((entryStart + 34) > moovBytes.byteLength) continue;
      const entryType = _pmQtFourCC(moovBytes, entryStart + 4);
      if (entryType !== 'tmcd') continue;

      const flags = moovDv.getUint32(entryStart + 20, false);
      const timeScale = moovDv.getUint32(entryStart + 24, false);
      const frameDuration = moovDv.getUint32(entryStart + 28, false);
      const numFrames = moovBytes[entryStart + 32] || 0;
      const rationalFps = _pmSnapFpsFromRational(timeScale, frameDuration);
      const fps = Number(rationalFps || numFrames || _pmFps || 24);
      if (!Number.isFinite(fps) || fps <= 0) continue;

      let chunkOffset = -1;
      if (stco) {
        if ((stco.payloadStart + 12) > moovBytes.byteLength) continue;
        const entryCountStco = moovDv.getUint32(stco.payloadStart + 4, false);
        if (entryCountStco < 1) continue;
        chunkOffset = moovDv.getUint32(stco.payloadStart + 8, false);
      } else if (co64) {
        if ((co64.payloadStart + 16) > moovBytes.byteLength) continue;
        const entryCountCo64 = moovDv.getUint32(co64.payloadStart + 4, false);
        if (entryCountCo64 < 1) continue;
        chunkOffset = _pmQtReadU64Be(moovDv, co64.payloadStart + 8);
      }
      if (!Number.isFinite(chunkOffset) || chunkOffset < 0 || (chunkOffset + 4) > file.size) continue;

      const sampleBytes = await _pmQtReadFileSlice(file, chunkOffset, 4);
      if (sampleBytes.byteLength < 4) continue;
      const sampleDv = new DataView(sampleBytes.buffer, sampleBytes.byteOffset, sampleBytes.byteLength);
      const startFrame = sampleDv.getInt32(0, false);
      if (!Number.isFinite(startFrame) || startFrame < 0) continue;

      return {
        startTc: framesToTC(startFrame, fps),
        fps,
        dropFrame: !!(flags & 0x0001),
      };
    }
  } catch (err) {
    console.warn('[PM] tmcd probe failed:', err);
  }
  return null;
}

async function _pmLoadVideo(file, handle = null) {
  if (!pmVideo) return;
  _pmForcePreviewVisible('load-video');
  // Restore video element visibility (may have been hidden by _pmClear)
  pmVideo.style.display = '';
  pmVideo.style.visibility = '';
  // Reset companion state — this file is loaded via browser, not companion
  _pmCompanionMode = false;
  _pmNativeAssetId = null;
  _pmNativeFps     = null;
  _pmNativeStartTc = null;
  _pmNativeCanPlay = false;
  _pmVideoFile = file;
  if (pmVideoHint) {
    pmVideoHint.style.backgroundImage = '';  // clear companion-mode preview frame
    pmVideoHint.style.display = 'none';
  }

  // In the Electron desktop app, resolve the native filesystem path for dropped files.
  // This enables the AVFoundation/VideoToolbox direct-play path in playableMedia.js
  // (sharedMediaOpen → companion /file/{assetId} → VideoToolbox ProRes decode on macOS),
  // which is Tier 1 in the playback priority: native > proxy.
  if (!file._nativePath && window.pfxPlatform?.getNativeFilePath) {
    const nativePath = window.pfxPlatform.getNativeFilePath(file);
    if (nativePath) file._nativePath = nativePath;
  }

  // Unified playable-media layer: handles direct play + ProRes native engine + proxy fallback.
  // Previous blob URL ref is released inside attachPlayableVideo before the new one is acquired.
  attachPlayableVideo(pmVideo, file, {
    onStatus: (label) => {
      if (_pmVideoFile !== file || !pmVideoHint) return;
      if (label === PLAYABLE_STATUS.direct || label === PLAYABLE_STATUS.proxy ||
          label === PLAYABLE_STATUS.native) {
        _pmProxyBarHide();
        _pmSetVideoStatus(null);
        pmVideoHint.style.display = 'none';
      } else if (label === PLAYABLE_STATUS.proxying) {
        _pmSetVideoStatus(null);
        _pmProxyBarShow(0);
      } else {
        _pmProxyBarHide();
        _pmSetVideoStatus(label);
        pmVideoHint.style.display = '';
      }
    },
    onProgress: (pct) => {
      if (_pmVideoFile !== file) return;
      _pmProxyBarShow(pct);
    },
    onMode: (mode) => {
      if (_pmVideoFile !== file) return;
      _pmProxyBarHide();
      if (pmVideoHint) pmVideoHint.style.display = 'none';
      if (mode !== 'native') _pmRemoveNativeEngineBadge();
    },
    onProxyFail: (hint) => {
      if (_pmVideoFile !== file || !pmVideoHint) return;
      _pmProxyBarHide();
      pmVideoHint.style.display = '';
      _pmSetVideoStatus(`⚠ ${hint}`);
    },
    onNoOutputDir: () => {
      if (_pmVideoFile !== file || !pmVideoHint) return;
      _pmProxyBarHide();
      pmVideoHint.style.display = '';
      _pmSetVideoStatus(
        '⚠ Set Media Root in Settings to enable ProRes proxy · ' +
        '<a href="#" class="pm-settings-link" data-goto="about">Open Settings</a>',
        true  // safe: hardcoded HTML only, no user-controlled data
      );
    },
    onNativeEngine: ({ engine, info }) => {
      if (_pmVideoFile !== file) return;
      const container = (file?.name || '').split('.').pop();
      _pmShowNativeEngineBadge(info, engine, container);
    },
  });
  localStorage.setItem(_lsKey('lastVideoName.v1'), file.name);
  // Persist native path so _pmTryRestoreVideo can auto-reopen via companion.
  if (file._nativePath) {
    try { localStorage.setItem(_lsKey('lastVideoNativePath.v1'), file._nativePath); } catch {}
  } else {
    try { localStorage.removeItem(_lsKey('lastVideoNativePath.v1')); } catch {}
  }
  // Mirror into a serializable global so the proxy video survives in the saved
  // project file (not only in project-keyed localStorage, which is lost on the
  // per-tab load path and fragile for markers-only projects with no EDL).
  try {
    window.__PFX_PULLPREP_MEDIA = file._nativePath
      ? { proxyVideoNativePath: file._nativePath, proxyVideoName: file.name || '' }
      : null;
  } catch {}
  if (handle) _pmIdbSaveHandle(handle);

  // ── Auto-detect start TC from filename ──────────────────────────────────────
  const guessedTc = _pmGuessTcFromFilename(file.name);
  if (guessedTc) {
    _pmNativeStartTc = guessedTc;
    _pmNativeFps = _pmFps || null;
  }
  if (guessedTc) window.__pmUpdateSyncDisplay?.();

  // Try the embedded QuickTime/MP4 tmcd track next. This keeps the HUD overlay
  // on the file's real start timecode instead of falling back to event SRC math.
  _pmProbeQuickTimeTmcd(file).then((meta) => {
    if (!meta || _pmVideoFile !== file) return;
    if (meta.fps) _pmNativeFps = meta.fps;
    if (meta.startTc) _pmNativeStartTc = meta.startTc;
    // When no EDL is loaded and no project fps is set, adopt the file's embedded fps
    // so that TC math reflects 23.976/29.97 etc. instead of the 24 default.
    // If project settings have been loaded, they take priority over the video file's fps.
    if (meta.fps && meta.fps !== _pmFps && _pmEvents.length === 0 && !(_pmGetProjectSettingsFps() > 0)) {
      _pmFps = Math.max(1, Math.round(meta.fps));  // integer tcBase
      _pmDisplayFps = meta.fps;                     // actual fps for display
      { const _r = _pmFpsToRational(meta.fps);
        _pmFrameClock.playNum = _r.num;
        _pmFrameClock.playDen = _r.den;
        _pmFrameClock.tcBase  = _pmFps; }
      if (pmCtxFps) pmCtxFps.textContent = _pmFormatFpsBadge();
    }
    const smartConf = _pmMaybeSmartSyncFromFileTc({ minConfidence: 60, focusSelection: true, silent: false, force: true });
    if (!smartConf) {
      try { window.__pmUpdateSyncDisplay?.(); } catch {}
      _pmLastSyncedF = -1; // force overlay/HUD refresh when tmcd arrives after the first paint
      try { _pmSyncFrame(); } catch {}
    }
  }).catch((err) => {
    console.warn('[PM] embedded timecode probe failed:', err);
  });

  _pmPushTimelineData();
}

// ─── Quick Settings row ───────────────────────────────────────────────────────
function _pmSetPackMode(v) {
  _pmTlPack  = !!v;
  const btn  = document.getElementById('pmTlPackBtn');
  if (btn) {
    btn.dataset.active = _pmTlPack ? 'true' : 'false';
    btn.classList.toggle('pm-tl-toggle-on', _pmTlPack);
  }
  if (!_pmTlPack) {
    // Turning pack off also disables intelligent pack
    _pmPackIntelligent = false;
    const iBtn = document.getElementById('pmTlIPackBtn');
    if (iBtn) { iBtn.dataset.active = 'false'; iBtn.classList.remove('pm-tl-toggle-on'); }
    const densEl = document.getElementById('pmPackDensityBadge');
    if (densEl) densEl.textContent = '';
    const densEl2 = document.getElementById('pmPackDensityBadgeMain');
    if (densEl2) densEl2.textContent = '';
  }
  _pmTlPanFr = 0;
  _tlClampPan();
  _pmScheduleDraw();
}

function _pmSetIPackMode(v) {
  _pmPackIntelligent = !!v;
  const btn = document.getElementById('pmTlIPackBtn');
  if (btn) {
    btn.dataset.active = _pmPackIntelligent ? 'true' : 'false';
    btn.classList.toggle('pm-tl-toggle-on', _pmPackIntelligent);
  }
  // Auto-enable pack when enabling intelligent pack
  if (_pmPackIntelligent && !_pmTlPack) _pmSetPackMode(true);
  _pmTlPanFr = 0;
  _tlClampPan();
  _pmScheduleDraw();
}

function _pmEnableVfxToggles() {
  const _setBtn = (id, val) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.dataset.active = val ? 'true' : 'false';
    btn.classList.toggle('pm-tl-toggle-on', val);
  };
  _pmTlSnap    = true; _setBtn('pmTlSnapBtn',   true);
  _pmTlShowMk  = true; _setBtn('pmTlMkVisBtn',  true);
  _pmTlShowSub = false; _setBtn('pmTlSubBtn',    false);
  _pmTlShowTr  = true; _setBtn('pmTlTrVisBtn',  true);
  _setBtn('pmTlPackBtn', _pmTlPack);
  _pmPushTimelineData();
  _pmScheduleDraw();
}

function _wireQsRow() {
  const row = document.getElementById('pmQsRow');
  if (!row) return;

  // Import mode toggle (scripted ↔ unscripted)
  const modeToggle = document.getElementById('pmImportModeToggle');
  if (modeToggle) {
    _pmApplyImportMode(_pmImportMode, { updateTimeline: false }); // restore UI only on init
    modeToggle.addEventListener('click', (e) => {
      const opt = e.target.closest('.pm-im-opt[data-mode]');
      if (!opt || opt.dataset.mode === _pmImportMode) return;
      _pmApplyImportMode(opt.dataset.mode, { updateTimeline: true });
    });
  }

  row.addEventListener('click', (e) => {
    const btn = e.target.closest('.pm-qs-btn[data-key]');
    if (!btn) return;
    const key = btn.getAttribute('data-key');

    const apply = window.__MPS_applyQsPreset;

    if (key === 'clear') {
      // All off → pack off
      _pmLocalQs.vfxmarker = false;
      _pmLocalQs.vfxrename = false;
      if (apply) apply({});
      _pmSetPackMode(false);
      _pmUpdateQsButtons();
      _pmRenderEventTable();

    } else if (key === 'conform') {
      // Toggle: if already active → all off; else apply Conform preset
      const isOn = !!(window.__MPS_qsState?.conform);
      _pmLocalQs.vfxmarker = false;
      _pmLocalQs.vfxrename = false;
      if (apply) apply(isOn ? {} : {
        conform: true, merge: true, flatten: true,
        decompose: true, metadata: true, autosplit: true, extra: true
      });
      // conform on → pack on; conform toggled off → pack off
      _pmSetPackMode(!isOn);
      // Immediately refresh with correct branch (conform uses raw events)
      _pmRefreshData();

    } else if (_PM_LOCAL_QS_KEYS.has(key)) {
      // Toggle: if already active → all off; else apply VFX preset
      const isOn = !!_pmLocalQs[key];
      _pmLocalQs.vfxmarker = false;
      _pmLocalQs.vfxrename = false;
      if (!isOn) {
        _pmLocalQs[key] = true;
        if (apply) apply({ flatten: true, decompose: true, metadata: true, extra: true });
        _pmTlZoom = 1;
        _pmSetPackMode(true);
        _pmEnableVfxToggles();
      } else {
        // was on → go all off → pack off
        if (apply) apply({});
        _pmSetPackMode(false);
      }
      // _pmRefreshData() reads raw events for VFX modes — run it now so the
      // timeline canvas redraws immediately with the correct data, without
      // waiting for the 80 ms debounced recompute.
      _pmRefreshData();

    } else if (typeof window.__MPS_toggleQS === 'function') {
      // Generic pipeline key — normal toggle
      window.__MPS_toggleQS(key);
      setTimeout(_pmUpdateQsButtons, 90);
    }
  });

  // Options toggle — show/hide modifier buttons
  document.getElementById('pmQsOptionsToggle')?.addEventListener('click', () => {
    row.classList.toggle('pm-qs-expanded');
  });

  _pmWireOcfRelinkBtn();
  _pmWireOcfDropZone();
}

