function _pmSlyNormalizeLangCommand(text) {
  const lang = _pmSlyGetVoiceLang();
  if (lang === 'en') return text;
  const pairs = _SLY_LANG_CMDS[lang] || [];
  let result = text;
  for (const [native, english] of pairs) {
    if (result.includes(native)) result = result.replace(native, english);
  }
  return result;
}

// ── Speak feedback ────────────────────────────────────────────────────────────
// SpeechSynthesis — wait for voices, use AudioContext beep as fallback
let _pmSlyVoicesReady = false;
function _pmSlyEnsureVoices(cb) {
  const voices = speechSynthesis.getVoices?.() || [];
  if (voices.length > 0) { _pmSlyVoicesReady = true; cb(voices); return; }
  speechSynthesis.onvoiceschanged = () => {
    _pmSlyVoicesReady = true;
    cb(speechSynthesis.getVoices?.() || []);
  };
  // Force voice load in Chromium
  try { speechSynthesis.speak(new SpeechSynthesisUtterance('')); speechSynthesis.cancel(); } catch {}
}

function _pmSlyVoiceSpeak(text, { rate = 1.0, volume = 1.0 } = {}) {
  if (!text) return;
  const say = (voices) => {
    try {
      speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(text.slice(0, 120));
      const _ttsLang = _pmSlyGetLangConf().locale;
      u.rate = rate; u.volume = volume; u.lang = _ttsLang;
      const v = voices.find(v => v.lang === _ttsLang && v.localService)
             || voices.find(v => v.lang.startsWith(_ttsLang.split('-')[0]))
             || voices.find(v => v.lang === 'en-US' && v.localService)
             || voices.find(v => v.lang.startsWith('en-'))
             || voices[0];
      if (v) u.voice = v;
      u.onerror = e => console.warn('[TTS]', e.error);
      speechSynthesis.speak(u);
    } catch(e) { console.warn('[TTS speak]', e); }
  };
  if (_pmSlyVoicesReady) {
    say(speechSynthesis.getVoices?.() || []);
  } else {
    _pmSlyEnsureVoices(say);
  }
}

// Pre-warm voices on module load
if (typeof speechSynthesis !== 'undefined') {
  _pmSlyEnsureVoices(() => {});
}

