// ── Match intent ──────────────────────────────────────────────────────────────
// Fuzzy token scoring: single-word patterns match if the word appears as a token;
// multi-word patterns match if ≥ 2/3 of their tokens appear and at least 2 hit.
// Highest hit-count wins; ties broken by longer pattern (more specific).
function _pmSlyMatchIntent(lower) {
  const inputTokens = new Set(lower.split(/\s+/));
  let best = null, bestHits = 0, bestPatLen = 0;

  for (const intent of _SLY_INTENTS) {
    for (const pat of intent.pat) {
      // Exact full-string match — always wins immediately
      if (lower === pat) return { intent, ctx: {} };

      const patTokens = pat.split(/\s+/);
      const hits = patTokens.filter(w => inputTokens.has(w)).length;

      if (patTokens.length === 1) {
        // Single token: must appear as a whole word in the input
        if (hits === 1) {
          if (bestHits < 1 || patTokens.length > bestPatLen) {
            best = { intent, ctx: {} }; bestHits = 1; bestPatLen = patTokens.length;
          }
        }
      } else {
        // Multi-word: need ≥ 2/3 overlap AND at least 2 matching tokens
        const ratio = hits / patTokens.length;
        if (ratio >= 0.67 && hits >= 2) {
          if (hits > bestHits || (hits === bestHits && patTokens.length > bestPatLen)) {
            best = { intent, ctx: {} }; bestHits = hits; bestPatLen = patTokens.length;
          }
        }
      }
    }
  }
  return best;
}

// ── Flag toggle helper ────────────────────────────────────────────────────────
function _pmSlyVoiceToggleFlag(flagKey, label) {
  const ev = _pmActiveEventIdx >= 0 ? _pmEvents[_pmActiveEventIdx] : null;
  if (!ev) { _pmSlyVoiceSpeak('No active event'); return; }
  const propMap = { retime: '_pmRetime', stabilize: '_pmStabilize', resize: '_pmResize' };
  const prop = propMap[flagKey];
  if (!prop) return;
  _pmSlySnapshot(`${label} toggle`);
  ev[prop] = ev[prop] === true ? false : true;
  try { _pmSaveMeta(ev); _pmRefreshData(); } catch {}
  _pmSlyVoiceSpeak(`${label} ${ev[prop] ? 'on' : 'off'}`);
  _pmSlyFlash(ev[prop] ? '✓' : '✗');
}

function _pmSlyVoiceSetFlag(flagKey, label, value) {
  const ev = _pmActiveEventIdx >= 0 ? _pmEvents[_pmActiveEventIdx] : null;
  if (!ev) { _pmSlyVoiceSpeak('No active event'); return; }
  const propMap = { retime: '_pmRetime', stabilize: '_pmStabilize', resize: '_pmResize' };
  const prop = propMap[flagKey];
  if (!prop) return;
  _pmSlySnapshot(`${label} ${value ? 'on' : 'off'}`);
  ev[prop] = value;
  try { _pmSaveMeta(ev); _pmRefreshData(); } catch {}
  _pmSlyVoiceSpeak(`${label} ${value ? 'on' : 'off'}`);
  _pmSlyFlash(value ? '✓' : '✗');
}

// ── Dispatch ──────────────────────────────────────────────────────────────────
async function _pmSlyDispatchCommand(text) {
  if (!text) return;
  if (text === _pmSlyVoiceLastCmd) return;
  _pmSlyVoiceLastCmd = text;
  setTimeout(() => { if (_pmSlyVoiceLastCmd === text) _pmSlyVoiceLastCmd = ''; }, 400);

  const _rawLower = text.toLowerCase().trim().replace(/[.,!?]$/, '');
  const lower = _pmSlyNormalizeLangCommand(_rawLower);

  // Awaiting dialog reply
  if (_pmSlyVoiceAwaitReply) {
    const { options, handler } = _pmSlyVoiceAwaitReply;
    _pmSlyVoiceAwaitReply = null;
    let matched = null;
    for (const [k, aliases] of Object.entries(options)) {
      if (aliases.some(a => lower.includes(a))) { matched = k; break; }
    }
    _pmSlyVoiceUpdateOverlay(`→ "${text}"`, false);
    setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 2000);
    if (matched) try { await handler(matched); } catch(e) { console.warn('[Voice]', e); }
    else _pmSlyVoiceSpeak("Didn't catch that");
    return;
  }

  // Prefix: "actually X" / "I meant X" — correction: clear dedup and re-dispatch
  const corrM = lower.match(/^(?:actually|i meant|no i mean|no actually|correction:?)\s+(.+)$/i);
  if (corrM) { _pmSlyVoiceLastCmd = ''; _pmSlyDispatchCommand(corrM[1]); return; }

  // Prefix: "name it X"
  const nameM = lower.match(/^(?:name it|call it|rename to|shot name(?:\s+is)?)\s+(.+)$/i);
  if (nameM) { _pmSlyVoiceSetName(nameM[1]); _pmSlyVoiceSpeak(`Named ${nameM[1]}`); return; }

  // Prefix: "note X"
  const noteM = lower.match(/^(?:note|add note|comment)\s+(.+)$/i);
  if (noteM) { _pmSlyVoiceAddNote(noteM[1]); _pmSlyVoiceSpeak('Note added'); return; }

  // Prefix: "set scope X" / "scope is X"
  const scopeM = lower.match(/^(?:set scope(?:\s+to)?|scope(?:\s+is)?|scope:)\s+(.+)$/i);
  if (scopeM) {
    const mk = _pmSlySelMkId ? _pmClipMarkers.find(m => m.id === _pmSlySelMkId) : _pmClipMarkers[_pmClipMarkers.length - 1];
    if (!mk) { _pmSlyVoiceSpeak('No marker selected'); return; }
    _pmSlySnapshot(`Scope: ${mk.shotName || mk.id}`);
    mk.scopeOfWork = scopeM[1].trim();
    try { _pmSaveClipMarkers(); _pmSlyRefreshMarkerCard(); } catch {}
    _pmSlyVoiceSpeak('Scope set');
    _pmSlyVoiceUpdateOverlay(`✓ Scope: "${scopeM[1].slice(0, 40)}"`, false);
    setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 2000);
    return;
  }

  // Prefix: "go to reel X" / "reel X" / "jump to reel X"
  const reelM = lower.match(/^(?:go to reel|jump to reel|reel|find reel)\s+(.+)$/i);
  if (reelM) {
    const q = reelM[1].trim().toUpperCase();
    const idx = _pmEvents.findIndex(ev => {
      const r = (ev.reel || ev.srcFile || ev.clip || '').toUpperCase().replace(/\.[^.]+$/, '');
      return r === q || r.startsWith(q) || r.includes(q);
    });
    if (idx >= 0) {
      try { _pmSetActiveRow(idx); } catch {}
      const reel = (_pmEvents[idx]?.reel || q).replace(/\.[^.]+$/, '').slice(0, 20);
      _pmSlyVoiceSpeak(`Reel ${reel}`);
      _pmSlyVoiceUpdateOverlay(`→ Reel: ${reel}`, false);
    } else {
      _pmSlyVoiceSpeak(`Reel ${q} not found`);
    }
    setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 2000);
    return;
  }

  // Prefix: "go to event N" / "shot N"
  const evM = lower.match(/^(?:go to (?:event|shot)|event|shot)\s+(\d+)$/i);
  if (evM) { const i=Math.min(Math.max(0,parseInt(evM[1],10)-1),_pmEvents.length-1); try{_pmSetActiveRow(i);}catch{}; _pmSlyVoiceSpeak(`Event ${evM[1]}`); return; }

  // Prefix: "ask X" → AI
  const askM = lower.match(/^(?:ask|ai|question)\s+(.+)$/i);
  if (askM) {
    _pmSlyVoiceSpeak('Thinking');
    try { const a = await _pmSlyAiChat(askM[1]); _pmSlyVoiceSpeak(a.slice(0,120)); _pmSlyToast(a.slice(0,80)); } catch { _pmSlyVoiceSpeak('AI unavailable'); }
    return;
  }

  // Compound: "pull ocean_bg_001" / "background wide shot" → mark type + auto-name
  const _compoundTypeMap = {
    'pull plate': 'PL', 'clean plate': 'CP', pull: 'PL', pl: 'PL',
    clean: 'CP', cp: 'CP', background: 'BG', bg: 'BG',
    foreground: 'FG', fg: 'FG', element: 'EL', el: 'EL',
    reference: 'RF', rf: 'RF',
  };
  const compM = lower.match(/^(pull\s+plate|clean\s+plate|pull|clean|pl|cp|background|bg|foreground|fg|element|el|reference|rf)\s+(\S.{1,})$/);
  if (compM) {
    const code = _compoundTypeMap[compM[1].trim()];
    const tail = compM[2].trim();
    if (code && !_pmSlyMatchIntent(tail)) {
      await _pmSlyVoiceMarkType(code);
      _pmSlyVoiceSetName(tail);
      _pmSlyVoiceSpeak(`${code}: ${tail}`);
      return;
    }
  }

  // Standard intents
  const result = _pmSlyMatchIntent(lower);
  if (result) {
    _pmSlyVoiceUpdateOverlay(`✓  ${result.intent.desc}`, false);
    _pmSlyLastAction = { fn: result.intent.fn, desc: result.intent.desc };
    setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 2000);
    try { await result.intent.fn(result.ctx); } catch(e) { console.warn('[Voice]', e); }
    return;
  }

  // Unmatched → AI auto-fallback (skip noise/filler words)
  const _isNoise = lower.length < 3 || /^(uh+|um+|ah+|oh+|hmm+|the|a|an|and|or|so|like|just|yeah|okay|ok)$/.test(lower);
  const _hasAi   = !!_pmSlyGetClaudeKey?.() || !!(window.ai?.languageModel || window.ai?.assistant);
  if (!_isNoise && _hasAi) {
    _pmSlyVoiceUpdateOverlay(`⟳ "${text.slice(0, 30)}"…`, false);
    try {
      const answer = await _pmSlyAiChat(text);
      const short  = answer.slice(0, 120);
      _pmSlyVoiceUpdateOverlay(`→ ${short.slice(0, 60)}`, false);
      setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 5000);
      _pmSlyVoiceSpeak(short);
      return;
    } catch { /* fall through to shot-name or dead-end */ }
  }

  // No AI or noise: if marker selected treat as shot name, else dead-end
  if (_pmSlySelMkId) {
    _pmSlyVoiceSetName(text);
    _pmSlyVoiceUpdateOverlay(`✓ Named: "${text}"`, false);
    _pmSlyVoiceSpeak(`Named ${text}`);
  } else {
    _pmSlyVoiceUpdateOverlay(`"${text}" — say a command or type below`, false);
  }
  setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 2000);
}

// ── Voice ask (two-way) ───────────────────────────────────────────────────────
function _pmSlyVoiceAsk(prompt, options) {
  return new Promise(resolve => {
    _pmSlyVoiceSpeak(prompt);
    _pmSlyVoiceUpdateOverlay(`❓ ${prompt}`, false);
    _pmSlyVoiceAwaitReply = { options, handler: async k => resolve(k) };
    setTimeout(() => { if (_pmSlyVoiceAwaitReply) { _pmSlyVoiceAwaitReply=null; resolve(null); } }, 8000);
  });
}

// ── Toggle voice on/off ───────────────────────────────────────────────────────
let _pmSlyMicLevelRaf = null;
let _pmSlyMicStream   = null;

function _pmSlyToggleVoice() {
  if (_pmSlyVoiceActive) { _pmSlyStopVoice(); return; }
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) { _pmSlyToast('Speech recognition requires Chrome'); return; }

  _pmSlyVoiceShowOverlay();
  _pmSlyVoiceUpdateOverlay('Finding microphone…', false);

  // Step 1: get permission (needed to see device labels)
  navigator.mediaDevices?.getUserMedia({ audio: true })
    .then(async tmpStream => {
      tmpStream.getTracks().forEach(t => t.stop());

      // Step 2: enumerate devices and pick the built-in mic, NOT virtual devices
      const devices = await navigator.mediaDevices.enumerateDevices();
      const inputs  = devices.filter(d => d.kind === 'audioinput');

      // Priority: built-in/MacBook > real hardware > avoid virtual/bridge/BlackHole
      const isVirtual   = d => /blackhole|pro.?tools|bridge|virtual|aggregate|360vme|soundflower|loopback/i.test(d.label);
      const isBuiltIn   = d => /built.?in|macbook|internal|microphone.*built/i.test(d.label);
      const isHardware  = d => !isVirtual(d);

      const chosen =
        inputs.find(isBuiltIn) ||
        inputs.find(isHardware) ||
        inputs[0];

      if (!chosen) {
        _pmSlyVoiceUpdateOverlay('❌ No microphone found', false);
        return;
      }

      const hint = document.getElementById('pmSlyVoMicHint');
      if (hint) hint.textContent = `Using: ${chosen.label.slice(0, 30) || 'default mic'}`;

      // Step 3: open stream from the chosen device
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: { deviceId: { exact: chosen.deviceId }, echoCancellation: true, noiseSuppression: true, autoGainControl: true }
      });

      _pmSlyMicStream = stream;
      _pmSlyStartMicMeter(stream);
      _pmSlyStartRecog(SR);
    })
    .catch(err => {
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        _pmSlyVoiceUpdateOverlay('❌ Microphone blocked', false);
        _pmSlyVoiceShowPermissionHelp();
      } else {
        _pmSlyVoiceUpdateOverlay(`Mic error: ${err.message}`, false);
        // Try without device selection
        _pmSlyStartRecog(SR);
      }
    });
}

// ── Live mic level meter in overlay ──────────────────────────────────────────
function _pmSlyStartMicMeter(stream) {
  try {
    const ctx   = new AudioContext();
    const src   = ctx.createMediaStreamSource(stream);
    const anal  = ctx.createAnalyser();
    anal.fftSize = 256;
    src.connect(anal);
    const buf = new Uint8Array(anal.frequencyBinCount);

    const tick = () => {
      if (!_pmSlyVoiceActive) { ctx.close(); return; }
      anal.getByteFrequencyData(buf);
      const avg = buf.reduce((a,b) => a+b, 0) / buf.length;
      const pct = Math.min(100, avg * 2.5);
      const bar  = document.getElementById('pmSlyVoMicBar');
      const hint = document.getElementById('pmSlyVoMicHint');
      if (bar) {
        bar.style.width = pct + '%';
        bar.style.background = pct > 15 ? '#4caf80' : pct > 5 ? '#e5c07b' : '#e06c75';
      }
      if (hint) {
        hint.textContent = pct > 15 ? '✓ mic active' : pct > 3 ? 'low signal' : '⚠ no signal — check mic device';
        hint.style.color  = pct > 15 ? '#4caf80' : pct > 3 ? '#e5c07b' : '#e06c75';
      }
      _pmSlyMicLevelRaf = requestAnimationFrame(tick);
    };
    _pmSlyMicLevelRaf = requestAnimationFrame(tick);
  } catch {}
}

function _pmSlyStartRecog(SR) {
  _pmSlyVoiceActive = true;
  const lbl = document.getElementById('pmCtxVoiceLabel');
  const sts = document.getElementById('pmCtxVoiceStatus');
  const btn = document.getElementById('pmCtxVoiceBtn');
  if (lbl) lbl.textContent = 'Voice';
  if (sts) { sts.textContent = '● REC'; sts.style.display = ''; }
  if (btn) btn.classList.add('is-active');
  _pmSlyVoiceSpeak(_pmSlyGetLangConf().readyText);
  _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false);
  _pmSlyVoiceRun(SR);
}

function _pmSlyVoiceRun(SR) {
  if (!_pmSlyVoiceActive) return;
  const recog = new SR();
  recog.lang = _pmSlyGetLangConf().locale;
  recog.continuous = false;        // single-utterance is reliable in Chrome extensions
  recog.interimResults = true;
  recog.maxAlternatives = 5;

  recog.onresult = e => {
    let interim = '', final = '', finalConf = 1;
    for (let i = 0; i < e.results.length; i++) {
      if (e.results[i].isFinal) {
        let best = e.results[i][0].transcript;
        let bestConf = e.results[i][0].confidence ?? 1;
        // Prefer any alt that matches a known intent, even at lower confidence
        for (let j = 1; j < e.results[i].length; j++) {
          const alt = e.results[i][j]?.transcript || '';
          if (alt && _pmSlyMatchIntent(alt.toLowerCase().trim())) { best = alt; bestConf = e.results[i][j]?.confidence ?? bestConf; break; }
        }
        final += best;
        finalConf = Math.min(finalConf, bestConf);
      } else { interim += e.results[i][0].transcript; }
    }
    if (interim) _pmSlyVoiceUpdateOverlay(interim, true);
    if (final) {
      if (finalConf > 0 && finalConf < 0.35) {
        _pmSlyVoiceUpdateOverlay(`⚠ "${final.trim().slice(0, 25)}" (low confidence)`, false);
        setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 1500);
      }
      _pmSlyDispatchCommand(final.trim());
    }
  };

  recog.onerror = e => {
    if (e.error === 'no-speech' || e.error === 'aborted') return;
    if (e.error === 'not-allowed') {
      _pmSlyVoiceActive = false;
      const btn = document.getElementById('pmCtxVoiceBtn');
      const sts = document.getElementById('pmCtxVoiceStatus');
      if (btn) btn.classList.remove('is-active');
      if (sts) sts.style.display = 'none';
      _pmSlyVoiceUpdateOverlay('❌ Mic blocked — see below', false);
      _pmSlyVoiceShowPermissionHelp();
      return;
    }
    if (e.error === 'network') { _pmSlyVoiceUpdateOverlay('⚠ Network error…', false); }
  };

  recog.onend = () => {
    if (!_pmSlyVoiceActive) return;
    _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false);
    setTimeout(() => { if (_pmSlyVoiceActive) _pmSlyVoiceRun(SR); }, 150);
  };

  _pmSlyVoiceRecog = recog;
  try { recog.start(); }
  catch { setTimeout(() => { if (_pmSlyVoiceActive) _pmSlyVoiceRun(SR); }, 400); }
}

function _pmSlyStopVoice() {
  _pmSlyVoiceActive = false;
  _pmSlyVoiceAwaitReply = null;
  cancelAnimationFrame(_pmSlyMicLevelRaf);
  try { _pmSlyMicStream?.getTracks().forEach(t => t.stop()); } catch {}
  _pmSlyMicStream = null;
  const btn = document.getElementById('pmCtxVoiceBtn');
  const sts = document.getElementById('pmCtxVoiceStatus');
  if (btn) btn.classList.remove('is-active');
  if (sts) sts.style.display = 'none';
  try { _pmSlyVoiceRecog?.abort(); } catch {}
  _pmSlyVoiceRecog = null;
  document.getElementById('pmSlyVoiceOverlay')?.remove();
  _pmSlyVoiceSpeak(_pmSlyGetLangConf().offText, { rate: 1.0, volume: 0.6 });
}

// ── Overlay ───────────────────────────────────────────────────────────────────
function _pmSlyVoiceShowOverlay() {
  if (document.getElementById('pmSlyVoiceOverlay')) return;
  const el = document.createElement('div');
  el.id = 'pmSlyVoiceOverlay';
  el.className = 'pm-sly-voice-overlay';
  // Build command help
  const cats = {};
  for (const i of _SLY_INTENTS) { if (!cats[i.cat]) cats[i.cat]=[];  cats[i.cat].push(i.desc); }
  const catLabels = {player:'Player',nav:'Navigate',mark:'Mark',auto:'Auto',view:'View',
                     edit:'Edit',export:'Export',project:'Project',info:'Status'};
  const catHtml = Object.entries(cats).map(([c,ds])=>
    `<div class="pm-sly-vo-cat"><div class="pm-sly-vo-cat-label">${catLabels[c]||c}</div>${ds.map(d=>`<span class="pm-sly-vo-cmd">${d}</span>`).join('')}</div>`
  ).join('');

  el.innerHTML = `
    <div class="pm-sly-vo-header">
      <span class="pm-sly-vo-pulse"></span> Voice Control
      <button class="pm-sly-vo-help-btn" id="pmSlyVoHelp">?</button>
      <button class="pm-sly-vo-close" id="pmSlyVoClose">✕</button>
    </div>
    <div class="pm-sly-vo-transcript" id="pmSlyVoTranscript">Listening…</div>
    <div class="pm-sly-vo-meter-wrap" title="Microphone level — should move when you speak">
      <span class="pm-sly-vo-meter-lbl">🎤</span>
      <div class="pm-sly-vo-meter-bg"><div class="pm-sly-vo-meter-bar" id="pmSlyVoMicBar"></div></div>
      <span class="pm-sly-vo-meter-hint" id="pmSlyVoMicHint">speak to see level</span>
    </div>
    <div class="pm-sly-vo-help-panel" id="pmSlyVoHelpPanel" style="display:none;">${catHtml}</div>
    <div class="pm-sly-vo-text-wrap">
      <input class="pm-sly-vo-text-inp" id="pmSlyVoText" placeholder="Or type: next · pull plate · auto mark · name it SH0010…" />
      <button class="pm-sly-vo-text-btn" id="pmSlyVoSend">→</button>
    </div>`;
  document.body.appendChild(el);

  document.getElementById('pmSlyVoClose')?.addEventListener('click', _pmSlyStopVoice);
  document.getElementById('pmSlyVoHelp')?.addEventListener('click', () => {
    const h = document.getElementById('pmSlyVoHelpPanel');
    if (h) h.style.display = h.style.display==='none' ? '' : 'none';
  });
  const send = () => {
    const inp = document.getElementById('pmSlyVoText');
    const v = inp?.value?.trim();
    if (!v) return;
    inp.value = '';
    _pmSlyVoiceUpdateOverlay(`> ${v}`, false);
    _pmSlyDispatchCommand(v);
  };
  document.getElementById('pmSlyVoSend')?.addEventListener('click', send);
  document.getElementById('pmSlyVoText')?.addEventListener('keydown', e => { if (e.key==='Enter'){e.preventDefault();send();} });
}

function _pmSlyVoiceUpdateOverlay(text, interim) {
  const el = document.getElementById('pmSlyVoTranscript');
  if (el) {
    el.textContent = text || _pmSlyListenText();
    el.className = 'pm-sly-vo-transcript' + (text.startsWith('✓')||text.startsWith('→') ? ' is-success' : interim ? ' is-interim' : '');
  }
  // Mirror short status on the ctx-bar button
  const sts = document.getElementById('pmCtxVoiceStatus');
  if (sts && _pmSlyVoiceActive) {
    if (interim && text) {
      const preview = text.slice(0, 18) + (text.length > 18 ? '…' : '');
      sts.textContent = preview;
    } else if (text.startsWith('✓') || text.startsWith('→')) {
      sts.textContent = '✓';
    } else {
      sts.textContent = '● REC';
    }
  }
}

function _pmSlyVoiceShowPermissionHelp() {
  const ov = document.getElementById('pmSlyVoiceOverlay');
  if (!ov || ov.querySelector('.pm-sly-vo-perm')) return;
  const d = document.createElement('div');
  d.className = 'pm-sly-vo-perm';
  d.innerHTML = `
    <b>Fix microphone access:</b><br>
    1. macOS: System Settings → Privacy &amp; Security → Microphone → enable <b>Chrome</b><br>
    2. Chrome: click 🔒 in address bar → Microphone → <b>Allow</b><br>
    3. Reload extension at <code>chrome://extensions</code>
    <br><small>Text commands below work without mic.</small>`;
  ov.appendChild(d);
}

// ── Action helpers ────────────────────────────────────────────────────────────
function _pmSlyVoiceNav(dir) {
  const cur = Math.max(0, _pmActiveEventIdx);
  const next = Math.max(0, Math.min(_pmEvents.length-1, cur+dir));
  try { _pmSetActiveRow(next); } catch {}
  const ev = _pmEvents[next];
  _pmSlyVoiceSpeak((dir>0?'Next — ':'Back — ') + (ev?.reel||ev?.clip||'').replace(/\.[^.]+$/,'').slice(0,20));
}

async function _pmSlyVoiceMarkType(code) {
  const evIdx = Math.max(0, _pmActiveEventIdx);
  const ev = _pmEvents[evIdx];
  if (!ev) { _pmSlyVoiceSpeak('Navigate to an event first'); return; }
  _pmSlySnapshot(`Voice ${code}`);
  const fps = _pmFps||24;
  let timing; try { timing = _pmMarkerTimingFromEvent(ev,fps); } catch {}
  if (!timing) { _pmSlyVoiceSpeak('Cannot mark here'); return; }
  const frame = tcToFrames(timing.recIn||'00:00:00:00', fps);
  const seq = _pmClipMarkers.filter(m=>m._plateCode===code).length+1;
  const shotName = _pmSlyGenerateShotName(ev, {_plateCode:code}, seq);
  const mk = {
    id: crypto.randomUUID?.() ?? `pm_${Date.now()}_${Math.random().toString(36).slice(2)}`,
    frame, tc: framesToTC(frame,fps), recIn:timing.recIn, recOut:timing.recOut,
    tcIn:timing.tcIn, tcOut:timing.tcOut, shotName,
    color:_pmNextMarkerColor||'Green', clipName:ev.clipName||ev.clip||'', reel:ev.reel||'',
    vendor:'', scopeOfWork:_pmSlyGenerateSoW({_plateCode:code},ev),
    scopeOfWorkList:[], note:'', noteType:'', noteTypeGroup:'',
    thumb:'', thumbAnn:'', annoStrokes:null,
    _thumbCapturing:false, _fromPrepMark:true, _plateCode:code, _eventIdx:evIdx,
  };
  _pmClipMarkers.push(mk);
  try { _pmRunAutoLink(); _pmSaveClipMarkers(); _pmRefreshData(); } catch {}
  _pmSlyFlash(code);
  _pmSlyVoiceSpeak(`${code==='PL'?'Pull plate':code==='CP'?'Clean plate':code} — ${shotName}`);
}

function _pmSlyVoiceSetName(text) {
  const mk = _pmSlySelMkId ? _pmClipMarkers.find(m=>m.id===_pmSlySelMkId) : _pmClipMarkers[_pmClipMarkers.length-1];
  if (!mk) { _pmSlyVoiceSpeak('No marker selected'); return; }
  _pmSlySnapshot(`Rename: ${mk.shotName || mk.id}`);
  mk.shotName = text.trim();
  try { _pmSaveClipMarkers(); _pmSlyRefreshMarkerCard(); _pmSlyRefreshMarkerStrip(); } catch {}
}

function _pmSlyVoiceAddNote(text) {
  const mk = _pmSlySelMkId ? _pmClipMarkers.find(m=>m.id===_pmSlySelMkId) : _pmClipMarkers[_pmClipMarkers.length-1];
  if (!mk) { _pmSlyVoiceSpeak('No marker'); return; }
  _pmSlySnapshot(`Note: ${mk.shotName || mk.id}`);
  mk.note = (mk.note ? mk.note+' ' : '') + text.trim();
  try { _pmSaveClipMarkers(); _pmSlyRefreshMarkerCard(); } catch {}
}

// ── Visual flash on viewer ────────────────────────────────────────────────────
function _pmSlyFlash(icon) {
  let el = document.getElementById('pmSlyVoiceFlash');
  if (!el) {
    el = document.createElement('div');
    el.id = 'pmSlyVoiceFlash';
    el.className = 'pm-sly-voice-flash';
    const slot = document.getElementById('pmSlyViewerSlot');
    (slot || document.body).appendChild(el);
  }
  el.textContent = icon;
  el.classList.remove('pm-sly-flash-anim');
  requestAnimationFrame(() => el.classList.add('pm-sly-flash-anim'));
}

// ═══════════════════════════════════════════════════════════════════════════════
//  INTELLIGENT VOICE INTERACTION LAYER
//  — guided workflow · spoken context · auto-advance · smart prompts
// ═══════════════════════════════════════════════════════════════════════════════

// ── Guided marking mode state ─────────────────────────────────────────────────
let _pmSlyGuideActive  = false;  // currently in guided workflow mode
let _pmSlyGuideQueue   = [];     // event indices to walk through
let _pmSlyGuideIdx     = 0;      // current position in guide queue

// ── Context-aware announcement ────────────────────────────────────────────────
// Called after voice activates — tells the user what's happening right now

function _pmSlyVoiceAnnounceContext() {
  const fps      = _pmFps || 24;
  const total    = _pmEvents.length;
  const linked   = _pmLinkMap.size;
  const mkCount  = _pmClipMarkers.length;
  const warns    = _pmSlyCountWarnMarkers();
  const pct      = total > 0 ? Math.round((linked / total) * 100) : 0;
  const { clusters } = _pmSlyBuildClusters();
  const next     = _pmSlyNextTarget(clusters);
  const ev       = _pmActiveEventIdx >= 0 ? _pmEvents[_pmActiveEventIdx] : null;

  let msg = '';

  if (total === 0) {
    msg = 'No timeline loaded. Say load timeline to get started.';
  } else if (linked === 0) {
    msg = `${total} events ready. ${clusters.length} camera rolls. Say start marking to begin, or auto mark all.`;
  } else if (pct === 100) {
    msg = `All ${total} events marked. ${mkCount} markers ready. Say export to deliver.`;
  } else if (warns > 0) {
    msg = `${pct} percent done. ${warns} QC warning${warns > 1 ? 's' : ''} need fixing. Say show warnings.`;
  } else {
    const remaining = total - linked;
    const nextReel  = next ? (_pmEvents[next.evIdx]?.reel || '').replace(/\.[^.]+$/, '').slice(0, 20) : '';
    msg = `${pct} percent done. ${remaining} events left. ${nextReel ? `Next: ${nextReel}.` : ''} Say continue, or start marking.`;
  }

  // Also show in overlay
  _pmSlyVoiceUpdateOverlay(msg.slice(0, 80), false);
  setTimeout(() => _pmSlyVoiceActive && _pmSlyVoiceUpdateOverlay(_pmSlyListenText(), false), 4000);

  _pmSlyVoiceSpeak(msg);
}

// Announce context when voice activates (hooks into _pmSlyStartRecog)
const _pmSlyStartRecogAndAnnounce = (SR) => {
  _pmSlyStartRecog(SR);
  setTimeout(() => { if (_pmSlyVoiceActive) _pmSlyVoiceAnnounceContext(); }, 2000);
};

// ── Guided marking flow ───────────────────────────────────────────────────────
// Say "start marking" → walks through every unlinked event one by one.
// For each: announces the reel name, asks PL or CP, marks it, moves to next.

function _pmSlyGuideStart() {
  const linkedSet = new Set([..._pmLinkMap.values()]);
  _pmSlyGuideQueue = _pmEvents
    .map((ev, i) => ({ ev, i }))
    .filter(({ ev, i }) => !linkedSet.has(i))
    .map(({ i }) => i);

  if (!_pmSlyGuideQueue.length) {
    _pmSlyVoiceSpeak('All events are already marked. Nothing to do.');
    return;
  }

  _pmSlyGuideActive = true;
  _pmSlyGuideIdx    = 0;
  _pmSlyVoiceSpeak(`Starting guided marking. ${_pmSlyGuideQueue.length} events to mark. Say the plate type for each shot, or skip to move on.`);
  setTimeout(() => _pmSlyGuideNext(), 3000);
}

function _pmSlyGuideNext() {
  if (!_pmSlyGuideActive || !_pmSlyVoiceActive) return;

  if (_pmSlyGuideIdx >= _pmSlyGuideQueue.length) {
    _pmSlyGuideActive = false;
    const count = _pmClipMarkers.length;
    _pmSlyVoiceSpeak(`Guided marking complete. ${count} markers created. Say export when ready.`);
    _pmSlyVoiceUpdateOverlay('✓ Guided marking done', false);
    return;
  }

  const evIdx = _pmSlyGuideQueue[_pmSlyGuideIdx];
  const ev    = _pmEvents[evIdx];
  if (!ev) { _pmSlyGuideIdx++; _pmSlyGuideNext(); return; }

  // Set active event
  try { _pmSetActiveRow(evIdx); } catch {}

  const reel     = (ev.reel || ev.srcFile || ev.clip || '').replace(/\.[^.]+$/, '').slice(0, 24);
  const fps      = _pmFps || 24;
  const inF      = tcToFrames(ev.recIn  || '00:00:00:00', fps);
  const outF     = tcToFrames(ev.recOut || '00:00:00:00', fps);
  const durSec   = Math.max(0, outF - inF) / fps;
  const suggested = _pmSlySmartDetectType(ev, null);
  const remaining = _pmSlyGuideQueue.length - _pmSlyGuideIdx;
  const _guideTypeNames = { PL: 'Pull Plate', CP: 'Clean Plate', BG: 'Background', FG: 'Foreground', EL: 'Element', RF: 'Reference' };
  const prompt = `${remaining} left. ${reel}. ${durSec.toFixed(1)} seconds. Suggested: ${_guideTypeNames[suggested] || suggested}. Say type or skip.`;

  _pmSlyVoiceUpdateOverlay(`[${_pmSlyGuideIdx + 1}/${_pmSlyGuideQueue.length}] ${reel}`, false);
  _pmSlyVoiceSpeak(prompt);

  // Wait for user response
  _pmSlyVoiceAwaitReply = {
    options: {
      PL:   ['pl','pull','pull plate','plate','yes','yeah','ok','sure', suggested === 'PL' ? 'yes' : '__'],
      CP:   ['cp','clean','clean plate'],
      BG:   ['bg','background'],
      FG:   ['fg','foreground'],
      EL:   ['el','element'],
      skip: ['skip','next','pass','no','cancel'],
      stop: ['stop','done','exit','quit','finish'],
    },
    handler: async key => {
      if (key === 'stop') {
        _pmSlyGuideActive = false;
        _pmSlyVoiceSpeak(`Stopped. ${_pmClipMarkers.length} markers created so far.`);
        return;
      }
      if (key === 'skip') {
        _pmSlyGuideIdx++;
        _pmSlyVoiceSpeak('Skipped');
        setTimeout(() => _pmSlyGuideNext(), 800);
        return;
      }
      // Mark it
      await _pmSlyVoiceMarkType(key);
      _pmSlyVoicePostMark();
      _pmSlyGuideIdx++;
      setTimeout(() => _pmSlyGuideNext(), 1200);
    }
  };
}

function _pmSlyGuideStop() {
  _pmSlyGuideActive     = false;
  _pmSlyVoiceAwaitReply = null;
  _pmSlyVoiceSpeak('Guided mode stopped.');
}

// ── Smart post-mark announcement ─────────────────────────────────────────────
// Called after a mark is created — announces progress and suggests next action
function _pmSlyVoicePostMark() {
  if (_pmSlyGuideActive) return; // guided mode handles its own announcements
  const total  = _pmEvents.length;
  const linked = _pmLinkMap.size;
  const pct    = total > 0 ? Math.round((linked / total) * 100) : 0;
  if (pct === 100) {
    setTimeout(() => _pmSlyVoiceSpeak('All events marked. Say export to deliver.'), 1500);
  } else {
    setTimeout(() => {
      const remaining = total - linked;
      _pmSlyVoiceSpeak(`${remaining} left. Say next to continue.`);
    }, 1200);
  }
}

// ── Extended command list ─────────────────────────────────────────────────────
// Add guided mode commands to _SLY_INTENTS

_SLY_INTENTS.push(
  { pat: ['start marking','begin marking','guided mode','guide me','walk me through'],
    desc: 'Start guided marking',  cat: 'auto',
    fn: () => _pmSlyGuideStart() },

  { pat: ['stop guided','stop guiding','exit guided','stop marking session'],
    desc: 'Stop guided mode',      cat: 'auto',
    fn: () => _pmSlyGuideStop() },

  { pat: ['what should i do','what now','guide me','help me','next action','what next'],
    desc: 'Smart advice',          cat: 'ai',
    fn: async () => {
      const { clusters } = _pmSlyBuildClusters();
      const t = _pmEvents.length;
      const l = _pmLinkMap.size;
      const w = _pmSlyCountWarnMarkers();
      const rec = _pmSlyAiRecommend(clusters, l, t, w);
      _pmSlyVoiceSpeak(rec.text.slice(0, 120));
      _pmSlyToast(rec.text.slice(0, 80));
    } },

  { pat: ['read current','what is this','current shot','tell me about this'],
    desc: 'Read current event',    cat: 'info',
    fn: () => {
      const ev = _pmEvents[Math.max(0, _pmActiveEventIdx)];
      if (!ev) { _pmSlyVoiceSpeak('No event active'); return; }
      const fps  = _pmFps || 24;
      const reel = (ev.reel || ev.clip || '').replace(/\.[^.]+$/, '').slice(0, 24);
      const inF  = tcToFrames(ev.recIn  || '00:00:00:00', fps);
      const outF = tcToFrames(ev.recOut || '00:00:00:00', fps);
      const dur  = ((outF - inF) / fps).toFixed(1);
      const type = _pmSlySmartDetectType(ev, null);
      const _rcNames = { PL: 'Pull Plate', CP: 'Clean Plate', BG: 'Background', FG: 'Foreground', EL: 'Element', RF: 'Reference' };
      const rtEff = ev._pmRetime === true || (ev._pmRetime == null && !!ev._pmRetimeAuto);
      const rsEff = ev._pmResize === true || (ev._pmResize == null && !!ev._pmResizeAuto);
      const stEff = !!ev._pmStabilize;
      const flags = [rtEff && 'retime', rsEff && 'resize', stEff && 'stabilize'].filter(Boolean);
      const flagStr = flags.length ? `. Flags: ${flags.join(', ')}` : '';
      _pmSlyVoiceSpeak(`${reel}. ${dur} seconds. Suggested: ${_rcNames[type] || type}${flagStr}.`);
    } },

  { pat: ['how many left','remaining','count'],
    desc: 'Remaining count',       cat: 'info',
    fn: () => {
      const t = _pmEvents.length;
      const l = _pmLinkMap.size;
      _pmSlyVoiceSpeak(`${t - l} events remaining out of ${t} total. ${Math.round(l/Math.max(1,t)*100)} percent done.`);
    } },

  { pat: ['read markers','list markers','what markers'],
    desc: 'Read marker list',      cat: 'info',
    fn: () => {
      if (!_pmClipMarkers.length) { _pmSlyVoiceSpeak('No markers yet.'); return; }
      const list = _pmClipMarkers.slice(0, 5).map(m => m.shotName || m.reel || '?').join(', ');
      const more = _pmClipMarkers.length > 5 ? ` and ${_pmClipMarkers.length - 5} more` : '';
      _pmSlyVoiceSpeak(`${_pmClipMarkers.length} markers: ${list}${more}.`);
    } },

  // ── Flag toggles ──────────────────────────────────────────────────────────
  { pat: ['retime','toggle retime','mark retime','needs retime','flag retime'],
    desc: 'Toggle retime',  cat: 'flag',
    fn: () => _pmSlyVoiceToggleFlag('retime', 'Retime') },

  { pat: ['retime on','set retime on','enable retime','turn on retime'],
    desc: 'Retime on',      cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('retime', 'Retime', true) },

  { pat: ['retime off','set retime off','disable retime','turn off retime','no retime','clear retime'],
    desc: 'Retime off',     cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('retime', 'Retime', false) },

  { pat: ['resize','toggle resize','mark resize','needs resize','flag resize'],
    desc: 'Toggle resize',  cat: 'flag',
    fn: () => _pmSlyVoiceToggleFlag('resize', 'Resize') },

  { pat: ['resize on','set resize on','enable resize','turn on resize'],
    desc: 'Resize on',      cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('resize', 'Resize', true) },

  { pat: ['resize off','set resize off','disable resize','turn off resize','no resize','clear resize'],
    desc: 'Resize off',     cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('resize', 'Resize', false) },

  { pat: ['stabilize','stab','toggle stab','toggle stabilize','needs stab','needs stabilize','mark stab','flag stab'],
    desc: 'Toggle stabilize', cat: 'flag',
    fn: () => _pmSlyVoiceToggleFlag('stabilize', 'Stabilize') },

  { pat: ['stabilize on','stab on','enable stab','enable stabilize','turn on stab'],
    desc: 'Stabilize on',   cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('stabilize', 'Stabilize', true) },

  { pat: ['stabilize off','stab off','disable stab','turn off stab','no stab','clear stab'],
    desc: 'Stabilize off',  cat: 'flag',
    fn: () => _pmSlyVoiceSetFlag('stabilize', 'Stabilize', false) },

  // ── Playback speed ────────────────────────────────────────────────────────
  { pat: ['half speed','50 percent','slow motion','slow mo','half'],
    desc: '½× speed', cat: 'player',
    fn: () => {
      const v = document.getElementById('pmVideo');
      if (v) v.playbackRate = 0.5;
      _pmSlyVoiceSpeak('Half speed'); _pmSlyFlash('½×');
    } },

  { pat: ['quarter speed','25 percent','quarter','very slow'],
    desc: '¼× speed', cat: 'player',
    fn: () => {
      const v = document.getElementById('pmVideo');
      if (v) v.playbackRate = 0.25;
      _pmSlyVoiceSpeak('Quarter speed'); _pmSlyFlash('¼×');
    } },

  { pat: ['double speed','two x','2x','fast','speed up','twice speed','double'],
    desc: '2× speed', cat: 'player',
    fn: () => {
      const v = document.getElementById('pmVideo');
      if (v) v.playbackRate = 2.0;
      _pmSlyVoiceSpeak('Double speed'); _pmSlyFlash('2×');
    } },

  { pat: ['normal speed','full speed','one x','1x','reset speed','regular speed','real time'],
    desc: 'Normal speed', cat: 'player',
    fn: () => {
      const v = document.getElementById('pmVideo');
      if (v) v.playbackRate = 1.0;
      _pmSlyVoiceSpeak('Normal speed'); _pmSlyFlash('1×');
    } },

  // ── Help ──────────────────────────────────────────────────────────────────
  { pat: ['help','commands','what can i say','list commands','what commands','voice help'],
    desc: 'Voice help', cat: 'info',
    fn: () => {
      const msg = 'Nav: next, previous, first, last. Mark: pull, clean, bg, fg, element, reference. Flags: retime, resize, stabilize. Speed: half speed, double speed, normal speed. Edit: undo, redo, delete marker. Info: status, read marker. Or say: name it X, note X, start marking.';
      _pmSlyVoiceSpeak(msg);
      _pmSlyVoiceUpdateOverlay('next · previous · pull · clean · bg · fg · el · rf · retime · resize · stab · half speed · normal speed · undo · status · name it · note · start marking', false);
    } }
);
